  MA_SYMBOLS      = true,
  SYM_IMAGE_BASE  = 1701,  -- Image 3.1701+: symbols imported from MA's symbol library
  SYM_AP_BASE     = 6001,  -- Appearance 6001+ (12 states per symbol)
  AXIS_IMAGE      = 1398,  -- Image 3.1398 / 1399 / 1400: the MAtricks axis button (red X / blue Y / green Z)
  AXIS_AP         = 4598,
  -- number discs (icons/num, tools/make_number_icons.py): value buttons with big numbers
  NUMBERS         = true,
  NUM_IMAGE_BASE  = 1001,  -- Image 3.1001+ (3 states per number and colour)
  NUM_AP_BASE     = 4001,  -- Appearance 4001+
  NUM2_IMAGE_BASE = 2901,  -- Image 3.2901+ / Appearance 8501+: the number discs after the first 80 (green Z axis ...)
  NUM2_AP_BASE    = 8501,
  ZFAM_IMAGE_BASE = 2971,  -- Image 3.2971+ / Appearance 8571+: Rev / Shuffle / Edit discs in the Z axis green
  ZFAM_AP_BASE    = 8571,
  -- category artwork (icons/cat): icons on the caption buttons
  CAT_IMAGE_BASE  = 1301,  -- Image 3.1301+
  CAT_AP_BASE     = 4401,  -- Appearance 4401+
  -- Gobo picker: the group's own gobo wheel as image buttons
  GOBO_IMAGE_BASE  = 801,  -- Image 3.801+: gobo images from the fixture library
  GOBO_AP_BASE     = 3601, -- Appearance 3601+: gobo buttons (3 states per image)
  GOBO_PRESET_BASE = 201,  -- Preset 3.201+: per group and wheel slot (40 per group)   -- bump when icons/round changes: setup re-imports the round images
  -- MA3 keeps macro names unique ("0", "0#2", "0#3"...), so the button text is
  -- the layout element's own text (CustomTextText) instead of the macro name.
  ELEMENT_TEXT    = true,
  THEME_COLORS    = true,   -- the grey / red button colours follow MA's colour theme ('global theme off' = Tom's)
  SECTION_FRAMES  = true,   -- thin frames around each section of a layout (buttons have no border)

  -- Writes every command and its result to FireSystem.log in the MA3
  -- library folder (handy when testing; set false when it all works).
  DEBUG_LOG       = true,
}

end

-- ==== FireSystemCore.lua (copied by tools/make_tools.py) ====
MODS.Core = function(_ENV)

-- ======================================================================
-- Small helpers
-- ======================================================================
-- helpers used in one place live in FN (kept from when this was one file with a 200-locals limit)
FN = {}
failures = {}

PATHS = {}  -- library / media paths (log = the log file)
function libraryPath()
  local dir
  pcall(function() dir = GetPath(Enums.PathType.Library) end)
  if type(dir) ~= "string" or dir == "" then
    pcall(function() dir = GetPath("library") end)
  end
  if type(dir) ~= "string" or dir == "" then
    local pd, home = os.getenv("ProgramData"), os.getenv("HOME")
    if pd and not home then dir = pd .. "\\MALightingTechnology\\gma3_library"  -- Windows onPC
    else dir = (home or os.getenv("USERPROFILE") or ".") .. "/MALightingTechnology/gma3_library" end
  end
  return (dir:gsub("[/\\]+$", ""))
end
-- paths: the console's own separator ("\\" on Windows onPC) is used throughout
function PATHS.sep()
  local s
  pcall(function() s = GetPathSeparator() end)
  if type(s) ~= "string" or s == "" then s = package and package.config and package.config:sub(1, 1) or "/" end
  return s
end
-- <library>/part/part...
function PATHS.lib(...)
  local sep, p = PATHS.sep(), libraryPath()
  for _, part in ipairs({...}) do p = p .. sep .. part end
  return (p:gsub("[/\\]", sep))
end
-- where FireSystem's PNGs are: CFG.ICON_PATH or <library>/media/images
function PATHS.media()
  if CFG.ICON_PATH then return (CFG.ICON_PATH:gsub("[/\\]", PATHS.sep()):gsub("[/\\]+$", "")) end
  return PATHS.lib("media", "images")
end
function PATHS.exists(path)
  local f = io.open(path, "rb")
  if f then f:close() return true end
  return false
end

-- the images packed into the FireSystemIcons component (base64 by file name), or nil
function PATHS.packed()
  local sig = FireSystemPluginArgs and FireSystemPluginArgs[2]
  local D = FireSystemIconData or (type(sig) == "table" and sig.FireSystemIconData) or nil
  return type(D) == "table" and D or nil
end
function PATHS.have(file)
  local D = PATHS.packed()
  return (D and D[file] ~= nil) or PATHS.exists(PATHS.media() .. PATHS.sep() .. file)
end
-- MA only imports images from files: write a packed image out just for its import ...
function PATHS.put(file)
  local D, path = PATHS.packed(), PATHS.media() .. PATHS.sep() .. file
  if not (D and D[file]) or PATHS.exists(path) then return false end
  local f = io.open(path, "wb")
  if not f then return false end
  f:write(PATHS.b64(D[file])) f:close()
  return true
end
-- ... and remove it again once it's in the show (only files FireSystem wrote itself)
function PATHS.drop(file, wrote)
  if wrote then pcall(os.remove, PATHS.media() .. PATHS.sep() .. file) end
end
-- base64 -> bytes
function PATHS.b64(s)
  local map = PATHS.b64map
  if not map then
    map = {}
    local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i = 1, 64 do map[abc:byte(i)] = i - 1 end
    PATHS.b64map = map
  end
  local out, bytes, nb = {}, {}, 0
  local byte, char = string.byte, string.char
  for i = 1, #s, 4 do
    local a, b, c, d = byte(s, i, i + 3)
    local n = map[a] * 262144 + map[b] * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
    nb = nb + 1 bytes[nb] = (n >> 16) & 255
    if c ~= 61 then nb = nb + 1 bytes[nb] = (n >> 8) & 255 end
    if d ~= 61 then nb = nb + 1 bytes[nb] = n & 255 end
    if nb >= 3000 then out[#out + 1] = char(table.unpack(bytes, 1, nb)) nb = 0 end
  end
  if nb > 0 then out[#out + 1] = char(table.unpack(bytes, 1, nb)) end
  return table.concat(out)
end

function dbg(line)
  if not CFG.DEBUG_LOG then return end
  pcall(function()
    PATHS.log = PATHS.log or PATHS.lib("FireSystem.log")
    local f = io.open(PATHS.log, "a")
    if f then f:write(os.date("%H:%M:%S "), line, "\n") f:close() end
  end)
end

function log(fmt, ...)
  Printf("[FireSystem] " .. string.format(fmt, ...))
end

function okResult(r)
  if r == nil or r == true then return true end
  if type(r) == "string" then return r:lower():sub(1, 2) == "ok" end
  return false
end

-- Run a command; failures are collected and printed at the end.
nCmds = 0  -- commands sent during this press (timing log)
function C(fmt, ...)
  local s = (select("#", ...) > 0) and string.format(fmt, ...) or fmt
  nCmds = nCmds + 1
  local r = Cmd(s)
  dbg(s .. "  ->  " .. tostring(r))
  if not okResult(r) then failures[#failures + 1] = s .. "  ->  " .. tostring(r) end
  return okResult(r)
end

-- Try several command variants, stop at the first that the console accepts.
function Cany(list)
  for _, s in ipairs(list) do
    nCmds = nCmds + 1
    local r = Cmd(s)
    dbg(s .. "  ->  " .. tostring(r))
    if okResult(r) then return true end
  end
  failures[#failures + 1] = list[1] .. "  (and " .. (#list - 1) .. " variants) rejected"
  return false
end

function obj(path)
  local ok, l = pcall(ObjectList, path)
  if ok and type(l) == "table" and l[1] then return l[1] end
  return nil
end

function objName(h)
  if not h then return nil end
  local ok, n = pcall(function() return h.name end)
  if ok then return n end
  return nil
end

function q(s) return '"' .. tostring(s):gsub('"', "'") .. '"' end
function fs(label) return CFG.PREFIX .. " " .. label end
function trim(s) return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end

function groupList()
  local t = {}
  for _, g in ipairs(CFG.GROUPS) do t[#t + 1] = tostring(g) end
  return "Group " .. table.concat(t, " + ")
end

-- compress {1,2,3,5} -> "1 Thru 3 + 5"
function rangeList(nums)
  table.sort(nums)
  local out, i = {}, 1
  while i <= #nums do
    local j = i
    while j < #nums and nums[j + 1] == nums[j] + 1 do j = j + 1 end
    out[#out + 1] = (j > i) and (nums[i] .. " Thru " .. nums[j]) or tostring(nums[i])
    i = j + 1
  end
  return table.concat(out, " + ")
end

-- "3" -> 3, "true" -> true, "soft" -> "soft"
function parseVal(a)
  if a == "true" then return true elseif a == "false" then return false end
  return tonumber(a) or a
end

function presetName(pool, no)
  local n = objName(obj(string.format("Preset %d.%d", pool, no)))
  if n then n = n:gsub("^" .. CFG.PREFIX .. " ", "") end
  return n
end

-- ======================================================================
-- Pages, pool numbers, presets
-- ======================================================================
PAGES = {"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk"}
PAGE = {
  dim  = {i = 0, title = "Dimmer FX",   nav = "DimmerFX Page"},
  col  = {i = 1, title = "Color",       nav = "Color Page"},
  cfx  = {i = 2, title = "Color FX",    nav = "ColorFX Page"},
  pos  = {i = 3, title = "Position",    nav = "Position Page"},
  pfx  = {i = 4, title = "Position FX", nav = "PositionFX Page"},
  beam = {i = 5, title = "Gobo Prism Zoom", nav = "GoboPrismZoom Page"},
  bump = {i = 6, title = "Bump",        nav = "Bump Page"},
  xk   = {i = 7, title = "X-Keys",      nav = "XKey Page"},
  grp  = {i = 8, title = "Group Builder", nav = "Groups"},  -- not in PAGES: shown on first start
  ccol = {i = 9, title = "Custom Colours", nav = "Custom Colours"},  -- not in PAGES: from the Color page
  gobo = {i = 10, title = "Gobo Picker", nav = "Gobo Picker"},      -- not in PAGES: from the Gobo page
  home = {i = 11, title = "Home", nav = "Home"},                    -- not in PAGES: launcher on a view button
  tc   = {i = 12, title = "Timecode", nav = "Timecode"},            -- not in PAGES: timecode transport
  songs = {i = 13, title = "Setlist", nav = "Setlist"},             -- not in PAGES: one timecode per song
  rec  = {i = 14, title = "Recording", nav = "Recording"},          -- not in PAGES: record while busking
  upd  = {i = 15, title = "Update Presets", nav = "Update Presets"}, -- not in PAGES: edit presets per group
  mast = {i = 16, title = "Masters", nav = "Masters"},              -- not in PAGES: masters / utility view
  -- combined pages (TC.combo): two pages under each other, in PAGES only while every page in them has
  -- TC.combo.MAX or fewer groups that can use it. Their macros have their own blocks (mb, mn macros each).
  dpf  = {i = 17, title = "Dimmer FX + Position FX", nav = "DimFX + PosFX", mb = 6501, mn = 600},
  pcol = {i = 18, title = "Position + Color", nav = "Pos + Color", mb = 7101, mn = 600},
  tced = {i = 19, title = "Timecode Editor", nav = "TC Editor", mb = 8101, mn = 200},  -- not in PAGES: the song's events
}
FIRE_PAGES = {"dim", "col", "cfx", "pos", "pfx", "beam"}
FN.SEQ_NAME = {dim = "DimmerFX_G%d", col = "Color_G%d", cfx = "ColorFX_G%d",
                  pos = "Position_G%d", pfx = "PositionFX_G%d", beam = "GoboPrismZoom_G%d"}

function seqNo(page, gi) return CFG.SEQ_BASE + PAGE[page].i * 10 + (gi - 1) end
function bumpSeq(slot, gi) return CFG.BUMP_SEQ[slot] + gi - 1 end
function xkSeq(gi) return CFG.XKEY_SEQ + gi - 1 end
function layoutNo(page) return CFG.LAYOUT_BASE + PAGE[page].i end
function macroNo(page, n) return (PAGE[page].mb or (CFG.MACRO_BASE + PAGE[page].i * CFG.MACRO_BLOCK)) + (n - 1) end

S = CFG.PRESET_SLOT
NCOL = #CFG.COLORS
NALLCOL = NCOL + #CFG.CUSTOM_COLORS
function colorPreset(ci) return S + (ci - 1) end          -- 4.201-215, customs 4.216-219
-- Pastel / Dark versions of every colour (Color page tint buttons): 4.231-249 and 4.261-279
function tintPreset(ci, tint)
  if tint == 1 then return S + 30 + (ci - 1) end
  if tint == 2 then return S + 60 + (ci - 1) end
  return colorPreset(ci)
end
-- {R, G, B, W} in % for a colour and tint: pastel = towards white (and a little W), dark = dimmer mix
function tintRGBW(rgb, w, tint)
  if tint == 1 then
    local function p(v) return math.floor(v * 0.5 + 50 + 0.5) end
    return {p(rgb[1]), p(rgb[2]), p(rgb[3]), math.max(w, 25)}
  elseif tint == 2 then
    local function d(v) return math.floor(v * 0.35 + 0.5) end
    return {d(rgb[1]), d(rgb[2]), d(rgb[3]), math.floor(w * 0.35)}
  end
  return {rgb[1], rgb[2], rgb[3], w}
end
function colorLines(c)  -- c = {R, G, B, W} in %
  local l = {
    string.format("Attribute %s At %d", q(CFG.ATTR.r), c[1]),
    string.format("Attribute %s At %d", q(CFG.ATTR.g), c[2]),
    string.format("Attribute %s At %d", q(CFG.ATTR.b), c[3]),
  }
  -- the extra emitters default to full on many fixtures (W at 100 washed every colour out)
  for _, e in ipairs({"W", "WW", "CW"}) do l[#l + 1] = string.format('?Attribute "ColorRGB_%s" At %d', e, c[4]) end
  for _, e in ipairs({"UV", "Y", "C", "M", "RY", "GY", "GC", "BC", "BM", "RM"}) do
    l[#l + 1] = string.format('?Attribute "ColorRGB_%s" At 0', e)
  end
  return l
end
function isCustomColor(ci) return ci > NCOL end
function colorName(ci) return isCustomColor(ci) and ("COLOR " .. (ci - NCOL)) or CFG.COLORS[ci][1] end
-- custom colour n as {R, G, B, W} in % (Custom Colours page), default from CUSTOM_COLORS
function customColor(n)
  local v = GetVar(GlobalVars(), "FS_cc_" .. n)
  if v == nil then v = CFG.GV_DEFAULTS["cc_" .. n] end
  local t = {}
  if type(v) == "string" then for x in v:gmatch("[%d%.]+") do t[#t + 1] = tonumber(x) end end
  if #t == 4 then return t end
  local c = CFG.CUSTOM_COLORS[n] or {0, 0, 0}
  local function pc(x) return math.floor(x / 255 * 4 + 0.5) * 25 end  -- nearest button value
  return {pc(c[1]), pc(c[2]), pc(c[3]), 0}
end

-- Appearances: Tom's greys and reds + one plain and one darker appearance
-- per color swatch.
AP_LIST = {
  {"idle",   "Idle",        {46, 46, 46}},
  {"on",     "Selected",    {152, 152, 152}},
  {"pend",   "Pending",     {170, 0, 8}},
  {"fire",   "Fire",        {140, 0, 5}},
  {"dirty",  "Fire Pending", {255, 60, 0}},
  {"live",   "Live",        {220, 0, 0}},
  {"blind",  "Blind",       {40, 40, 40}},
  {"hdr",    "Header",      {15, 15, 15}},
  {"store",  "Store Empty", {83, 0, 0}},
  {"stored", "Store Full",  {170, 0, 0}},
  {"recall", "Preset Full", {139, 139, 139}},
  {"off",    "Off",         {70, 0, 0}},
}
do
  local function dark(rgb) return {math.floor(rgb[1] * .45), math.floor(rgb[2] * .45), math.floor(rgb[3] * .45)} end
  for ci, c in ipairs(CFG.COLORS) do
    AP_LIST[#AP_LIST + 1] = {"c" .. ci, c[1], c[2]}
    AP_LIST[#AP_LIST + 1] = {"cs" .. ci, c[1] .. " On", dark(c[2])}
  end
  for k, rgb in ipairs(CFG.CUSTOM_COLORS) do
    local ci = NCOL + k
    AP_LIST[#AP_LIST + 1] = {"c" .. ci, "Color " .. k, rgb}
    AP_LIST[#AP_LIST + 1] = {"cs" .. ci, "Color " .. k .. " On", dark(rgb)}
  end
end
AP = {}
for i, a in ipairs(AP_LIST) do AP[a[1]] = i - 1 end
function apNo(k) return CFG.APPEARANCE_BASE + (AP[k] or 0) end

function setApColor(no, rgb)
  Cany({
    string.format('Set Appearance %d Property "BackR" %d "BackG" %d "BackB" %d "BackAlpha" 255',
                  no, rgb[1], rgb[2], rgb[3]),
    string.format('Set Appearance %d Property "Color" "%02X%02X%02XFF"', no, rgb[1], rgb[2], rgb[3]),
  })
end

-- ======================================================================
-- Colour theme: the grey / red state colours follow MA's active colour theme
-- (Menu > Desk Lights & Color Theme). Each state takes a theme colour, scaled;
-- the first name that resolves wins. The colour swatches, round discs, executor
-- kinds and page backgrounds keep their own colours. 'global theme off' goes
-- back to Tom's colours, 'global theme' re-reads the theme now.
-- ======================================================================
FN.TH = {
  MAP = {  -- state key -> {{theme colour, scale}, ...} (Group.Name = ColorGroups, Def:Group.Name = ColorDefCollect)
    idle   = {{"Button.Background"}, {"Def:Global.ButtonBackground"}},
    on     = {{"Def:Global.Selected", .75}, {"Button.ActiveText", .75}},
    pend   = {{"Def:Global.Alert", .85}},
    fire   = {{"Def:Global.Alert", .7}},
    dirty  = {{"Def:Global.Error"}},
    live   = {{"Def:Global.Alert"}},
    blind  = {{"Button.Background", .8}, {"Def:Global.ButtonBackgroundDarker"}},
    hdr    = {{"Def:Global.Header"}},
    store  = {{"Def:Global.Alert", .45}},
    stored = {{"Def:Global.Alert", .85}},
    recall = {{"Def:Global.Bright"}},
    off    = {{"Def:Global.Alert", .35}},
    canvas = {{"Def:Global.BackgroundDark"}},
  },
  MAXL = {idle = 70, blind = 60, hdr = 50, canvas = 40},  -- brightest (luma) a state may get; others 170
  orig = {},   -- Tom's colours (AP_LIST as written above), for 'global theme off'
}
for i = 1, 12 do FN.TH.orig[AP_LIST[i][1]] = AP_LIST[i][3] end
FN.TH.orig.canvas = {0, 0, 0}
FN.TH.canvas = {0, 0, 0}
-- a theme colour as {r, g, b} (0-255, alpha laid over black: the pages are black), or nil.
-- RGBA comes as "RRGGBBAA" text (like the theme files); numbers and tables are taken too.
function FN.TH.rgb(o)
  if not o then return nil end
  local v
  for _, get in ipairs({function() return o.RGBA end, function() return o:Get("RGBA") end,
                        function() return o:Get("RGBA", Enums.Roles.Display) end}) do
    local ok, x = pcall(get)
    if ok and x ~= nil and x ~= "" then v = x break end
  end
  local c
  if type(v) == "string" then
    local hex = v:match("^#?(%x%x%x%x%x%x%x?%x?)$")
    if hex then
      c = {tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16),
           #hex == 8 and tonumber(hex:sub(7, 8), 16) or 255}
    else
      local t = {}
      for x in v:gmatch("[%d%.]+") do t[#t + 1] = tonumber(x) end
      if #t >= 3 then c = t end
    end
  elseif type(v) == "number" then
    v = math.floor(v)
    c = {(v >> 24) & 255, (v >> 16) & 255, (v >> 8) & 255, v & 255}
  elseif type(v) == "table" or type(v) == "userdata" then
    pcall(function()
      c = {v.r or v.R or v[1], v.g or v.G or v[2], v.b or v.B or v[3], v.a or v.A or v[4]}
    end)
  end
  if not (c and tonumber(c[1]) and tonumber(c[2]) and tonumber(c[3])) then
    -- a colour without its own value: the colour definition it points at
    local ok, ref = pcall(function() return o.ColorDefRef end)
    if ok and ref and ref ~= o and type(ref) ~= "string" then return FN.TH.rgb(ref) end
    return nil
  end
  local scale = 1
  if c[1] <= 1 and c[2] <= 1 and c[3] <= 1 and (c[4] or 1) <= 1 then scale = 255 end  -- 0-1 floats
  local a = (tonumber(c[4]) or (scale == 255 and 1 or 255)) * scale / 255
  local out = {}
  for i = 1, 3 do out[i] = math.max(0, math.min(255, math.floor(c[i] * scale * a + 0.5))) end
  return out
end
function FN.TH.find(ct, name)
  local def, grp, key = name:match("^(Def:)(.-)%.(.+)$")
  if not def then grp, key = name:match("^(.-)%.(.+)$") end
  local ok, h = pcall(function()
    local base = def and ct.ColorDefCollect or ct.ColorGroups
    return base[grp][key]
  end)
  return ok and h or nil
end
-- the theme's state colours {key = rgb} and a signature of them, or nil (no theme / it can't be read)
function FN.TH.read()
  local ok, ct = pcall(function() return Root().ColorTheme end)
  if not (ok and ct) then return nil end
  local cols, sig = {}, {}
  for k, list in pairs(FN.TH.MAP) do
    for _, e in ipairs(list) do
      local c = FN.TH.rgb(FN.TH.find(ct, e[1]))
      if c then
        local m = e[2] or 1
        cols[k] = {math.floor(c[1] * m + 0.5), math.floor(c[2] * m + 0.5), math.floor(c[3] * m + 0.5)}
        break
      end
    end
    if not cols[k] then return nil end  -- half a theme looks worse than Tom's colours
  end
  -- the button text and artwork are white: light themes give darker tones of their colours
  for k, c in pairs(cols) do
    local max, l = FN.TH.MAXL[k] or 170, .299 * c[1] + .587 * c[2] + .114 * c[3]
    if l > max then for i = 1, 3 do c[i] = math.floor(c[i] * max / l + 0.5) end end
  end
  for k, c in pairs(cols) do sig[#sig + 1] = string.format("%s%02X%02X%02X", k, c[1], c[2], c[3]) end
  table.sort(sig)
  return cols, table.concat(sig, " ")
end
-- the colours to use now: the theme's, or Tom's when it's off / unreadable
function FN.TH.colors()
  if not CFG.THEME_COLORS or GetVar(GlobalVars(), "FS_theme") == "off" then return FN.TH.orig, "off" end
  local cols, sig = FN.TH.read()
  if not cols then return FN.TH.orig, "off" end
  return cols, sig
end
-- recolours FireSystem's appearances that carry a state colour (made before the theme changed)
function FN.TH.recolor(cols)
  local ranges = {  -- {from, to, states per object}
    {CFG.APPEARANCE_BASE, CFG.APPEARANCE_BASE + 12 - 1},
    {CFG.ICON_AP_BASE, CFG.ROUND_AP_BASE - 1}, {CFG.ART_AP_BASE, CFG.GOBO_AP_BASE - 1},
    {CFG.ART2_AP_BASE, CFG.SYM_AP_BASE - 1}, {CFG.SYM_AP_BASE, CFG.BG_AP_BASE - 1},
  }
  local pre, n = CFG.PREFIX .. " ", 0
  local ok, list = pcall(function() return ShowData().Appearances:Children() end)
  if not (ok and type(list) == "table") then return 0 end
  for _, h in ipairs(list) do
    local no, name = tonumber(h.no), tostring(h.name)
    local c
    if no and name:sub(1, #pre) == pre then
      for _, r in ipairs(ranges) do
        if no >= r[1] and no <= r[2] then c = cols[AP_LIST[(no - r[1]) % 12 + 1][1]] break end
      end
      -- category captions on the header colour (the clear Color FX STEP captions stay clear)
      if not c and no >= CFG.CAT_AP_BASE and no < CFG.CAT_AP_BASE + 197 and name:sub(1, #pre + 2) == pre .. "c "
         and not name:find(" left$") then c = cols.hdr end
      if not c and no == CFG.APPEARANCE_BASE + 99 then c = cols.canvas end
    end
    if c then
      -- only the colour: the alpha stays (captions let the page background through)
      if pcall(function() h.BACKR, h.BACKG, h.BACKB = c[1], c[2], c[3] end) then n = n + 1 end
    end
  end
  return n
end
-- checks the theme (a dozen property reads) and follows it when it changed
function FN.TH.check(force)
  local cols, sig = FN.TH.colors()
  for i = 1, 12 do local k = AP_LIST[i][1] if cols[k] then AP_LIST[i][3] = cols[k] end end
  FN.TH.canvas = cols.canvas or {0, 0, 0}
  if not force and GetVar(GlobalVars(), "FS_theme_sig") == sig then return end
  if not obj("Appearance " .. CFG.APPEARANCE_BASE) then return end  -- nothing built yet: made with these colours
  local n = FN.TH.recolor(cols)
  SetVar(GlobalVars(), "FS_theme_sig", sig)
  return n, sig
end

end

-- ==== FireSystemArt.lua (copied by tools/make_tools.py) ====
MODS.Art = function(_ENV)

-- ======================================================================
-- Icons: fs_<name>.png, imported into Image 3.201+ (ICON_LIST order).
-- A button with an icon gets an appearance per icon and state (grey,
-- red ...), made the first time it is needed: ICON_AP_BASE + icon*N + state.
-- ======================================================================
ICON_LIST = {
  "pen", "eye", "power", "g1", "g2", "g3", "g4", "g5",
  "g6", "g7", "g8", "random", "bulb_off", "bulb_full", "bulb_half", "sine1",
  "sine3", "sine4", "down1", "down3", "down4", "up1", "up3", "up4",
  "square1", "square3", "square4", "fan", "heart", "person", "rev", "shuffle",
  "pan1", "pan2", "pan3", "pan4", "pan5", "pan6", "pan7", "pan8",
  "pan9", "pan10", "tilt1", "tilt2", "tilt3", "tilt4", "tilt5", "tilt6",
  "tilt7", "left", "right", "out", "in", "pan_wide", "tilt_swing", "up",
  "down", "cloud", "minus", "plus", "iris", "cone", "gobo", "prism",
  "shaper", "lines", "strobe", "all", "oddeven", "blocks", "pan11", "pan12",
  -- Position FX page (tools/make_move_icons.py); round images 3.581+ (the 301+ block is full)
  "mv_out", "mv_in", "mv_left", "mv_right", "mv_wide", "mv_tswing", "mv_up", "mv_down",
  "mv_circle", "fly_in", "fly_out"
}
ICON_IDX = {}
for i, n in ipairs(ICON_LIST) do ICON_IDX[n] = i end
N_STATES = 12   -- the first 12 entries of AP_LIST (not the color swatches)

-- button label -> icon, as drawn on Tom's pages
FN.ICON_BY_LABEL = {
  ["Rnd"] = "random", ["Full"] = "bulb_full", ["Half"] = "bulb_half", ["Flash"] = "bulb_full",
  ["Sin 1"] = "sine1", ["Sin 3"] = "sine3", ["Sin 4"] = "sine4",
  ["Dn 1"] = "down1", ["Dn 3"] = "down3", ["Dn 4"] = "down4",
  ["Up 1"] = "up1", ["Up 3"] = "up3", ["Up 4"] = "up4",
  ["Sq 1"] = "square1", ["Sq 3"] = "square3", ["Sq 4"] = "square4", ["|<->|"] = "fan",
  ["Sine"] = "sine1", ["Ramp Dn"] = "down1", ["Ramp Up"] = "up1", ["Square"] = "square1",
  ["Ramp"] = "down1", ["Heart"] = "heart",
  ["Edit"] = "person", ["Single"] = "person", ["Rev"] = "rev", ["Shuffle"] = "shuffle",
  ["Multi"] = "pen", ["Copy"] = "pen", ["Blind"] = "eye",
  ["<>"] = "out", ["><"] = "in", ["<"] = "left", [">"] = "right", ["<.>"] = "pan_wide",
  ["^v"] = "tilt_swing", ["^"] = "up", ["v"] = "down", ["Cloud"] = "cloud",
  ["-"] = "minus", ["+"] = "plus", ["Strobe"] = "strobe", ["Zoom"] = "cone",
  ["="] = "all", ["::"] = "oddeven", ["::."] = "blocks",
}
FN.BEAM_ICON = {iris = "iris", zoom = "cone", gobo1 = "gobo", gobo2 = "gobo", prism = "prism",
                   shape = "shaper", add = "lines"}

function imagePath(i) return string.format("Image %d.%d", CFG.IMAGE_POOL, CFG.ICON_IMAGE_BASE + i - 1) end
function iconsReady() return CFG.ICONS and GetVar(GlobalVars(), "FS_icons_ok") == "1" end

-- appearance for (state, icon); nil when that combination can't be used
iconApSeen = {}
function FN.iconAp(k, icon)
  local ii, si = ICON_IDX[icon], AP[k]
  if not ii or not si or si >= N_STATES then return nil end
  local no = CFG.ICON_AP_BASE + (ii - 1) * N_STATES + si
  if iconApSeen[no] ~= nil then return iconApSeen[no] or nil end
  local want = CFG.PREFIX .. " " .. icon .. " " .. AP_LIST[si + 1][2]
  local h = obj("Appearance " .. no)
  local name = h and objName(h)
  if h and name ~= want then
    if not (name and name:sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " ") and name ~= "" then
      iconApSeen[no] = false   -- someone else's appearance: leave it alone
      return nil
    end
  end
  local function hasImage(ap)
    local ok, im = pcall(function() return ap.Image end)
    return ok and im ~= nil and im ~= ""
  end
  if name ~= want or not hasImage(h) then  -- also repairs appearances made without their image
    if name ~= want then
      C("Store Appearance %d /Overwrite", no)
      C("Label Appearance %d %s", no, q(want))
      setApColor(no, AP_LIST[si + 1][3])
    end
    -- the image is a handle, set from Lua like MA's own scripts do;
    -- 'Set Appearance N Property "Image" "Image 3.201"' answers Ok but sets nothing
    local img, ap = imagePath(ii), obj("Appearance " .. no)
    local im = obj(img)
    if ap and im then
      pcall(function() ap.Image = im end)
      if not hasImage(ap) then pcall(function() ap:Set("Image", im) end) end
      if not hasImage(ap) then
        Cany({ string.format('Set Appearance %d Property "Image" "%s"', no, im:Addr()),
               string.format('Set Appearance %d Property "Image" "%s"', no, im:ToAddr()) })
      end
    end
    dbg(string.format("Appearance %d image %s  ->  %s", no, img, tostring(ap and hasImage(ap))))
  end
  iconApSeen[no] = no
  return no
end

-- ======================================================================
-- ROUND style (see CFG.ROUND): coloured discs for 1x1 buttons
-- ======================================================================
-- colour families {dark idle, bright on}; same as tools/make_round_icons.py
ROUND_FAMILY_COLORS = {
  red = {{140, 0, 0}, {255, 20, 20}}, green = {{0, 110, 20}, {0, 210, 60}},
  blue = {{0, 40, 160}, {0, 120, 255}}, orange = {{150, 75, 0}, {255, 150, 0}},
  purple = {{100, 0, 130}, {190, 40, 255}}, teal = {{0, 105, 110}, {0, 210, 215}},
  yellow = {{125, 110, 0}, {235, 215, 0}}, magenta = {{130, 0, 110}, {255, 0, 210}},
}
FN.ROUND_FAMILIES = {"red", "green", "blue", "orange", "purple", "teal", "yellow", "magenta"}
ROUND_STATE = {idle = 0, on = 1, pend = 2}
ROUND_SUFFIX = {[0] = "i", [1] = "o", [2] = "p"}
roundSeen = {}

function importImage(no, file)
  if obj(string.format("Image %d.%d", CFG.IMAGE_POOL, no)) then return true end
  local dir = PATHS.media()
  local wrote = PATHS.put(file)
  Cany({
    string.format('Import Image %d.%d /File "%s" /Path "%s" /NoConfirm', CFG.IMAGE_POOL, no, file, dir),
    string.format('Import Image %d.%d /File "%s" /Path "%s"', CFG.IMAGE_POOL, no, file, dir),
  })
  PATHS.drop(file, wrote)
  local h = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, no))
  if h then Cmd(string.format("Label Image %d.%d %s", CFG.IMAGE_POOL, no, q(fs(file:gsub("%.png$", ""))))) end
  return h ~= nil
end

-- appearance with a state colour and an image (made once; kept while it has this name)
function imageAp(no, want, rgb, img)
  if objName(obj("Appearance " .. no)) == want then return end
  C("Store Appearance %d /Overwrite", no)
  C("Label Appearance %d %s", no, q(want))
  setApColor(no, rgb)
  local h, im = obj("Appearance " .. no), obj(string.format("Image %d.%d", CFG.IMAGE_POOL, img))
  pcall(function() h.Image = im end)
end

-- appearance with an image, transparent back; tint = {r,g,b} or nil (white)
function makeImageAp(no, label, imgNo, tint)
  local want = fs(label)
  local h = obj("Appearance " .. no)
  if objName(h) == want then return no end
  C("Store Appearance %d /Overwrite", no)
  C("Label Appearance %d %s", no, q(want))
  C('Set Appearance %d Property "BackR" 0 "BackG" 0 "BackB" 0 "BackAlpha" 0', no)
  h = obj("Appearance " .. no)
  local im = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, imgNo))
  pcall(function()
    h.Image = im
    local c = tint or {255, 255, 255}
    h.ImageR, h.ImageG, h.ImageB, h.ImageAlpha = c[1], c[2], c[3], 255
  end)
  return no
end

-- disc appearance for an icon button, or nil (then the square style is used)
-- icons that also come in the MAtricks axis colours (fs_r_<icon>_<red|blue>_<s>.png)
FN.ROUND_FAM_ICONS = {"rev", "shuffle", "person"}
function FN.roundIconAp(k, icon, fam)
  if k == "dis" then
    -- greyed out (the group can't use it): the idle disc, dimmed
    local ii = ICON_IDX[icon]
    if not (CFG.ROUND and ii) then return nil end
    local key = icon .. "dis"
    if roundSeen[key] ~= nil then return roundSeen[key] or nil end
    local img = CFG.ROUND_IMAGE_BASE + (ii > 72 and 280 + (ii - 73) * 3 or (ii - 1) * 3)
    local ok = importImage(img, string.format("fs_r_%s_i.png", icon))
    roundSeen[key] = ok and makeImageAp(CFG.ROUND_AP_BASE + 800 + ii, "r " .. icon .. " dis", img, {90, 90, 90}) or false
    return roundSeen[key] or nil
  end
  local si, ii = ROUND_STATE[k], ICON_IDX[icon]
  if not (CFG.ROUND and si and ii) then return nil end
  if fam == "red" or fam == "blue" or fam == "green" then
    local xi
    for i, n in ipairs(FN.ROUND_FAM_ICONS) do if n == icon then xi = i end end
    if xi then
      local key = icon .. fam .. si
      if roundSeen[key] == nil then
        local off = ((xi - 1) * 2 + (fam == "red" and 0 or 1)) * 3 + si
        local img, apNo = CFG.ROUND_IMAGE_BASE + 230 + off, CFG.ROUND_AP_BASE + 400 + off
        if fam == "green" then  -- (the Z axis came later: its own range)
          off = (xi - 1) * 3 + si
          img, apNo = CFG.ZFAM_IMAGE_BASE + off, CFG.ZFAM_AP_BASE + off
        end
        local ok = importImage(img, string.format("fs_r_%s_%s_%s.png", icon, fam, ROUND_SUFFIX[si]))
        roundSeen[key] = ok and makeImageAp(apNo, "r " .. icon .. " " .. fam .. " " .. k, img) or false
      end
      return roundSeen[key] or nil
    end
  end
  local key = icon .. si
  if roundSeen[key] ~= nil then return roundSeen[key] or nil end
  local img = CFG.ROUND_IMAGE_BASE + (ii > 72 and 280 + (ii - 73) * 3 or (ii - 1) * 3) + si
  local ok = importImage(img, string.format("fs_r_%s_%s.png", icon, ROUND_SUFFIX[si]))
  roundSeen[key] = ok and makeImageAp(CFG.ROUND_AP_BASE + (ii - 1) * 3 + si, "r " .. icon .. " " .. k, img) or false
  return roundSeen[key] or nil
end

-- zoom level disc (1 narrow .. 4 full) for the Gobo page's Zoom button
function FN.zoomAp(n, k)
  local si = ROUND_STATE[k]
  if not (CFG.ROUND and si and n and n >= 1 and n <= 4) then return nil end
  local key = "zoom" .. n .. si
  if roundSeen[key] ~= nil then return roundSeen[key] or nil end
  local off = (n - 1) * 3 + si
  local img = CFG.ROUND_IMAGE_BASE + 260 + off
  local ok = importImage(img, string.format("fs_r_zoom%d_%s.png", n, ROUND_SUFFIX[si]))
  roundSeen[key] = ok and makeImageAp(CFG.ROUND_AP_BASE + 460 + off, "r zoom" .. n .. " " .. k, img) or false
  return roundSeen[key] or nil
end

-- tinted disc for a text button (0°, 90°, numbers ...)
function FN.roundTextAp(k, family)
  local si, fi = ROUND_STATE[k], nil
  for i, f in ipairs(FN.ROUND_FAMILIES) do if f == family then fi = i end end
  if k == "dis" and CFG.ROUND and fi then
    local key = family .. "dis"
    if roundSeen[key] ~= nil then return roundSeen[key] or nil end
    local ok = importImage(CFG.ROUND_DISC_IMAGE, "fs_disc.png")
    local c = ROUND_FAMILY_COLORS[family][1]
    roundSeen[key] = ok and makeImageAp(CFG.ROUND_AP_BASE + 330 + fi, "disc " .. family .. " dis", CFG.ROUND_DISC_IMAGE,
      {math.floor(c[1] * .35), math.floor(c[2] * .35), math.floor(c[3] * .35)}) or false
    return roundSeen[key] or nil
  end
  if not (CFG.ROUND and si and fi) then return nil end
  local key = family .. si
  if roundSeen[key] ~= nil then return roundSeen[key] or nil end
  local img = CFG.ROUND_DISC_IMAGE + (si == 2 and 1 or 0)
  local ok = importImage(img, si == 2 and "fs_disc_ring.png" or "fs_disc.png")
  -- idle dark, on inverted (white disc, coloured text), pending bright with ring
  local c = (si == 1) and {255, 255, 255} or ROUND_FAMILY_COLORS[family][si == 0 and 1 or 2]
  roundSeen[key] = ok and makeImageAp(CFG.ROUND_AP_BASE + 300 + (fi - 1) * 3 + si, "disc " .. family .. " " .. k, img, c) or false
  return roundSeen[key] or nil
end

-- artwork buttons: white icon + label image on the state colour (same order as tools/make_button_art.py)
ART_LIST = {"clear", "fire", "savelook", "recall1", "recall2", "recall3", "recall4",
  "store1", "store2", "store3", "store4", "nav_dim", "nav_col", "nav_cfx", "nav_pos", "nav_pfx",
  "nav_beam", "nav_bump", "nav_xk", "customcolours", "back", "clearsel", "done", "grpclear", "copy",
  "color", "bground", "colbg", "prep", "live", "recallgrp", "mxclear", "stop", "rotate", "pastel", "dark"}
-- more artwork (tools/make_extra_art.py), in its own image / appearance range
ART_LIST.x = {}
ART_LIST.x.list2 = {"nav_home", "home_big", "fit", "fit_big", "bump_keys", "strobe_knobs", "store_grp", "back_gobo", "h_build", "h_groups", "h_auto", "h_rig", "h_masters", "h_views", "h_open", "h_tc", "h_songs", "h_rec", "h_upd", "h_util", "t_internal", "t_ltc", "t_midi", "t_artnet", "t_record", "t_timeline", "t_blend", "t_top", "t_play", "t_pause", "t_stop", "t_rec", "t_prev", "t_next", "t_songs", "t_recview", "s_song", "s_add", "s_rename", "s_delete", "s_tc", "r_rec", "r_stop", "r_tc", "r_save", "u_color", "u_pan", "u_tilt", "u_zoom", "u_strobe", "u_update", "u_clear", "u_revert", "ut_cook", "ut_editrecipe", "ut_cuefade", "ut_offfade", "ut_selcue", "ut_seloff", "ut_additive", "ut_gmnone", "ut_listref", "ut_gridstore", "ut_storedefault", "ut_encbar", "ut_clone", "ut_save", "ut_teston", "ut_testoff", "ut_fdim", "ut_fpos", "ut_fgobo", "ut_fcol", "ut_fbeam", "ut_ffocus", "ut_store", "ut_assign", "ut_goplus", "ut_gominus", "ut_copymx", "ut_clearall", "h_mast", "nav_mast", "m_open", "m_util", "m_masters", "nav_home3", "m_page1", "m_page2"}
ART_LIST.x.only = {fit = true, fit_big = true, store_grp = true, t_rec = true, s_song = true, r_rec = true}  -- live text written under the icon
ART_IDX = {}
for i, n in ipairs(ART_LIST) do ART_IDX[n] = i end
for i, n in ipairs(ART_LIST.x.list2) do ART_IDX[n] = 100 + i end
artSeen = {}
function FN.artAp(k, art)
  local ai, si = ART_IDX[art], AP[k]
  if not (CFG.ART and ai and si and si < 12) then return nil end
  if ai > 100 and not ART_LIST.x.checked then
    -- the extra artwork list changed (new buttons): drop the old images / appearances so the
    -- numbers match the list again
    ART_LIST.x.checked = true
    local sig = #ART_LIST.x.list2 .. ":" .. table.concat(ART_LIST.x.list2, ","):len()
    if GetVar(GlobalVars(), "FS_art2_sig") ~= sig then  -- (gv / sv are defined further down)
      for i = 0, 199 do
        local h = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, CFG.ART2_IMAGE_BASE + i))
        if h then Cmd(string.format("Delete Image %d.%d /NC", CFG.IMAGE_POOL, CFG.ART2_IMAGE_BASE + i)) end  -- FireSystem's range
      end
      for no2 = CFG.ART2_AP_BASE, CFG.ART2_AP_BASE + 200 * 12 do
        local h = obj("Appearance " .. no2)
        if h and tostring(h.name):sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " " then Cmd(string.format("Delete Appearance %d /NC", no2)) end
      end
      for k in pairs(artSeen) do artSeen[k] = nil end
      SetVar(GlobalVars(), "FS_art2_sig", sig)
    end
  end
  local no = CFG.ART_AP_BASE + (ai - 1) * 12 + si
  local img = CFG.ART_IMAGE_BASE + ai - 1
  if ai > 100 then
    no = CFG.ART2_AP_BASE + (ai - 101) * 12 + si
    img = CFG.ART2_IMAGE_BASE + ai - 101
  end
  if artSeen[no] ~= nil then return artSeen[no] or nil end
  if not importImage(img, "fs_a_" .. art .. ".png") then artSeen[no] = false return nil end
  imageAp(no, fs("a " .. art .. " " .. k), AP_LIST[si + 1][3], img)
  artSeen[no] = no
  return no
end
-- ---- number discs and category artwork -------------------------------------
