  {"^tc view rec$", "h_rec", 4, 2}, {"^global upd$", "h_upd"}, {"^global utility$", "h_util"},
  {"^tc source internal$", "t_internal"}, {"^tc source ltc$", "t_ltc"}, {"^tc source midi$", "t_midi"},
