-- ==== FireSystemState.lua (copied by tools/make_tools.py) ====
MODS.State = function(_ENV)

-- ======================================================================
-- State (persisted in GlobalVars so it survives reloads and show saves)
-- ======================================================================
LOOK_DEFAULTS = {
  dim  = {form = 0},
  col  = {color = 0, tint = 0, split = 0, color2 = 0, tint2 = 0},  -- split: see TC.part
  cfx  = {form = 0, c1 = 1, c2 = 3, c3 = 11, c4 = 5, c5 = 14, n = 2,  -- n = colours (steps) in the effect, 2-5
          t1 = 0, t2 = 0, t3 = 0, t4 = 0, t5 = 0},                       -- each step's Pastel (1) / Dark (2)
  pos  = {pan = 0, tilt = 0},
  pfx  = {panfx = 0, tiltfx = 0, size = 2},
  beam = {iris = 0, zoom = 0, gobo1 = 0, gobo2 = 0, prism = 0, shape = 0, add = 0,
          gobo1rot = false, prismrot = false, shaperot = false},
}
MX_DEFAULT = {shift = 0, blk = 0, grp = 0, wings = 0, width = 0, phase = 0, rev = false,
                    speed = 0, bpm = 0, rate = 0, shuf = false, fade = 0, spread = false, frev = false,
                    delay = 0, drev = false, sym = false, live = false}
-- The big X on the FX pages steps the MAtricks columns through the X, Y and Z
-- axis. Each axis keeps its own values (Y ones are stored as y_<field>, Z ones as z_<field>).
FN.AXES = {"X", "Y", "Z"}
FN.AXIS_PRE = {X = "", Y = "y_", Z = "z_"}
FN.AXIS_NEXT = {X = "Y", Y = "Z", Z = "X"}
FN.AXIS_FAM = {X = "red", Y = "blue", Z = "green"}  -- the MAtricks buttons' colour per axis
FN.AXIS_FIELDS = {"shift", "blk", "grp", "wings", "width", "phase", "rev", "speed", "bpm", "shuf",
                     "fade", "spread", "frev", "delay", "drev", "sym"}
IS_AXIS_FIELD = {}
for _, f in ipairs(FN.AXIS_FIELDS) do
  IS_AXIS_FIELD[f] = true
  MX_DEFAULT["y_" .. f] = MX_DEFAULT[f]
  MX_DEFAULT["z_" .. f] = MX_DEFAULT[f]
end
function axKey(axis, field)
  if IS_AXIS_FIELD[field] then return (FN.AXIS_PRE[axis] or "") .. field end
  return field
end

function ser(t)
  local parts = {}
  for k, v in pairs(t) do parts[#parts + 1] = k .. "=" .. tostring(v) end
  table.sort(parts)
  return table.concat(parts, ";")
end

function deser(s)
  local t = {}
  if type(s) ~= "string" then return t end
  for k, v in s:gmatch("([%w_]+)=([^;|]*)") do t[k] = parseVal(v) end
  return t
end

function gv(key) local v = GetVar(GlobalVars(), "FS_" .. key) if v == nil then v = CFG.GV_DEFAULTS[key] end return v end  -- always one value (GetVar returns none when unset)
function sv(key, val) SetVar(GlobalVars(), "FS_" .. key, val) end

function copy(t) local o = {} for k, v in pairs(t) do o[k] = v end return o end

function loadGroup(page, gi)
  local d = copy(MX_DEFAULT)
  for k, v in pairs(LOOK_DEFAULTS[page] or {}) do d[k] = v end
  d.dirty = false
  for k, v in pairs(deser(gv(page .. "_" .. gi))) do d[k] = v end
  return d
end
function saveGroup(page, gi, st) sv(page .. "_" .. gi, ser(st)) end

function loadTable(key, defaults)
  local t = copy(defaults)
  for k, v in pairs(deser(gv(key))) do t[k] = v end
  return t
end

function getAxis(page) local a = gv("axis_" .. page) return FN.AXIS_PRE[a] and a or "X" end
-- the Bump page's MAtricks buttons edit X (""), Y ("y": the keys ymb / ymg / ymw / ymp<step>) or
-- Z ("z": zmb ...); the same big X / Y / Z button as the FX pages
function BM.axisKey() return (FN.AXIS_PRE[getAxis("bump")]:gsub("_", "")) end
function getGlobal() return loadTable("global", {live = false, solo = false}) end
function setGlobal(t) sv("global", ser(t)) end

-- ---- timecode state (Timecode / Setlist / Recording pages) ----------------
TC = {}
-- Colour Fill: the UTIL entry with color = true. On the Color page it is one more row after the
-- groups (row #GROUPS + 1, Sequence seqNo("col", row)); its dimmer is its Utility fader.
TC.fill = {}
-- (several entries can have color = n: their rows go under the groups in that order)
function TC.fill.list()
  local t = {}
  for i, u in ipairs(CFG.UTIL) do if u.color then t[#t + 1] = i end end
  table.sort(t, function(a, b)
    local x, y = tonumber(CFG.UTIL[a].color) or 1, tonumber(CFG.UTIL[b].color) or 1
    if x ~= y then return x < y end
    return a < b
  end)
  return t
end
function TC.fill.entry(k) local i = TC.fill.list()[k or 1] if i then return i, CFG.UTIL[i] end end
function TC.fill.group(k) local i = TC.fill.entry(k) return i and (CFG.UTIL_GROUP_BASE + i - 1) or nil end
-- the first fill row on this page (nil: the page has none); k(page, gi) = which fill row gi is
function TC.fill.gi(page) if page == "col" and TC.fill.entry(1) then return #CFG.GROUPS + 1 end end
function TC.fill.k(page, gi)
  local k = (gi or 0) - #CFG.GROUPS
  if page == "col" and k >= 1 and k <= #TC.fill.list() then return k end
end
function TC.fill.n(page) return #CFG.GROUPS + (page == "col" and #TC.fill.list() or 0) end  -- rows of the page
-- group number of row gi (the fill rows after the busking groups)
function TC.grp(gi) return CFG.GROUPS[gi] or TC.fill.group((gi or 0) - #CFG.GROUPS) or nil end
-- name of the show's group gi (shown next to its G button; read on every refresh, so a renamed
-- group shows straight away)
function TC.gname(gi)
  local g = CFG.GROUPS[gi]
  local n = g and objName(obj("Group " .. g))
  return (type(n) == "string" and trim(n) ~= "") and trim(n) or ""
end
-- can group row gi use a Gobo/Prism/Zoom item? (any of its fixtures has one of the attributes;
-- cached until the groups change). Items it can't use are greyed out on the Gobo page.
TC.CAP_ATTRS = {iris = {"Iris"}, zoom = {"Zoom"}, gobo1 = {"Gobo1"}, gobo2 = {"Gobo2"}, prism = {"Prism1", "Effects1"},
                shape = {"Blade1A", "Blade1Rot", "ShaperRot", "Blade1"},
                dim = {"Dimmer"}, color = {"ColorRGB_R", "ColorRGB_C", "Color1"}, pos = {"Pan", "Tilt"}}
-- what a group needs for each page: a group without it gets greyed-out buttons on that page
TC.PAGE_CAP = {dim = "dim", col = "color", cfx = "color", pos = "pos", pfx = "pos"}
function TC.pcap(page, gi) local k = TC.PAGE_CAP[page] return not k or TC.cap(gi, k) end
TC.capCache = {}
-- combined pages: with few groups two pages fit on one. A combined page is in PAGES while every
-- page in it has 1 to MAX groups that can use it (checked at setup, kept in FS_combos)
TC.combo = {MAX = 5, ORDER = {"dpf", "pcol"}, DEF = {dpf = {"dim", "pfx"}, pcol = {"pos", "col"}}}
-- the groups (by index) that can use a page: a combined page shows only their rows
function TC.combo.rows(page)
  local t = {}
  for gi = 1, #CFG.GROUPS do if TC.pcap(page, gi) then t[#t + 1] = gi end end
  return t
end
-- which combined pages this show gets (asks the fixtures, so it clears the selection)
function TC.combo.check()
  local on = {}
  for _, c in ipairs(TC.combo.ORDER) do
    local ok = true
    for _, p in ipairs(TC.combo.DEF[c]) do
      local n = #TC.combo.rows(p)
      if n < 1 or n > TC.combo.MAX then ok = false end
    end
    if ok then on[#on + 1] = c end
  end
  SetVar(GlobalVars(), "FS_combos", table.concat(on, ","))
  TC.combo.apply()
end
-- PAGES = the 8 pages + the combined pages the show has
function TC.combo.apply()
  for i = #PAGES, 1, -1 do if TC.combo.DEF[PAGES[i]] then table.remove(PAGES, i) end end
  for c in tostring(GetVar(GlobalVars(), "FS_combos") or ""):gmatch("%a+") do
    if TC.combo.DEF[c] then PAGES[#PAGES + 1] = c end
  end
end
function TC.combo.on(c) for _, p in ipairs(PAGES) do if p == c then return true end end return false end
-- the pages' build version: a show that gains or loses a combined page gets its pages rebuilt
function TC.combo.ver() return CFG.PAGES_VER .. "/" .. tostring(GetVar(GlobalVars(), "FS_combos") or "") end
-- Position FX page icons (PAN_FX / TILT_FX order; nil = text disc)
TC.MOVE_ICON = {pan = {"mv_out", "mv_left", "mv_right", "mv_wide"},
                tilt = {"mv_tswing", "mv_up", "mv_down", "mv_circle", "fly_in", "fly_out"}}
function TC.cap(gi, key)
  local g, attrs = TC.grp(tonumber(gi)), TC.CAP_ATTRS[key]  -- (Colour Fill rows too)
  if not g or not attrs then return true end
  local ck = g .. ":" .. key
  if TC.capCache[ck] == nil then
    local ov = TC.feat.get(g)[key]  -- set by hand on the Group Builder (Features)
    if ov ~= nil then TC.capCache[ck] = ov else TC.capCache[ck] = TC.feat.detect(g, key) end
  end
  return TC.capCache[ck]
end
-- group features: what the fixtures of group g have (TC.feat.detect), or what was set by hand
-- (Group Builder > Features) when the detection gets it wrong. Kept per group number in FS_feat_<g>
-- as "color=1,gobo1=0": 1 = on, 0 = off, a feature not listed = detected.
TC.feat = {KEYS = {{"dim", "Dimmer"}, {"color", "Colour"}, {"pos", "Position"}, {"gobo1", "Gobo 1"},
                   {"gobo2", "Gobo 2"}, {"prism", "Prism"}, {"iris", "Iris"}, {"zoom", "Zoom"}, {"shape", "Shapers"}}}
function TC.feat.detect(g, key)
  local attrs = TC.CAP_ATTRS[key]
  local ok, has = pcall(function()
    local idx = {}
    for _, a in ipairs(attrs) do local i = GetAttributeIndex(a) if i then idx[#idx + 1] = i end end
    if #idx == 0 then return false end
    Cmd("ClearSelection"); Cmd("Group " .. g)
    local fi, found = SelectionFirst(), false
    while fi and not found do
      for _, i in ipairs(idx) do if GetUIChannelIndex(fi, i) then found = true end end
      fi = SelectionNext(fi)
    end
    Cmd("ClearSelection")
    return found
  end)
  return (not ok) or has == true
end
function TC.feat.get(g)
  local t = {}
  for k, v in tostring(gv("feat_" .. g) or ""):gmatch("(%w+)=(%d)") do t[k] = (v == "1") end
  return t
end
function TC.feat.set(g, t)
  local l = {}
  for _, f in ipairs(TC.feat.KEYS) do
    if t[f[1]] ~= nil then l[#l + 1] = f[1] .. "=" .. (t[f[1]] and "1" or "0") end
  end
  sv("feat_" .. g, table.concat(l, ","))
  TC.capCache = {}
end
-- the Group Builder's Features button of group g: how many features are set by hand
function TC.feat.count(g) local n = 0 for _ in pairs(TC.feat.get(g)) do n = n + 1 end return n end
-- Features pop-up: per feature Auto (= what the fixtures have) / On / Off
function TC.feat.edit(g)
  if not obj("Group " .. g) then
    MessageBox({title = "FireSystem", message = "Store Group " .. g .. " first.", commands = {{value = 1, name = "OK"}}})
    return
  end
  local cur, sel = TC.feat.get(g), {}
  for i, f in ipairs(TC.feat.KEYS) do
    local auto = "Auto (" .. (TC.feat.detect(g, f[1]) and "has it" or "not found") .. ")"
    local v = cur[f[1]] == nil and 1 or (cur[f[1]] and 2 or 3)
    -- (MA sorts the selectors by name: the number keeps them in this order)
    sel[#sel + 1] = {name = i .. " " .. f[2], selectedValue = v, type = 1, values = {[auto] = 1, ["On"] = 2, ["Off"] = 3}}
  end
  local ok, r = pcall(MessageBox, {title = "Features of Group " .. g .. " " .. tostring(objName(obj("Group " .. g)) or ""),
    message = "Auto = what FireSystem found in the group's fixtures.\nOn / Off = use this instead, when it got it wrong.\n" ..
              "Off greys the group out on that feature's buttons. Combined pages follow on the next DONE.",
    commands = {{value = 1, name = "OK"}, {value = 2, name = "All Auto"}, {value = 0, name = "Cancel"}}, selectors = sel})
  if not ok or type(r) ~= "table" or not r.success or r.result == 0 then return end
  local t = {}
  if r.result == 1 and type(r.selectors) == "table" then
    for i, f in ipairs(TC.feat.KEYS) do
      local v = r.selectors[i .. " " .. f[2]]
      if v == 2 then t[f[1]] = true elseif v == 3 then t[f[1]] = false end
    end
  end
  TC.feat.set(g, t)
  dbg(string.format("Group %d features: %s", g, tostring(gv("feat_" .. g))))
end

-- page backgrounds: one choice per FireSystem page, and one for Home and the tool pages
-- (not in AP: setup walks every AP entry as an appearance number)
TC.bg = {}
TC.bg.EXTRA = {"home", "mast", "upd", "tc", "songs", "rec", "tced", "gobo", "ccol", "grp"}
function TC.bg.key(page)
  if page == "fader" then return page end
  if TC.combo.DEF[page] then return TC.combo.DEF[page][1] end  -- a combined page: its top page's background
  for _, p in ipairs(PAGES) do if p == page then return page end end
  return "extra"
end
function TC.bg.index(key)
  local v = GetVar(GlobalVars(), "FS_bg_" .. key)
  if v == nil then v = CFG.GV_DEFAULTS["bg_" .. key] end
  local i = tonumber(v or "")
  return (i and CFG.BACKGROUNDS[i]) and i or 1
end
-- the canvas appearance of a page's layout (Black unless a background is picked)
function TC.bg.ap(page)
  local i = TC.bg.index(TC.bg.key(page))
  local b = CFG.BACKGROUNDS[i]
  if i > 1 then
    local no, img = CFG.BG_AP_BASE + i - 1, b.image or (CFG.BG_IMAGE_BASE + i - 1)
    local im = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, img))
    if not im and b.file and importImage(img, b.file) then im = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, img)) end
    if im then
      local want, h = fs("bg " .. b[1]), obj("Appearance " .. no)
      if not h then
        C("Store Appearance %d", no)
        C("Label Appearance %d %s", no, q(want))
        setApColor(no, {0, 0, 0})
        h = obj("Appearance " .. no)
      elseif objName(h) ~= want then  -- relabel only: re-storing it would wipe the image
        dbg(string.format("bg: Appearance %d is %q, want %q", no, tostring(objName(h)), want))
        C("Label Appearance %d %s", no, q(want))
      end
      if h then
        local ok = pcall(function()
          h.Image = im
          h.ImageR, h.ImageG, h.ImageB, h.ImageAlpha = 255, 255, 255, 255
        end)
        pcall(function() h.ImageMode = "Stretch" end)
        if not ok then dbg(string.format("bg: could not set the image of Appearance %d", no)) end
        return h
      end
    end
    Echo(string.format("FireSystem: background %s has no image - %s", b[1],
      b.file and ("copy " .. b.file .. " into media/images") or string.format("store one into Image %d.%d", CFG.IMAGE_POOL, img)))
  end
  return obj("Appearance " .. (CFG.APPEARANCE_BASE + 99))
end
-- a page's layout gets its background. MA stretches the canvas image over the layout's box:
-- PositionX/Y is the box's centre (0,0 1920 x 1080 by default), in the same units and direction as
-- the buttons' PosX/Y (checked on onPC 2.4; 'global bgy' flips Y). The box is fitted
-- around the buttons and widened to the screen's shape, so the picture fills the view.
function TC.bg.set(page)
  local L = layoutNo(page)
  local lh = obj("Layout " .. L)
  if not lh then return end
  pcall(function() lh.CanvasAppearance = TC.bg.ap(page) end)
  local x, y, w, h
  pcall(function()
    x, y = tonumber(lh:Get("UsedX")), tonumber(lh:Get("UsedY"))
    w, h = tonumber(lh:Get("UsedW")), tonumber(lh:Get("UsedH"))
  end)
  -- MA hands UsedX/Y back unsigned (-4 reads 65532), like the elements' PosX/Y
  if x and x > 32767 then x = x - 65536 end
  if y and y > 32767 then y = y - 65536 end
  if not (x and y and w and h and w > 0 and h > 0) then
    dbg(string.format("bg: layout %d has no used area (%s %s %s %s)", L, tostring(x), tostring(y), tostring(w), tostring(h)))
    return
  end
  local aspect = 16 / 9
  pcall(function() aspect = TC.bg.aspect() end)  -- (FIT comes later in the file)
  local bh = h * 1.06
  local bw = math.max(w * 1.06, bh * math.max(aspect, 2.4))  -- (the view is wider than the screen's shape)
  local sign = (gv("bg_yinv") == "1") and -1 or 1
  C('Set Layout %d Property "PositionX" %d "PositionY" %d "DimensionW" %d "DimensionH" %d',
    L, math.floor(x + w / 2 + 0.5), math.floor(sign * (y + h / 2) + 0.5), math.floor(bw + 0.5), math.floor(bh + 0.5))
end
-- the fader bank: executor pages 1-BG_PAGES get the background with their page number
function TC.bg.faders()
  local i = TC.bg.index("fader")
  local b = CFG.BACKGROUNDS[i]
  if gv("bg_pg_ver") ~= CFG.BG_PAGE_VER then  -- new numbered images: drop the old imports
    for k, bk in ipairs(CFG.BACKGROUNDS) do
      for p = 1, (k == 1 or bk.file) and CFG.BG_PAGES or 0 do
        local no = CFG.BG_PAGE_IMAGE_BASE + (k - 1) * 10 + p - 1
        if obj(string.format("Image %d.%d", CFG.IMAGE_POOL, no)) then C("Delete Image %d.%d /NC", CFG.IMAGE_POOL, no) end
      end
    end
    sv("bg_pg_ver", CFG.BG_PAGE_VER)
  end
  for p = 1, CFG.BG_PAGES do
    local ph = obj("Page " .. p)
    if ph then
      local h
      if b.file or i == 1 then  -- one of ours: the numbered version
        local name = (i == 1) and "black" or b.file:match("^fs_bg_(.-)%.png$")
        local img, no = CFG.BG_PAGE_IMAGE_BASE + (i - 1) * 10 + p - 1, CFG.BG_PAGE_AP_BASE + (i - 1) * 10 + p - 1
        if importImage(img, string.format("fs_pg_%s_%d.png", name, p)) then
          local want = fs(string.format("page %d %s", p, b[1]))
          if not obj("Appearance " .. no) then
            C("Store Appearance %d", no)
            setApColor(no, {0, 0, 0})
          end
          if objName(obj("Appearance " .. no)) ~= want then C("Label Appearance %d %s", no, q(want)) end
          h = obj("Appearance " .. no)
          local im = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, img))
          pcall(function() h.Image = im h.ImageMode = "Stretch" end)
        else
          Echo(string.format("FireSystem: copy fs_pg_%s_%d.png into media/images", name, p))
        end
      else  -- your own image (no number)
        h = TC.bg.ap("fader")
      end
      if h then
        local ok = pcall(function() ph.Appearance = h end)
        pcall(function() ok = ph.Appearance ~= nil end)
        if not ok then Cany({ string.format("Assign Appearance %d At Page %d", tonumber(h.No) or 0, p) }) end
      end
    end
  end
end
-- sets the background on every built layout that uses it, and on the fader bank
function TC.bg.apply()
  local all = {}
  for _, p in ipairs(PAGES) do all[#all + 1] = p end
  for _, p in ipairs(TC.bg.EXTRA) do all[#all + 1] = p end
  for _, p in ipairs(all) do TC.bg.set(p) end
  TC.bg.faders()
end

TC.SOURCES = { {"internal", "Internal"}, {"ltc", "LTC"}, {"midi", "MIDI"}, {"artnet", "Art-Net"} }
TC.MODES = { {"record", "Record Presses"}, {"timeline", "Timeline Cues"}, {"blend", "Blend"} }
function TC.song() return math.max(1, math.min(CFG.TC_SONGS, tonumber(gv("tc_song") or "") or 1)) end
function TC.no(i) return CFG.TC_BASE + (i or TC.song()) - 1 end
function TC.obj(i) local h pcall(function() h = DataPool().Timecodes[TC.no(i)] end) return h end
function TC.name(i)
  local h = TC.obj(i)
  return h and tostring(h.name):gsub("^" .. CFG.PREFIX .. " ", "") or nil
end
function TC.source() return gv("tc_source") or "internal" end
function TC.mode() return gv("tc_mode") or "blend" end
function TC.recording(i)
  local h, r = TC.obj(i), false
  if h then pcall(function() r = h.ISRECORDING(h) == true end) end
  return r
end
function TC.label(list, key) for _, x in ipairs(list) do if x[1] == key then return x[2] end end return key end
-- the timecode transport row on every page (switched on / off on the Timecode page)
function TC.barOn() return gv("tc_bar") ~= "0" end
TC.BAR_SKIP = {tc = true, tced = true, grp = true}  -- the Timecode pages have their own transport; the Group Builder is setup

-- ---- Update Presets page ---------------------------------------------------
TC.upd = {CATS = { {"color", "Color"}, {"pan", "Pan"}, {"tilt", "Tilt"}, {"zoom", "Zoom"}, {"beam", "Gobo Beam"},
                   {"strobe", "Strobe"}, {"meas", "Measure"} }}
-- the presets a category of the Update Presets page shows: {label, pool, no, colour index}
function TC.upd.list(cat)
  local l = {}
  if cat == "color" then
    for ci = 1, NALLCOL do l[#l + 1] = {colorName(ci), 4, colorPreset(ci), ci} end
  elseif cat == "pan" or cat == "tilt" then
    for i, p in ipairs(cat == "pan" and PANS or TILTS) do
      l[#l + 1] = {p[2] or ("User " .. p[1]), 2, p[4], nil, p[2] and ((cat == "pan" and "pan" or "tilt") .. i) or nil}
    end
  elseif cat == "zoom" then
    for i, z in ipairs({"Zoom Narrow", "Zoom Mid", "Zoom Wide", "Zoom Full"}) do l[#l + 1] = {z, 6, 200 + i} end
  elseif cat == "beam" then
    -- the Gobo / Prism / Zoom page's presets (zoom has its own tab): a row per item
    for _, b in ipairs(CFG.BEAM) do
      if b.key ~= "zoom" then
        for i, no in ipairs(b.presets) do l[#l + 1] = {presetName(b.pool, no) or (b.label .. " " .. i), b.pool, no} end
        while #l % 10 > 0 do l[#l + 1] = {skip = true} end
      end
    end
  elseif cat == "strobe" then
    -- a row per kind: G1-G8, then the shared ones (Strobe All uses the shared Strobe)
    for r, k in ipairs(STROBES.grp) do
      for gi = 1, 8 do
        if CFG.GROUPS[gi] then l[#l + 1] = {k[2] .. " " .. gi, STROBES.pool, STROBES.no(k[1], gi)}
        else l[#l + 1] = {skip = true} end
      end
      local f = STROBES[({1, 3})[r]]
      if f then l[#l + 1] = {f[1], STROBES.pool, f[2]} else l[#l + 1] = {skip = true} end
      if r == 1 then l[#l + 1] = {STROBES[2][1], STROBES.pool, STROBES[2][2]} else l[#l + 1] = {skip = true} end
    end
  end
  return l
end
function TC.upd.cat() return gv("upd_cat") or "color" end

-- slot 1 = G#_Bump keys, 2 = G#_Rnd Strobe knobs, 3 = G#_Strobe knobs. Look fields are
-- <field><step> (0 = off), e.g. dim1 = 3 is Full on step 1. The strobes are Flash keys at Full.
function BM.bumpDefault(slot)
  local t = {steps = 1, fade = 0, fout = 0, off = 0.5, delay = 0, wings = 0}
  for k = 1, BM.MAX do
    for _, f in ipairs(BM.LOOK) do t[f[1] .. k] = 0 end
    t["col" .. k] = 0
  end
  t.dim1 = 3
  if slot == 3 then t.shut1 = 2 t.flash = true end
  if slot == 2 then t.shut1 = 3 t.flash = true end
  return t
end
-- executor key of a bump: Go+ (every press plays the next look, which switches itself off),
-- or Flash (the look is on while the key is held: Flash on the Bump page)
function BM.key(b, slot) return (b and (b.flash == true or b.flash == "true")) and "Flash" or "Go+" end
function BM.isFlash(b) return BM.key(b) == "Flash" end
-- a cue's timing and command live in its Part 0 (the cue itself only owns the trigger), so they
-- are set there directly
function BM.partProp(sq, cue, name, v)
  return Cany({ string.format('Set Sequence %d Cue %s Part 0 Property "%s" %s', sq, cue, name, v),
                string.format('Set Sequence %d Cue %s Property "%s" %s', sq, cue, name, v) })
end
-- deletes every cue of a sequence (but not the sequence)
function BM.clearCues(seq)
  for _, c in ipairs((obj("Sequence " .. seq) or {Children = function() return {} end}):Children()) do
    local no = tonumber(c.no)
    if no and no > 0 then Cmd(string.format("Delete Sequence %d Cue %s /NC", seq, tostring(no / 1000))) end
  end
end
-- step k of bump slot / group gi has its own sequence: 401+ (30 per slot, 3 per group)
function BM.stepSeq(slot, gi, k) return CFG.BUMP_STEP_BASE + (slot - 1) * 30 + (gi - 1) * 3 + (k - 1) end
function getBump(gi, slot)
  local key = "bm_" .. gi .. "_" .. slot
  -- once: slot 2 was the old G#_Full bump (now Rnd Strobe), and the strobe knobs become
  -- Flash keys at Full with Strobe
  if (slot == 2 or slot == 3) and gv("bmv_" .. gi .. "_" .. slot) ~= "2" then
    local t = (slot == 3) and loadTable(key, BM.bumpDefault(slot)) or BM.bumpDefault(slot)
    if slot == 3 then t.flash, t.steps, t.dim1, t.shut1 = true, 1, 3, 2 end
    sv(key, ser(t))
    sv("bmv_" .. gi .. "_" .. slot, "2")
  end
  local t = loadTable(key, BM.bumpDefault(slot))
  -- older settings: sel<step> (All / Odd / Even / Left / Right) and mxb/mxg/mxw/mxp<step>
  -- (button numbers) -> mb/mg/mw/mp<step> (values)
  for k = 1, BM.MAX do
    local old, ob = tonumber(t["sel" .. k]), tonumber(t["mxb" .. k])
    if t["mg" .. k] == nil and old then
      local pr = BM.MXP[old] or BM.MXP[1]
      t["mb" .. k], t["mg" .. k], t["mw" .. k], t["mp" .. k] = pr[3], pr[4], pr[5], pr[6]
    elseif t["mg" .. k] == nil and ob then
      local og, ow = tonumber(t["mxg" .. k]) or 1, tonumber(t["mxw" .. k]) or 1
      t["mb" .. k] = (ob == 5) and 0 or ob
      t["mg" .. k] = (og <= 1) and 0 or og
      t["mw" .. k] = (ow == 2) and 2 or 0
      t["mp" .. k] = tonumber(t["mxp" .. k]) or 1
    end
    for _, f in ipairs({"sel", "mxb", "mxg", "mxw", "mxp"}) do t[f .. k] = nil end
  end
  return t
end
function setBump(gi, slot, t) sv("bm_" .. gi .. "_" .. slot, ser(t)) end
-- LOS (as the MA start show's Live Output System): the groups a bump key fires on, as group
-- indexes ("1,3" in b.grps). Empty / unset = the key's own group, as before.
function BM.grps(b, gi)
  local t, seen = {}, {}
  for d in tostring(b and b.grps or ""):gmatch("%d+") do
    local n = tonumber(d)  -- (MA's Lua won't let a for loop's variable be assigned)
    if CFG.GROUPS[n] and not seen[n] then seen[n] = true t[#t + 1] = n end
  end
  if #t == 0 then t = {gi} end
  table.sort(t)
  return t
end
-- a LOS over several groups: Delay (+ Wings) runs over all their fixtures as one row (the groups
-- side by side in group order), so Wings 2 on a left and a right group goes outside -> in. Each
-- group's recipe line gets its own Delay From / To out of that row: s / e = the line's first and
-- last fixture in the row, T = fixtures in the row, D = Delay, w = Delay Wings.
function BM.spreadDelay(props, s, e, T, D, w, partWings)
  local function f(i)
    if T <= 1 then return 0 end
    if (w or 0) < 2 then return i / (T - 1) end
    local W = T / w
    local j = math.min(w - 1, math.floor(i / W))
    local loc = i - j * W
    if j % 2 == 1 then loc = W - 1 - loc end
    return W > 1 and math.max(0, math.min(1, loc / (W - 1))) or 0
  end
  local function r(v) return math.floor(v * D * 1000 + 0.5) / 1000 end
  -- does the group sit inside one wing (its delay then runs straight from s to e)?
  local inOne = (w or 0) < 2 or math.min(w - 1, math.floor(s / (T / w))) == math.min(w - 1, math.floor(e / (T / w)))
  local p = {}
  for _, x in ipairs(props) do
    local drop = x[1] == "DelayFromX" or x[1] == "DelayToX" or (x[1] == "XWings" and not partWings)
    if not drop then p[#p + 1] = x end
  end
  if inOne then
    p[#p + 1] = {"DelayFromX", r(f(s))}
    p[#p + 1] = {"DelayToX", r(f(e))}
  else
    -- (a group across the middle: its own two wings, from its edge to the latest delay in it)
    local hi = 0
    for i = s, e do hi = math.max(hi, f(i)) end
    if not partWings then p[#p + 1] = {"XWings", 2} end
    p[#p + 1] = {"DelayFromX", r(math.min(f(s), f(e)))}
    p[#p + 1] = {"DelayToX", r(hi)}
  end
  return p
end
-- which bumps the panel edits, its included groups and the step being edited
function BM.bumpTarget() local t = tonumber(gv("bm_target") or "") return (t == 2 or t == 3) and t or 1 end
function BM.bumpIncluded(slot)
  local v, t = gv("bm_inc_" .. slot), {}
  if v == nil then return {1} end
  for n in tostring(v):gmatch("%d+") do t[#t + 1] = tonumber(n) end
  return {t[1] or 1}  -- one group at a time (older shows may have saved several)
end
function BM.bumpEditStep(slot) return math.max(1, math.min(BM.MAX, tonumber(gv("bm_step_" .. slot) or "") or 1)) end
function getXk(gi) return loadTable("xk_" .. gi, {pattern = 8, zoom = false, col = "none", single = false}) end
function setXk(gi, t) sv("xk_" .. gi, ser(t)) end

-- selection = list of group indexes (1..#GROUPS) per page (the G buttons)
function getSel(page)
  local s, out = gv("sel_" .. page), {}
  if type(s) == "string" then for n in s:gmatch("%d+") do out[#out + 1] = tonumber(n) end end
  return out
end
function setSel(page, list)
  local t = {}
  for _, n in ipairs(list) do t[#t + 1] = tostring(n) end
  sv("sel_" .. page, table.concat(t, ","))
end
function isSel(page, gi)
  for _, n in ipairs(getSel(page)) do if n == gi then return true end end
  return false
end

-- ======================================================================
-- MAtricks: state -> scratch MAtricks object
-- ======================================================================
function matricksProps(page, st)
  local p = {}
  local function add(k, v) p[#p + 1] = {k, v} end
  local sym = false
  local fan = st.form and ((page == "dim" and DIM_FORMS[st.form] and DIM_FORMS[st.form][3] == "fan")
                        or (page == "cfx" and CFX_FORMS[st.form] and CFX_FORMS[st.form][2] == "fan"))
  for _, A in ipairs(FN.AXES) do
    local function g(f) return st[axKey(A, f)] end
    if (g("shift") or 0) > 0 then add(A .. "Shift", g("shift")) end
    if (g("blk") or 0) > 0 then add(A .. "Block", g("blk")) end
    if (g("grp") or 0) > 0 then add(A .. "Group", g("grp")) end
    -- Sym: mirrored around the centre (2 wings) unless more wings are picked; the
    -- PhaserTransform below also mirrors the pan, so the wings move in opposite directions
    local wings = g("wings") or 0
    if g("sym") then
      sym = true
      if wings < 2 then wings = 2 end
    end
    if wings > 0 then add(A .. "Wings", wings) end
    if (g("width") or 0) > 0 then add(A .. "Width", g("width")) end
    if g("shuf") then add(A .. "Shuffle", 1) end
    local function range(name, from, to, rev)
      if rev then from, to = to, from end
      add(name .. "From" .. A, from); add(name .. "To" .. A, to)
    end
    local phase, speed = g("phase") or 0, SPEEDS[page] and SPEEDS[page][g("speed") or 0]
    if (g("bpm") or 0) > 0 then speed = {g("bpm"), g("bpm")} end  -- typed with Edit
    if not speed and page == "pfx" and A == "X" and CFG.PFX_BPM then speed = {CFG.PFX_BPM, CFG.PFX_BPM} end
    if fan and A == "X" then phase, speed = 360, {0, 0} end  -- the fan: phaser spread over the group, frozen
    -- Rate multiplies the X, Y and Z speed (2 ^ rate); without a speed it scales the speed master instead
    local mul = 2 ^ (tonumber(st.rate) or 0)
    if speed and mul ~= 1 and BM.RATES_ON[page] then
      local function r(v) return math.floor(v * mul * 100 + 0.5) / 100 end
      speed = {r(speed[1]), r(speed[2])}
    end
    if phase > 0 then range("Phase", 0, phase, g("rev")) end
    if speed then range("Speed", speed[1], speed[2], false) end
    -- fade spreads across X from 0 by default (a wave); "Same" = every fixture the same fade
    if (g("fade") or 0) > 0 then range("Fade", g("spread") and g("fade") or 0, g("fade"), g("frev")) end
    if (g("delay") or 0) > 0 then range("Delay", 0, g("delay"), g("drev")) end
  end
  -- Transform Mirror inverts the pan of the mirrored wings (MA sets XInvW / InvertStyle Pan
  -- itself); it acts on the wings already set, so it comes last
  if sym then add("PhaserTransform", "Mirror") end
  return p
end

-- Leaves the given group selected with the MAtricks applied.
function presetExists(pool, no) return obj(string.format("Preset %d.%d", pool, no)) ~= nil end

function usePreset(pool, no, what)
  if presetExists(pool, no) then return string.format("At Preset %d.%d", pool, no) end
  Echo(string.format("FireSystem: %s is empty - store it into Preset %d.%d", what, pool, no))
  return nil
end

end

-- ==== FireSystemFire.lua (copied by tools/make_tools.py) ====
MODS.Fire = function(_ENV)

-- ======================================================================
-- FIRE
-- ======================================================================
CONTENT = {}

CONTENT.dim = function(st)
  if (st.form or 0) == 0 then return nil end
  return { string.format("At Preset 1.%d", dimPreset(st.form)) }
end

CONTENT.col = function(st)
  local out = {}
  local function line(ci, t, half)
    ci, t = tonumber(ci) or 0, tonumber(t) or 0
    if ci == 0 then return end
    if t > 0 and not presetExists(4, tintPreset(ci, t)) then t = 0 end  -- e.g. a COLOR n not made yet
    local l = usePreset(4, tintPreset(ci, t), colorName(ci))
    if l then out[#out + 1] = l .. (half and (" Half " .. half) or "") end
  end
  if (tonumber(st.split) or 0) > 0 then line(st.color, st.tint, 1) line(st.color2, st.tint2, 2)
  else line(st.color, st.tint) end
  return #out > 0 and out or nil
end

-- Color page halves: a group's colour can be split into its odd / even or left / right fixtures,
-- each half with its own colour and Pastel / Dark (st.split 1 = odd / even, 2 = left / right; the
-- first half is st.color / st.tint, the second st.color2 / st.tint2). The header's All / Odd / Even /
-- Left / Right buttons pick the half a colour press sets (All = the whole group one colour again).
TC.part = {LIST = { {"all", "All"}, {"odd", "Odd"}, {"even", "Even"}, {"left", "Left"}, {"right", "Right"} },
           KIND = {odd = 1, even = 1, left = 2, right = 2}, SIDE = {odd = 1, even = 2, left = 1, right = 2}}
function TC.part.cur() local p = gv("col_part") return TC.part.KIND[p] and p or "all" end
-- the field the current half shows (nil = both: All on a split group)
function TC.part.field(st, field)
  local p, sp = TC.part.cur(), tonumber(st.split) or 0
  if p == "all" and sp > 0 then return nil end
  if sp == 0 or TC.part.KIND[p] ~= sp then return field end
  return TC.part.SIDE[p] == 2 and (field .. "2") or field
end
function TC.part.lit(st, field, val)
  local f = TC.part.field(st, field)
  if f then return st[f] == val end
  return st[field] == val or st[field .. "2"] == val
end
function TC.part.tint(st) return tonumber(st[TC.part.field(st, "tint") or "tint"]) or 0 end  -- shown on the swatches
-- before a press on a row: starts (both halves keep the group's colour) or ends the split;
-- returns the field the press sets
function TC.part.prep(st, field)
  local p, sp = TC.part.cur(), tonumber(st.split) or 0
  local kind = TC.part.KIND[p]
  if not kind then
    if sp > 0 and field == "color" then st.split, st.color, st.color2 = 0, 0, 0 end
    return field
  end
  if sp ~= kind then st.split, st.color2, st.tint2 = kind, st.color, st.tint end
  return TC.part.SIDE[p] == 2 and (field .. "2") or field
end
-- a half's recipe MAtricks: the look's Fade / Delay / Shuffle, Group 2 (odd / even) or Block =
-- half the group's columns (left / right) and X = the half, as the bumps' parts. No Wings or Sym:
-- they would mirror the halves.
function TC.part.mx(g, st, side)
  local p = {}
  for _, x in ipairs(matricksProps("col", st)) do
    if x[1] ~= "XWings" and x[1] ~= "PhaserTransform" then p[#p + 1] = x end
  end
  if tonumber(st.split) == 2 then
    BM.part(g, {b = 1, g = 1, w = 0, p = 1})  -- fills BM.units[g] (the group's grid)
    local cols, n = {}, 0
    for _, u in ipairs(BM.units[g] or {}) do if not cols[u.x] then cols[u.x] = true n = n + 1 end end
    p[#p + 1] = {"XBlock", math.max(1, math.ceil(n / 2))}
  end
  p[#p + 1] = {"XGroup", 2}
  p[#p + 1] = {"X", side}
  return p
end

-- Color FX: the colours of the effect's steps (COLOR, BACK GROUND, then STEP 3-5 as added with the arrows)
TC.CFX_MAX = 5
function TC.cfxCols(st)
  local n, cols = math.max(2, math.min(TC.CFX_MAX, math.floor(tonumber(st.n) or 2))), {}
  for k = 1, n do cols[k] = tonumber(st["c" .. k]) or LOOK_DEFAULTS.cfx["c" .. k] end
  return cols
end
-- step k's preset: colour ci in the step's Pastel / Dark version (the plain colour while that isn't made)
function TC.cfxPreset(st, k, ci)
  local t = tonumber(st["t" .. k]) or 0
  if t > 0 and not presetExists(4, tintPreset(ci, t)) then t = 0 end
  return tintPreset(ci, t)
end

CONTENT.cfx = function(st)
  if (st.form or 0) == 0 then return nil end
  local c = {}
  for k, ci in ipairs(TC.cfxCols(st)) do
    local no = TC.cfxPreset(st, k, ci)
    if not usePreset(4, no, colorName(ci)) then return nil end
    c[#c + 1] = string.format("At Preset 4.%d", no)
  end
  return c
end

CONTENT.pos = function(st)
  local c = {}
  if st.pan > 0 then c[#c + 1] = usePreset(2, PANS[st.pan][4], "Pan " .. PANS[st.pan][1]) end
  if st.tilt > 0 then c[#c + 1] = usePreset(2, TILTS[st.tilt][4], "Tilt " .. TILTS[st.tilt][1]) end
  if #c == 0 then return nil end
  return c
end

CONTENT.pfx = function(st)
  local c = {}
  if st.panfx > 0 and st.tiltfx ~= 4 then c[#c + 1] = usePreset(2, panFxPreset(st.panfx, st.size), "Pan FX " .. PAN_FX[st.panfx][1]) end
  if st.tiltfx > 0 then
    local no, pool = tiltFxPreset(st.tiltfx, st.size)
    c[#c + 1] = usePreset(pool, no, "Tilt FX")
  end
  if #c == 0 then return nil end
  return c
end

CONTENT.beam = function(st)
  local c = {}
  if st.zoomfx and presetExists(6, CFG.ZOOM_FX_PRESET) then c[#c + 1] = "At Preset 6." .. CFG.ZOOM_FX_PRESET end
  for _, b in ipairs(CFG.BEAM) do
    local idx = st[b.key] or 0
    if idx > 0 and tonumber(st[b.key .. "p"]) then
      -- the group's own preset: a gobo picked on the Gobo Picker (pool 3) or a prism slot (pool 5)
      c[#c + 1] = string.format("At Preset %d.%d", b.key == "prism" and 5 or 3, tonumber(st[b.key .. "p"]))
    elseif idx > 0 and b.presets[idx] then
      c[#c + 1] = string.format("At Preset %d.%d", b.pool, b.presets[idx])
    end
    local rv = tonumber(st[b.key .. "rot"]) or 0
    local rp = CFG.ROT_POOL[b.key] or {5, 0}
    if rv > 0 and (tonumber(st[b.key .. "rotp"]) or 0) >= rp[2] then
      c[#c + 1] = string.format("At Preset %d.%d", rp[1], tonumber(st[b.key .. "rotp"]))
    end
  end
  if #c == 0 then return nil end
  return c
end

-- MAtricks phase only counts for values typed on the Phase layer, so after the
-- look is in the programmer spread it explicitly: At Phase 0 Thru <phase>
-- (MAtricks block/group/wings decide how the spread falls over the fixtures)
-- ======================================================================
-- Recipes: Sequence <seq> Cue 1 Part 0.k = one recipe line per preset
-- ======================================================================
-- Color and Position alternate between Cue 1 and Cue 2: FIRE writes the new look into the
-- cue that isn't playing and goes to it, so MA fades into it with the recipe's MAtricks
-- Fade / Delay / Wings (a change to the playing cue would jump straight to the new values).
-- TC.cue[seq] = the cue the recipe calls work on (1 when not set)
TC.cue = {}
function rAddr(seq, k, sub) return string.format("Sequence %d Cue %d Part 0.%d%s", seq, TC.cue[seq] or 1, k, sub or "") end
function TC.playingCue(seq)
  local c
  pcall(function()
    local sh = DataPool().Sequences[seq]
    if sh:HasActivePlayback() then c = sh:CurrentChild() c = c and tonumber(c.no) and tonumber(c.no) / 1000 end
  end)
  return c
end

-- first recipe fire of a sequence: replace the old stored cue by an empty one
function ensureRecipeCue(seq)
  -- (checks for a recipe line, not just the flag: setup recreates the sequences)
  local cue = TC.cue[seq] or 1
  local flag = "rcp_" .. seq .. (cue == 1 and "" or ("_" .. cue))
  if gv(flag) == "1" and obj(rAddr(seq, 1)) then return end
  C("ClearAll")
  if cue == 1 and obj("Sequence " .. seq .. " Cue 1") then C("Delete Sequence %d Cue 1 /NC", seq) end
  if not obj(string.format("Sequence %d Cue %d", seq, cue)) then C("Store Sequence %d Cue %d /Overwrite", seq, cue) end
  -- no cue fade of its own: the recipe's MAtricks Fade / Delay do the timing
  BM.partProp(seq, cue, "CueInFade", "0")
  sv("cf_" .. seq .. "_" .. cue, "0")  -- (FX Fade: the cue's fade is 0 again)
  sv(flag, "1")
end

-- every MAtricks property in one Set: wanted values, "None" for the rest
-- (no Reset, so a running effect never drops its spread for a moment)
MX_PROPS = {}
for _, A in ipairs(FN.AXES) do
  for _, f in ipairs({"Shift", "Block", "Group", "Wings", "Width", "Shuffle"}) do MX_PROPS[#MX_PROPS + 1] = A .. f end
  for _, f in ipairs({"Phase", "Speed", "Fade", "Delay"}) do
    MX_PROPS[#MX_PROPS + 1] = f .. "From" .. A; MX_PROPS[#MX_PROPS + 1] = f .. "To" .. A
  end
end
for _, A in ipairs(FN.AXES) do MX_PROPS[#MX_PROPS + 1] = A end  -- which part of the groups lights (bumps)
MX_PROPS[#MX_PROPS + 1] = "PhaserTransform"  -- last: it mirrors the wings set before it
-- true when the recipe already holds this value ("None" = not set)
function sameVal(cur, want)
  if want == "None" then return cur == nil or tostring(cur) == "None" end
  local a, b = tonumber(cur), tonumber(want)
  if a and b then return math.abs(a - b) < 0.01 end
  return tostring(cur) == want
end
function recipeMatricks(addr, page, st, h, props)
  local want = {}
  for _, pr in ipairs(props or matricksProps(page, st)) do want[pr[1]] = tostring(pr[2]) end
  local parts = {}
  for _, k in ipairs(MX_PROPS) do
    local w, cur = want[k] or "None", nil
    if h then pcall(function() cur = h[k] end) end
    -- Mirror is sent again after any other change, so it follows new wings
    local again = k == "PhaserTransform" and w ~= "None" and #parts > 0
    if again or not (h and sameVal(cur, w)) then parts[#parts + 1] = q(k) .. " " .. q(w) end
  end
  -- only what changed: re-sending identical values makes MA recalculate the running phaser
  if #parts > 0 then C("Set %s Property %s", addr, table.concat(parts, " ")) end
end
function recipeIs(h, field, addr)  -- does the recipe already point at this object?
  local ok, same = pcall(function()
    local o = h[field]
    return o ~= nil and o:ToAddr() == ObjectList(addr)[1]:ToAddr()
  end)
  return ok and same
end
function setEnabled(addr, h)
  local on = false
  if h then pcall(function() on = h.Enabled == true end) end
  if not on then C('Set %s Property "Enabled" "Yes"', addr) end
end

-- Color FX steps: {color preset no, hard}, one step per colour (2-5)
function FN.cfxSteps(shape, cols)  -- cols = the steps' colour presets
  local s, n = {}, #cols
  for k, no in ipairs(cols) do
    -- Ramp Dn: snaps to the first colour, fades through the rest; Ramp Up: fades, snaps on the last
    local hard = (shape == "square" or shape == "heart") or (shape == "down" and k == 1) or (shape == "up" and k == n)
    s[k] = {no, hard}
  end
  -- Heart: the first colour is a short flash over the others (at least 4 steps)
  if shape == "heart" then while #s < 4 do s[#s + 1] = {s[#s][1], true} end end
  return s  -- sine, fan: every step fades
end

function FN.playIfIdle(seq)
  local active, onSnap = false, false
  pcall(function()
    local sh = DataPool().Sequences[seq]
    active = sh:HasActivePlayback()
    -- a timecode replay left it on a recorded snapshot cue: back to the live cue 1
    local c = active and sh:CurrentChild()
    onSnap = c and tonumber(c.no) and tonumber(c.no) >= CFG.TC_SNAP_BASE * 1000
  end)
  if not active or onSnap then
    Cany({ string.format("Goto Sequence %d Cue 1", seq), string.format("Go+ Sequence %d", seq) })
  end
end

-- a recorded press: copy the live cue 1 to the next snapshot cue and play that one
-- (the group's state goes with it: its look and MAtricks show in the Timecode Editor, and
-- the look can be edited there with the page's own buttons)
function TC.snapshot(seq, page, st)
  local k = math.max(CFG.TC_SNAP_BASE, tonumber(gv("snap_" .. seq) or "") or CFG.TC_SNAP_BASE)
  sv("snap_" .. seq, tostring(k + 1))
  C("Copy Sequence %d Cue %d At Sequence %d Cue %d /NC", seq, TC.cue[seq] or 1, seq, k)
  C("Label Sequence %d Cue %d %s", seq, k, q(fs("TC " .. (TC.name() or ("Song " .. TC.song())) .. TC.rec.snap(seq, k, page, st))))
  C("Goto Sequence %d Cue %d", seq, k)
end

-- Rate: speed scale of the group's cue (the cue that plays the look)
function TC.applyRate(page, seq, st, cue)
  if not BM.RATES_ON[page] then return end
  local names = {[-8] = "Div256", [-7] = "Div128", [-6] = "Div64", [-5] = "Div32", [-4] = "Div16", [-3] = "Div8",
                 [-2] = "Div4", [-1] = "Div2", [0] = "One", [1] = "Mul2", [2] = "Mul4", [3] = "Mul8", [4] = "Mul16",
                 [5] = "Mul32", [6] = "Mul64", [7] = "Mul128", [8] = "Mul256"}
  local want, cur = math.floor(tonumber(st.rate) or 0), nil
  -- a group with its own X / Y / Z speed gets the rate in that speed (matricksProps), not here
  for _, ax in ipairs(FN.AXES) do
    local k = FN.AXIS_PRE[ax]
    if (tonumber(st[k .. "speed"]) or 0) > 0 or (tonumber(st[k .. "bpm"]) or 0) > 0
       or (page == "pfx" and ax == "X" and CFG.PFX_BPM) then want = 0 end
  end
  local part = string.format("Sequence %d Cue %d Part 0", seq, cue or 1)
  pcall(function() cur = tonumber(obj(part).SPEEDSCALE) end)
  if cur ~= want and names[want] then C('Set %s Property "SpeedScale" "%s"', part, names[want]) end
end

-- FX Fade (Dimmer FX, Color FX, Position FX): seconds a FIRE fades from the running effect into
-- the new one (0 = off: changes go straight into the running effect, which keeps running)
TC.FX_FADE = {dim = true, cfx = true, pfx = true}
function TC.fxFade(page)
  if not TC.FX_FADE[page] then return 0 end
  return math.max(0, tonumber(gv("fxfade_" .. page) or "") or 0)
end
-- the cue fade of an FX page's cue (remembered, so it's only sent when it changes)
function TC.cueFade(seq, cue, t)
  local key = "cf_" .. seq .. "_" .. cue
  if tonumber(gv(key) or "") == t then return end
  if BM.partProp(seq, cue, "CueInFade", tostring(t)) then sv(key, tostring(t)) end
end

-- one StandardRecipe line per preset ("1.212") in the sequence's cue TC.cue[seq]: group g,
-- the preset and the look's MAtricks (only what changed is sent)
function TC.recipeParts(seq, g, presets, page, st)
  for k, p in ipairs(presets) do
    local g, props = g, nil
    if type(p) == "table" then g, props, p = p[1], p[3], p[2] end  -- {group, preset[, MAtricks]}
    local a = rAddr(seq, k)
    local h = obj(a)
    local cls
    if h then pcall(function() cls = h:GetClass() end) end
    if h and cls ~= "StandardRecipe" then C("Delete %s /NC", a) h = nil end
    if not h then C('Store Type "StandardRecipe" %s', a) h = obj(a) end
    if not recipeIs(h, "Selection", "Group " .. g) then C("Assign Group %d At %s", g, a) end
    if not recipeIs(h, "Values", "Preset " .. p) then C("Assign Preset %s At %s", p, a) end
    recipeMatricks(a, page, st, h, props)
    setEnabled(a, h)
  end
end
-- lines from n on are left over from an earlier look: switched off
function TC.recipeOff(seq, n, upto)
  for k = n, upto or 8 do
    local h, on = obj(rAddr(seq, k)), false
    if h then pcall(function() on = h.Enabled == true end) end
    if on then C('Set %s Property "Enabled" "No"', rAddr(seq, k)) end
  end
end

-- a plain on / off look as cue 1 of seq: {{group, "pool.no"}, ...}, no MAtricks
function TC.recipeCue(seq, lines)
  C("ClearAll")
  TC.cue[seq] = 1
  ensureRecipeCue(seq)
  TC.recipeParts(seq, lines[1][1], lines, "bump", copy(MX_DEFAULT))
  TC.recipeOff(seq, #lines + 1, 64)
  TC.cue[seq] = nil
end

-- returns false when the look can't be expressed as recipes (old method then)
-- quiet: only store the look into cue 1 (the sequence isn't started; its fader starts it)
function fireRecipe(page, gi, st, quiet)
  local seq, g = seqNo(page, gi), TC.grp(gi)
  local n0 = nCmds
  local static = (page == "col" or page == "pos")
  -- Color / Position, and FX pages with an FX Fade: the new look goes into the cue that isn't
  -- playing and MA fades into it; otherwise into the playing cue, which keeps running
  local fxf = TC.fxFade(page)
  local alt = static or fxf > 0
  local pc = TC.playingCue(seq)
  local ek = not quiet and TC.ed.k(seq)  -- editing a recorded look (Timecode Editor): into its cue
  if ek then TC.cue[seq] = ek
  elseif quiet then TC.cue[seq] = tonumber(quiet) or 1  -- (a number: store into that cue)
  elseif alt then TC.cue[seq] = (pc == 1) and 2 or 1
  else TC.cue[seq] = (pc == 2) and 2 or 1 end
  local presets, steps = {}, nil
  if page == "cfx" then
    local cols = TC.cfxCols(st)
    for k, ci in ipairs(cols) do
      cols[k] = TC.cfxPreset(st, k, ci)
      if not usePreset(4, cols[k], colorName(ci)) then return true end
    end
    steps = FN.cfxSteps(CFX_FORMS[st.form][2], cols)
  else
    for _, line in ipairs(CONTENT[page](st)) do
      local p, half = line:match("^At Preset ([%d%.]+)$"), nil
      if not p then p, half = line:match("^At Preset ([%d%.]+) Half (%d)$") end  -- a Color page half
      if not p then return false end
      presets[#presets + 1] = half and {g, p, TC.part.mx(g, st, tonumber(half))} or p
    end
  end
  if page == "dim" then TC.dim.restart(seq) end
  ensureRecipeCue(seq)
  local used = 0
  if steps then
    local a = rAddr(seq, 1)
    local h = obj(a)
    local cls
    if h then pcall(function() cls = h:GetClass() end) end
    if h and cls ~= "PhaserRecipe" then C("Delete %s /NC", a) h = nil end
    if not h then C('Store Type "PhaserRecipe" %s', a) h = obj(a) end
    local n = 0
    pcall(function() n = h[1]:Count() end)
    for k = n + 1, #steps do C("Store %s /NC", rAddr(seq, 1, ".1." .. k)) end
    for k = n, #steps + 1, -1 do C("Delete %s /NC", rAddr(seq, 1, ".1." .. k)) end
    for k, sp in ipairs(steps) do
      local vs = rAddr(seq, 1, ".1." .. k .. ".1")
      local vh, cur, tr = obj(vs), nil, nil
      if vh then pcall(function() cur = tostring(vh.ValueAbsolute) tr = tonumber(vh.TransX) end) end
      local pname = objName(obj("Preset 4." .. sp[1]))
      if not (cur and pname and cur:find(pname, 1, true)) then C("Assign Preset 4.%d At %s", sp[1], vs) end
      local wantT = sp[2] and 0 or 100
      if tr ~= wantT then C('Set %s Property "TransX" %d', vs, wantT) end
    end
    h = obj(a)
    if not recipeIs(h, "Selection", "Group " .. g) then C("Assign Group %d At %s", g, a) end
    recipeMatricks(a, page, st, h)
    setEnabled(a, h)
    used = 1
  else
    TC.recipeParts(seq, g, presets, page, st)
    used = #presets
  end
  TC.recipeOff(seq, used + 1)
  local cue = TC.cue[seq] or 1
  TC.applyRate(page, seq, st, cue)
  if TC.FX_FADE[page] then
    -- the fade into this cue: FX Fade, or none (also when the effect starts from off)
    -- (stored only: no fade, the fader brings it in)
    local f = quiet and 0 or fxf
    if f > 0 or tonumber(gv("cf_" .. seq .. "_" .. cue) or "0") ~= 0 then TC.cueFade(seq, cue, f) end
  end
  if quiet then
    -- stored only
  elseif ek then
    C("Goto Sequence %d Cue %s", seq, TC.ed.num(ek))  -- the edited look on stage
  elseif TC.recording() and TC.mode() ~= "timeline" then
    -- recording a song: the look goes into its own cue, so the timecode replays this look
    TC.snapshot(seq, page, st)
  elseif alt and (nCmds > n0 or TC.playingCue(seq) ~= cue) then
    -- static looks: fade into the other cue with the recipe's Fade / Delay / Wings; effects
    -- with an FX Fade: crossfade into the other cue over that time
    -- (without one, effect pages aren't re-triggered: that would restart the running phaser)
    C("Goto Sequence %d Cue %d", seq, cue)
  else
    FN.playIfIdle(seq)
  end
  TC.cue[seq] = nil
  return true
end

-- Dimmer FX faders (executors 2xx): the fader is the Master of the group's Dimmer FX sequence.
-- With no Dimmer FX chosen, the sequence holds Full (the first bulb) without playing, so the
-- fader brought up from 0 starts it: the group comes up to full with no FX.
-- With an FX Fade the looks alternate between cues 1 and 2, and the fader at 0 switches the
-- sequence off (Auto Stop). MA's default Restart Mode (First Cue) then brought back cue 1 when
-- the fader came up, which could be the look before the last one: the sequence restarts on its
-- current cue instead, and a stored-only look goes into both cues.
TC.dim = {}  -- (the Dimmer FX faders; a field, as the main chunk is at its 200 locals)
function TC.dim.restart(seq)
  local s = obj("Sequence " .. seq)
  if not s or gv("rstm_no") == "1" then return end
  local function current()
    local rm = ""
    pcall(function() rm = tostring(s:Get("RestartMode", Enums.Roles.Display)) end)
    return rm:lower():find("current") ~= nil, rm
  end
  local ok, rm = current()
  if ok then return end
  for _, v in ipairs({"Current Cue", "CurrentCue", "Current"}) do
    Cmd(string.format('Set Sequence %d Property "RestartMode" "%s"', seq, v))
    ok, rm = current()
    if ok then break end
  end
  dbg(string.format("Sequence %d RestartMode = %s", seq, rm))
  if not ok then sv("rstm_no", "1") end  -- (this MA version won't take it: not tried again)
end
-- the look stored into cue 1, and into cue 2 when there is one (the fader restarts either)
function TC.dim.store(gi, st)
  local seq = seqNo("dim", gi)
  fireRecipe("dim", gi, st, 1)
  if obj(string.format("Sequence %d Cue 2", seq)) then fireRecipe("dim", gi, copy(st), 2) end
end
function TC.dim.idle(gi)
  if not CFG.DIM_IDLE_FULL then return end
  local st = copy(MX_DEFAULT)
  st.form = 1
  TC.dim.store(gi, st)
end
-- the sequence holds the group's look without playing it (setup, executors)
function TC.dim.prime(gi)
  local st = loadGroup("dim", gi)
  if (st.form or 0) == 0 then return TC.dim.idle(gi) end
  TC.dim.store(gi, st)
end

-- the Colour Fill's group (Home > Utility Page makes it) and its colour sequence
function TC.fill.ready(seq, k)
  local _, u = TC.fill.entry(k)
  local g = TC.fill.group(k)
  if not obj("Group " .. g) then
    MessageBox({title = "FireSystem", message = string.format("%s needs Group %d.\n\n" ..
      "Store its fixtures into Group %d (or set them in UTIL), then press Home > Utility Page for its fader.",
      u[1], g, g), commands = {{value = 1, name = "OK"}}})
    return false
  end
  if not obj("Sequence " .. seq) then
    C("Store Sequence %d /Overwrite", seq)
    C("Label Sequence %d %s", seq, q(fs(u[1] .. " Color")))
  end
  return true
end

function fireGroup(page, gi, st)
  local seq = seqNo(page, gi)
  if TC.fill.k(page, gi) and not TC.fill.ready(seq, TC.fill.k(page, gi)) then return end
  local content = CONTENT[page](st)
  local ek = TC.ed.k(seq)
  if ek and not content then
    Echo("FireSystem: an empty look can't go into a timecode cue - delete the event in the Timecode Editor instead")
    return
  end
  if not content then
    local active = false
    pcall(function() active = DataPool().Sequences[seq]:HasActivePlayback() end)
    local fxf = TC.fxFade(page)
    if active and fxf > 0 then
      Cany({ string.format("Off Sequence %d Fade %s", seq, tostring(fxf)), string.format("Off Sequence %d", seq) })
    elseif active then C("Off Sequence %d", seq) end
    if page == "dim" then TC.dim.idle(gi) end
  elseif not fireRecipe(page, gi, st) then
    Echo(string.format("FireSystem: %s G%d - this look has no presets to point a recipe at", PAGE[page].title, gi))
  elseif ek then
    return TC.ed.saved(page, gi, seq, ek, st)
  end
  st.dirty = false
  saveGroup(page, gi, st)
  sv("fired_" .. page .. "_" .. gi, ser(st))
end

-- Fires every group with pending changes; if none are pending, re-fires the selection.
function firePage(page)
  local eg = TC.ed.on(page)  -- editing a recorded look: FIRE saves just that group's look
  if eg then return fireGroup(page, eg, loadGroup(page, eg)) end
  local list = {}
  for gi = 1, TC.fill.n(page) do
    if loadGroup(page, gi).dirty then list[#list + 1] = gi end
  end
  if #list == 0 then list = getSel(page) end
  for _, gi in ipairs(list) do fireGroup(page, gi, loadGroup(page, gi)) end
end

function clearLook(page, st)
  for k, v in pairs(LOOK_DEFAULTS[page] or {}) do
    if not (page == "cfx" and (k:match("^[ct]%d$") or k == "n")) and k ~= "size" then st[k] = v end
  end
end

-- the power buttons: switch a page (or one group) off right away
function offGroup(page, gi)
  local st = loadGroup(page, gi)
  clearLook(page, st)
  fireGroup(page, gi, st)
end
function offPage(page) for gi = 1, TC.fill.n(page) do offGroup(page, gi) end end

end

-- ==== FireSystemBumps.lua (copied by tools/make_tools.py) ====
MODS.Bumps = function(_ENV)

-- ======================================================================
-- Bumps / X-Keys (rebuilt as soon as a setting changes)
-- ======================================================================
function FN.colorForBump(gi, mode)
  if mode == "none" then return nil end
  local st = loadGroup("cfx", gi)
  if mode == "color" then return TC.cfxPreset(st, 1, st.c1) end
  return TC.cfxPreset(st, 2, st.c2)
end

-- channel sets of group g's fixture type for the bump's Gobo / Prism / Iris buttons:
-- {gobo = {open = {attr, dmx}, [1] = ...}, prism = {...}, iris = {...}} (cached per run)
BM.cache = {}
function BM.bumpSets(g)
  if BM.cache[g] then return BM.cache[g] end
  local res = {gobo = {}, prism = {}, iris = {}}
  pcall(function()
    local ft, mode = PROFILE.group(g)
    if not mode then return end
    local function dmx8(h) return tonumber(tostring(h):sub(1, 2), 16) end
    local prismOpen, prism2Fn, fx  -- fx: an Effects1 ("FX1") wheel, the prism on many profiles
    for _, ch in ipairs(mode.DMXChannels:Children()) do
      local attr = tostring(ch.name):match("_([^_]+)$") or tostring(ch.name)
      local chOpen, chPrism
      for _, lc in ipairs(ch:Children()) do
        for _, cf in ipairs(lc:Children()) do
          local fn = tostring(cf.name):lower()
          local sets = {}
          for _, cs in ipairs(cf:Children()) do
            local df = dmx8(cs:Get("DMXFrom", Enums.Roles.Display))
            local dt = dmx8(cs:Get("DMXTo", Enums.Roles.Display))
            if df and dt then
              local n = tostring(cs.name):lower()
              sets[#sets + 1] = {name = n, v = {attr = attr, dmx = math.floor((df + dt) / 2)}}
              if n:find("open", 1, true) then chOpen = chOpen or sets[#sets].v end
            end
          end
          local function first(pat, nth)
            local c = 0
            for _, x in ipairs(sets) do
              if (pat and x.name:find(pat)) or (not pat and not x.name:find("open", 1, true)
                 and not x.name:find("no feature", 1, true)) then
                c = c + 1
                if c == (nth or 1) then return x.v end
              end
            end
          end
          local moving = fn:find("rot") or fn:find("spin") or fn:find("pos") or fn:find("shake")
          if fn:match("^gobo1") and not moving then
            res.gobo.open = res.gobo.open or first("open")
            res.gobo[1] = res.gobo[1] or first()
          elseif fn:match("^prism1") and not moving then
            chPrism = true
            prismOpen = prismOpen or first("open")
            res.prism[1] = res.prism[1] or first()
            res.prism[2] = res.prism[2] or first(nil, 2)
          elseif fn:match("^prism2") and not moving then
            prism2Fn = prism2Fn or first()
          elseif fn:match("^effects1") and not moving and not fx then
            fx = {open = first("open") or chOpen, first(), first(nil, 2)}
          elseif fn:match("^iris") and not fn:find("pulse") and not fn:find("strobe") then
            res.iris.open = res.iris.open or first("open")
            res.iris.close = res.iris.close or first("clos")
          end
        end
      end
      if chPrism then prismOpen = prismOpen or chOpen end  -- e.g. an effect wheel's "open" slot
    end
    if not res.prism[1] and fx then prismOpen, res.prism[1], res.prism[2] = fx.open, fx[1], fx[2] end
    res.prism.open = prismOpen
    if prism2Fn then res.prism[2] = prism2Fn end
  end)
  BM.cache[g] = res
  return res
end

-- programmer lines for one look field of a bump (value v = button index, 1 = Off)
-- shutter functions of group g's fixture type: {strobe = {attr, dmx}, random, pulse, open}
-- (strobe speeds at 75 % towards the fast end of each range)
BM.shut = {}
function BM.shutter(g)
  if BM.shut[g] then return BM.shut[g] end
  local res, still = {}, {}
  pcall(function()
    local ft, mode = PROFILE.group(g)
    if not mode then return end
    local function dmx8(h) return tonumber(tostring(h):sub(1, 2), 16) end
    for _, ch in ipairs(mode.DMXChannels:Children()) do
      local attr = tostring(ch.name):match("_([^_]+)$") or tostring(ch.name)
      if attr:lower():find("shutter") or attr:lower():find("strobe") then
        for _, lc in ipairs(ch:Children()) do
          for _, cf in ipairs(lc:Children()) do
            local fn = tostring(cf.name):lower()
            local lo, hi, first
            for _, cs in ipairs(cf:Children()) do
              local df, dt = dmx8(cs:Get("DMXFrom", Enums.Roles.Display)), dmx8(cs:Get("DMXTo", Enums.Roles.Display))
              if df and dt then
                lo, hi = math.min(lo or df, df), math.max(hi or dt, dt)
                first = first or tostring(cs.name):lower()
              end
              if tostring(cs.name):lower():find("open", 1, true) and not res.open and df then
                res.open = {attr = attr, dmx = math.floor((df + dt) / 2)}
              end
            end
            if lo and hi then
              local fastLow = first and first:find("max", 1, true) ~= nil  -- "max Strobe" first = fast at low DMX
              local v = {attr = attr, dmx = math.floor(fastLow and (lo + (hi - lo) * 0.25) or (lo + (hi - lo) * 0.75))}
              -- by the function's attribute (Shutter1Strobe / ..StrobePulse / ..StrobeRandom), else
              -- by its name; never a strobe duration or a strobe mode
              local fa = ""
              pcall(function() fa = tostring(cf:Get("Attribute", Enums.Roles.Display) or ""):lower() end)
              local exact = fa:match("^shutter%d*strobe$") and "strobe" or fa:match("^shutter%d*strobepulse$") and "pulse"
                         or fa:match("^shutter%d*stroberandom$") and "random" or nil
              local key = exact or ((fn:find("duration", 1, true) or fn:find("mode", 1, true)) and nil)
                       or (fn:find("random") and not fn:find("pulse") and "random")
                       or (fn:find("pulse") and not fn:find("random") and "pulse")
                       or (fn:find("strobe") and not fn:find("pulse") and not fn:find("random") and "strobe") or nil
              if key and hi > lo and (not res[key] or (exact and not res[key].exact)) then
                v.exact = exact and true or nil
                res[key] = v
              end
              -- the channel's value that doesn't strobe ("Null" on a strobe-rate channel)
              if not key and not fn:find("effect", 1, true) and not still[attr] then
                still[attr] = {attr = attr, dmx = math.floor((lo + hi) / 2)}
              end
            end
          end
        end
      end
    end
  end)
  -- a fixture with a strobe-rate channel and a separate effect channel (random / pulse / open
  -- there): every strobe sets both, and open puts the rate channel back to its still value
  if res.strobe then res.still = still[res.strobe.attr] end
  -- the group's own elements must have that channel (pixel cells of a fixture often don't:
  -- their shutter is on the main fixture) - otherwise the dimmer chase is used
  local function has(grp)  -- does any element of grp have the shutter's channel?
    local found = false
    pcall(function()
      local a = res.strobe or res.random or res.pulse or res.open
      local ai = a and GetAttributeIndex(a.attr)
      Cmd("ClearSelection"); Cmd("Group " .. grp)
      local fi = SelectionFirst()
      while fi and ai and not found do
        if GetUIChannelIndex(fi, ai) then found = true end
        fi = SelectionNext(fi)
      end
      Cmd("ClearSelection")
    end)
    return found
  end
  local any = next(res) == nil or has(g)
  -- pixel cells without the shutter: the shutter of their main fixtures (the group's Masters
  -- group, BM.masterNo) strobes instead, else the dimmer chase
  if not any and next(res) then
    local M = BM.buildMasters(g) and BM.masterNo(g)
    any = M and has(M)
    if any then
      res.sel = "Group " .. M
      dbg("shutter G" .. g .. " on its main fixtures: Group " .. M)
    end
  end
  if not any then res = {} end
  BM.shut[g] = res
  local t = {}
  for k, v in pairs(res) do if type(v) == "table" then t[#t + 1] = k .. "=" .. v.attr .. "@" .. v.dmx end end
  dbg("shutter G" .. g .. ": " .. table.concat(t, " "))
  return res
end
-- programmer lines for a strobe of group g: the shutter's own strobe, else a fast dimmer chase
function BM.strobeLines(g, kind)
  local sh = BM.shutter(g)
  local x = sh[kind] or (kind == "pulse" and sh.strobe) or (kind == "random" and sh.strobe)
  local function at(v) return string.format("?Attribute %s At Decimal8 %d", q(v.attr), v.dmx) end
  -- split rate / effect channels: the other channel goes with it
  local function other(v, w) return (w and w.attr ~= v.attr) and w or nil end
  if kind == "open" then
    if not sh.open then return {} end
    local l = {at(sh.open)}
    local s2 = sh.strobe and other(sh.open, sh.still)
    if s2 and sh.strobe.attr ~= sh.open.attr then l[#l + 1] = at(s2) end
    if sh.sel then table.insert(l, 1, sh.sel) end  -- the main fixtures hold the shutter
    return l
  end
  if x then
    local l = {at(x)}
    local w = (x == sh.strobe) and other(x, sh.open) or other(x, sh.strobe)  -- effect open / the rate
    if w then l[#l + 1] = at(w) end
    if sh.sel then table.insert(l, 1, sh.sel) end
    return l
  end
  -- no shutter strobe (LED / dimmer fixtures): dimmer on / off phaser, hard steps
  local l = {string.format("Attribute %s At 100", q(CFG.ATTR.dim)), "Step 2", string.format("Attribute %s At 0", q(CFG.ATTR.dim))}
  if kind ~= "pulse" then l[#l + 1] = "Step 1 At Transition 0" l[#l + 1] = "Step 2 At Transition 0" end
  l[#l + 1] = string.format("?At Speed %d", (kind == "pulse") and 240 or 600)
  if kind == "random" then l[#l + 1] = "?At Phase 0 Thru 360" l[#l + 1] = "?Absolute" end
  l[#l + 1] = "Step 1"
  return l
end

function BM.bumpLines(g, field, v)
  local function dmx(x) return x and {string.format("?Attribute %s At Decimal8 %d", q(x.attr), x.dmx)} or {} end
  local A = CFG.ATTR
  if field == "dim" then return {string.format("Attribute %s At %d", q(A.dim), v == 2 and 0 or 100)} end
  if field == "shut" and v == -1 then return BM.strobeLines(g, "open") end
  if field == "shut" then
    -- the group's own Strobe / Rnd / Gen preset (21.x) by reference, so updating the preset changes
    -- the bumps; else the shared Strobe / Rnd Strobe preset
    local kind = (v == 2) and "strobe" or (v == 4) and "gen" or "random"
    local gi
    for i, x in ipairs(CFG.GROUPS) do if x == g or BM.linNo(x) == g then gi = i end end
    local p = STROBES[(v == 2) and 1 or 3][2]
    if gi and presetExists(STROBES.pool, STROBES.no(kind, gi)) then p = STROBES.no(kind, gi) end
    if presetExists(STROBES.pool, p) then
      local sel = BM.shutter(g).sel  -- pixel cells: the preset's shutter is on their main fixtures
      return sel and {sel, string.format("At Preset %d.%d", STROBES.pool, p)} or {string.format("At Preset %d.%d", STROBES.pool, p)}
    end
    return BM.strobeLines(g, (v == 2) and "strobe" or "random")
  end
  if field == "zoom" then return {string.format("?Attribute %s At Decimal8 %d", q("Zoom"), v == 2 and 0 or 255)} end
  if field == "pos" then return {string.format("?Attribute %s At %d", q(A.tilt), v == 2 and 60 or 0)} end
  local cs = BM.bumpSets(g)
  if field == "gobo" then return dmx(v == 2 and cs.gobo[1] or cs.gobo.open) end
  if field == "iris" then return dmx(v == 2 and cs.iris.close or cs.iris.open) end
  if field == "prism" then return dmx(v == 2 and cs.prism.open or cs.prism[v - 2]) end
  if field == "col" then
    local c = CFG.COLORS[v]
    if not c then return {} end
    local white = (c[3][1] >= 100 and c[3][2] >= 100 and c[3][3] >= 100) and 100 or 0
    local l = {}
    for _, x in ipairs(colorLines(tintRGBW(c[3], white, 0))) do l[#l + 1] = (x:sub(1, 1) == "?") and x or ("?" .. x) end
    return l
  end
  return {}
end

-- the bump options that set values straight from the fixture profiles, as one All preset each
-- (21.281+, every group's own values), so a bump step can be recipe lines: {field, value, name}
BM.OPTS = {
  {"dim", 2, "Dim 0"}, {"prism", 2, "Prism Open"}, {"prism", 3, "Prism 1"}, {"prism", 4, "Prism 2"},
  {"gobo", 2, "Gobo 1"}, {"gobo", 3, "Gobo Open"}, {"iris", 2, "Iris Close"}, {"iris", 3, "Iris Open"},
  {"zoom", 2, "Zoom Small"}, {"zoom", 3, "Zoom Big"}, {"pos", 2, "Tilt Up"}, {"pos", 3, "Tilt Down"},
  {"shut", -1, "Shutter Open"},
}
function BM.optNo(f, v)
  for i, o in ipairs(BM.OPTS) do if o[1] == f and o[2] == v then return CFG.BUMP_PRESET + i - 1 end end
end
-- programmer lines for option i over every group (pixel groups: their Masters' shutter too)
function BM.optLines(i)
  local o, l = BM.OPTS[i], {}
  for _, g in ipairs(CFG.GROUPS) do
    l[#l + 1] = "ClearSelection"
    l[#l + 1] = "Group " .. g
    for _, x in ipairs(BM.bumpLines(g, o[1], o[2])) do l[#l + 1] = x end
  end
  return l
end
-- the recipe lines of one bump step: {{group, "pool.no", MAtricks}, ...} (a value whose preset is
-- missing is left out)
function BM.stepLines(g, eff, k, mxProps, MG, fields, UG)
  local l, seen = {}, {}
  local function add(grp, pool, no, props)
    if not presetExists(pool, no) then
      failures[#failures + 1] = string.format("Preset %d.%d is missing (Home > Build makes it): left out of the bump", pool, no)
      return false
    end
    local key = grp .. "/" .. pool .. "." .. no
    if not seen[key] then l[#l + 1] = {grp, pool .. "." .. no, props} seen[key] = true end
    return true
  end
  for _, f in ipairs(fields) do
    local v = eff[f][k]
    if v and (f == "col" or v > 1 or v == -1) then
      local ok
      if f == "col" then ok = CFG.COLORS[v] and add(g, 4, colorPreset(v), mxProps)
      elseif f == "dim" and v == 3 then
        ok = add(g, 1, FULL_PRESET, mxProps)
        -- pixel cells: their main fixtures' master dimmer goes to Full with them
        if ok and MG then ok = add(MG, STROBES.pool, STROBES.mfull, {}) end
      elseif f == "shut" and v > 1 then
        local kind = (v == 2) and "strobe" or (v == 4) and "gen" or "random"
        local gi
        for i, x in ipairs(CFG.GROUPS) do if x == g or BM.linNo(x) == g then gi = i end end
        local pn = gi and STROBES.no(kind, gi)
        if not (pn and presetExists(STROBES.pool, pn)) then pn = STROBES[(v == 2) and 1 or 3][2] end
        -- pixel cells: the shutter is on their Masters group (all of it, as before)
        local M = tonumber((BM.shutter(g).sel or ""):match("^Group (%d+)$"))
        ok = add(M or g, STROBES.pool, pn, M and {} or mxProps)
        -- Master toggle: that group strobes with it
        if ok and UG then ok = add(UG, STROBES.pool, pn, {}) end
      else
        local no = BM.optNo(f, v)
        local M = (f == "shut") and tonumber((BM.shutter(g).sel or ""):match("^Group (%d+)$"))
        ok = no and add(M or g, STROBES.pool, no, M and {} or mxProps)
      end
    end
  end
  -- Master toggle: your master group at Full (Masters Full and the strobe presets only hold the
  -- Masters groups 111-118, so another group gets no values)
  if UG and #l > 0 then add(UG, STROBES.pool, STROBES.mfull, {}) end
  return l
end
-- a bump step's MAtricks on its recipe lines: the timing (Delay, Delay Wings) and, with a Group
-- on an axis, which part lights (Block, Group, Wings, X / Y / Z = the part, as MA's own MAtricks)
function BM.stepMx(g, mx, st)
  local p = matricksProps("bump", st)
  local cols, rows, deps = {}, {}, {}
  local function count(t) local n = 0 for _ in pairs(t) do n = n + 1 end return n end
  for _, ax in ipairs({{"X", mx}, {"Y", mx.y}, {"Z", mx.z}}) do
    local A, m = ax[1], ax[2]
    if m and (m.g or 0) > 1 then
      if not next(cols) then
        BM.part(g, {b = 1, g = 1, w = 0, p = 1})  -- fills BM.units[g] (the group's grid)
        for _, u in ipairs(BM.units[g] or {}) do cols[u.x] = true rows[u.y] = true deps[u.z] = true end
      end
      local n = count(({X = cols, Y = rows, Z = deps})[A])
      local b = (m.b or 1) == 0 and math.max(1, math.ceil(n / 2)) or (m.b or 1)
      for i = #p, 1, -1 do if p[i][1] == A .. "Wings" then table.remove(p, i) end end
      if b > 1 then p[#p + 1] = {A .. "Block", b} end
      p[#p + 1] = {A .. "Group", m.g}
      if (m.w or 0) > 1 then p[#p + 1] = {A .. "Wings", m.w} end
      p[#p + 1] = {A, math.max(1, m.p or 1)}
    end
  end
  return p
end

-- the group's elements in group order: {{addr, x, y}, ...} (cached per run). A unit = one cell
-- of the group's selection grid: a fixture that sits there with its cells (a Mini B) counts
-- once, a pixel strip's cells (each in its own grid cell) count one by one.
BM.units = {}
function BM.parentOf(addr) return tostring(addr):match("^(.-)%.%d+$") or tostring(addr) end
-- the elements left to right on the grid group's selection grid (then top to bottom), so
-- parts and linear groups follow where the fixtures sit, not their numbers
function BM.gridSort(list)
  local t = {}
  for i, u in ipairs(list) do t[i] = {u = u, i = i, x = tonumber(u.x) or i, y = tonumber(u.y) or 0, z = tonumber(u.z) or 0} end
  table.sort(t, function(a, b)
    if a.x ~= b.x then return a.x < b.x end
    if a.y ~= b.y then return a.y < b.y end
    if a.z ~= b.z then return a.z < b.z end
    return a.i < b.i
  end)
  local out = {}
  for i, e in ipairs(t) do out[i] = e.u end
  return out
end
function BM.unitKey() return function(u) return tostring(u.x) .. "/" .. tostring(u.y) .. "/" .. tostring(u.z or 0) end end
function BM.part(g, mx)
  if not BM.units[g] then
    local t = {}
    pcall(function()
      Cmd("ClearSelection"); Cmd("Group " .. g)
      local fi, x, y, z = SelectionFirst()
      while fi do
        -- cells as "Fixture 301.002": the command line reads "301.2" / "+ 301.2" differently
        local a = tostring(GetSubfixture(fi):ToAddr()):gsub("%.(%d+)", function(d) return string.format(".%03d", tonumber(d)) end)
        t[#t + 1] = {addr = a, x = tonumber(x) or #t, y = tonumber(y) or 0, z = tonumber(z) or 0}
        fi, x, y, z = SelectionNext(fi)
      end
      Cmd("ClearSelection")
    end)
    BM.units[g] = t
  end
  -- X, Y and Z each have their own Block / Group / Wings / Part, over the grid's columns (X),
  -- rows (Y) and layers (Z); an element is lit when every axis lights its column, row and layer
  local function axis(field, a)
    local vals, rank = {}, {}
    for _, u in ipairs(BM.units[g]) do if not rank[u[field]] then rank[u[field]] = true vals[#vals + 1] = u[field] end end
    table.sort(vals)
    for i, v in ipairs(vals) do rank[v] = i - 1 end
    local n = #vals
    local groups, wings = math.max(1, a.g or 0), math.max(1, a.w or 0)
    local m = math.ceil(n / wings)                         -- columns / rows per wing
    local blk = ((a.b or 1) <= 0) and math.max(1, math.ceil(m / 2)) or (a.b or 1)
    return function(u)
      if groups <= 1 then return true end
      local i = rank[u[field]]
      local wing, pos = math.floor(i / m), i % m
      if wing % 2 == 1 then pos = m - 1 - pos end          -- every other wing mirrored
      return math.floor(pos / blk) % groups + 1 == ((a.p or 1) - 1) % groups + 1
    end
  end
  local inX, inY, inZ = axis("x", mx), axis("y", mx.y or {}), axis("z", mx.z or {})
  local inP, outP = {}, {}
  for _, u in ipairs(BM.units[g]) do
    if inX(u) and inY(u) and inZ(u) then inP[#inP + 1] = u.addr else outP[#outP + 1] = u.addr end
  end
  return inP, outP
end
-- X / Cross-hatch pan presets: each grid cell of the group (left to right) gets +F or -F
-- (X: left half +F, right half -F, the middle one 0; hatch: alternating)
function BM.panPattern(groups, kind, F)
  local l = {}
  for _, g in ipairs(groups) do
    BM.units[g] = nil
    BM.part(g, {g = 1, w = 1, b = 0, p = 1})  -- fills BM.units[g]
    local cells, order = {}, {}
    local key = BM.unitKey()
    for _, u in ipairs(BM.gridSort(BM.units[g] or {})) do
      local k = key(u)
      if not cells[k] then cells[k] = {} order[#order + 1] = k end
      table.insert(cells[k], u.addr)
    end
    local n = #order
    for i, k in ipairs(order) do
      local v
      if kind == "x" then
        v = (n % 2 == 1 and i == (n + 1) / 2) and 0 or ((i <= n / 2) and F or -F)
      else
        v = (i % 2 == 1) and F or -F
      end
      l[#l + 1] = "ClearSelection"
      l[#l + 1] = table.concat(cells[k], " + ")
      l[#l + 1] = string.format("Attribute %s At %d", q(CFG.ATTR.pan), v)
    end
  end
  return l
end
-- Linear groups: the same fixtures as a grid group, but on one row of the selection grid (stored
-- with LINEAR_GROUP_BASE + group number). Bumps and X-Keys pick the grid or the linear group.
function BM.linNo(g) return CFG.LINEAR_GROUP_BASE + g end
-- Stores the current selection as group L laid out in one row: the selected fixtures in
-- selection order, re-selected one after another. A grid cell holding one fixture's cells
-- becomes that fixture, so its cells stay together. The selection is stored as it is first, so
-- the group is never lost when MA refuses the one-row re-selection (FireSystem.log says why).
function BM.storeLinear(L, name)
  local n0 = 0
  pcall(function() n0 = SelectionCount() end)
  local order, fids, fseen = {}, {}, {}
  pcall(function()
    local fi, x, y = SelectionFirst()
    while fi do
      local sf = GetSubfixture(fi)
      local a
      pcall(function()
        -- cells as "301.002": the command line reads "+ 301.2" differently
        a = tostring(sf:ToAddr()):gsub("^.-Fixture%s+", ""):gsub("%.(%d+)", function(d) return string.format(".%03d", tonumber(d)) end)
      end)
      local e = {addr = a, x = tonumber(x), y = tonumber(y)}
      order[#order + 1] = e
      -- the fixture ID (a cell takes its fixture's)
      local fid, h = nil, sf
      for _ = 1, 4 do
        if not h then break end
        pcall(function() fid = tonumber(tostring(h.FID or h.fid or "")) end)
        if fid then break end
        local ok, p = pcall(function() return h:Parent() end)
        h = ok and p or nil
      end
      e.fid = fid
      fi, x, y = SelectionNext(fi)
    end
  end)
  if n0 == 0 and #order == 0 then return false end
  C("Store Group %d /Overwrite", L)
  if name then C("Label Group %d %s", L, q(name)) end
  -- left to right as they sit in the grid group, one entry per grid cell: a cell holding a
  -- fixture together with its own cells becomes that fixture (MA selects its cells with it)
  order = BM.gridSort(order)
  for _, e in ipairs(order) do
    if e.fid and not fseen[e.fid] then fseen[e.fid] = true fids[#fids + 1] = tostring(e.fid) end
  end
  local addrs = {}
  for _, e in ipairs(order) do if e.addr then addrs[#addrs + 1] = e end end
  order = addrs
  local out, seen, cells, corder = {}, {}, {}, {}
  local key = BM.unitKey()
  for _, u in ipairs(order) do
    local k = key(u)
    if not cells[k] then cells[k] = {} corder[#corder + 1] = k end
    table.insert(cells[k], u.addr)
  end
  local function put(a) if not seen[a] then seen[a] = true out[#out + 1] = a end end
  for _, k in ipairs(corder) do
    local c, main = cells[k], nil
    for _, a in ipairs(c) do if a == BM.parentOf(a) then main = a end end  -- the fixture itself
    for _, a in ipairs(c) do if BM.parentOf(a) ~= main and a ~= main then main = nil end end
    if main then put(main) else for _, a in ipairs(c) do put(a) end end
  end
  local done = false
  for _, list in ipairs(#out > 0 and {out} or {fids}) do
    if not done and #list > 0 then
      C("ClearAll")
      local line = "Fixture " .. table.concat(list, " + Fixture ")  -- MA wants the keyword on each one
      local r = Cmd(line)
      local n = 0
      pcall(function() n = SelectionCount() end)
      dbg(string.format("linear Group %d: %s  ->  %s, %d selected", L, line, tostring(r), n))
      if n > 0 then C("Store Group %d /Overwrite", L) done = true end
    end
  end
  if not done then dbg(string.format("linear Group %d: kept the selection as it was (one-row re-selection refused)", L)) end
  C("ClearAll")
  return math.max(#out, #fids, n0)
end
-- builds group g's linear group from it (kept when you stored your own with Store L)
function BM.buildLinear(g)
  local L = BM.linNo(g)
  if obj("Group " .. L) and gv("lin_auto_" .. g) ~= "1" then return true end
  if not obj("Group " .. g) then return false end
  C("ClearAll")
  C("Group %d", g)
  local n = BM.storeLinear(L, (objName(obj("Group " .. g)) or ("G" .. g)) .. " Lin")
  if n then
    sv("lin_auto_" .. g, "1")
    dbg(string.format("Group %d: linear version of Group %d (%d fixtures)", L, g, n))
  end
  C("ClearAll")
  return n ~= false
end
function BM.ensureLinears() for _, g in ipairs(CFG.GROUPS) do BM.buildLinear(g) end end
-- Masters groups: the main fixtures of a group of pixel cells (Group MASTER_GROUP_BASE + group
-- number, e.g. Group 111 for Group 1). Stored once; store your own over it and it's kept.
function BM.masterNo(g)
  if g > CFG.LINEAR_GROUP_BASE and g <= CFG.LINEAR_GROUP_BASE + CFG.GROUP_SLOTS then g = g - CFG.LINEAR_GROUP_BASE end
  return CFG.MASTER_GROUP_BASE + g
end
-- the Masters groups that exist (pixel groups' main fixtures)
function BM.masterGroups()
  local t = {}
  for _, g in ipairs(CFG.GROUPS) do if obj("Group " .. BM.masterNo(g)) then t[#t + 1] = BM.masterNo(g) end end
  return t
end
function BM.buildMasters(g)
  local M = BM.masterNo(g)
  if obj("Group " .. M) and gv("mg_auto_" .. M) ~= "1" then return true end
  if not obj("Group " .. g) then return false end
  local function norm(a)
    return (tostring(a):gsub("^.-Fixture%s+", ""):gsub("%.(%d+)", function(d) return string.format(".%03d", tonumber(d)) end))
  end
  local mine, fx, seen, out = {}, {}, {}, {}
  pcall(function()
    local fi
    -- the cells of every busking group (a fixture's cells may be split over groups)
    for _, x in ipairs(CFG.GROUPS) do
      Cmd("ClearSelection"); Cmd("Group " .. x)
      fi = SelectionFirst()
      while fi do mine[norm(GetSubfixture(fi):ToAddr())] = true fi = SelectionNext(fi) end
    end
    Cmd("ClearSelection"); Cmd("Group " .. g)
    fi = SelectionFirst()
    while fi do
      local a = norm(GetSubfixture(fi):ToAddr())
      mine[a] = true
      local p = BM.parentOf(a)
      if p ~= a and not seen[p] then seen[p] = true fx[#fx + 1] = p end
      fi = SelectionNext(fi)
    end
    -- each cell's fixture: its elements that aren't busking-group cells
    for _, p in ipairs(fx) do
      Cmd("ClearSelection"); Cmd("Fixture " .. p)
      fi = SelectionFirst()
      while fi do
        local a = norm(GetSubfixture(fi):ToAddr())
        if not mine[a] and not seen["m" .. a] then seen["m" .. a] = true out[#out + 1] = "Fixture " .. a end
        fi = SelectionNext(fi)
      end
    end
    Cmd("ClearSelection")
  end)
  if #out == 0 then return false end  -- not pixel cells (or MA gave nothing back)
  C("ClearAll")
  C(table.concat(out, " + "))
  C("Store Group %d /Overwrite", M)
  C("Label Group %d %s", M, q((objName(obj("Group " .. g)) or ("G" .. g)) .. " Masters"))
  C("ClearAll")
  sv("mg_auto_" .. M, "1")
  dbg(string.format("Group %d: main fixtures of Group %d (%d)", M, g, #out))
  return true
end
-- the group a bump / X-Key selects: its linear group when set to Linear (built if missing)
function BM.grp(gi, t)
  local g = CFG.GROUPS[gi]
  if g and t and t.lin then
    if obj("Group " .. BM.linNo(g)) or BM.buildLinear(g) then return BM.linNo(g) end
  end
  return g
end

function rebuildBump(gi, slot)
  local b = getBump(gi, slot)
  -- the groups this key fires on (LOS): their grid or linear groups
  local GS = {}
  for _, gx in ipairs(BM.grps(b, gi)) do GS[#GS + 1] = BM.grp(gx, b) end
  local g = GS[1]
  local flash = BM.isFlash(b)
  local n = flash and 1 or math.max(1, math.min(BM.MAX, tonumber(b.steps) or 1))
  local st = copy(MX_DEFAULT)
  st.delay, st.wings = tonumber(b.delay) or 0, tonumber(b.wings) or 0
  local seq = bumpSeq(slot, gi)
  -- Go+ bump: the key only triggers. Its sequence has one empty cue per step whose command
  -- starts that step's own sequence (BM.stepSeq). A step sequence plays the look (cue 1) and
  -- switches itself off again (cue 2 follows after Off Time and releases the look over Fade Out,
  -- then Off), so fast hits overlap instead of cutting each other off.
  -- Flash bump: the look is cue 1 of the bump's own sequence, on while the key is held (one step).
  -- A field that is Off in a step keeps the value of the step before it; when it is only
  -- set in a later step, step 1 starts from neutral (open, white, dimmer 0, shutter open).
  local NEUTRAL = {dim = 2, prism = 2, gobo = 3, iris = 3, col = 1, shut = -1}
  -- the shutter goes last: for pixel cells it selects their main fixtures
  local fields = {"col"}
  for _, f in ipairs(BM.LOOK) do if f[1] ~= "shut" then fields[#fields + 1] = f[1] end end
  fields[#fields + 1] = "shut"
  local eff = {}
  for _, f in ipairs(fields) do
    local vals, last = {}, nil
    for k = 1, n do local v = tonumber(b[f .. k]) or 0 if v > 0 then last = v end vals[k] = last end
    if n > 1 and last then for k = 1, n do if vals[k] then break end vals[k] = NEUTRAL[f] or last end end
    eff[f] = vals
  end
  local function sec(v) return tostring(tonumber(v) or 0) end
  local function trig(sq, cue, v)
    Cany({ string.format('Set Sequence %d Cue %s Property "TrigType" %s', sq, cue, v),
           string.format('Set Sequence %d Cue %s Part 0 Property "TrigType" %s', sq, cue, v) })
  end
  -- switching between Go+ and Flash: the bump's sequence starts again from no cues
  local mode = flash and "flash" or "go"
  if gv("bmmode_" .. seq) ~= mode then
    C("ClearAll")
    BM.clearCues(seq)
    sv("bmmode_" .. seq, mode)
  end
  -- Go+: the step switches the key's sequence off again, so the executor doesn't stay lit. With
  -- more steps it must then restart at its next cue (RestartMode); if MA won't take that, the
  -- key's sequence stays on as before so the steps still advance
  local offTrig = false
  if not flash and obj("Sequence " .. seq) then
    Cmd(string.format('Set Sequence %d Property "WrapAround" "Yes"', seq))
    local rm = ""
    for _, v in ipairs({"Next Cue", "NextCue", "Next"}) do
      Cmd(string.format('Set Sequence %d Property "RestartMode" "%s"', seq, v))
      pcall(function() rm = tostring(obj("Sequence " .. seq):Get("RestartMode", Enums.Roles.Display)) end)
      if rm:lower():find("next") then break end
    end
    offTrig = (n == 1) or rm:lower():find("next") ~= nil
    dbg(string.format("Sequence %d RestartMode = %s  ->  key switched off by its steps: %s", seq, rm, tostring(offTrig)))
  end
  local MGS, span, T = {}, {}, 0
  for _, gx in ipairs(GS) do
    BM.units[gx] = nil
    BM.shutter(gx)  -- looked up now: it clears the selection, so never in the middle of a step
    MGS[gx] = obj("Group " .. BM.masterNo(gx)) and BM.masterNo(gx)
    if #GS > 1 then  -- the fixtures of each group in the LOS row (for the shared Delay)
      BM.part(gx, {b = 1, g = 1, w = 0, p = 1})
      local n = math.max(1, #(BM.units[gx] or {}))
      span[gx] = {T, T + n - 1}
      T = T + n
    end
  end
  local UG = tonumber(b.mgrp)
  if UG and not obj("Group " .. UG) then UG = nil end
  if UG then BM.shutter(UG) end
  local spread = #GS > 1 and st.delay > 0
  for k = 1, n do
    -- MAtricks part of this step (not carried over: every step says what it lights)
    local function mxv(f, d) return math.floor(tonumber(b[f .. k]) or d) end
    local mx = {b = mxv("mb", 1), g = mxv("mg", 0), w = mxv("mw", 0), p = math.max(1, mxv("mp", 1)),
      y = {b = mxv("ymb", 1), g = mxv("ymg", 0), w = mxv("ymw", 0), p = math.max(1, mxv("ymp", 1))},
      z = {b = mxv("zmb", 1), g = mxv("zmg", 0), w = mxv("zmw", 0), p = math.max(1, mxv("zmp", 1))}}
    -- the step is recipe lines on the bump's group (and its Masters) pointing at presets, with
    -- the step's part as the lines' MAtricks
    local target = flash and seq or BM.stepSeq(slot, gi, k)
    if not flash then BM.ensureStepSeq(target, gi, slot, k) end
    local rl, seen = {}, {}
    for idx, gx in ipairs(GS) do
      local props = BM.stepMx(gx, mx, st)
      if spread then
        props = BM.spreadDelay(props, span[gx][1], span[gx][2], T, st.delay, st.wings, (mx.g or 0) > 1)
      end
      for _, l in ipairs(BM.stepLines(gx, eff, k, props, MGS[gx], fields, idx == 1 and UG or nil)) do
        local key = tostring(l[1]) .. "/" .. l[2]
        if not seen[key] then seen[key] = true rl[#rl + 1] = l end
      end
    end
    C("ClearAll")
    TC.cue[target] = 1
    ensureRecipeCue(target)
    TC.recipeParts(target, g, rl, "bump", st)
    TC.recipeOff(target, #rl + 1, 64)
    TC.cue[target] = nil
    if flash then
      C("ClearAll")
      BM.partProp(seq, 1, "CueInFade", sec(b.fade))
      -- releasing the key: the sequence goes off over Fade Out (its OffCue's fade)
      BM.partProp(seq, '"OffCue"', "CueInFade", sec(b.fout))
    else
      local ss = target
      C("ClearAll")
      BM.partProp(ss, 1, "CueInFade", sec(b.fade))
      BM.partProp(ss, 1, "CueOutFade", sec(b.fout))
      -- cue 2 follows Off Time after the look is in and releases it over Fade Out
      for _, gx in ipairs(GS) do
        C("Group %d", gx)
        C("At Release")
        if BM.shutter(gx).sel or MGS[gx] then C(BM.shutter(gx).sel or ("Group " .. MGS[gx])) C("At Release") end
      end
      if UG then C("Group %d", UG) C("At Release") end
      C("Store Sequence %d Cue 2 /Overwrite", ss)
      C("ClearAll")
      trig(ss, 2, '"Follow"')
      BM.partProp(ss, 2, "CueInDelay", sec(b.off))
      BM.partProp(ss, 2, "CueInFade", sec(b.fout))
      -- the bump's key goes dark as the look is released (the trigger sequence switches off; it
      -- restarts at its next cue, so the next press still plays the next step), and once the
      -- release has faded, cue 3 switches the step sequence itself off
      BM.partProp(ss, 2, "Command", q(offTrig and ("Off Sequence " .. seq) or ""))
      if not obj(string.format("Sequence %d Cue 3", ss)) then C("Store Sequence %d Cue 3 /Overwrite", ss) end
      trig(ss, 3, '"Follow"')
      BM.partProp(ss, 3, "CueInDelay", tostring((tonumber(b.fout) or 0) + 0.1))
      BM.partProp(ss, 3, "Command", q("Off Sequence " .. ss))
      -- what MA really holds (FireSystem.log), as cue: trig / delay / fade / command
      pcall(function()
        local t = {}
        for cno = 1, 3 do
          local cue = obj(string.format("Sequence %d Cue %d", ss, cno))
          local p0 = obj(string.format("Sequence %d Cue %d Part 0", ss, cno))
          if cue and p0 then
            t[#t + 1] = string.format("%d: %s / %s / %s / %s", cno, tostring(cue:Get("TrigType", Enums.Roles.Display)),
              tostring(p0:Get("CueInDelay", Enums.Roles.Display)), tostring(p0:Get("CueInFade", Enums.Roles.Display)),
              tostring(p0:Get("Command", Enums.Roles.Display)))
          end
        end
        dbg("bump step Sequence " .. ss .. "  " .. table.concat(t, "  |  "))
      end)
    end
  end
  C("ClearAll")
  if flash then
    -- no trigger cues and no step sequences in Flash mode
    for _, c in ipairs((obj("Sequence " .. seq) or {Children = function() return {} end}):Children()) do
      local no = tonumber(c.no)
      if no and no > 1000 then Cmd(string.format("Delete Sequence %d Cue %s /NC", seq, tostring(no / 1000))) end
    end
  else
    -- the trigger sequence: empty cue k starts step k (cues no longer used go)
    for _, c in ipairs((obj("Sequence " .. seq) or {Children = function() return {} end}):Children()) do
      local no = tonumber(c.no)
      if no and no > 0 and (no / 1000 > n or no % 1000 ~= 0) then Cmd(string.format("Delete Sequence %d Cue %s /NC", seq, tostring(no / 1000))) end
    end
    for k = 1, n do
      if not obj(string.format("Sequence %d Cue %d", seq, k)) then C("Store Sequence %d Cue %d /Overwrite", seq, k) end
      -- the other steps go off first: hit fast, the previous step would still be on with this one
      local cmd = {}
      for k2 = 1, n do if k2 ~= k then cmd[#cmd + 1] = string.format("Off Sequence %d", BM.stepSeq(slot, gi, k2)) end end
      cmd[#cmd + 1] = string.format("Goto Sequence %d Cue 1", BM.stepSeq(slot, gi, k))
      C('Set Sequence %d Cue %d Part 0 Property "Command" %s', seq, k, q(table.concat(cmd, "; ")))
      BM.partProp(seq, k, "CueInFade", "0")
    end
  end
  for k = n + 1, BM.MAX do
    local ss = BM.stepSeq(slot, gi, k)
    local h = obj("Sequence " .. ss)
    if h and BM.isOurs(h) then Cmd(string.format("Off Sequence %d", ss)) Cmd(string.format("Delete Sequence %d /NC", ss)) end
  end
  if flash then  -- Flash mode has no step sequences at all
    local h = obj("Sequence " .. BM.stepSeq(slot, gi, 1))
    if h and BM.isOurs(h) then Cmd(string.format("Off Sequence %d", BM.stepSeq(slot, gi, 1))) Cmd(string.format("Delete Sequence %d /NC", BM.stepSeq(slot, gi, 1))) end
  end
  -- the bump's executor: Go+ to step through the looks, Flash to hold the look
  local ex, pg
  for _, r in ipairs(CFG.EXEC_ROWS) do
    if r.what == BM.ROW[slot] then pg, ex = TC.ex.at(r.what .. gi, r.page or CFG.EXEC_PAGE, r.base + gi) end
  end
  if ex and CFG.ASSIGN_EXECUTORS then
    local path = string.format("Page %d.%d", pg, ex)
    local h = TC.ex.handle(pg, ex)
    local ok = false
    pcall(function()
      if h and h.Object and tonumber(h.Object.No) == seq then h.Key = BM.key(b, slot) ok = tostring(h.Key) == BM.key(b, slot) end
    end)
    if h and not ok then
      pcall(function()
        if h.Object and tonumber(h.Object.No) == seq then
          ok = okResult(Cmd(string.format('Set %s Property "Key" "%s"', h:ToAddr(), BM.key(b, slot)))) and true
        end
      end)
    end
    dbg(string.format('%s .Key = "%s"  ->  %s', path, BM.key(b, slot), tostring(ok)))
  end
end

function FN.rebuildStrobeAll()
  -- recipes: each group at Full + its strobe, the pixel groups' Masters at Full + their shutter
  -- strobe (the shared Strobe preset), so updating a preset plays straight away
  local seq, lines = CFG.STROBE_SEQ, {}
  local function add(grp, pool, no) if presetExists(pool, no) then lines[#lines + 1] = {grp, pool .. "." .. no} end end
  for _, g in ipairs(CFG.GROUPS) do
    add(g, 1, FULL_PRESET)
    local M = obj("Group " .. BM.masterNo(g)) and BM.masterNo(g)
    if M then add(M, STROBES.pool, STROBES.mfull) end
    local sel = tonumber((BM.shutter(g).sel or ""):match("^Group (%d+)$"))
    add(sel or g, STROBES.pool, STROBES[1][2])
  end
  if #lines > 0 then TC.recipeCue(seq, lines) end
end

function rebuildXk(gi)
  local x, g = getXk(gi), CFG.GROUPS[gi]
  g = BM.grp(gi, x)
  local st, name = copy(MX_DEFAULT), XK_PATTERNS[x.pattern][2]
  if name == "In" then st.phase, st.wings = 360, 2
  elseif name == "Random" then st.phase, st.shuf = 360, true
  elseif name == "Out" then st.phase, st.wings, st.rev = 360, 2, true
  elseif name == "Odd/Even" then st.phase, st.grp = 180, 2
  elseif name == "Right" then st.phase = 360
  elseif name == "Blocks" then st.phase, st.blk = 360, 2
  elseif name == "Left" then st.phase, st.rev = 360, true end
  -- person on = one fixture at a time (narrow pulse), off = wider square
  local dp = dimPreset(x.single and 14 or 12)
  local cp = FN.colorForBump(gi, x.col)
  if cp and not presetExists(4, cp) then cp = nil end
  local zp = x.zoom and CFG.BUMP_ZOOM_PRESET and obj("Preset " .. CFG.BUMP_ZOOM_PRESET) and CFG.BUMP_ZOOM_PRESET
  -- recipes: one line per preset on the group with the pattern's MAtricks, so a changed
  -- preset or group plays straight away (nothing stored from the programmer)
  local seq = xkSeq(gi)
  local presets = {}
  if presetExists(1, dp) then presets[#presets + 1] = "1." .. dp end
  if cp then presets[#presets + 1] = "4." .. cp end
  if zp then presets[#presets + 1] = zp end
  TC.cue[seq] = 1
  ensureRecipeCue(seq)
  TC.recipeParts(seq, g, presets, "xk", st)
  TC.recipeOff(seq, #presets + 1)
  TC.cue[seq] = nil
end

end

-- ==== FireSystemLayouts.lua (copied by tools/make_tools.py) ====
MODS.Layouts = function(_ENV)

-- ======================================================================
-- Layout button specs (deterministic order => deterministic macro numbers)
-- ======================================================================
-- Each button: {label, arg, col, row, w, h, fb, lbl}
--   fb(ctx)  -> appearance key      lbl(ctx) -> label text (dynamic labels)
-- emb: the page as a part of a combined page (TC.combo): {rows = the groups to show, slim = no shared
-- header buttons and no MAtricks columns (the page above has them for both)}; returns its buttons
-- without navigation, frames or macro numbers
function buildSpec(page, emb)
  local B = {}
  -- sections: every button gets the current section; frames are drawn around each section
  local curSec = "main"
  local function sec(n) curSec = n end
  -- ghost: a row/column for a group slot the show doesn't use (fewer than 8 groups), so
  -- every show gets the same page; its buttons are greyed out and do nothing
  local ghost, capGi = false, nil  -- capGi: the group row being added (greyed if it can't use the page)
  local function add(label, arg, col, row, fb, o)
    o = o or {}
    if ghost then
      arg, fb = "global noop", function() return "dis" end
      if o.lbl then o.lbl = function() return "" end end
    elseif capGi and TC.PAGE_CAP[page] then
      -- greyed out while the group has nothing this page sets
      local gi0, fb0, lbl0 = capGi, fb, o.lbl
      fb = function(c) if not TC.pcap(page, gi0) then return "dis" end return fb0 and fb0(c) or "idle" end
      if lbl0 then o.lbl = function(c) if not TC.pcap(page, gi0) then return "" end return lbl0(c) end end
    end
    local icon = o.icon or (not o.noIcon and FN.ICON_BY_LABEL[label]) or nil
    B[#B + 1] = {label = label, arg = arg, col = col, row = row, fb = fb, fam = o.fam, gobo = o.gobo,
                 sec = o.sec or curSec,
                 w = o.w or 1, h = o.h or 1, lbl = o.lbl, icon = icon, cat = o.cat, tsize = o.tsize,
                 num = not icon and not o.lbl and (o.w or 1) == 1 and (o.h or 1) == 1 and arg ~= "global noop"
                       and ICN.NUMLABEL[label] or nil,
                 axis = o.axis, cmd = o.cmd, rec = o.rec, fill = o.fill, gname = o.gname, dtxt = o.dtxt,
                 art = (not icon) and not o.cat and not o.axis and FN.artFor(label, arg, o.w or 1, o.h or 1, o.lbl) or nil}
  end
  local function on(cond) return cond and "on" or "idle" end
  -- the recording dot: a little red REC while the song's timecode records (invisible otherwise);
  -- tapping it stops the recording
  local function recDot(col, row)
    add("REC", "tc recdot", col, row, function() return TC.recording() and "rec" or "norec" end,
        {rec = true, sec = "ext", noIcon = true, tsize = "11", fam = function() return "red" end,
         lbl = function() return TC.recording() and "REC" or "" end})
  end
  -- the timecode transport: its own row above the page, so busking can be recorded into the
  -- song's timecode (and played back) from any page. Tapping the name opens the Timecode page.
  local function tcBar()
    local top = 0
    for _, b in ipairs(B) do top = math.min(top, b.row - b.h + 1) end
    local r = top - 1.25
    local function fam(f) return function() return f end end
    sec("tcbar")
    add("Timecode", "tc view tc", 0, r, function() return "hdr" end, {w = 3, noIcon = true, tsize = "14", lbl = function()
      return (TC.recording() and "REC: " or "TC: ") .. (TC.name() or ("Song " .. TC.song())) end})
    add("Top", "tc bar top", 3.25, r, nil, {noIcon = true, fam = fam("blue")})
    add("Play", "tc bar play", 4.25, r, nil, {noIcon = true, fam = fam("green")})
    add("Pause", "tc bar pause", 5.25, r, nil, {noIcon = true, fam = fam("yellow")})
    add("Stop", "tc bar stop", 6.25, r, nil, {noIcon = true, fam = fam("orange")})
    -- lit while recording; tap again to stop
    add("REC", "tc bar rec", 7.25, r, function() return TC.recording() and "on" or "idle" end, {noIcon = true, fam = fam("red")})
  end
  -- MAtricks buttons: red while the columns edit X, blue for Y, green for Z
  local function axisFam(c) return FN.AXIS_FAM[c.axis] or "red" end
  local function hdr() return "hdr" end
  local function caption(text, col, row, o)
    o = o or {}
    o.cat = o.cat or (CFG.ART and ICN.CATFOR[text .. "|" .. (o.w or 1)]) or nil
    if o.cat then o.icon = nil o.noIcon = true end
    add(text, "global noop", col, row, hdr, o)
  end
  local P = page .. " "
  local NR = #CFG.GROUPS                   -- the show's groups
  local NG = math.max(NR, CFG.GROUP_SLOTS)  -- rows on the pages (unused ones greyed out)
  -- the group rows: (row, group) for every slot, or on a combined page only the groups that use it
  local function slots()
    local t = {}
    if emb then for _, gi in ipairs(emb.rows) do t[#t + 1] = gi end else for gi = 1, NG do t[#t + 1] = gi end end
    return ipairs(t)
  end

  -- grey = active, red = changed and waiting for FIRE (as on Tom's pages)
  local function has(c, t, field, val)
    local function is(st)  -- (Color page: the colour / tint of the half being set, TC.part)
      if page == "col" and (field == "color" or field == "tint") then return TC.part.lit(st, field, val) end
      return st[field] == val
    end
    if t == "all" then
      for gi = 1, NR do if not is(c.gs[gi]) then return false end end
      return true
    end
    return is(c.gs[t])
  end
  local function cellFb(t, field, val)
    return function(c)
      if not has(c, t, field, val) then return "idle" end
      if t ~= "all" and c.gs[t].dirty then return "pend" end
      return "on"
    end
  end
  local function cell(label, t, field, val, col, row, o)
    add(label, P .. "cell " .. t .. " " .. field .. " " .. tostring(val), col, row, cellFb(t, field, val), o)
  end
  -- the group's name beside its G button (left of the G column), so the rows don't have to be
  -- guessed; empty for unused slots. right = w: the name goes right of the G instead, w wide
  -- (Gobo page: the G sits left in its column's header, the name next to it; tapping it picks the group too)
  local function gName(gi, col, row, sc, right)
    local gh, cg = ghost, capGi
    ghost, capGi = false, nil  -- (never greyed: just text)
    add("Name " .. gi, (right and not gh) and (P .. "grp " .. gi) or "global noop", right and (col + 1) or (col - 1.75), row,
        function() return "hide" end, {w = right or 1.5, noIcon = true, gname = right and "left" or "right", sec = sc,
        tsize = "14", lbl = function() return TC.gname(gi) end})
    ghost, capGi = gh, cg
  end
  local function gButton(gi, col, row, o)
    o = o or {}
    o.icon = "g" .. gi
    if not curSec:match("^col") then o.sec = o.sec or "g" end
    local w = o.w or 1
    o.w = 1
    add("G" .. gi, P .. "grp " .. gi, col, row, function(c)
      if c.sel[gi] then return "on" end
      return c.gs[gi] and c.gs[gi].dirty and "dirty" or "idle"
    end, o)
    gName(gi, col, row, o.sec, w > 1 and (w - 1) or nil)
  end

  -- header pieces
  local function clearBtn(col, row) add("CLEAR", P .. "clearall", col, row, hdr) end
  local function pen(col, row)
    add("Multi", "global solo", col, row, function(c) return on(c.g.solo) end,
        {lbl = function(c) return c.g.solo and "Solo" or "Multi" end})
  end
  local function eye(col, row)
    add("Blind", "global live", col, row, function(c) return c.g.live and "live" or "blind" end,
        {icon = "eye", lbl = function(c) return c.g.live and "LIVE" or "Blind" end})
  end
  local function fire(col, row, w)
    -- one FIRE for every page: it fires the pending changes of all pages
    add("FIRE", "global fire " .. page, col, row, function(c) return c.anyDirty and "dirty" or "fire" end, {w = w or 2})
  end
  local function power(col, row) add("Off", P .. "off", col, row, function() return "off" end, {icon = "power"}) end
  local function saveLook(col, row) add("SAVE LOOK", "global savelook", col, row, function() return "store" end) end
  local function presets(col, row, title)
    caption(title or "Presets", col, row, {w = 2})
    for i = 1, 4 do
      add("PRESET " .. i, P .. "precall " .. i, col + 1 + i, row,
          function(c) return c.pp[i] and "recall" or "idle" end)
    end
  end
  local function storePresets(col, row)
    caption("Store Preset", col, row, {w = 2})
    for i = 1, 4 do
      add("PRESET " .. i, P .. "pstore " .. i, col + 1 + i, row,
          function(c) return c.pp[i] and "stored" or "store" end)
    end
  end
  -- the same header on every fire page, so the shared buttons never move
  local function header()
    -- (one spacing everywhere: 0.25 grid units between sections, the header 0.25 above the page)
    local slim = emb and emb.slim  -- the lower page of a combined page: the shared buttons are above
    sec("ctl"); clearBtn(0, -2.25); if not slim then recDot(1.25, -2.25); pen(0, -1.25) end
    if TC.FX_FADE[page] then  -- FX Fade: type the seconds a FIRE fades into the new effect
      add("FX Fade", P .. "fxfade", 2.5, -2.25, function() return TC.fxFade(page) > 0 and "on" or "idle" end,
          {w = 2, noIcon = true, sec = "ext", lbl = function()
            local t = TC.fxFade(page)
            return t > 0 and ("FX Fade " .. string.format("%g", t) .. "s") or "FX Fade Off" end})
    end; if not slim then eye(2, -1.25); fire(3, -1.25) end; power(5, -1.25); if not slim then saveLook(6, -1.25) end
    sec("pre"); presets(7.25, -2.25); storePresets(7.25, -1.25)
    sec("main")
  end
  local function shuffle(col, row)
    add("Shuffle", P .. "mxt shuf", col, row, function(c) return on(c.st and c.st[axKey(c.axis, "shuf")]) end,
        {fam = axisFam, sec = (row < 0) and "ext" or nil})
  end

  -- MAtricks columns, acting on the groups selected with the G buttons
  local function mx(field, val, label, col, row)
    add(label, P .. "mx " .. field .. " " .. tostring(val), col, row,
        function(c) return on(c.st and c.st[axKey(c.axis, field)] == val) end, {fam = axisFam})
  end
  local function mxt(field, label, col, row)
    add(label, P .. "mxt " .. field, col, row, function(c) return on(c.st and c.st[axKey(c.axis, field)]) end,
        {fam = axisFam})
  end
  -- header with the current value; the "X" column is titled with the axis
  local function mxHead(title, field, col, row, fmt)
    caption(title, col, row, {lbl = function(c)
      local t = (title == "X") and c.axis or title
      local v = c.st and c.st[axKey(c.axis, field)] or 0
      if v == 0 or v == false then return t .. " None" end
      return t .. " " .. (fmt and fmt(v) or tostring(v))
    end})
  end
  local function custom(field, col, row) add("Edit", P .. "mxedit " .. field, col, row, nil, {fam = axisFam}) end
  local function valueCol(title, field, values, col, row0, withCustom)
    mxHead(title, field, col, row0)
    for i, v in ipairs(values) do mx(field, v, tostring(v), col, row0 + i) end
    if withCustom then custom(field, col, row0 + #values + 1) end
  end
  -- X / Block / Group / Wings / Width / Phase / Speed, as on the FX pages
  local function fxColumns(x, row0)
    local prevSec = curSec; sec("mx")
    -- the big X: steps every MAtricks column through the X, Y and Z axis
    add("X", P .. "axis", x, row0 + 3, function(c) return c.axis ~= "X" and "on" or "hdr" end,
        {h = 2, axis = true, lbl = function(c) return c.axis end})
    x = x + 1.25
    valueCol("X", "shift", {0, 1, 2, 3, 4}, x, row0, true)
    valueCol("Block", "blk", {0, 2, 3, 4}, x + 1, row0, true)
    valueCol("Group", "grp", {0, 1, 2, 3, 4}, x + 2, row0, true)
    valueCol("Wings", "wings", {0, 2, 3, 4}, x + 3, row0, true)
    mxt("sym", "Sym", x + 3, row0 + 7)  -- symmetrical: mirrored around the centre
    valueCol("Width", "width", {0, 1, 2, 3, 4}, x + 4, row0, true)
    caption("Phase", x + 5, row0)
    mxt("rev", "Rev", x + 5, row0 + 1)
    for i, p in ipairs({0, 90, 180, 270, 360}) do mx("phase", p, p .. "°", x + 5, row0 + 1 + i) end
    custom("phase", x + 5, row0 + 7)
    caption("Speed", x + 6, row0, {lbl = function(c)
      local b = c.st and c.st[axKey(c.axis, "bpm")] or 0
      if b > 0 then return "Speed " .. b end
      local v = c.st and c.st[axKey(c.axis, "speed")] or 0
      local s = SPEEDS[page][v]
      return s and ("Speed " .. s[1] .. "/" .. s[2]) or "Speed None" end})
    for i, s in ipairs(SPEEDS[page]) do mx("speed", i, s[1] .. "/" .. s[2], x + 6, row0 + i) end
    custom("bpm", x + 6, row0 + 7)
    if BM.RATES_ON[page] then
      -- Rate: multiplies the page's speed master for the group (MA speed scale of its cue)
      caption("Rate", x + 7, row0, {lbl = function(c) return "Rate " .. BM.rateLabel(c.st and c.st.rate or 0) end})
      for i, r in ipairs({-2, -1, 0, 1, 2}) do mx("rate", r, BM.rateLabel(r), x + 7, row0 + i) end
      custom("rate", x + 7, row0 + 7)
      sec(prevSec)
      return x + 8
    end
    sec(prevSec)
    return x + 7
  end
  -- Fade / Delay / Shuffle / Wings, as on the Color and Position pages
  local function timingColumns(x, row0)
    local prevSec = curSec; sec("mx")
    mxHead("Fade", "fade", x, row0)
    mxt("spread", "Same", x, row0 + 1)
    mxt("frev", "Rev", x, row0 + 2)
    for i = 0, 3 do mx("fade", i, tostring(i), x, row0 + 3 + i) end
    custom("fade", x, row0 + 7)
    mxHead("Delay", "delay", x + 1, row0)
    mxt("drev", "Rev", x + 1, row0 + 2)
    for i = 0, 3 do mx("delay", i, tostring(i), x + 1, row0 + 3 + i) end
    custom("delay", x + 1, row0 + 7)
    shuffle(x + 2.25, row0)
    mxt("sym", "Sym", x + 2.25, row0 + 1)  -- symmetrical: mirrored around the centre
    mxHead("Wings", "wings", x + 2.25, row0 + 2)
    for i, w in ipairs({0, 2, 3, 4}) do mx("wings", w, tostring(w), x + 2.25, row0 + 2 + i) end
    custom("wings", x + 2.25, row0 + 7)
    sec(prevSec)
  end

  local function navRow(row)
    sec("nav")
    for i, p in ipairs(PAGES) do
      add(PAGE[p].nav, "global page " .. p, (i - 1) * 2, row, function() return on(p == page) end, {w = 2})
    end
    -- Fill Screen: every page fills the view on its own (off = all pages the same size)
    add("Fill Screen", "global fit", #PAGES * 2 + 0.25, row, function() return on(gv("fit_mode") == "fill") end,
        {w = 2, lbl = function() return gv("fit_mode") == "fill" and "Fill Screen" or "Same Size" end})
    add("Home", "global home", #PAGES * 2 + 2.25, row, function() return "hdr" end, {w = 2})
    add("Masters", "global mast", #PAGES * 2 + 4.25, row, function() return "hdr" end, {w = 2})
  end

  local nav
  if TC.combo.DEF[page] then
    -- combined page: its pages one under the other, each with only the groups that can use it.
    -- The buttons are the pages' own (same commands, b.pg = the page they light up from); the top
    -- page's MAtricks columns are shared: they set both pages (TC.combo.action)
    -- the page below goes as high as it fits: next to the MAtricks columns, under the group rows
    local function clash(sub, dy)
      for _, b in ipairs(sub) do
        local r1 = b.row - b.h + 1 + dy
        for _, o in ipairs(B) do
          if b.col < o.col + o.w + 0.2 and o.col < b.col + b.w + 0.2
             and r1 < o.row + 1.2 and o.row - o.h + 1 < b.row + 1 + dy + 0.2 then return true end
        end
      end
      return false
    end
    local y = 0
    for k, sp in ipairs(TC.combo.DEF[page]) do
      local sub = buildSpec(sp, {rows = TC.combo.rows(sp), slim = k > 1})
      local top, bot = math.huge, -math.huge
      for _, b in ipairs(sub) do top, bot = math.min(top, b.row - b.h + 1), math.max(bot, b.row) end
      if k > 1 then
        y = 0
        while clash(sub, y - top) do y = y + 0.25 end
      end
      for _, b in ipairs(sub) do
        b.row, b.pg = b.row - top + y, sp
        if b.sec == "mx" then b.arg = tostring(b.arg):gsub("^" .. sp .. " ", page .. " ") end
        if b.sec ~= "ext" then b.sec = sp .. " " .. tostring(b.sec) end  -- (frames per page)
        B[#B + 1] = b
      end
      y = y + bot - top + 1.25
    end
    nav = 0  -- (under everything: see below)
  elseif page == "dim" then
    -- header: CLEAR / pen / eye FIRE power ... Preset 1-4, Store Preset 1-4
    header()
    for r, gi in slots() do ghost, capGi = gi > NR, gi
      gButton(gi, 0, r - 1)
      cell("Rnd", gi, "shuf", true, 1.25, r - 1)
      cell("Off", gi, "form", 0, 2.5, r - 1, {icon = "bulb_off"})
      for c, i in ipairs(DIM_FORMS.order) do
        cell(DIM_FORMS[i][1], gi, "form", i, 3.75 + c - 1 + (c == #DIM_FORMS and 0.25 or 0), r - 1)
      end
    end
    ghost, capGi = false, nil
    local xr = fxColumns(3.75 + #DIM_FORMS + 0.5, 0) or (3.75 + #DIM_FORMS + 0.5 + 9.25)
    -- Specials: 12 toggles (2 rows of 6) top right, beside the header, with their fade time and
    -- All Off; the Specials fader is their Group Master
    sec("spec")
    local sx = xr - 6
    add("Fade", P .. "specfade", sx - 1.25, -2.25, function() return TC.spec.fade() > 0 and "on" or "idle" end,
        {noIcon = true, lbl = function()
          local t = TC.spec.fade()
          return "Specials Fade " .. string.format("%g", t) .. "s" end})
    add("All Off", P .. "specoff", sx - 1.25, -1.25, function() return "off" end, {noIcon = true})
    for i = 1, CFG.SPECIALS do
      add("SP" .. i, P .. "spec " .. i, sx + (i - 1) % 6, -2.25 + math.floor((i - 1) / 6),
          function() return TC.spec.on(i) and "on" or "idle" end,
          {noIcon = true, fam = function() return "orange" end, lbl = function()
            local n = gv("spec_name_" .. i)
            return (type(n) == "string" and n ~= "") and (i .. " " .. n:sub(1, 10)) or ("SP " .. i) end})
    end
    nav = NG + 0.25
  elseif page == "col" then
    -- header: eye FIRE, Store Presets 1-4, Presets 1-4 ; top row = all groups
    header()
    add("Custom Colours", "global ccol", 13.5, -1.25, function() return "hdr" end, {w = 2, sec = "ext"})
    -- the half of each group a colour press sets: All, Odd / Even or Left / Right fixtures (TC.part)
    for i, pt in ipairs(TC.part.LIST) do
      add(pt[2], P .. "part " .. pt[1], 13.5 + i - 1, -2.25, function() return on(TC.part.cur() == pt[1]) end,
          {noIcon = true, sec = "ext", fam = function() return "magenta" end})
    end
    -- every row has its own buttons (top row = all groups), so no group selection here;
    -- Pastel / Dark per row at the end (prep like every other button, again = normal)
    local tx = NALLCOL + 1.75
    -- the Colour Fill (UTIL color = true) gets its own row under the groups
    local fgi = TC.fill.gi(page)
    -- on a combined page only the groups that can use colour, one under the other
    local use, NGr = {}, emb and #emb.rows or NG
    for i, gi in ipairs(emb and emb.rows or {}) do use[gi] = i end
    for r = 0, TC.fill.n(page) do
      if not emb or r == 0 or r > NR or use[r] then
        local t = (r == 0) and "all" or r
        local fk = TC.fill.k(page, r)
        local isFill = fk ~= nil
        local y = isFill and (NGr + 0.25 + fk) or (use[r] or r)
        capGi = (r > 0) and r or nil
        if isFill then
          local _, u = TC.fill.entry(fk)
          -- a disc like the G buttons, so the name stays readable on any background
          add(u[1], "global noop", 0, y, function() return "idle" end,
              {sec = "g", fill = true, noIcon = true, fam = function() return "magenta" end})
        elseif r > 0 then
          add("G" .. r, "global noop", 0, y, function() return "idle" end, {icon = "g" .. r, sec = "g"})
          gName(r, 0, y, "g")
        end
        cell("Pastel", t, "tint", 1, tx, y, {sec = "tint", fill = isFill})
        cell("Dark", t, "tint", 2, tx + 1, y, {sec = "tint", fill = isFill})
        for ci = 1, NALLCOL do
          local idle = isCustomColor(ci) and ("COLOR " .. (ci - NCOL)) or " "
          add(idle, P .. "cell " .. t .. " color " .. ci, 0.25 + ci + (isCustomColor(ci) and 0.25 or 0), y,
              function(c) return (has(c, t, "color", ci) and "cs" or "c") .. ci end,
              {lbl = function(c) return (has(c, t, "color", ci) and not CFG.ROUND) and "X" or idle end, fill = isFill})
        end
      end
    end
    -- the unused group slots, greyed out
    ghost, capGi = true, nil
    for gi = NR + 1, emb and 0 or NG do
      add("G" .. gi, "global noop", 0, gi, nil, {icon = "g" .. gi, sec = "g"})
      gName(gi, 0, gi, "g")
      cell("Pastel", gi, "tint", 1, tx, gi, {sec = "tint"})
      cell("Dark", gi, "tint", 2, tx + 1, gi, {sec = "tint"})
      for ci = 1, NALLCOL do add(" ", "global noop", 0.25 + ci + (isCustomColor(ci) and 0.25 or 0), gi) end
    end
    ghost, capGi = false, nil
    if not (emb and emb.slim) then timingColumns(NALLCOL + 4, 0) end
    nav = (fgi and NG + 1.5 + #TC.fill.list()) or (NG + 1.25)
  elseif page == "cfx" then
    header(); shuffle(13.5, -1.25)
    for gi = 1, NG do ghost, capGi = gi > NR, gi
      gButton(gi, 0, gi - 1)
      cell("Off", gi, "form", 0, 1.25, gi - 1, {icon = "bulb_off"})
      for i, f in ipairs(CFX_FORMS) do cell(f[1], gi, "form", i, 2.5 + i - 1 + (f[2] == "fan" and 0.25 or 0), gi - 1) end
    end
    ghost, capGi = false, nil
    fxColumns(2.5 + #CFX_FORMS + 0.5, 0)
    -- STEP 1-5 rows (1 = the colour, 2 = the background) for the selected groups: the down arrow adds
    -- a step (its row appears), the up arrow takes the last one away (2-5 colours)
    local function nSteps(c) return c.st and #TC.cfxCols(c.st) or 2 end
    for r = 1, TC.CFX_MAX do
      local key, row = "c" .. r, NG - 0.75 + r
      local function shown(c) return r <= 2 or nSteps(c) >= r end
      -- (the step's image: "STEP" with a pink numbered ring right of it, the text is in the image)
      local txt = CFG.ART and "" or ("STEP " .. r)
      add("STEP " .. r, "global noop", 0, row, function(c) return shown(c) and "hdr" or "hide" end,
          {w = 2, noIcon = true, cat = CFG.ART and ("cfxstep" .. r) or nil, lbl = r > 2 and function(c) return shown(c) and txt or "" end or nil})
      for ci = 1, NALLCOL do
        local idle = isCustomColor(ci) and ("COLOR " .. (ci - NCOL)) or " "
        local function picked(c) return c.st and c.st[key] == ci end
        add(idle, P .. "mx " .. key .. " " .. ci, 1.25 + ci + (isCustomColor(ci) and 0.25 or 0), row,
            function(c) if not shown(c) then return "hide" end return (picked(c) and "cs" or "c") .. ci end,
            {lbl = function(c) if not shown(c) then return "" end return (picked(c) and not CFG.ROUND) and "X" or idle end})
      end
      -- Pastel / Dark for the step (again = the normal colour), as on the Color page
      for t, name in ipairs({"Pastel", "Dark"}) do
        add(name, P .. "mx t" .. r .. " " .. t, NALLCOL + 1.75 + t, row, function(c)
          if not shown(c) then return "hide" end
          return (c.st and tonumber(c.st["t" .. r]) == t) and "on" or "idle"
        end, {lbl = function(c) return shown(c) and name or "" end})
      end
    end
    add("^", P .. "steps -1", NALLCOL + 5, NG + 0.25, function(c) return nSteps(c) > 2 and "idle" or "dis" end)
    add("v", P .. "steps 1", NALLCOL + 5, NG + 1.25, function(c) return nSteps(c) < TC.CFX_MAX and "idle" or "dis" end)
    nav = NG + 2.5
  elseif page == "pos" then
    header()
    for r, gi in slots() do ghost, capGi = gi > NR, gi
      gButton(gi, 0, r - 1)
      for i, p in ipairs(PANS) do cell(p[1], gi, "pan", i, 0.25 + i, r - 1, {icon = p[2] and ("pan" .. i)}) end
      for i, t in ipairs(TILTS) do cell(t[1], gi, "tilt", i, #PANS + 1.5 + i - 1, r - 1, {icon = t[2] and ("tilt" .. i)}) end
    end
    ghost, capGi = false, nil
    timingColumns(#PANS + #TILTS + 1.75, -1)
    nav = NG + 0.25
  elseif page == "pfx" then
    header(); shuffle(13.5, -1.25)
    for r, gi in slots() do ghost, capGi = gi > NR, gi
      gButton(gi, 0, r - 1)
      add("Off", P .. "offgrp " .. gi, 1.25, r - 1, function() return "off" end, {icon = "power"})
      cell("Off", gi, "panfx", 0, 2.5, r - 1, {icon = "power"})
      for i, f in ipairs(PAN_FX) do cell(f[1], gi, "panfx", i, 2.5 + i, r - 1, {icon = TC.MOVE_ICON.pan[i]}) end
      local x = 2.5 + #PAN_FX + 1.25
      cell("Off", gi, "tiltfx", 0, x, r - 1, {icon = "power"})
      for i, f in ipairs(TILT_FX) do cell(f[1], gi, "tiltfx", i, x + i, r - 1, {icon = TC.MOVE_ICON.tilt[i]}) end
      x = x + #TILT_FX + 1.25
      -- size of all the group's position FX: neither lit = normal, - smaller, + bigger
      local function size(c, sz)
        local g = c.gs[gi]
        if g.size ~= sz then return "idle" end
        return g.dirty and "pend" or "on"
      end
      add("-", P .. "fxsize " .. gi .. " 1", x, r - 1, function(c) return size(c, 1) end)
      add("+", P .. "fxsize " .. gi .. " 3", x + 1, r - 1, function(c) return size(c, 3) end)
    end
    ghost, capGi = false, nil
    if not (emb and emb.slim) then fxColumns(2.5 + #PAN_FX + 1.25 + #TILT_FX + 1.25 + 2.25, 0) end
    nav = NG + 0.25
  elseif page == "beam" then
    -- one column per group, as on Tom's Gobo/Prism/Zoom page
    header()
    for gi = 1, NG do ghost, capGi = gi > NR, gi
      sec("col" .. gi)
      local x = (gi - 1) * 3.25
      gButton(gi, x, 0, {w = 3})
      for r, b in ipairs(CFG.BEAM) do
        add(b.label, P .. "pick " .. gi .. " " .. b.key, x, r, function(c)
          if not TC.cap(gi, b.key) then return "dis" end  -- the group has no such attribute: greyed out
          return (c.gs[gi][b.key] or 0) > 0 and (c.gs[gi].dirty and "pend" or "on") or "idle"
        end, {icon = FN.BEAM_ICON[b.key], lbl = function(c)
          if not TC.cap(gi, b.key) then return "" end
          local i = c.gs[gi][b.key] or 0
          if i == 0 then return "-" end
          if b.key == "zoom" and CFG.ROUND then return "" end  -- the zoom disc shows the level
          if c.gs[gi][b.key .. "n"] then return c.gs[gi][b.key .. "n"] end
          return presetName(b.pool, b.presets[i]) or (b.label .. " " .. i)
        end})
        if b.rotFn then
          -- rotation: each tap goes to the next option (Off, Stop, CW 1-3, CCW 1-3)
          add("Rot", P .. "rot " .. gi .. " " .. b.key, x + 1, r, function(c)
            if not TC.cap(gi, b.key) then return "dis" end
            local v = c.gs[gi][b.key .. "rot"]
            return (tonumber(v) or 0) > 0 and (c.gs[gi].dirty and "pend" or "on") or "idle"
          end, {lbl = function(c)
            if not TC.cap(gi, b.key) then return "" end
            local v = tonumber(c.gs[gi][b.key .. "rot"]) or 0
            return v > 0 and ROT_OPTS[v][1] or (b.key == "shape" and "Rotate" or "Rot")
          end, fam = function() return "teal" end})
        elseif b.key == "zoom" then
          add("Zoom FX", P .. "cell " .. gi .. " zoomfx true", x + 1, r, function(c)
            if not TC.cap(gi, "zoom") then return "dis" end
            return cellFb(gi, "zoomfx", true)(c)
          end, {icon = "sine1"})
        end
        caption(b.label, x + 2, r)
      end
      local r0 = #CFG.BEAM + 1
      add("MX Clear", P .. "mxclear " .. gi, x, r0, function() return "idle" end)
      cell("90°", gi, "phase", 90, x + 1, r0)
      cell("180°", gi, "phase", 180, x + 2, r0)
      cell("Shuffle", gi, "shuf", true, x, r0 + 1)
      cell("270°", gi, "phase", 270, x + 1, r0 + 1)
      cell("360°", gi, "phase", 360, x + 2, r0 + 1)
      cell("PREP", gi, "live", false, x, r0 + 2)
      cell("LIVE", gi, "live", true, x + 1, r0 + 2)
      add("RECALL", P .. "recallgrp " .. gi, x + 2, r0 + 2)
    end
    ghost, capGi = false, nil
    nav = #CFG.BEAM + 4.5
  elseif page == "bump" then
    -- LOS panel of the MA start show, laid out like the other pages: G column = groups to
    -- include, a row per look option, colour block, then MAtricks and timing columns.
    -- Everything below the header is for the step picked with Step 1-3.
    local function cur(c) return c.bm end
    local function stepVal(c, f) return tonumber(cur(c)[f .. c.bmStep]) or 0 end
    local function purple() return "purple" end
    local function red() return "red" end
    -- header: which bumps, how many steps, which step is edited
    sec("ctl")
    for i, t in ipairs(BM.TARGETS) do
      add(t[2] .. " " .. t[3], "bump target " .. t[1], (i - 1) * 1.4, -1.25,
          function(c) return on(c.bmTarget == t[1]) end, {w = 1.33})
    end
    sec("steps")
    for k = 1, BM.MAX do
      add(k .. " Step", "bump steps " .. k, 4.25 + k - 1, -1.25, function(c)
        if BM.isFlash(cur(c)) and k > 1 then return "off" end  -- a Flash bump has one look
        return on((tonumber(cur(c).steps) or 1) == k) end, {fam = purple})
    end
    sec("estep")
    for k = 1, BM.MAX do
      add("Step " .. k, "bump step " .. k, 7.5 + k - 1, -1.25, function(c)
        if k > (BM.isFlash(cur(c)) and 1 or (tonumber(cur(c).steps) or 1)) then return "off" end
        return on(c.bmStep == k) end, {fam = purple})
    end
    -- Go+ (each press plays the next step, which switches itself off) or Flash (on while held)
    sec("mode")
    add("Flash", "bump flash", 10.75, -1.25, function(c) return BM.isFlash(cur(c)) and "live" or "idle" end,
        {w = 2, lbl = function(c) return BM.isFlash(cur(c)) and "Flash (hold)" or "Go+ (auto off)" end})
    -- the bump runs over the grid group or its linear version (one row)
    add("Linear", "bump lin", 13, -1.25, function(c) return on(cur(c).lin) end,
        {w = 2, lbl = function(c) return cur(c).lin and "Linear group" or "Grid group" end})
    -- Master: your group of the pixels' main fixtures comes up (dimmer Full) and strobes with the bump
    add("Master", "bump mst", 15.25, -1.25, function(c) return on(cur(c).mgrp ~= nil) end,
        {w = 2, lbl = function(c) return cur(c).mgrp and ("Master Grp " .. tostring(cur(c).mgrp)) or "Master off" end})
    recDot(17.5, -1.25)
    -- G column: the groups whose bumps change
    sec("g")
    for gi = 1, NG do ghost, capGi = gi > NR, gi
      add("G" .. gi, "bump inc " .. gi, 0, gi - 1, function(c) return on(c.bmInc[gi]) end, {icon = "g" .. gi})
      gName(gi, 0, gi - 1)
    end
    ghost, capGi = false, nil
    -- one row per look option (caption + buttons)
    sec("main")
    local LX = 1.25
    for r, f in ipairs(BM.LOOK) do
      caption(f[2], LX, r - 1, {w = 2, noIcon = true})
      for v, label in ipairs(f[3]) do
        add(label, "bump set " .. f[1] .. " " .. v, LX + 2 + v - 1, r - 1, function(c)
          local cv = stepVal(c, f[1])
          return on((cv == 0 and 1 or cv) == v) end, {icon = f[4][v], fam = purple, noIcon = not f[4][v]})
      end
    end
    -- the bump's timing columns next to them (header shows the value)
    sec("time")
    local TX = LX + 2 + 4 + 0.25
    for i, t in ipairs(BM.TIME) do
      local x = TX + i - 1
      caption(t[2], x, 0, {noIcon = true, lbl = function(c) return t[2] .. " " .. tostring(cur(c)[t[1]] or 0) end})
      for j, v in ipairs(t[3]) do
        add(tostring(v), "bump set " .. t[1] .. " " .. tostring(v), x, j,
            function(c) return on(tonumber(cur(c)[t[1]]) == v) end, {noIcon = true, fam = red})
      end
      add("Edit", "bump edit " .. t[1], x, 5, nil, {fam = red})
    end
    -- LOS: the groups the edited key fires on (any of them; one press fires them all, and Delay +
    -- Wings run over them as one row). The G column picks the key, this block its groups.
    sec("los")
    local LOSX = TX + #BM.TIME + 0.25
    caption("Fires on", LOSX, 0, {w = 4, noIcon = true, lbl = function(c)
      local t = {}
      for _, gx in ipairs(c.bmGrps) do t[#t + 1] = "G" .. gx end
      return "Key G" .. c.bmKey .. " fires on " .. table.concat(t, " ") end})
    for gx = 1, NG do ghost = gx > NR
      add("G" .. gx, "bump grp " .. gx, LOSX + (gx - 1) % 4, 1 + math.floor((gx - 1) / 4), function(c)
        for _, x in ipairs(c.bmGrps) do if x == gx then return "on" end end
        return "idle" end, {icon = "g" .. gx})
    end
    ghost = false
    local LR = 1 + math.ceil(NG / 4)
    add("Own group", "bump grp own", LOSX, LR, function(c) return on(#c.bmGrps == 1 and c.bmGrps[1] == c.bmKey) end,
        {w = 2, noIcon = true})
    add("All groups", "bump grp all", LOSX + 2, LR, function(c) return on(#c.bmGrps == NR) end, {w = 2, noIcon = true})
    -- colour line, as on the Color page
    local row = #BM.LOOK
    sec("col")
    caption("Color", LX, row, {w = 2, noIcon = true})
    add("Off", "bump set col 0", LX + 2, row, function(c) return on(stepVal(c, "col") == 0) end, {icon = "power"})
    for ci = 1, NCOL do
      add(" ", "bump set col " .. ci, LX + 2 + ci, row, function(c)
        return (stepVal(c, "col") == ci and "cs" or "c") .. ci end)
    end
    -- MAtricks of the step below it: presets, then Block / Group / Wings / Part (+ Edit)
    local function mxv(c, f) return tonumber(cur(c)[BM.axisKey() .. f[1] .. c.bmStep]) or f[3] end
    sec("mx")
    -- X / Y / Z: which axis the MAtricks buttons below edit (each axis keeps its own values)
    caption("MAtricks", LX, row + 1, {noIcon = true, lbl = function(c) return "MAtricks " .. c.axis end})
    add("X", "bump axis", LX + 1, row + 1, function(c) return c.axis ~= "X" and "on" or "hdr" end,
        {axis = true, lbl = function(c) return c.axis end})
    for i, pr in ipairs(BM.MXP) do
      add(pr[1], "bump mxpreset " .. i, LX + 2 + i - 1, row + 1, function(c)
        local v = {}
        for j, f in ipairs(BM.MX) do v[j] = mxv(c, f) end
        if pr[4] == 0 then return on(v[2] <= 1 and v[3] <= 1) end
        return on(v[1] == pr[3] and v[2] == pr[4] and v[3] == pr[5] and v[4] == pr[6])
      end, {icon = pr[2], fam = purple})
    end
    local x = LX
    for _, f in ipairs(BM.MX) do
      caption(f[2], x, row + 2, {noIcon = true, lbl = function(c)
        local v = mxv(c, f)
        for _, o in ipairs(f[4]) do if o[1] == v then return f[2] .. " " .. o[2] end end
        return f[2] .. " " .. tostring(v) end})
      for j, o in ipairs(f[4]) do
        add(o[2], "bump set " .. f[1] .. " " .. o[1], x + j, row + 2, function(c) return on(mxv(c, f) == o[1]) end,
            {icon = (o[2] == "Off") and "power" or nil, noIcon = true, fam = red})
      end
      add("Edit", "bump edit " .. f[1], x + #f[4] + 1, row + 2, nil, {fam = red})
      x = x + #f[4] + 2.25
    end
    nav = row + 3.25
  elseif page == "xk" then
    -- one column per group: cone / copy, COLOR / BACKGROUND, person, then the chase patterns
    sec("ctl")
    add("FIRE", "global fire xk", 0, -1.25, function(c) return c.anyDirty and "dirty" or "fire" end, {w = 2})
    recDot(2.25, -1.25)
    for gi = 1, NG do ghost, capGi = gi > NR, gi
      sec("col" .. gi)
      local x = (gi - 1) * 2.25
      local function xfb(fn) return function(c) return on(fn(c.xk[gi])) end end
      add("Zoom", "xk set " .. gi .. " zoom", x, 0, xfb(function(s) return s.zoom end))
      add("Copy", "xk copy " .. gi, x + 1, 0)
      add("COLOR", "xk set " .. gi .. " col color", x, 1, xfb(function(s) return s.col == "color" end))
      add("BACK GROUND", "xk set " .. gi .. " col bg", x + 1, 1, xfb(function(s) return s.col == "bg" end))
      add("Single", "xk set " .. gi .. " single", x + 1, 2, xfb(function(s) return s.single end))
      -- the chase runs over the grid group or its linear version (one row)
      add("Linear", "xk set " .. gi .. " lin", x, 2, xfb(function(s) return s.lin end),
          {lbl = function(c) return (c.xk[gi] or {}).lin and "Linear" or "Grid" end})
      for i, p in ipairs(XK_PATTERNS) do
        local col, row = (i - 1) % 2, 3 + math.floor((i - 1) / 2)
        add(p[1], "xk set " .. gi .. " pattern " .. i, x + col, row, xfb(function(s) return s.pattern == i end))
      end
      -- the group's name with its number (unused slots keep the plain "G6")
      caption("G" .. gi, x, 7, {w = 2, lbl = gi <= NR and function()
        local n = TC.gname(gi)
        return n ~= "" and ("G" .. gi .. " " .. n) or ("G" .. gi) end or nil})
    end
    ghost, capGi = false, nil
    nav = 8.5
  elseif page == "home" then
    -- launcher (on a view button): what you play with first, then the setup tools
    caption("FireSystem", 0, -1.25, {w = 17, noIcon = true, tsize = "32"})
    recDot(17.25, -1.25)
    local function tile(label, arg, col, row, fb, o)
      o = o or {}
      o.w, o.h, o.tsize = o.w or 4, o.h or 2, "24"
      add(label, arg, col, row, fb or function() return "idle" end, o)
    end
    local function head(text, row) caption(text, 0, row, {w = 17, noIcon = true, tsize = "20"}) end
    sec("play")
    head("PLAY", 0)
    tile("Open FireSystem", "global open", 0, 2.25, function() return "fire" end)
    tile("Masters & Utility", "global mast", 4.33, 2.25, function() return "on" end)
    tile("Timecode", "tc view tc", 8.66, 2.25, function() return "on" end)
    tile("Recording", "tc view rec", 13, 2.25, function() return "on" end)
    sec("tools")
    head("SHOW TOOLS", 3.5)
    tile("Update Presets", "global upd", 0, 5.75)
    tile("Setlist (songs)", "tc view songs", 4.33, 5.75)
    tile("Same Size", "global fit", 8.66, 5.75, function() return on(gv("fit_mode") == "fill") end,
         {lbl = function() return gv("fit_mode") == "fill" and "Fill Screen" or "Same Size" end})
    tile("Console & Views", "global views", 13, 5.75)
    sec("setup")
    head("SETUP  (new show: Group Builder or Auto Groups, then Build / Update)", 7)
    tile("Build / Update FireSystem", "global setup", 0, 9.25, function() return "off" end)
    tile("Group Builder", "global groups", 4.33, 9.25)
    tile("Auto Groups (one per fixture type)", "global autogroups", 8.66, 9.25)
    tile("Patch RIG + Groups (from the plugin's RIG)", "global rig", 13, 9.25)
    tile("Masters (executor page)", "global masters", 0, 11.5)
    tile("Utility Page (exec page " .. CFG.UTIL_PAGE .. ")", "global utility", 4.33, 11.5)
    -- page backgrounds: pick a page (or All), then a background
    sec("bg")
    head("PAGE BACKGROUNDS  (pick a page, then a background)", 13.75)
    local tg = {{"all", "All Pages"}}
    for _, p in ipairs(PAGES) do if not TC.combo.DEF[p] then tg[#tg + 1] = {p, PAGE[p].title} end end
    tg[#tg + 1] = {"extra", "Home & Tools"}
    tg[#tg + 1] = {"fader", "Fader Bank"}
    local tw = 17 / #tg
    for i, t in ipairs(tg) do
      add(t[2], "global bgt " .. t[1], (i - 1) * tw, 15, function() return on((gv("bg_target") or "all") == t[1]) end,
          {w = tw - 0.1, tsize = "14", noIcon = true})
    end
    local bw = 17 / 7
    for i, b in ipairs(CFG.BACKGROUNDS) do
      add(b[1], "global bg " .. i, ((i - 1) % 7) * bw, 16.25 + math.floor((i - 1) / 7), function()
        local t = gv("bg_target") or "all"
        return on(TC.bg.index(t == "all" and "dim" or t) == i) end, {w = bw - 0.1, tsize = "16", noIcon = true})
    end
    nav = nil
  elseif page == "mast" then
    -- Masters & Utility: utility macros, page / wing of the executor window, navigation
    -- (6 across, so the layout fills the wide window next to the executors)
    caption("Masters & Utility", 0, -1.25, {w = 12, noIcon = true, tsize = "24"})
    recDot(12.25, -1.25)
    sec("util")
    for i, u in ipairs(CFG.UTIL_MACROS) do
      local x, y = ((i - 1) % 6) * 2, math.floor((i - 1) / 6)
      add(u[2], "util " .. u[1], x, y, function() return "idle" end, {w = 2, cmd = u[3], tsize = "14"})
    end
    local r = math.ceil(#CFG.UTIL_MACROS / 6) + 0.25
    sec("pages")
    add("Page 1 Playbacks", "util page1", 0, r, function() return "idle" end, {w = 4, cmd = {"Page " .. CFG.EXEC_PAGE}, tsize = "18"})
    add("Page 2 Group Masters", "util page2", 4, r, function() return "idle" end, {w = 4, cmd = {"Page 2"}, tsize = "18"})
    add("Page " .. CFG.UTIL_PAGE .. " Utility", "util page" .. CFG.UTIL_PAGE, 8, r, function() return "idle" end, {w = 4, cmd = {"Page " .. CFG.UTIL_PAGE}, tsize = "18"})
    for k = 1, 6 do
      add("Wing " .. k, "global wing " .. k, (k - 1) * 2, r + 1, function()
        return on((gv("wing") or "1") == tostring(k)) end, {w = 2, tsize = "18", noIcon = true})
    end
    sec("nav")
    add("Home", "global home", 0, r + 2.25, function() return "hdr" end, {w = 3})
    add("Open FireSystem", "global open", 3, r + 2.25, function() return "fire" end, {w = 3})
    add("Build Utility Page", "global utility", 6, r + 2.25, nil, {w = 3})
    add("Build Masters", "global masters", 9, r + 2.25, nil, {w = 3})
    nav = nil
  elseif page == "upd" then
    -- Update Presets: pick groups and a preset, tweak it in the programmer, UPDATE
    sec("tabs")
    for i, c in ipairs(TC.upd.CATS) do
      add(c[2], "upd cat " .. c[1], (i - 1) * 2, -1.25, function() return on(TC.upd.cat() == c[1]) end, {w = 2, tsize = "18", noIcon = true})
    end
    add("Home", "global home", #TC.upd.CATS * 2 + 0.25, -1.25, nil, {w = 2, tsize = "18"})
    recDot(#TC.upd.CATS * 2 + 2.5, -1.25)
    sec("g")
    for gi = 1, NG do ghost, capGi = gi > NR, gi
      add("G" .. gi, "upd grp " .. gi, 0, gi - 1, function(c) return on(c.sel[gi]) end, {icon = "g" .. gi})
      gName(gi, 0, gi - 1)
    end
    ghost, capGi = false, nil
    sec("main")
    local cat = TC.upd.cat()
    if cat == "meas" then
      -- Measure: one fixture at a time, one emitter at full, the rest of the rig dark (for a colour meter)
      local M = "upd meas "
      local function t(o) o.noIcon, o.tsize = true, o.tsize or "16" return o end
      caption("Measure", 1.25, 0, t({w = 10, lbl = function()
        local m = TC.meas.cur()
        if not m then return "Pick groups on the left (none = all): their fixtures, one at a time" end
        return string.format("Fixture %d %s  -  %s %s  (%d of %d)", m.fid, m.name, m.ft, m.mode,
          TC.meas.idx(), #TC.meas.list()) end}))
      add("< Prev", M .. "prev", 1.25, 1, nil, t({w = 2}))
      add("Next >", M .. "next", 3.25, 1, nil, t({w = 2}))
      add("Next Type >>", M .. "type", 5.25, 1, nil, t({w = 2}))
      add("Reload Fixtures", M .. "load", 7.25, 1, nil, t({w = 2}))
      add("Done", M .. "done", 9.25, 1, function() return "off" end, t({w = 2}))
      sec("em")
      for i = 1, TC.meas.SLOTS do
        local function em() local m = TC.meas.cur() return m, m and m.em[i] end
        add("Emitter " .. i, M .. "em " .. i, 1.25 + ((i - 1) % 5) * 2, 2.25 + math.floor((i - 1) / 5), function()
          local _, a = em()
          if not a then return "dis" end
          local ci = TC.meas.CI[a[2]]
          if not ci then return on(gv("meas_em") == a[1]) end
          return (gv("meas_em") == a[1] and "c" or "cs") .. ci end, t({w = 2, tsize = "14", dtxt = true, lbl = function()
          local m, a = em()
          if not a then return "" end
          local x, y = tostring(gv(TC.meas.key(m, a[1])) or ""):match("^(%S+) (%S+)")
          return x and string.format("%s  %.3f %.3f", a[2], tonumber(x), tonumber(y)) or a[2] end}))
      end
      sec("act")
      add("All Emitters", M .. "all", 1.25, 6.5, function() return on(gv("meas_em") == "all") end, t({w = 2, h = 2}))
      add("Dark", M .. "dark", 3.25, 6.5, function() return on(gv("meas_em") == "dark") end, t({w = 2, h = 2}))
      add("LOG READING", M .. "log", 5.5, 6.5, function() return "fire" end, t({w = 3, h = 2, tsize = "20"}))
      caption("Readings", 1.25, 7.75, t({w = 10, tsize = "14", lbl = function()
        local l = gv("meas_last")
        return (l and l ~= "") and ("Last: " .. l) or ("Readings go to gma3_library/" .. TC.meas.FILE) end}))
    else
      for i, p in ipairs(TC.upd.list(cat)) do
        local x, y = 1.25 + (i - 1) % 10, math.floor((i - 1) / 10)
        local id = p.skip and "" or (p[2] .. "." .. p[3])
        if p.skip then  -- an empty slot (a group the show doesn't use)
        elseif p[4] then
          add(" ", "upd recall " .. id, x, y, function()
            return ((gv("upd_last") == id) and "cs" or "c") .. p[4] end,
            {lbl = function() return gv("keep_" .. id) == "1" and "*" or " " end})
        else
          add(p[1], "upd recall " .. id, x, y, function()
            if gv("upd_last") == id then return "on" end
            return gv("keep_" .. id) == "1" and "pend" or "idle" end, {noIcon = not p[5], icon = p[5]})
        end
      end
      sec("act")
      local yo = math.max(0, math.ceil(#TC.upd.list(cat) / 10) - 3)  -- (Gobo Beam: more rows of presets)
      caption("Preset", 1.25, 3.25 + yo, {w = 6, noIcon = true, tsize = "18", lbl = function()
        local id = gv("upd_last")
        if not id or id == "" then return "Tap a preset: it loads for the selected groups" end
        return "Preset " .. id .. " " .. tostring(objName(obj("Preset " .. id)) or "") ..
          (gv("keep_" .. id) == "1" and "  (updated)" or "") end})
      add("UPDATE", "upd store", 1.25, 5.5 + yo, function() return "fire" end, {w = 3, h = 2, tsize = "24"})
      add("Clear", "upd clear", 4.5, 5.5 + yo, nil, {w = 2, h = 2, tsize = "18"})
      add("Revert to FireSystem", "upd revert", 6.75, 5.5 + yo, function() return "off" end, {w = 3, h = 2, tsize = "16"})
    end
    nav = nil
  elseif page == "tc" then
    -- Timecode: source (big toggle), mode, transport for the song picked on the Setlist
    caption("Timecode", 0, -1, {w = 8, noIcon = true, tsize = "24", lbl = function()
      return "Timecode: " .. (TC.name() or ("Song " .. TC.song() .. " (empty)")) end})
    recDot(8.25, -1)
    local function tile(label, arg, col, row, w, fb, o)
      o = o or {}
      o.w, o.h, o.tsize = w, 2, o.tsize or "20"
      add(label, arg, col, row, fb or function() return "idle" end, o)
    end
    for i, src in ipairs(TC.SOURCES) do
      tile(src[2], "tc source " .. src[1], (i - 1) * 2, 1, 2, function() return on(TC.source() == src[1]) end)
    end
    for i, m in ipairs(TC.MODES) do
      tile(m[2], "tc mode " .. m[1], (i - 1) * 2.75, 3.25, 2.5, function() return on(TC.mode() == m[1]) end)
    end
    tile("Top", "tc top", 0, 5.5, 2)
    tile("Play", "tc play", 2, 5.5, 2, function() return "on" end)
    tile("Pause", "tc pause", 4, 5.5, 2)
    tile("Stop", "tc stop", 6, 5.5, 2)
    tile("REC", "tc rec", 0, 7.75, 4, function() return TC.recording() and "live" or "fire" end,
         {tsize = "28", lbl = function() return TC.recording() and "RECORDING - tap to stop" or "REC" end})
    tile("< Song", "tc prev", 4.25, 7.75, 1.75)
    tile("Song >", "tc next", 6.25, 7.75, 1.75)
    tile("Setlist", "tc view songs", 0, 10, 2.5)
    tile("Recording", "tc view rec", 2.75, 10, 2.5)
    tile("Home", "global home", 5.5, 10, 2.5)
    tile("Edit Timecode", "tc view tced", 0, 12.25, 8, function() return "on" end,
         {lbl = function() return "Edit Timecode (every recorded event)" end})
    -- the transport row on every other page: on / off (the pages are rebuilt at once)
    tile("Controls on every page", "tc showbar", 0, 14.5, 8, function() return on(TC.barOn()) end,
         {lbl = function() return TC.barOn() and "Transport on every page: ON" or "Transport on every page: OFF" end})
    nav = nil
  elseif page == "songs" then
    -- Setlist: one timecode show per song (Timecode 201+)
    caption("Setlist", 0, -1, {w = 8.25, noIcon = true, tsize = "24"})
    recDot(8.5, -1)
    local half = math.ceil(CFG.TC_SONGS / 2)
    for i = 1, CFG.TC_SONGS do
      local col, row = (i > half) and 4.25 or 0, (i - 1) % half
      add("Song " .. i, "tc song " .. i, col, row, function()
        if TC.song() == i then return "on" end
        return TC.obj(i) and "idle" or "blind" end,
        {w = 4, tsize = "20", lbl = function() return i .. ".  " .. (TC.name(i) or "(empty)") end})
    end
    local r = half + 0.25
    add("Add Song", "tc add", 0, r, nil, {w = 2, tsize = "16"})
    add("Rename", "tc rename", 2, r, nil, {w = 2, tsize = "16"})
    add("Delete", "tc delete", 4.25, r, function() return "off" end, {w = 2, tsize = "16"})
    add("Timecode", "tc view tc", 6.25, r, function() return "on" end, {w = 2, tsize = "16"})
    nav = nil
  elseif page == "rec" then
    -- Recording: record the busking of the picked song (FireSystem on another screen)
    caption("Recording", 0, -1, {w = 8, noIcon = true, tsize = "24", lbl = function()
      return "Recording: " .. (TC.name() or ("Song " .. TC.song())) .. "  (" .. TC.label(TC.MODES, TC.mode()) .. ")" end})
    recDot(8.25, -1)
    add("REC", "tc rec", 0, 2, function() return TC.recording() and "live" or "fire" end,
        {w = 4, h = 3, tsize = "32", lbl = function() return TC.recording() and "RECORDING" or "REC" end})
    add("Stop", "tc stop", 4, 2, nil, {w = 4, h = 3, tsize = "32"})
    for i, m in ipairs(TC.MODES) do
      add(m[2], "tc mode " .. m[1], (i - 1) * 2.75, 4.25, function() return on(TC.mode() == m[1]) end,
          {w = 2.5, h = 2, tsize = "18"})
