    btn("-0.1s", "tced nudge -0.1", 2, R + 6.25, 1.75)
    btn("+0.1s", "tced nudge 0.1", 4, R + 6.25, 1.75)
    btn("+1s", "tced nudge 1", 6, R + 6.25, 1.75)
    btn("Set Time", "tced time", 8, R + 6.25, 1.75)
    btn("Jump", "tced jump", 10, R + 6.25, 2)
    btn("Timecode", "tc view tc", 0, R + 7.5, 2.75)
    btn("Recording", "tc view rec", 3, R + 7.5, 2.75)
    btn("Home", "global home", 6, R + 7.5, 2.75)
    nav = nil
  elseif page == "grp" then
    -- Group Builder: pick fixtures in the Selection Grid in stage order, then store
    caption("1. Select fixtures in the Selection Grid, in the order effects should run (e.g. left to right)",
      0, -2, {w = 16})
    caption("2. Tap Store G1-G8 and name the group.   3. DONE builds FireSystem with your groups.", 0, -1, {w = 16})
    for gi = 1, 8 do
      add("Store G" .. gi, "global storegrp " .. gi, (gi - 1) * 2, 1,
        function() return obj("Group " .. gi) and "on" or "idle" end,
        {w = 2, h = 2, lbl = function()
          local n = objName(obj("Group " .. gi))
          return n and ("G" .. gi .. "\n" .. n) or ("Store G" .. gi)
        end})
      add("Clear", "global cleargrp " .. gi, (gi - 1) * 2, 2, function() return "off" end, {w = 2})
      -- Edit Grid: selects the group so its fixtures can be arranged in the Selection Grid
      -- (Setup in the grid's title bar, then drag them, or the grid's tools); tap again to save
      add("Edit Grid", "global editgrp " .. gi, (gi - 1) * 2, 3,
        function() return gv("grp_edit") == tostring(gi) and "pend" or "idle" end,
        {w = 2, noIcon = true, lbl = function() return gv("grp_edit") == tostring(gi) and "Save Grid" or "Edit Grid" end})
      -- Features: turn colour, position, gobo ... on or off by hand when the detection got it wrong
      add("Features", "global grpfeat " .. gi, (gi - 1) * 2, 4,
        function() return TC.feat.count(gi) > 0 and "pend" or "idle" end,
        {w = 2, noIcon = true, lbl = function()
          local n = TC.feat.count(gi)
          return n > 0 and ("Features\n" .. n .. " set") or "Features"
        end})
    end
    -- linear versions (one row) for Bumps / X-Keys set to Linear; DONE builds the empty ones from G1-G8
    caption("Optional: Store L1-L8 = the same fixtures in one row (Bumps / X-Keys set to Linear). Empty ones are built from G1-G8.",
      0, 5.5, {w = 16})
    for gi = 1, 8 do
      add("Store L" .. gi, "global storelin " .. gi, (gi - 1) * 2, 6.5,
        function() return obj("Group " .. BM.linNo(gi)) and "on" or "idle" end,
        {w = 2, lbl = function()
          local n = objName(obj("Group " .. BM.linNo(gi)))
          return n and ("L" .. gi .. " " .. n) or ("Store L" .. gi)
        end})
      add("Clear", "global clearlin " .. gi, (gi - 1) * 2, 7.5, function() return "off" end, {w = 2})
    end
    add("Clear Selection", "global clearsel", 0, 9, function() return "idle" end, {w = 4})
    -- 3D Grid: the selection (none: the groups you pick) placed in the grid by stage position;
    -- the toggle makes Home > Auto Groups do the same with the groups it builds
    add("3D Grid", "global grid3d", 4.25, 9, function() return "idle" end, {w = 3.75, noIcon = true,
      lbl = function() return "3D Grid (selection or groups)" end})
    add("Auto 3D", "global grid3dauto", 8.25, 9, function() return on(gv("grid3d_auto") == "1") end, {w = 3.5, noIcon = true,
      lbl = function() return "Auto Groups 3D: " .. (gv("grid3d_auto") == "1" and "On" or "Off") end})
    add("DONE: Build FireSystem", "global grpdone", 12, 9, function() return "fire" end, {w = 4})
    -- the Utility page's groups (Front Wash, Specials, Haze ...): store the selection into one, or
    -- arrange it in the grid; Utility Page keeps them as you stored them from then on
    caption("Utility groups: Store = the selection, Edit Grid = arrange it (kept by Home > Utility Page).", 0, 10.5, {w = 16})
    for i, u in ipairs(CFG.UTIL) do
      local g = CFG.UTIL_GROUP_BASE + i - 1
      add("Store " .. u[1], "global storegrp " .. g .. " " .. fs(u[1]), (i - 1) * 2, 11.5,
        function() return obj("Group " .. g) and "on" or "idle" end, {w = 2, noIcon = true,
        lbl = function() return u[1] .. (obj("Group " .. g) and "" or " (empty)") end})
      add("Edit Grid", "global editgrp " .. g, (i - 1) * 2, 12.5,
        function() return gv("grp_edit") == tostring(g) and "pend" or "idle" end,
        {w = 2, noIcon = true, lbl = function() return gv("grp_edit") == tostring(g) and "Save Grid" or "Edit Grid" end})
    end
    recDot(16.25, -2)
  end
  if page == "gobo" then
    local gi, key = tonumber(gv("gp_g") or "") or 1, gv("gp_key") or "gobo1"
    caption("Gobo Picker", 0, -2, {w = 6, lbl = function()
      return string.format("G%d %s - tap a gobo", gi, (GOBO_WHEEL[key] or {attr = "?"}).attr)
    end})
    add("Back", "global page beam", 7, -2, function() return "hdr" end, {w = 3, lbl = function() return "Back" end})
    recDot(10.25, -2)
    for k = 1, GOBO_WHEEL.MAX do
      local col, row = ((k - 1) % 6) * 2, math.floor((k - 1) / 6) * 2
      add("", "global goboset " .. k, col, row, function(c)
        local st = c.gs and c.gs[gi]
        return (st and st[key] == k) and "on" or "idle"
      end, {w = 2, h = 2, gobo = k, lbl = function(c) local sl = c.wheel and c.wheel[k] return sl and sl.name or "" end})
    end
  end
  if page == "ccol" then
    caption("Custom colours: tap a value for R, G, B and W. COLOR 1-4 update live, also in running looks.", 0, -2, {w = 22})
    add("Back to Color", "global page col", 23, -2, function() return "hdr" end, {w = 3})
    recDot(26.25, -2)
    local CH = {{"R", "red"}, {"G", "green"}, {"B", "blue"}, {"W", "orange"}}
    for n = 1, #CFG.CUSTOM_COLORS do
      local x0, ci = (n - 1) * 6.75, NCOL + n
      add("COLOR " .. n, "global noop", x0, -1, function() return "cs" .. ci end, {w = 6})
      for r, ch in ipairs(CH) do
        caption(ch[1], x0, r - 1)
        for j, v in ipairs({0, 25, 50, 75, 100}) do
          add(tostring(v), string.format("global ccset %d %d %d", n, r, v), x0 + j, r - 1,
            function() return (customColor(n)[r] == v) and "on" or "idle" end, {fam = function() return ch[2] end})
        end
      end
    end
  end
  if emb then return B end  -- (part of a combined page: it adds the rest)
  if nav then
    -- below everything it spans: with few groups the MAtricks columns reach lower than the grid
    local right = #PAGES * 2 + 6.25
    for _, b in ipairs(B) do
      if b.col < right and b.sec ~= "ext" then nav = math.max(nav, b.row + 1.25) end
    end
    navRow(nav)
  end
  if TC.barOn() and not TC.BAR_SKIP[page] then tcBar() end
  -- one frame per section (2+ buttons), put first so it sits behind the buttons
  if CFG.SECTION_FRAMES then
    local box, order = {}, {}
    for _, b in ipairs(B) do
      if b.sec and b.sec ~= "ext" then
        local t = box[b.sec]
        if not t then t = {n = 0}; box[b.sec] = t; order[#order + 1] = b.sec end
        t.n = t.n + 1
        -- an element grows upward from its row: a button of height h covers rows row-h+1 .. row
        local top = b.row - b.h + 1
        t.c1 = math.min(t.c1 or b.col, b.col); t.r1 = math.min(t.r1 or top, top)
        t.c2 = math.max(t.c2 or (b.col + b.w), b.col + b.w); t.r2 = math.max(t.r2 or (b.row + 1), b.row + 1)
      end
    end
    -- each frame is four thin lines in the gap around the section, so it never covers a button
    local F = {}
    for _, k in ipairs(order) do
      local t = box[k]
      if t.n >= 2 then
        for _, side in ipairs({"top", "bottom", "left", "right"}) do
          F[#F + 1] = {label = "", arg = "global noop", col = t.c1, row = t.r2 - 1, w = 1, h = 1,
                       frame = side, bar = (k == "tcbar"), box = {t.c1, t.c2, t.r1, t.r2}, fb = function() return "frame" end}
        end
      end
    end
    for i = #F, 1, -1 do table.insert(B, 1, F[i]) end
  end
  -- macro of each button: the page's block, but the transport row has its own block, so
  -- switching it on or off never moves the page's macros (B.nMain = macros in the page's block)
  local nm, nb, nf, nn = 0, 0, 0, 0
  for _, b in ipairs(B) do
    if b.gname then  -- the group names: their own block (the pages' blocks are nearly full)
      nn = nn + 1
      b.M = CFG.NAME_MACRO + PAGE[page].i * 20 + nn - 1
    elseif b.bar or b.sec == "tcbar" then
      b.bar, nb = true, nb + 1
      b.M = CFG.TCBAR_MACRO + PAGE[page].i * 10 + nb - 1
    elseif b.fill then  -- the Colour Fill row: its own block
      nf = nf + 1
      b.M = CFG.FILL_MACRO + nf - 1
    else
      nm = nm + 1
      b.M = macroNo(page, nm)
    end
  end
  B.nMain = nm
  return B
end

-- ======================================================================
-- Feedback (button appearances and labels)
-- ======================================================================
function pagePresetKey(page, n) return "pp_" .. page .. "_" .. n end

-- text drawn on layout element n of a page (see CFG.ELEMENT_TEXT)
function setElementText(page, n, text)
  local lh = obj("Layout " .. layoutNo(page))
  local el = lh and lh[n]
  if not el then return false end
  local ok = pcall(function()
    if el.CustomTextText ~= text then el.CustomTextText = text end
  end)
  return ok
end

lastAp, lastTxt = {}, {}
TC.names = {}  -- text set on each button (see refresh)
-- transparent appearance for the section frames
function FN.frameAp()
  local no = CFG.APPEARANCE_BASE + 98
  if objName(obj("Appearance " .. no)) ~= fs("Frame Line") then
    C("Store Appearance %d /Overwrite", no)
    C("Label Appearance %d %s", no, q(fs("Frame Line")))
    C('Set Appearance %d Property "BackR" 90 "BackG" 90 "BackB" 90 "BackAlpha" 255', no)
  end
  return no
end
-- the recording dot (see recDot): red disc while recording, invisible (transparent) otherwise
function TC.recAp(rec)
  local no = CFG.APPEARANCE_BASE + (rec and 96 or 97)
  local want = fs(rec and "Rec Dot" or "Rec Hidden")
  if objName(obj("Appearance " .. no)) ~= want then
    if rec and CFG.ROUND and importImage(CFG.ROUND_DISC_IMAGE, "fs_disc.png") then
      makeImageAp(no, "Rec Dot", CFG.ROUND_DISC_IMAGE, {255, 0, 0})
    else
      C("Store Appearance %d /Overwrite", no)
      C("Label Appearance %d %s", no, q(want))
      if rec then setApColor(no, {220, 0, 0})
      else C('Set Appearance %d Property "BackR" 0 "BackG" 0 "BackB" 0 "BackAlpha" 0', no) end
    end
  end
  return no
end
-- what a page's buttons light up from (its groups' looks, selection, presets ...)
function TC.ctx(page)
  local sel = getSel(page)
  local ctx = {page = page, axis = getAxis(page), g = getGlobal(), sel = {}, selList = sel, dirty = false,
               gs = {}, pp = {}, bump = {}, xk = {}}
  for _, gi in ipairs(sel) do ctx.sel[gi] = true end
  for _, p in ipairs(FIRE_PAGES) do  -- the linked FIRE shows changes waiting on any page
    for gi = 1, TC.fill.n(p) do
      if not ctx.anyDirty and (deser(gv(p .. "_" .. gi)).dirty == true) then ctx.anyDirty = true end
    end
  end
  if LOOK_DEFAULTS[page] then
    for gi = 1, TC.fill.n(page) do
      ctx.gs[gi] = loadGroup(page, gi)
      if ctx.gs[gi].dirty then ctx.dirty = true end
    end
    ctx.st = ctx.gs[sel[1] or 1]
    for i = 1, 4 do
      local v = gv(pagePresetKey(page, i))
      ctx.pp[i] = type(v) == "string" and v ~= ""
    end
  elseif page == "bump" then
    ctx.bmTarget = BM.bumpTarget()
    ctx.bmInc = {}
    local inc = BM.bumpIncluded(ctx.bmTarget)
    for _, gi in ipairs(inc) do ctx.bmInc[gi] = true end
    ctx.bm = getBump(inc[1] or 1, ctx.bmTarget)
    ctx.bmKey = inc[1] or 1
    ctx.bmGrps = BM.grps(ctx.bm, ctx.bmKey)
    ctx.bmStep = math.min(BM.bumpEditStep(ctx.bmTarget), BM.isFlash(ctx.bm) and 1 or (tonumber(ctx.bm.steps) or 1))
  elseif page == "xk" then
    for gi = 1, #CFG.GROUPS do ctx.xk[gi] = getXk(gi) end
  elseif page == "gobo" then
    local gi, key = tonumber(gv("gp_g") or "") or 1, gv("gp_key") or "gobo1"
    for g2 = 1, #CFG.GROUPS do ctx.gs[g2] = loadGroup("beam", g2) end
    ctx.wheel = CFG.GROUPS[gi] and cachedWheel(CFG.GROUPS[gi], key) or {}
  end
  return ctx
end
function refresh(page)
  local spec = buildSpec(page)
  -- a combined page's buttons light up from their own page (b.pg)
  local ctxs = {}
  local function ctxOf(p) ctxs[p] = ctxs[p] or TC.ctx(p) return ctxs[p] end
  local buckets, icons = {}, iconsReady()
  for n, b in ipairs(spec) do
    local ctx, pg = ctxOf(b.pg or page), b.pg or page
    local k = b.fb and b.fb(ctx) or "idle"
    local sk = ICN.S.key(b)
    local apn = (b.rec and TC.recAp(k == "rec")) or (sk and ICN.S.ap(b.cat and "hdr" or k, sk))
                or (b.art and FN.artAp(k, b.art)) or (b.cat and ICN.catAp(b.cat)) or (b.axis and ICN.axisAp(ctx.axis)) or nil
    if b.frame then apn = FN.frameAp() end
    if k == "hide" then apn = TC.recAp(false) end  -- not in use right now: invisible (Color FX STEP rows)
    if b.gobo then
      local sl = ctx.wheel and ctx.wheel[b.gobo]
      apn = sl and goboAp(goboImage(sl.file, sl.path), k) or apNo(sl and k or "hdr")
    end
    -- Gobo page: the Zoom button shows the zoom level that is picked
    if pg == "beam" and not apn then
      local gz = tostring(b.arg):match(" pick (%d+) zoom$")
      local stz = gz and ctx.gs[tonumber(gz)]
      if stz and (stz.zoom or 0) > 0 then apn = FN.zoomAp(stz.zoom, k) end
    end
    -- Gobo page: a gobo button shows the gobo that is picked
    if pg == "beam" and not apn then
      local gi2, key2 = tostring(b.arg):match(" pick (%d+) (gobo%d)$")
      local st2 = gi2 and ctx.gs[tonumber(gi2)]
      if st2 and (st2[key2] or 0) > 0 and st2[key2 .. "f"] then
        apn = goboAp(goboImage(st2[key2 .. "f"], st2[key2 .. "d"]), k)
      end
    end
    -- which picture the button really got (the text under / instead of it depends on it)
    local pic = (apn and not b.rec and not b.frame) and true or false
    if not apn and CFG.ROUND and b.w == 1 and b.h == 1 and (ROUND_STATE[k] or k == "dis") then
      local fam = b.fam and b.fam(ctx)
      if icons and b.icon then apn = FN.roundIconAp(k, b.icon, fam) pic = apn ~= nil
      elseif not b.icon then
        fam = fam or textFamily(b.lbl and b.lbl(ctx) or b.label)
        if b.num and ICN.numReady() then apn = ICN.numAp(k, b.label, fam) pic = apn ~= nil end
        apn = apn or (fam and FN.roundTextAp(k, fam))
      end
    end
    local txt = "FFFFFFFF"
    if b.dtxt and type(k) == "string" and k:match("^c%d+$") then txt = "000000FF" end  -- (dark text on a bright swatch)
    if CFG.ROUND and b.w == 1 and b.h == 1 then
      if not apn and type(k) == "string" and k:match("^cs?%d+$") then
        -- Color page: each group's row shows its Pastel / Dark tint; the top row follows the selection
        local tint = 0
        if pg == "col" then
          local t = tostring(b.arg):match(" cell (%w+) color ")
          if t == "all" then  -- the top row shows a tint when every group has it
            local first = ctx.gs[1] and TC.part.tint(ctx.gs[1]) or 0
            tint = first
            for g2 = 2, #CFG.GROUPS do if (ctx.gs[g2] and TC.part.tint(ctx.gs[g2]) or 0) ~= first then tint = 0 end end
          else
            local st = tonumber(t) and ctx.gs[tonumber(t)]
            tint = st and TC.part.tint(st) or 0
          end
        elseif pg == "cfx" then  -- Color FX: each STEP row shows its Pastel / Dark
          local r = tostring(b.arg):match(" mx c(%d) ")
          tint = r and ctx.st and tonumber(ctx.st["t" .. r]) or 0
        end
        apn = FN.roundSwatchAp(k, tint)
      end
      -- active text discs are inverted: white disc, text in the family colour
      if apn and k == "on" and not b.icon then
        local fam = (b.fam and b.fam(ctx)) or textFamily(b.lbl and b.lbl(ctx) or b.label)
        if fam and ROUND_FAMILY_COLORS[fam] then txt = hex(ROUND_FAMILY_COLORS[fam][2]) end
      end
    end
    local Mt = b.pg and (page .. b.M) or b.M  -- (text is per layout: a combined page shares the Colour Fill macros)
    if lastTxt[Mt] ~= txt then
      local lh = obj("Layout " .. layoutNo(page))
      if lh and pcall(function() lh[n].CustomTextColor = txt end) then lastTxt[Mt] = txt end
    end
    if k == "dis" then k = "hdr" end  -- greyed out without round discs: the header look
    if not apn and icons and b.icon then apn = FN.iconAp(k, b.icon) pic = apn ~= nil end
    apn = apn or apNo(k)
    -- buttons built without text because their picture carries it (artwork, number disc, icon):
    -- when that picture isn't there (e.g. a show opened on another computer without
    -- FireSystem's PNGs), they show their name instead of nothing
    if CFG.ELEMENT_TEXT and (not b.lbl or b.axis) and not b.frame and not b.gobo then
      local want = b.label
      if pic and not ICN.S.key(b) and (b.art or b.num or b.icon or (b.cat and ICN.catMode(b.cat) == "full")) then want = "" end
      if pic and b.axis then want = "" end
      if b.axis and not pic then want = ctx.axis end
      if (b.icon and not pic or not b.icon) and TC.names[Mt] ~= want then
        if setElementText(page, n, want) then TC.names[Mt] = want end
      end
    end
    -- only buttons whose appearance changed since the last press (lastAp lives
    -- as long as the plugin is loaded; a reload or setup redraws everything)
    local M = b.M
    if lastAp[M] ~= apn then
      lastAp[M] = apn
      buckets[apn] = buckets[apn] or {}
      table.insert(buckets[apn], M)
    end
    if b.lbl and not b.axis then
      local want = b.lbl(ctx)
      -- category headers: the name is on the artwork, the text is just the value
      if b.cat and not ICN.S.key(b) and ICN.catMode(b.cat) == "top" and ICN.catAp(b.cat) and want:sub(1, #b.label + 1) == b.label .. " " then
        want = want:sub(#b.label + 2)
      end
      if not (CFG.ELEMENT_TEXT and setElementText(page, n, want)) then
        local M = b.M
        if trim(objName(obj("Macro " .. M))) ~= trim(want) then
          Cmd(string.format("Label Macro %d %s", M, q(want)))
        end
      end
    end
  end
  for apn, list in pairs(buckets) do
    nCmds = nCmds + 1
    Cmd(string.format("Assign Appearance %d At Macro %s", apn, rangeList(list)))
  end
  -- a page in a combined page: that one follows
  if not TC.combo.DEF[page] and not TC.combo.busy then
    for c, def in pairs(TC.combo.DEF) do
      if (def[1] == page or def[2] == page) and TC.combo.on(c) and obj("Layout " .. layoutNo(c)) then refresh(c) end
    end
  end
end

function refreshAll()
  TC.combo.busy = true  -- (the combined pages are in PAGES: each once)
  for _, p in ipairs(PAGES) do refresh(p) end
  TC.combo.busy = false
end

end

-- ==== FireSystemActions.lua (copied by tools/make_tools.py) ====
MODS.Actions = function(_ENV)

-- ======================================================================
-- Button actions
-- ======================================================================
-- groups a press acts on: in Multi mode a press on a selected group's row
-- also applies to the other selected groups
function targets(page, t)
  if t == "all" then
    local out = {}
    for gi = 1, #CFG.GROUPS do if TC.pcap(page, gi) then out[#out + 1] = gi end end
    return out
  end
  local gi = tonumber(t)
  if not gi or not (CFG.GROUPS[gi] or TC.fill.k(page, gi)) or not TC.pcap(page, gi) then return {} end
  if page == "col" then return {gi} end  -- Color page: every row is its own group (no selection)
  if not getGlobal().solo and isSel(page, gi) then
    local out = {}
    for _, n in ipairs(getSel(page)) do if TC.pcap(page, n) then out[#out + 1] = n end end
    return out
  end
  return {gi}
end

function forSelected(page, fn)
  local sel = getSel(page)
  if page == "col" then sel = {} end  -- Color page: no G buttons, so every row (Colour Fill too)
  if #sel == 0 then  -- no G selected: act on every group (and show them selected)
    for gi = 1, TC.fill.n(page) do sel[#sel + 1] = gi end
    setSel(page, sel)
  end
  for _, gi in ipairs(sel) do
    local st = loadGroup(page, gi)
    fn(st, gi)
    st.dirty = true
    saveGroup(page, gi, st)
  end
  return true
end

-- LIVE fires every change; a group set to LIVE (Gobo page) fires its own changes
function afterChange(page)
  if TC.ed.on(page) then return refresh(page) end  -- editing a recorded look: only FIRE saves it
  if getGlobal().live then firePage(page)
  else
    for gi = 1, #CFG.GROUPS do
      local st = loadGroup(page, gi)
      if st.live and st.dirty then fireGroup(page, gi, st) end
    end
  end
  refresh(page)
end

function askNumber(title, current)
  local ok, v = pcall(TextInput, title, tostring(current or 0))
  return ok and tonumber(v) or nil
end

function pageAction(page, act, a1, a2, a3)
  if page == "pfx" and act == "cell" and a2 == "tiltfx" and (tonumber(a3) or 0) > 4 then
    local ok, err = pcall(TC.flyPresets, true)
    if not ok then dbg("Fly presets failed: " .. tostring(err)) end
  end
  if page == "beam" and ((act == "pick" or act == "rot") and not TC.cap(a1, a2)
                         or (act == "cell" and a2 == "zoomfx" and not TC.cap(a1, "zoom"))) then
    return refresh(page)  -- greyed out: this group can't do it
  end
  -- the group has nothing this page sets (no Pan/Tilt on Position, no colour on Color ...)
  if (act == "grp" or act == "offgrp" or act == "fxsize" or act == "cell") and tonumber(a1)
     and not TC.pcap(page, tonumber(a1)) then
    return refresh(page)
  end
  if act:match("^spec") then TC.spec.action(act, a1)
  elseif act == "fire" then firePage(page)
  elseif act == "off" then offPage(page)
  elseif act == "offgrp" then offGroup(page, tonumber(a1))
  elseif act == "grp" then
    local gi, g = tonumber(a1), getGlobal()
    if g.solo then setSel(page, {gi})
    else
      local sel, out, found = getSel(page), {}, false
      for _, n in ipairs(sel) do if n == gi then found = true else out[#out + 1] = n end end
      if not found then out[#out + 1] = gi end
      setSel(page, out)
    end
  elseif act == "cell" then
    -- a1 = target, a2 = field, a3 = value; pressing an active cell switches it off
    local field, val, list = a2, parseVal(a3), targets(page, a1)
    local states, fld, allOn = {}, {}, true
    for _, gi in ipairs(list) do
      states[gi] = loadGroup(page, gi)
      -- Color page: the colour / tint of the half being set (TC.part)
      fld[gi] = (page == "col" and (field == "color" or field == "tint")) and TC.part.prep(states[gi], field) or field
      if states[gi][fld[gi]] ~= val then allOn = false end
    end
    for _, gi in ipairs(list) do
      local st = states[gi]
      if allOn then
        local d = (LOOK_DEFAULTS[page] or {})[fld[gi]]
        if d == nil then d = MX_DEFAULT[fld[gi]] end
        st[fld[gi]] = d
      else st[fld[gi]] = val end
      if page == "col" and field == "tint" and TC.part.cur() == "all" then st.tint2 = st.tint end
      if page == "pfx" and not allOn and (val or 0) ~= 0 then
        -- the circle (Cloud) moves pan and tilt, so it replaces the other FX and vice versa
        -- (the size stays: - / + set it for all of the group's position FX)
        if field == "tiltfx" and val == 4 then st.panfx = 0
        elseif field == "panfx" and st.tiltfx == 4 then st.tiltfx = 0 end
      end
      st.dirty = true
      saveGroup(page, gi, st)
    end
    return afterChange(page)
  elseif act == "clearall" then
    for gi = 1, TC.fill.n(page) do
      local st = loadGroup(page, gi)
      clearLook(page, st)
      for k, v in pairs(MX_DEFAULT) do st[k] = v end
      st.dirty = true
      saveGroup(page, gi, st)
    end
    return afterChange(page)
  elseif act == "mxclear" then
    local function reset(st) for k, v in pairs(MX_DEFAULT) do if k ~= "live" then st[k] = v end end end
    if a1 then
      local gi = tonumber(a1)
      local st = loadGroup(page, gi)
      reset(st); st.dirty = true; saveGroup(page, gi, st)
    elseif not forSelected(page, reset) then return refresh(page) end
    return afterChange(page)
  elseif act == "part" then  -- Color page: the half a colour press sets (TC.part)
    sv("col_part", a1)
  elseif act == "axis" then  -- the big X: step the MAtricks columns through X, Y and Z
    sv("axis_" .. page, FN.AXIS_NEXT[getAxis(page)])
  elseif act == "steps" then  -- Color FX arrows: one colour (step) more or less, 2-5
    local d = tonumber(a1) or 0
    if forSelected(page, function(st) st.n = math.max(2, math.min(TC.CFX_MAX, #TC.cfxCols(st) + d)) end) then
      return afterChange(page)
    end
  elseif act == "mx" then
    local ri = page == "cfx" and tonumber(a1:match("^c(%d)$") or "")
    if ri and ri > 2 then  -- a STEP row that is hidden: nothing to pick
      local sel = getSel(page)
      if #TC.cfxCols(loadGroup(page, sel[1] or 1)) < ri then return refresh(page) end
    end
    local v, k = parseVal(a2), axKey(getAxis(page), a1)
    -- pressing the value that is already set on every selected group clears it
    local sel, allOn = getSel(page), true
    if #sel == 0 then allOn = false end
    for _, gi in ipairs(sel) do if loadGroup(page, gi)[k] ~= v then allOn = false end end
    if allOn and IS_AXIS_FIELD[a1] then v = MX_DEFAULT[k] end
    if allOn and (a1 == "tint" or a1:match("^t%d$")) then v = 0 end  -- Pastel / Dark again = normal colours
    local kb = axKey(getAxis(page), "bpm")  -- a speed button replaces a typed speed
    if forSelected(page, function(st) st[k] = v if a1 == "speed" then st[kb] = 0 end end) then return afterChange(page) end
  elseif act == "mxt" then
    local k = axKey(getAxis(page), a1)
    if forSelected(page, function(st) st[k] = not st[k] end) then return afterChange(page) end
  elseif act == "mxedit" then  -- the person buttons: type your own value
    local k, sel = axKey(getAxis(page), a1), getSel(page)
    local v
    if a1 == "rate" then  -- typed as a factor (2, 4, 0.5 ...): the nearest power of two
      local f = askNumber("Rate (speed master x)", 2 ^ (sel[1] and loadGroup(page, sel[1]).rate or 0))
      if f and f > 0 then v = math.max(-8, math.min(8, math.floor(math.log(f) / math.log(2) + 0.5))) end
      k = "rate"
    else
      v = askNumber(getAxis(page) .. " " .. (a1 == "bpm" and "Speed (BPM)" or a1), sel[1] and loadGroup(page, sel[1])[k] or 0)
    end
    local ks = axKey(getAxis(page), "speed")
    if v and forSelected(page, function(st) st[k] = v if a1 == "bpm" then st[ks] = 0 end end) then return afterChange(page) end
  elseif act == "fxfade" then  -- FX Fade: seconds between fires (0 = off)
    local v = askNumber("FX Fade: seconds a FIRE fades into the new effect (0 = off)", TC.fxFade(page))
    if v and v >= 0 then sv("fxfade_" .. page, tostring(v)) end
  elseif act == "fxsize" then  -- Position FX - / +: smaller / bigger effects, again = normal
    local sz = tonumber(a2) or 2
    local list, allOn = targets(page, a1), true
    for _, gi in ipairs(list) do if loadGroup(page, gi).size ~= sz then allOn = false end end
    for _, gi in ipairs(list) do
      local st = loadGroup(page, gi)
      st.size = allOn and 2 or sz
      st.dirty = true
      saveGroup(page, gi, st)
    end
    return afterChange(page)
  elseif act == "circle" then  -- older layouts: small / big circle, again = off
    local sz = tonumber(a2) or 2
    local list, allOn = targets(page, a1), true
    for _, gi in ipairs(list) do
      local st = loadGroup(page, gi)
      if not (st.tiltfx == 4 and st.size == sz) then allOn = false end
    end
    for _, gi in ipairs(list) do
      local st = loadGroup(page, gi)
      if allOn then st.tiltfx, st.size = 0, 2
      else st.panfx, st.tiltfx, st.size = 0, 4, sz end
      st.dirty = true
      saveGroup(page, gi, st)
    end
    return afterChange(page)
  elseif act == "size" then  -- Position FX - / +
    for _, gi in ipairs(targets(page, a1)) do
      local st = loadGroup(page, gi)
      st.size = math.max(1, math.min(3, st.size + tonumber(a2)))
      st.dirty = true
      saveGroup(page, gi, st)
    end
    return afterChange(page)
  elseif act == "rot" then  -- Gobo page: rotation, each tap = next option
    local gi, key = tonumber(a1), a2
    local b
    for _, x in ipairs(CFG.BEAM) do if x.key == key then b = x end end
    if not (b and b.rotFn and CFG.GROUPS[gi]) then return end
    local ki = ({gobo1 = 0, prism = 1, shape = 2})[key] or 0
    for _, g2 in ipairs(targets(page, gi)) do
      local st = loadGroup(page, g2)
      local v = ((tonumber(st[key .. "rot"]) or 0) + 1) % (#ROT_OPTS + 1)
      st[key .. "rot"], st[key .. "rotp"] = v, nil
      if v > 0 then
        local r = FN.rotDMX(CFG.GROUPS[g2], b.rotFn, ROT_OPTS[v])
        if r then
          local rp = CFG.ROT_POOL[key] or {5, CFG.ROT_PRESET_BASE}
          local pool, no = rp[1], rp[2] + (g2 - 1) * 30 + ki * 10 + v
          local want = fs(string.format("G%d %s %s", g2, b.label, ROT_OPTS[v][1]))
          if objName(obj(string.format("Preset %d.%d", pool, no))) ~= want then
            C("ClearAll"); C("Group %d", CFG.GROUPS[g2])
            C("Attribute %s At Decimal8 %d", q(r.attr), r.dmx)
            Cany({ string.format("Store Preset %d.%d /Overwrite /Selective", pool, no), string.format("Store Preset %d.%d /Overwrite", pool, no) })
            C("Label Preset %d.%d %s", pool, no, q(want))
            C("ClearAll")
          end
          st[key .. "rotp"] = no
        else
          Echo("FireSystem: G" .. g2 .. " has no " .. b.label .. " rotation")
        end
      end
      st.dirty = true
      saveGroup(page, g2, st)
    end
    return afterChange(page)
  elseif act == "pick" then  -- Gobo page: choose from a list of presets
    if (a2 == "gobo1" or a2 == "gobo2") and CFG.GROUPS[tonumber(a1) or 0] and cachedWheel(CFG.GROUPS[tonumber(a1)], a2) then
      sv("gp_g", a1); sv("gp_key", a2)
      if FS_openExtraPage then return FS_openExtraPage("gobo") end
    end
    -- a prism: the group's own prism slots from its fixture profile, stored as presets when picked
    local ps = a2 == "prism" and CFG.GROUPS[tonumber(a1) or 0] and FN.prismSets(CFG.GROUPS[tonumber(a1)])
    if ps then
      local gi, items = tonumber(a1), {"None"}
      for _, sl in ipairs(ps) do items[#items + 1] = sl.name end
      local st = loadGroup(page, gi)
      local ok, idx, value = pcall(PopupInput, {title = "Prism G" .. gi, caller = GetFocusDisplay(),
                                                 items = items, selectedValue = st.prismn or "None"})
      local choice
      if ok and value then
        for i, it in ipairs(items) do if it == value then choice = i - 1 end end
      elseif ok and type(idx) == "number" then choice = idx end
      if choice == nil then return refresh(page) end
      for _, g2 in ipairs(targets(page, gi)) do
        local s2, sets2, k2 = loadGroup(page, g2), CFG.GROUPS[g2] and FN.prismSets(CFG.GROUPS[g2]), 0
        if g2 == gi then k2 = choice
        elseif choice > 0 and sets2 then  -- another selected group: its slot with the same name
          for k = #sets2, 1, -1 do if sets2[k].name == items[choice + 1] then k2 = k end end
        end
        if choice == 0 or k2 > 0 then
          s2.prism, s2.prismp, s2.prismn = k2, nil, nil
          if k2 > 0 then s2.prismp, s2.prismn = FN.prismPreset(g2, k2, sets2[k2]), sets2[k2].name end
          s2.dirty = true
          saveGroup(page, g2, s2)
        end
      end
      return afterChange(page)
    end
    local gi, b = tonumber(a1), nil
    for _, x in ipairs(CFG.BEAM) do if x.key == a2 then b = x end end
    if not b then return end
    local items = {"None"}
    for i, pno in ipairs(b.presets) do items[#items + 1] = presetName(b.pool, pno) or (b.label .. " " .. i) end
    local st = loadGroup(page, gi)
    local ok, idx, value = pcall(PopupInput, {title = b.label .. " G" .. gi, caller = GetFocusDisplay(),
                                               items = items, selectedValue = items[(st[b.key] or 0) + 1]})
    local choice
    if ok and value then
      for i, it in ipairs(items) do if it == value then choice = i - 1 end end
    elseif ok and type(idx) == "number" then choice = idx
    elseif not ok then choice = ((st[b.key] or 0) + 1) % (#b.presets + 1) end  -- no popup: step through
    if choice == nil then return refresh(page) end
    for _, g2 in ipairs(targets(page, gi)) do
      local s2 = loadGroup(page, g2)
      s2[b.key], s2.dirty = choice, true
      s2[b.key .. "p"], s2[b.key .. "n"], s2[b.key .. "f"], s2[b.key .. "d"] = nil, nil, nil, nil  -- (not the group's own any more)
      saveGroup(page, g2, s2)
    end
    return afterChange(page)
  elseif act == "recallgrp" then  -- undo pending changes: back to what was last fired
    local gi = tonumber(a1)
    local f = gv("fired_" .. page .. "_" .. gi)
    local st = loadGroup(page, gi)
    if type(f) == "string" and f ~= "" then
      for k, v in pairs(LOOK_DEFAULTS[page] or {}) do st[k] = v end  -- (fields newer than the saved look)
      for k, v in pairs(deser(f)) do st[k] = v end
    end
    st.dirty = false
    saveGroup(page, gi, st)
  elseif act == "pstore" then  -- Store Preset: the whole page (every group) into slot n
    local t = {}
    for gi = 1, TC.fill.n(page) do
      local st = loadGroup(page, gi)
      st.dirty = nil
      t[gi] = ser(st)
    end
    sv(pagePresetKey(page, a1), table.concat(t, "|"))
    Echo("FireSystem: stored " .. PAGE[page].title .. " preset " .. a1)
  elseif act == "precall" then
    local s = gv(pagePresetKey(page, a1))
    if type(s) ~= "string" or s == "" then Echo("FireSystem: preset " .. a1 .. " is empty") return refresh(page) end
    local gi = 0
    for part in (s .. "|"):gmatch("([^|]*)|") do
      gi = gi + 1
      if CFG.GROUPS[gi] or TC.fill.k(page, gi) then
        local st = loadGroup(page, gi)
        for k, v in pairs(LOOK_DEFAULTS[page] or {}) do st[k] = v end  -- (fields newer than the preset)
        for k, v in pairs(deser(part)) do st[k] = v end
        st.dirty = true
        saveGroup(page, gi, st)
      end
    end
    return afterChange(page)
  end
  refresh(page)
end

-- a combined page's shared MAtricks: the top page takes the press, then the page below gets the
-- same MAtricks (every axis) on its selected groups (all of them when none is selected)
function TC.combo.action(page, act, a1, a2, a3)
  local A, Bp = TC.combo.DEF[page][1], TC.combo.DEF[page][2]
  pageAction(A, act, a1, a2, a3)
  sv("axis_" .. Bp, getAxis(A))
  local src = loadGroup(A, getSel(A)[1] or 1)
  local keys = {}
  for k in pairs(MX_DEFAULT) do
    if k ~= "live" then keys[#keys + 1] = k end  -- (MX_DEFAULT holds the y_ / z_ keys too)
  end
  local list = getSel(Bp)
  if Bp == "col" or #list == 0 then list = {} for gi = 1, TC.fill.n(Bp) do list[#list + 1] = gi end end
  local diff = false
  for _, gi in ipairs(list) do
    local st = loadGroup(Bp, gi)
    for _, k in ipairs(keys) do if st[k] ~= src[k] then diff = true end end
  end
  if not diff then return refresh(Bp) end
  forSelected(Bp, function(st) for _, k in ipairs(keys) do st[k] = src[k] end end)
  afterChange(Bp)
end

function FN.bumpAction(act, a1, a2)
  local slot = BM.bumpTarget()
  local inc = BM.bumpIncluded(slot)
  if act == "target" then
    sv("bm_target", tostring(tonumber(a1) or 1))
  elseif act == "inc" then
    -- one group at a time: tapping a G button edits just that group's bump
    local gi = tonumber(a1)
    if gi and CFG.GROUPS[gi] then sv("bm_inc_" .. slot, tostring(gi)) end
  elseif act == "step" then
    if not (BM.isFlash(getBump(inc[1] or 1, slot)) and (tonumber(a1) or 1) > 1) then
      sv("bm_step_" .. slot, tostring(tonumber(a1) or 1))
    end
  elseif act == "flash" then  -- the included groups' bumps become Flash keys (again = Go+)
    local want = not BM.isFlash(getBump(inc[1] or 1, slot))
    for _, gi in ipairs(inc) do
      if CFG.GROUPS[gi] then
        local b = getBump(gi, slot)
        b.flash = want
        setBump(gi, slot, b)
        rebuildBump(gi, slot)
      end
    end
    if want then sv("bm_step_" .. slot, "1") end
  elseif act == "mst" then  -- a master group comes up and strobes with the bumps (again = off)
    local b0 = getBump(inc[1] or 1, slot)
    local want = nil
    if not b0.mgrp then
      -- suggest a group named "...master..." (else the group's Masters group)
      local def = obj("Group " .. BM.masterNo(CFG.GROUPS[inc[1] or 1] or 1)) and BM.masterNo(CFG.GROUPS[inc[1] or 1] or 1)
      pcall(function()
        for _, h in ipairs(ShowData().DataPools.Default.Groups:Children()) do
          if not def and tostring(h.name):lower():find("master") then def = tonumber(h.no) end
        end
      end)
      want = askNumber("Master group (main fixtures with the shutter)", def or 0)
      if not want or want <= 0 or not obj("Group " .. want) then return refresh("bump") end
    end
    for _, gi in ipairs(inc) do
      if CFG.GROUPS[gi] then
        local b = getBump(gi, slot)
        b.mgrp = want
        setBump(gi, slot, b)
        rebuildBump(gi, slot)
      end
    end
  elseif act == "grp" then  -- LOS: the groups the edited key fires on (own / all / toggle one)
    local key = inc[1] or 1
    if not CFG.GROUPS[key] then return refresh("bump") end
    local b = getBump(key, slot)
    local t = BM.grps(b, key)
    if a1 == "own" then t = {key}
    elseif a1 == "all" then t = {} for gx = 1, #CFG.GROUPS do t[#t + 1] = gx end
    else
      local gx, out, had = tonumber(a1), {}, false
      if not (gx and CFG.GROUPS[gx]) then return refresh("bump") end
      for _, x in ipairs(t) do if x == gx then had = true else out[#out + 1] = x end end
      if not had then out[#out + 1] = gx end
      if #out == 0 then return refresh("bump") end  -- (a key always fires on at least one group)
      t = out
    end
    table.sort(t)
    b.grps = table.concat(t, ",")
    setBump(key, slot, b)
    rebuildBump(key, slot)
  elseif act == "axis" then  -- the MAtricks buttons edit X (columns), Y (rows) or Z (depth)
    sv("axis_bump", FN.AXIS_NEXT[getAxis("bump")])
  elseif act == "lin" then  -- the included groups' bumps run over the linear group (again = grid)
    local want = not getBump(inc[1] or 1, slot).lin
    for _, gi in ipairs(inc) do
      if CFG.GROUPS[gi] then
        local b = getBump(gi, slot)
        b.lin = want
        setBump(gi, slot, b)
        rebuildBump(gi, slot)
      end
    end
  elseif act == "steps" or act == "set" or act == "mxpreset" or act == "edit" then
    if act == "edit" then  -- type your own value (MAtricks of the step, or a time of the bump)
      local b0 = getBump(inc[1] or 1, slot)
      local key = BM.IS_MX[a1] and (BM.axisKey() .. a1 .. BM.bumpEditStep(slot)) or a1
      local title = a1
      for _, f in ipairs(BM.MX) do if f[1] == a1 then title = f[2] .. " (step " .. BM.bumpEditStep(slot) .. ")" end end
      for _, t in ipairs(BM.TIME) do if t[1] == a1 then title = t[2] .. (a1 == "wings" and "" or " (seconds)") end end
      local v = askNumber(title, b0[key] or 0)
      if not v then return refresh("bump") end
      act, a2 = "set", tostring(BM.IS_MX[a1] and math.floor(v) or v)
    end
    -- every included group gets the change, then its bump is rebuilt
    local step = BM.bumpEditStep(slot)
    for _, gi in ipairs(inc) do
      if CFG.GROUPS[gi] then
        local b = getBump(gi, slot)
        if act == "steps" then
          b.steps = tonumber(a1) or 1
        elseif act == "mxpreset" then
          local pr = BM.MXP[tonumber(a1) or 1] or BM.MXP[1]
          local ax = BM.axisKey()
          b[ax .. "mb" .. step], b[ax .. "mg" .. step], b[ax .. "mw" .. step], b[ax .. "mp" .. step] = pr[3], pr[4], pr[5], pr[6]
        else
          local v = tonumber(a2) or 0
          local timing = false
          for _, t in ipairs(BM.TIME) do if t[1] == a1 then timing = true end end
          if timing then b[a1] = v
          elseif BM.IS_MX[a1] then b[BM.axisKey() .. a1 .. step] = v
          elseif a1 == "col" then b["col" .. step] = v
          else b[a1 .. step] = (v == 1) and 0 or v end
        end
        setBump(gi, slot, b)
        rebuildBump(gi, slot)
      end
    end
    if act == "steps" and step > (tonumber(a1) or 1) then sv("bm_step_" .. slot, tostring(a1)) end
  end
  if TC.recording() then TC.rec.bumps() end  -- recording: the timecode puts the new settings back
  refresh("bump")
end

function FN.xkAction(act, a1, a2, a3)
  local gi = tonumber(a1)
  if act == "copy" then  -- copy this group's X-Key settings to every group
    local x = getXk(gi)
    for g2 = 1, #CFG.GROUPS do setXk(g2, x); rebuildXk(g2) end
    return refresh("xk")
  end
  local x = getXk(gi)
  if a2 == "zoom" then x.zoom = not x.zoom
  elseif a2 == "single" then x.single = not x.single
  elseif a2 == "lin" then x.lin = not x.lin
  elseif a2 == "col" then x.col = (x.col == a3) and "none" or a3
  elseif a2 == "pattern" then x.pattern = tonumber(a3) end
  setXk(gi, x)
  rebuildXk(gi)
  refresh("xk")
end

end

-- ==== FireSystemSetup.lua (copied by tools/make_tools.py) ====
MODS.Setup = function(_ENV)

-- ======================================================================
-- SETUP
-- ======================================================================
function isOurs(h)
  local n = objName(h)
  if n and n:sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " " then return true end
  -- button macros carry their label as name ("0", "X"...): they are ours when
  -- they call this plugin, or when this show was already set up by FireSystem
  local cls
  pcall(function() cls = h:GetClass() end)
  if cls == "Macro" then
    local mine = GetVar(GlobalVars(), "FS_icons_ok") ~= nil
    pcall(function()
      for i = 1, h:Count() do
        if tostring(h[i].Command or ""):find(CFG.PLUGIN_NAME, 1, true) then mine = true end
      end
    end)
    return mine
  end
  return false
end
BM.isOurs = isOurs  -- (for the bump code above)

function allSequences()
  local t = {}
  for _, page in ipairs(FIRE_PAGES) do
    for gi = 1, #CFG.GROUPS do t[#t + 1] = {seqNo(page, gi), page, string.format(FN.SEQ_NAME[page], gi)} end
  end
  for slot = 1, 3 do
    for gi = 1, #CFG.GROUPS do t[#t + 1] = {bumpSeq(slot, gi), "bump", "G" .. gi .. "_" .. CFG.BUMP_NAMES[slot]} end
  end
  for gi = 1, #CFG.GROUPS do t[#t + 1] = {xkSeq(gi), "xk", "XKeys_G" .. gi .. "_Chase"} end
  t[#t + 1] = {CFG.STROBE_SEQ, "bump", "Strobe All"}
  for k in ipairs(TC.fill.list()) do
    local _, u = TC.fill.entry(k)
    t[#t + 1] = {seqNo("col", #CFG.GROUPS + k), "col", u[1] .. " Color"}
  end
  return t
end

function FN.plannedObjects()
  local t = {}
  local function p(path) t[#t + 1] = path end
  for _, page in ipairs(PAGES) do
    p("Layout " .. layoutNo(page))
    for _, b in ipairs(buildSpec(page)) do p("Macro " .. b.M) end
  end
  for _, s in ipairs(allSequences()) do p("Sequence " .. s[1]) end
  for k in pairs(AP) do p("Appearance " .. apNo(k)) end
  p("MAtricks " .. CFG.MATRICKS_WORK)
  if CFG.CREATE_PRESETS then
    for i = 1, #DIM_FORMS do p("Preset 1." .. dimPreset(i)) end
    for _, f in ipairs(STROBES) do p("Preset " .. STROBES.pool .. "." .. f[2]) end
    for i = 1, NCOL do p("Preset 4." .. colorPreset(i)) end
    for _, f in ipairs(PANS) do if f[2] then p("Preset 2." .. f[4]) end end
    for _, f in ipairs(TILTS) do if f[2] then p("Preset 2." .. f[4]) end end
    for i, f in ipairs(PAN_FX) do if f[2] then for s = 1, 3 do p("Preset 2." .. panFxPreset(i, s)) end end end
    for i = 1, #TILT_FX do for s = 1, 3 do local no, pool = tiltFxPreset(i, s) p("Preset " .. pool .. "." .. no) end end
  end
  return t
end

function storePreset(pool, no, label, lines)
  -- updated on the Update Presets page: yours now, setup leaves it alone (Revert hands it back)
  if gv("keep_" .. pool .. "." .. no) == "1" then dbg(string.format("Preset %d.%d kept (updated by you)", pool, no)) return end
  -- a preset that's already there is left alone ("global presets" makes them all again)
  if not BM.forcePresets and presetExists(pool, no) then dbg(string.format("Preset %d.%d kept (already there)", pool, no)) return end
  C("ClearAll")
  C(groupList())
  for _, l in ipairs(lines) do
    -- "?" = optional (an attribute some fixtures don't have): no failure if refused
    if l == CFG.SNAP_CMD or l:sub(1, 1) == "?" then Cmd((l:gsub("^%?", ""))) else C(l) end
  end
  -- Selective: every fixture keeps exactly these values (Universal presets get
  -- converted per fixture type, which washed the colours out and lost the fans)
  Cany({ string.format("Store Preset %d.%d /Overwrite /Selective", pool, no),
         string.format("Store Preset %d.%d /Overwrite", pool, no) })
  C("Label Preset %d.%d %s", pool, no, q(fs(label)))
  C("ClearAll")
end

-- phaser steps; snaps[i] = true makes step i hard
function steps(attr, values, snaps)
  local l = {}
  for i, v in ipairs(values) do
    if i > 1 then l[#l + 1] = "Step " .. i end
    l[#l + 1] = string.format('Attribute %s At %s', q(attr), tostring(v))
  end
  -- hard steps: "Step n At Transition 0" (a plain "At Transition 0" doesn't stick)
  for i = 1, #values do
    if snaps == true or (type(snaps) == "table" and snaps[i]) then
      l[#l + 1] = string.format("Step %d At Transition 0", i)
    end
  end
  return l
end

-- smooth (sine) curve: every step accelerates out and decelerates in, as in
-- MA's "Create a Sinus Dimmer Phaser"
function eased(lines, n)
  for i = 1, n do
    lines[#lines + 1] = string.format("Step %d At Acceleration -100", i)
    lines[#lines + 1] = string.format("Step %d At Deceleration -100", i)
  end
  return lines
end

-- Pan and Tilt share an activation group: setting one puts the other in the programmer
-- at its current value (centre), and a tilt preset would then reset the pan fan of the
-- line before it. Knock the other attribute out before storing.
function without(attr, lines)
  lines[#lines + 1] = groupList()
  lines[#lines + 1] = string.format("?Off Attribute %s", q(attr))
  return lines
end

function num(v) return (math.floor(v) == v) and string.format("%d", v) or string.format("%.1f", v) end

function FN.dimFormLines(shape, n)
  local D = CFG.ATTR.dim
  if shape == "full" then return {string.format("Attribute %s At 100", q(D))} end
  if shape == "half" then return {string.format("Attribute %s At 50", q(D))} end
  if shape == "fan" then return eased(steps(D, {0, 100}), 2) end
  -- width 1/n: the shape, then n-1 empty steps
  local vals, snaps
  if shape == "sine" then vals, snaps = {100, 0}, {false, false}
  elseif shape == "down" then vals, snaps = {100, 0}, {true, false}
  elseif shape == "up" then vals, snaps = {100, 0}, {false, true}
  else vals, snaps = {100, 0}, {true, true} end
  for _ = 3, n + 1 do vals[#vals + 1] = 0; snaps[#snaps + 1] = true end
  local l = steps(D, vals, snaps)
  if shape == "sine" then eased(l, 2) end
  return l
end

function createPresets()
  local A = CFG.ATTR
  for i, f in ipairs(DIM_FORMS) do storePreset(1, dimPreset(i), f[2], FN.dimFormLines(f[3], f[4])) end
  -- strobe attributes are in Hz (60 was out of range and "Failed");
  -- fixtures that only have Sh1 get its "Strobe" channel set instead
  -- per group from its fixture profile (the strobe range of its shutter, or a dimmer chase)
  local function strobeAll(kind)
    local l = {}
    for _, g in ipairs(CFG.GROUPS) do
      l[#l + 1] = "ClearSelection"
      l[#l + 1] = "Group " .. g
      for _, x in ipairs(BM.strobeLines(g, kind)) do l[#l + 1] = x end
    end
    return l
  end
  BM.shut = {}
  local mg = BM.masterGroups()
  if #mg > 0 then
    local l = {"ClearSelection"}
    for _, M in ipairs(mg) do l[#l + 1] = "Group " .. M end
    l[#l + 1] = string.format("Attribute %s At 100", q(A.dim))
    storePreset(STROBES.pool, STROBES.mfull, "Masters Full", l)
  end
  for i, o in ipairs(BM.OPTS) do storePreset(STROBES.pool, CFG.BUMP_PRESET + i - 1, "Bump " .. o[3], BM.optLines(i)) end
  storePreset(STROBES.pool, STROBES[1][2], "Strobe",     strobeAll("strobe"))
  storePreset(STROBES.pool, STROBES[2][2], "Pulse Strb", strobeAll("pulse"))
  storePreset(STROBES.pool, STROBES[3][2], "Rnd Strobe", strobeAll("random"))
  for gi, g in ipairs(CFG.GROUPS) do
    local name = objName(obj("Group " .. g)) or ("G" .. gi)
    for _, k in ipairs(STROBES.grp) do
      local l = {"ClearSelection", "Group " .. g}
      for _, x in ipairs(BM.strobeLines(g, k[1] == "gen" and "random" or k[1])) do l[#l + 1] = x end
      -- 21.241-246 held Fly In / Out before they moved to 21.271-276: those are replaced
      local was = tostring(objName(obj(string.format("Preset %d.%d", STROBES.pool, STROBES.no(k[1], gi)))) or "")
      local force = BM.forcePresets
      if was:find("^Fly") then BM.forcePresets = true end
      storePreset(STROBES.pool, STROBES.no(k[1], gi), k[2] .. " " .. name, l)
      BM.forcePresets = force
    end
  end
  for _, f in ipairs(STROBES) do  -- the old copies in the Dimmer pool
    local h = obj("Preset 1." .. f[2])
    if h and isOurs(h) then Cmd(string.format("Delete Preset 1.%d /NC", f[2])) end
  end
  for i, c in ipairs(CFG.COLORS) do
    -- white only for White, the other extra emitters off
    local white = (c[3][1] >= 100 and c[3][2] >= 100 and c[3][3] >= 100) and 100 or 0
    storePreset(4, colorPreset(i), c[1], colorLines(tintRGBW(c[3], white, 0)))
    storePreset(4, tintPreset(i, 1), c[1] .. " Pastel", colorLines(tintRGBW(c[3], white, 1)))
    storePreset(4, tintPreset(i, 2), c[1] .. " Dark", colorLines(tintRGBW(c[3], white, 2)))
  end
  local F = CFG.PAN_FAN
  -- groups whose own fixtures have Pan: pixel / cell groups of a moving light
  -- would otherwise overwrite its fan with their own spread
  local panGroups = {}
  pcall(function()
    local pa = GetAttributeIndex(A.pan)
    for _, g in ipairs(CFG.GROUPS) do
      Cmd("ClearAll"); Cmd("Group " .. g)
      local fi = SelectionFirst()
      if fi and GetUIChannelIndex(fi, pa) then panGroups[#panGroups + 1] = g end
    end
    Cmd("ClearAll")
  end)
  if #panGroups == 0 then panGroups = CFG.GROUPS end
  dbg("pan fans on groups " .. table.concat(panGroups, ","))
  for _, p in ipairs(PANS) do
    if p[2] and type(p[3]) == "string" then
      storePreset(2, p[4], p[2], without(A.tilt, BM.panPattern(panGroups, p[3], F)))
    elseif p[2] then
      local a, b = p[3][1] * F, p[3][2] * F
      local v = (a == b) and num(a) or (num(a) .. " Thru " .. num(b))
      -- spread within each group (one "Thru" over the whole rig fanned across all groups)
      local l = {}
      for _, g in ipairs(panGroups) do
        l[#l + 1] = "ClearSelection"  -- keeps the values already set, so each group fans on its own
        l[#l + 1] = "Group " .. g
        l[#l + 1] = string.format("Attribute %s At %s", q(A.pan), v)
      end
      storePreset(2, p[4], p[2], without(A.tilt, l))
    end
  end
  for _, t in ipairs(TILTS) do
    if t[2] then storePreset(2, t[4], t[2], without(A.pan, {string.format("Attribute %s At %d", q(A.tilt), t[3])})) end
  end
  -- starter zoom presets (DMX steps, so they work on any fixture): narrow -> full
  for i, z in ipairs({{"Zoom Narrow", 0}, {"Zoom Mid", 85}, {"Zoom Wide", 170}, {"Zoom Full", 255}}) do
    storePreset(6, 200 + i, z[1], {string.format("?Attribute %s At Decimal8 %d", q("Zoom"), z[2])})
  end
  -- Zoom FX: a sine between narrow and full
  storePreset(6, CFG.ZOOM_FX_PRESET, "Zoom Sine", eased({
    string.format("?Attribute %s At Decimal8 0", q("Zoom")), "Step 2",
    string.format("?Attribute %s At Decimal8 255", q("Zoom")) }, 2))
  -- Position FX in three sizes. Relative (CFG.PFX_RELATIVE): the steps are typed on the
  -- Relative layer around 0, so they move around wherever the heads are pointing
  local REL = CFG.PFX_RELATIVE
  local T0 = REL and 0 or CFG.FX_TILT
  local function fx(lines)
    if not REL then return lines end
    -- a typed At value lands on the Absolute layer even with Relative selected: name the layer
    for i, l in ipairs(lines) do lines[i] = l:gsub("^(Attribute .- At )(%-?[%d%.]+)$", "%1Relative %2") end
    table.insert(lines, 1, "Relative")
    lines[#lines + 1] = "Absolute"
    return lines
  end
  for s, Z in ipairs(CFG.FX_SIZE) do
    local tag = ({" -", "", " +"})[s]
    storePreset(2, panFxPreset(1, s), "Pan Swing" .. tag, fx(without(A.tilt, eased(steps(A.pan, {-Z, Z}), 2))))
    storePreset(2, panFxPreset(2, s), "Pan Left" .. tag, fx(without(A.tilt, eased(steps(A.pan, {-2 * Z, 0}), 2))))
    storePreset(2, panFxPreset(3, s), "Pan Right" .. tag, fx(without(A.tilt, eased(steps(A.pan, {0, 2 * Z}), 2))))
    storePreset(2, panFxPreset(4, s), "Pan Wide" .. tag, fx(without(A.tilt, eased(steps(A.pan, {-2 * Z, 2 * Z}), 2))))
    storePreset(2, tiltFxPreset(1, s), "Tilt Swing" .. tag, fx(without(A.pan, eased(steps(A.tilt, {T0 - Z, T0 + Z}), 2))))
    storePreset(2, tiltFxPreset(2, s), "Tilt Up" .. tag, fx(without(A.pan, eased(steps(A.tilt, {T0, T0 + Z}), 2))))
    storePreset(2, tiltFxPreset(3, s), "Tilt Down" .. tag, fx(without(A.pan, eased(steps(A.tilt, {T0 - Z, T0}), 2))))
    -- circle: 12 points on a real circle (the old 4 points made a tiny diamond)
    local R, circ = CFG.CIRCLE_SIZE[s] or Z, {}
    for i = 1, 12 do
      local a = (i - 1) * math.pi / 6
      if i > 1 then circ[#circ + 1] = "Step " .. i end
      circ[#circ + 1] = string.format("Attribute %s At %s", q(A.pan), num(math.floor(R * math.sin(a) * 10 + 0.5) / 10))
      circ[#circ + 1] = string.format("Attribute %s At %s", q(A.tilt), num(math.floor((T0 + R * math.cos(a)) * 10 + 0.5) / 10))
    end
    storePreset(2, tiltFxPreset(4, s), "Circle" .. tag, fx(circ))
  end
  TC.flyPresets()
end

-- Fly In / Out (tilt FX 5 and 6): fade up, sweep the tilt, fade out, go back dark (the MAtricks
-- spread makes the wave). They move and dim, so they live in the All pool. missing = only the
-- ones not there yet (made on the first press, so no Build / Update is needed)
function TC.flyPresets(missing)
  local A, REL = CFG.ATTR, CFG.PFX_RELATIVE
  local tc = REL and 0 or CFG.FX_TILT
  -- every MA phaser step owns an equal slot: slot 1 snaps the dimmer on (dimmer Transition 0)
  -- while the tilt already sweeps, slots 2-3 sweep on and fade out, slot 4 goes back dark and
  -- slot 5 waits there dark, so the heads have settled before the next snap on (no bounce)
  local function fly(a, b)
    local d = (b - a) / 3
    local T, D, l = {a + d, a + 2 * d, b, a, a}, {100, 50, 0, 0, 0}, {}
    if REL then l[1] = "Relative" end
    for i = 1, #T do
      l[#l + 1] = "Step " .. i
      l[#l + 1] = string.format("Attribute %s At %s%s", q(A.tilt), REL and "Relative " or "", num(T[i]))
    end
    if REL then l[#l + 1] = "Absolute" end
    for i = 1, #D do
      l[#l + 1] = "Step " .. i
      l[#l + 1] = string.format("Attribute %s At %d", q(A.dim), D[i])
      if i == 1 then l[#l + 1] = string.format("Attribute %s At Transition 0", q(A.dim)) end
    end
    return without(A.pan, l)
  end
  for s, Z in ipairs(CFG.FX_SIZE) do
    local tag = ({" -", "", " +"})[s]
    for fi, f in ipairs({{"Fly In", tc + Z, tc - Z}, {"Fly Out", tc - Z, tc + Z}}) do
      local no, pool = tiltFxPreset(4 + fi, s)
      if not (missing and presetExists(pool, no) and gv("fly_ver") == "6") then storePreset(pool, no, f[1] .. tag, fly(f[2], f[3])) end
    end
  end
  sv("fly_ver", "6")  -- bump when the Fly steps or numbers change: older Fly presets are remade on the next press
end

function createAppearances()
  for i, a in ipairs(AP_LIST) do
    local no, rgb = CFG.APPEARANCE_BASE + i - 1, a[3]
    C("Store Appearance %d /Overwrite", no)
    C("Label Appearance %d %s", no, q(fs(a[2])))
    setApColor(no, rgb)
  end
end

-- Imports fs_<name>.png into Image 3.201+ (slots that already hold an
-- image are kept, so you can also import them yourself in the Images pool).
function importIcons()
  for k in pairs(iconApSeen) do iconApSeen[k] = nil end
  if not CFG.ICONS then sv("icons_ok", "") return end
  -- a new show: the looks pack (global looks export) brings every icon at once
  if FS_packImport and not obj("Appearance " .. CFG.APPEARANCE_BASE) then FS_packImport() end
  local dir = PATHS.media()
  local found, missing = 0, {}
  for i, name in ipairs(ICON_LIST) do
    local no, file = CFG.ICON_IMAGE_BASE + i - 1, "fs_" .. name .. ".png"
    if not obj(imagePath(i)) then
      local wrote = PATHS.put(file)
      Cany({
        string.format('Import Image %d.%d /File "%s" /Path "%s" /NoConfirm', CFG.IMAGE_POOL, no, file, dir),
        string.format('Import Image %d.%d /File "%s" /Path "%s"', CFG.IMAGE_POOL, no, file, dir),
        string.format('Import Image "Images".%d /File "%s" /Path "%s"', no, file, dir),
        string.format('Import Image %d.%d /File "%s"', CFG.IMAGE_POOL, no, file),
      })
      PATHS.drop(file, wrote)
    end
    if obj(imagePath(i)) then
      found = found + 1
      Cmd(string.format("Label %s %s", imagePath(i), q(fs(name))))
    else missing[#missing + 1] = file end
  end
  sv("icons_ok", found > 0 and "1" or "")
  if #missing > 0 then
    failures[#failures + 1] = string.format("Icons: %d of %d images could not be imported from %s " ..
      "(first: %s). Copy the PNGs from the icons folder there, or import them into Image %d.%d+ " ..
      "yourself, then run setup again.", #missing, #ICON_LIST, dir, missing[1], CFG.IMAGE_POOL, CFG.ICON_IMAGE_BASE)
  end
end

-- links a sequence to a speed / playback master. MA takes the master's name ("Speed4",
-- "Playback2"); "Speed 4" is accepted too but leaves the link at None, so read it back.
function trySeqMaster(seq, prop, kind, n)
  if not n or n == 0 then return end
  local want = kind .. n
  local named = (CFG.MASTER_NAMES[kind] or {})[n]  -- (the master may carry its FireSystem name)
  local function linked()
    local v
    pcall(function() v = tostring(DataPool().Sequences[seq]:Get(prop, Enums.Roles.Display)) end)
    return v == want or (named ~= nil and v == named)
  end
  if linked() then return true end
  for _, val in ipairs({q(want), q(kind .. " " .. n), tostring(n), named and q(named) or nil}) do
    Cmd(string.format('Set Sequence %d Property %s %s', seq, q(prop), val))
    if linked() then dbg(string.format("Sequence %d %s = %s", seq, prop, want)) return true end
  end
  failures[#failures + 1] = string.format("Sequence %d: could not link %s %s", seq, prop, want)
  return false
end

-- executor colours and master names (Home > Build / Update, and 'global looks')
TC.look = {seen = {}}
function TC.look.ap(kind)
  for i, l in ipairs(CFG.EXEC_LOOKS) do
    if l[1] == kind then
      local no, want = CFG.EXEC_AP_BASE + i - 1, fs("exec " .. l[2])
      if not TC.look.seen[no] then  -- once per press: label and colour (the colour may have changed)
        TC.look.seen[no] = true
        if not obj("Appearance " .. no) then C("Store Appearance %d", no) end
        if objName(obj("Appearance " .. no)) ~= want then C("Label Appearance %d %s", no, q(want)) end
        setApColor(no, l[3])
      end
      return no
    end
  end
end
-- what = "Sequence 101", "Group 1", "Macro 1000" or a master {kind, n}
function TC.look.give(kind, what)
  local no = TC.look.ap(kind)
  if not no or not what then return end
  if type(what) == "string" then
    if obj(what) then C("Assign Appearance %d At %s", no, what) end
    return
  end
  local mk, n = what[1], what[2]
  local ok = false
  pcall(function()
    local m = ShowData().Masters[mk][n]
    m.Appearance = obj("Appearance " .. no)
    ok = m.Appearance ~= nil
  end)
  if not ok then
    Cany({ string.format('Assign Appearance %d At Master "%s".%d', no, mk, n),
           string.format('Assign Appearance %d At Master %s.%d', no, mk, n) })
  end
end
function TC.look.masters()
  for mk, names in pairs(CFG.MASTER_NAMES) do
    for n, name in ipairs(names) do
      local cur
      pcall(function() cur = ShowData().Masters[mk][n].name end)
      if cur ~= name then
        local ok = pcall(function() ShowData().Masters[mk][n].name = name end)
        pcall(function() ok = ShowData().Masters[mk][n].name == name end)
        if not ok then
          Cany({ string.format('Label Master "%s".%d %s', mk, n, q(name)),
                 string.format('Label Master %s.%d %s', mk, n, q(name)) })
        end
        dbg(string.format("Master %s %d named %s (was %s)", mk, n, name, tostring(cur)))
      end
      TC.look.give(mk == "Speed" and "speed" or "pb", {mk, n})
      local sc = (CFG.MASTER_SPEEDSCALE[mk] or {})[n]
      if sc then
        local ok = pcall(function() ShowData().Masters[mk][n].SpeedScale = sc end)
        pcall(function() ok = tostring(ShowData().Masters[mk][n].SpeedScale) == sc end)
        if not ok then Cmd(string.format('Set Master "%s".%d Property "SpeedScale" "%s"', mk, n, sc)) end
      end
    end
  end
end
TC.ex = {}
-- executor ex of page pg (its handle), or nil
function TC.ex.handle(pg, ex)
  local h
  pcall(function() for _, c in ipairs(DataPool().Pages[pg]:Children()) do if tonumber(c.No) == ex then h = c end end end)
  return h
end
-- sets an executor's key / fader / fix (from Lua; the property names MA's executors use)
function TC.ex.set(pg, ex, key, fader, fix)
  local c = TC.ex.handle(pg, ex)
  if not c then return end
  if fader then pcall(function() c.FADER = fader end) end
  if key then pcall(function() c.Key = key end) end
  if fix ~= nil then pcall(function() c.FIX = fix and "Yes" or "No" end) end
end
-- the copies in CFG.EXEC_COPIES whose object exists, on executors that are empty (or hold it)
function TC.ex.copies(onlyUtil)
  for _, e in ipairs(CFG.EXEC_COPIES or {}) do
    local pg, ex, what = e[1], e[2], e[3]
    local ui = tonumber(tostring(what):match("^util(%d+)$"))
    if (ui ~= nil) == (onlyUtil == true) then
      local addr, key, fader
      if ui and CFG.UTIL[ui] then
        local u = CFG.UTIL[ui]
        if u.specials then addr = "Group " .. (CFG.UTIL_GROUP_BASE + ui - 1)
        else
          addr = "Sequence " .. (CFG.UTIL_SEQ_BASE + ui - 1)
          key, fader = (u[3] == "dim") and "Toggle" or "Go+", (u[3] == "dim") and "Master" or "X"
        end
      elseif what == "fire" and CFG.FIRE_MACRO then addr = "Macro " .. CFG.FIRE_MACRO
      else
        local kind, n = tostring(what):match("^(%a+)(%d+)$")
        if kind then addr = string.format('Master "%s".%s', kind, n) end
      end
      if addr and (addr:sub(1, 6) == "Master" or obj(addr)) then
        if not obj("Page " .. pg) then C("Store Page %d", pg) end
        local path = string.format("Page %d.%d", pg, ex)
        local cur, free = obj(path), true
        pcall(function() local o = cur and cur.Object free = (o == nil) or isOurs(o) or o:GetClass():find("Master") ~= nil end)
        if free then
          Cany({ string.format("Assign %s At %s", addr, path) })
          TC.ex.set(pg, ex, key, fader, e.fix)
        else
          dbg(path .. " is in use - copy of " .. what .. " left out")
        end
      end
    end
  end
end

-- executor positions: Masters & Utility > Save Executor Positions remembers where FireSystem's
-- executors are now (after you move them in MA), and setup puts them there from then on
-- (GlobalVar FS_exec_map: key=p<page>x<exec>). Reset Executor Positions goes back to CFG.
TC.ex = TC.ex or {}
-- every executor FireSystem places: {key, class, object no, default page, default exec}
function TC.ex.slots()
  local t = {}
  local SEQ = {dim = function(gi) return seqNo("dim", gi) end, dimfader = function(gi) return seqNo("dim", gi) end,
    bump = function(gi) return bumpSeq(1, gi) end, rnd = function(gi) return bumpSeq(2, gi) end,
    strobe = function(gi) return bumpSeq(3, gi) end, xk = function(gi) return xkSeq(gi) end}
  for gi = 1, #CFG.GROUPS do
    for _, r in ipairs(CFG.EXEC_ROWS) do
      local pg = r.page or CFG.EXEC_PAGE
      if r.what == "group" then t[#t + 1] = {"group" .. gi, "Group", CFG.GROUPS[gi], pg, r.base + gi}
      elseif SEQ[r.what] then t[#t + 1] = {r.what .. gi, "Sequence", SEQ[r.what](gi), pg, r.base + gi} end
    end
  end
  local P = CFG.EXEC_PAGE
  t[#t + 1] = {"strobeall", "Sequence", CFG.STROBE_SEQ, P, CFG.STROBE_EXEC}
  if CFG.WHITE_EXEC then t[#t + 1] = {"white", "Sequence", CFG.WHITE_SEQ, P, CFG.WHITE_EXEC} end
  if CFG.LOOKS_EXEC then t[#t + 1] = {"looks", "Sequence", CFG.LOOKS_SEQ, P, CFG.LOOKS_EXEC} end
  if CFG.FIRE_MACRO and CFG.FIRE_EXEC then t[#t + 1] = {"fire", "Macro", CFG.FIRE_MACRO, P, CFG.FIRE_EXEC} end
  for _, m in ipairs(CFG.MASTER_EXECS or {}) do t[#t + 1] = {"m" .. m[2] .. m[3], "Master", m[2] .. m[3], m[4] or P, m[1]} end
  for i, u in ipairs(CFG.UTIL or {}) do
    t[#t + 1] = u.specials and {"util" .. i, "Group", CFG.UTIL_GROUP_BASE + i - 1, CFG.UTIL_PAGE, u[4]}
                or {"util" .. i, "Sequence", CFG.UTIL_SEQ_BASE + i - 1, CFG.UTIL_PAGE, u[4]}
  end
  return t
end
-- where key's executor goes: the saved position, else the default
function TC.ex.at(key, pg, ex)
  local v = deser(gv("exec_map"))[key]
  local p, e = tostring(v or ""):match("^p(%d+)x(%d+)$")
  if p then return tonumber(p), tonumber(e) end
  return pg, ex
end
-- the slot an executor's object belongs to (nil if it isn't one of ours)
function TC.ex.match(slots, o)
  local cls, no, name = "", nil, ""
  pcall(function() cls = tostring(o:GetClass()) end)
  pcall(function() no = tonumber(o.No) end)
  pcall(function() name = tostring(o.name) end)
  for _, sl in ipairs(slots) do
    if sl[2] == "Master" then
      local kind, n = sl[3]:match("^(%a+)(%d+)$")
      local named = (CFG.MASTER_NAMES[kind] or {})[tonumber(n)]
      if cls:find("Master") and (name == sl[3] or name == named or name == kind .. " " .. n) then return sl end
    elseif cls == sl[2] and no == sl[3] then
      return sl
    end
  end
end
-- after Reset: clears the executors at the old saved positions (only those still holding our
-- object), so the defaults don't leave a copy behind. util = the Utility page's (START.utility)
function TC.ex.tidy(util)
  local old = deser(gv("exec_old"))
  if next(old) == nil then return end
  local slots = TC.ex.slots()
  for _, sl in ipairs(slots) do
    local v = old[sl[1]]
    if v and (sl[1]:match("^util") ~= nil) == util then
      old[sl[1]] = nil
      local p, e = tostring(v):match("^p(%d+)x(%d+)$")
      p, e = tonumber(p), tonumber(e)
      local tp, te = TC.ex.at(sl[1], sl[4], sl[5])
      if p and (p ~= tp or e ~= te) then
        pcall(function()
          for _, c in ipairs(DataPool().Pages[p]:Children()) do
            if tonumber(c.No) == e and c.Object and TC.ex.match({sl}, c.Object) then
              C("Delete Page %d.%d /NC", p, e)
            end
          end
        end)
      end
    end
  end
  sv("exec_old", ser(old))
end
function TC.ex.save()
  local slots, map, moved, found = TC.ex.slots(), {}, {}, 0
  pcall(function()
    for _, page in ipairs(DataPool().Pages:Children()) do
      local pg = tonumber(page.No)
      for _, c in ipairs(page:Children()) do
        local o
        pcall(function() o = c.Object end)
        local sl = o and TC.ex.match(slots, o)
        if sl and not map[sl[1]] then
          local ex = tonumber(c.No)
          map[sl[1]] = string.format("p%dx%d", pg, ex)
          found = found + 1
          if pg ~= sl[4] or ex ~= sl[5] then moved[#moved + 1] = string.format("%s %d.%d", sl[1], pg, ex) end
        end
      end
    end
  end)
  if found == 0 then
    MessageBox({title = "FireSystem", message = "Found none of FireSystem's executors - nothing saved.",
      commands = {{value = 1, name = "OK"}}})
    return
  end
  sv("exec_map", ser(map))
  sv("exec_old", "")
  dbg("exec map: " .. ser(map))
  MessageBox({title = "FireSystem", message = string.format(
    "Saved the positions of %d executors.\n%s\n\nBuild / Update now keeps them there.", found,
    #moved > 0 and ("Moved from the default: " .. table.concat(moved, ", ")) or "All are in their default places."),
    commands = {{value = 1, name = "OK"}}})
end

-- a bump step's own sequence (made when the bump is built)
function BM.ensureStepSeq(ss, gi, slot, k)
  local h = obj("Sequence " .. ss)
  if h and not isOurs(h) then failures[#failures + 1] = "Sequence " .. ss .. " is in use (bump step)" return end
  if not h then C("Store Sequence %d /Overwrite", ss) end
  C("Label Sequence %d %s", ss, q(fs(string.format("G%d_%s Step %d", gi, CFG.BUMP_NAMES[slot], k))))
  C('Set Sequence %d Property "Priority" "High"', ss)
  trySeqMaster(ss, "SpeedMaster", "Speed", CFG.SPEED_MASTER.bump)
  trySeqMaster(ss, "PlaybackMaster", "Playback", CFG.PLAYBACK_MASTER.bump)
  trySeqMaster(ss, "RateMaster", "Speed", CFG.RATE_MASTER.bump)
end

-- ---- Specials (Dimmer page corner) ---------------------------------------
TC.spec = {}
function TC.spec.entry() for i, u in ipairs(CFG.UTIL) do if u.specials then return i, u end end end
function TC.spec.seq(i) return CFG.SPECIAL_SEQ + i - 1 end
function TC.spec.fade() return math.max(0, tonumber(gv("spec_fade") or "") or 0) end
-- on = toggled on here and still playing (a fade-out or an Off elsewhere shows as off)
function TC.spec.on(i) return gv("spec_on_" .. i) == "1" and TC.playingCue(TC.spec.seq(i)) ~= nil end
function TC.spec.set(i, on)
  sv("spec_on_" .. i, on and "1" or "0")
  C("%s Sequence %d", on and "Go+" or "Off", TC.spec.seq(i))
end
-- the Specials group (made from UTIL's fixtures when the show doesn't have it yet)
function TC.spec.group()
  local i, u = TC.spec.entry()
  if not i then return nil end
  local g = CFG.UTIL_GROUP_BASE + i - 1
  if not obj("Group " .. g) and u[2] and u[2] ~= "" then
    local okFix = false
    pcall(function() local l = ObjectList("Fixture " .. u[2]) okFix = l and #l > 0 end)
    if okFix then
      C("ClearAll") C("Fixture %s", u[2])
      C("Store Group %d /Overwrite", g) C("Label Group %d %s", g, q(fs(u[1])))
      C("ClearAll")
    end
  end
  return obj("Group " .. g) and g or nil
end
-- one sequence per special: its fixture at Full in cue 1 (toggled from the Dimmer page)
function TC.spec.build()
  local g = TC.spec.group()
  if not g then
    local _, u = TC.spec.entry()
    MessageBox({title = "FireSystem", message = "The specials need their group: store the special fixtures into Group " ..
      (CFG.UTIL_GROUP_BASE + (TC.spec.entry() or 2) - 1) .. " (or set them in UTIL: " .. tostring(u and u[2]) .. ").",
      commands = {{value = 1, name = "OK"}}})
    return false
  end
  BM.units[g] = nil
  BM.part(g, {g = 1, w = 1, b = 0, p = 1})  -- the group's elements, left to right
  local cells, order, key = {}, {}, BM.unitKey()
  for _, u in ipairs(BM.gridSort(BM.units[g] or {})) do
    local k = key(u)
    if not cells[k] then cells[k] = {} order[#order + 1] = k end
    table.insert(cells[k], u.addr)
  end
  for i = 1, CFG.SPECIALS do
    local seq, sh = TC.spec.seq(i), obj("Sequence " .. TC.spec.seq(i))
    if sh and not isOurs(sh) then
      failures[#failures + 1] = "Sequence " .. seq .. " is in use - Special " .. i .. " skipped"
    elseif order[i] then
      local addr = table.concat(cells[order[i]], " + ")
      C("ClearAll") Cmd(addr)
      local name = "Special " .. i
      pcall(function() name = tostring(GetSubfixture(SelectionFirst()).name or name) end)
      C('Attribute "Dimmer" At 100')
      C("Store Sequence %d Cue 1 /Overwrite", seq)
      C("Label Sequence %d %s", seq, q(fs("Special " .. i)))
      sv("spec_name_" .. i, name)
      C("ClearAll")
    elseif sh then
      C("Delete Sequence %d /NC", seq)
      sv("spec_name_" .. i, "")
    end
  end
  sv("spec_built", tostring(g) .. ":" .. #order)
  TC.spec.setFade(TC.spec.fade())
  return true
end
function TC.spec.setFade(t)
  sv("spec_fade", tostring(t))
  for i = 1, CFG.SPECIALS do
    local seq = TC.spec.seq(i)
    if obj("Sequence " .. seq) then
      BM.partProp(seq, 1, "CueInFade", tostring(t))
      Cany({ string.format('Set Sequence %d Cue "OffCue" Part 0 Property "CueInFade" %s', seq, tostring(t)),
             string.format('Set Sequence %d Cue "OffCue" CueFade %s', seq, tostring(t)) })
    end
  end
end
function TC.spec.action(act, a1)
  if act == "spec" then
    local i = tonumber(a1)
    if not i then return end
    if (gv("spec_built") or "") == "" or not obj("Sequence " .. TC.spec.seq(i)) then
      if not TC.spec.build() then return end
    end
    if not obj("Sequence " .. TC.spec.seq(i)) then return end
    TC.spec.set(i, not TC.spec.on(i))
  elseif act == "specfade" then
    local v = askNumber("Specials: fade in / out in seconds", TC.spec.fade())
    if v and v >= 0 then TC.spec.setFade(v) end
  elseif act == "specoff" then
    for i = 1, CFG.SPECIALS do if obj("Sequence " .. TC.spec.seq(i)) then TC.spec.set(i, false) end end
  elseif act == "specbuild" then  -- re-reads the Specials group (after you changed it)
    TC.spec.build()
  end
end

function FN.createSequences()
  for _, s in ipairs(allSequences()) do
    local seq, page = s[1], s[2]
    C("Store Sequence %d /Overwrite", seq)
    C("Label Sequence %d %s", seq, q(fs(s[3])))
    if CFG.HIGH_PRIORITY[page] then C('Set Sequence %d Property "Priority" "High"', seq) end
    trySeqMaster(seq, "SpeedMaster", "Speed", CFG.SPEED_MASTER[page])
    trySeqMaster(seq, "PlaybackMaster", "Playback", CFG.PLAYBACK_MASTER[page])
    trySeqMaster(seq, "RateMaster", "Speed", CFG.RATE_MASTER[page])
  end
end

function addMacroLine(m, cmdText)
  local ok = pcall(function()
    local line = m:Append()
    line:Set("Command", cmdText)
  end)
  if not ok then
    ok = pcall(function()
      local line = m:Create(1)
      line:Set("Command", cmdText)
    end)
  end
  return ok
end

function createLayoutsAndMacros(pages)
  local W, H, G = CFG.BTN_W, CFG.BTN_H, CFG.GAP
  for _, page in ipairs(pages or PAGES) do sv("fit_" .. page, "1,1") end  -- fresh: not stretched (layoutFix fits them)
  local hideNames
  for _, page in ipairs(pages or PAGES) do
    local L = layoutNo(page)
    C("Store Layout %d /Overwrite", L)
    local lh = obj("Layout " .. L)
    if lh then pcall(function() for i = lh:Count(), 1, -1 do lh:Delete(i) end end) end
    C("Label Layout %d %s", L, q(fs(PAGE[page].title)))
    for n, b in ipairs(buildSpec(page)) do
      local M = b.M
      C("Store Macro %d /Overwrite", M)
      local mh = obj("Macro " .. M)
      if mh then pcall(function() for i = mh:Count(), 1, -1 do mh:Delete(i) end end) end
      C("Label Macro %d %s", M, q(b.label))
      if b.cmd then  -- a plain MA macro (the Masters page's utility macros)
        for _, line in ipairs(b.cmd) do
          if not (mh and addMacroLine(mh, line)) then failures[#failures + 1] = "Macro " .. M .. ": could not add line  " .. line end
        end
      elseif b.arg ~= "global noop" then  -- captions are buttons without a command
        local line = string.format('Plugin "%s" "%s"', CFG.PLUGIN_NAME, b.arg)
        if not (mh and addMacroLine(mh, line)) then
          failures[#failures + 1] = "Macro " .. M .. ": could not add line  " .. line
        end
      end
      C("Assign Macro %d At Layout %d", M, L)
      local idx = n
      lh = obj("Layout " .. L)
      if lh then pcall(function() idx = lh:Count() end) end
      C('Set Layout %d.%d Property "PosX" %d "PosY" %d "PositionW" %d "PositionH" %d',
        L, idx, math.floor(b.col * (W + G) + 0.5), math.floor(CFG.Y_DIR * b.row * (H + G) + 0.5),
        math.floor(b.w * W + (b.w - 1) * G + 0.5), math.floor(b.h * H + (b.h - 1) * G + 0.5))
      -- icon buttons and round discs: no border or indicator strip
      if b.frame then  -- section frame line: 2 px, in the gap just outside the section's buttons
        local c1, c2, r1, r2 = b.box[1], b.box[2], b.box[3], b.box[4]
        local t, o = G, G                             -- thickness, distance outside the buttons (fills the gap)
        local xL = math.floor(c1 * (W + G) + 0.5) - o
        local xR = math.floor(c2 * (W + G) - G + 0.5) + o
        local yBottom = math.floor(CFG.Y_DIR * (r2 - 1) * (H + G) + 0.5) - o
        local yTop = math.floor(CFG.Y_DIR * r1 * (H + G) + 0.5) + H + o
        local px, py, pw, ph
        if b.frame == "top" then px, py, pw, ph = xL, yTop - t, xR - xL, t
        elseif b.frame == "bottom" then px, py, pw, ph = xL, yBottom, xR - xL, t
        elseif b.frame == "left" then px, py, pw, ph = xL, yBottom, t, yTop - yBottom
        else px, py, pw, ph = xR - t, yBottom, t, yTop - yBottom end
        C('Set Layout %d.%d Property "PosX" %d "PosY" %d "PositionW" %d "PositionH" %d', L, idx, px, py, pw, ph)
        pcall(function()
          local e = obj("Layout " .. L)[idx]
          e.VisibilityBorder = true
          e.BorderColor = "5A5A5AFF"
          e.BorderSize = 1
          e.VisibilityIndicatorBar = false
          e.VisibilityObjectName = false
          e.CustomTextText = ""
        end)
      end
      if b.gobo then  -- gobo name under the image
        pcall(function() local e = obj("Layout " .. L)[idx] e.CustomTextAlignmentV = "Bottom" e.CustomTextSize = "12" end)
      end
      local disc = b.art or b.icon or b.fam or b.gname or (CFG.ROUND and b.w == 1 and b.h == 1 and b.arg ~= "global noop"
        and (({red = 1, orange = 1, blue = 1})[textFamily(b.label) or ""]
             or b.arg:find(" color %d") or b.arg:find(" mx c[12] %d")))
      if disc then
        pcall(function()
          local e = obj("Layout " .. L)[idx]
          e.VisibilityBorder = false
          e.VisibilityIndicatorBar = false
        end)
      end
      local iconOnly = b.icon and CFG.HIDE_ICON_NAMES and iconsReady()
      if CFG.ELEMENT_TEXT and not iconOnly and hideNames ~= false then
        local symk = ICN.S.key(b)
        local blank = not symk and ((b.art and CFG.ART) or (b.cat and ICN.catMode(b.cat) == "full")) or b.axis or b.gname
                      or (b.num and ICN.numReady() and CFG.ROUND)
        local okText = setElementText(page, idx, blank and "" or b.label)
        if b.tsize then pcall(function() obj("Layout " .. L)[idx].CustomTextSize = b.tsize end) end
        if symk then  -- MA symbol on top, the name under it
          pcall(function()
            local e = obj("Layout " .. L)[idx]
            e.CustomTextAlignmentV = "Bottom"
            e.CustomTextSize = b.h >= 2 and "20" or ((b.w >= 2) and "16" or "12")
          end)
        elseif b.art and b.lbl then  -- live text under an icon-only artwork
          pcall(function() local e = obj("Layout " .. L)[idx] e.CustomTextAlignmentV = "Bottom" e.CustomTextSize = "16" end)
        end
        if b.cat and ICN.catMode(b.cat) == "top" then  -- live value under the category icon
          pcall(function() local e = obj("Layout " .. L)[idx] e.CustomTextAlignmentV = "Bottom" e.CustomTextSize = "16" end)
        end
        dbg(string.format('Layout %d.%d CustomTextText "%s"  ->  %s', L, idx, b.label, tostring(okText)))
        if okText then
          hideNames = Cany({
            string.format('Set Layout %d.%d Property "VisibilityObjectName" 0', L, idx),
            string.format('Set Layout %d.%d Property "VisibilityObjectName" "No"', L, idx),
          })
        end
      end
      if b.gname then  -- group name: right next to its G (left of it, or right of it on the Gobo page)
        pcall(function()
          local e = obj("Layout " .. L)[idx]
          e.CustomTextAlignmentH = b.gname == "left" and "Left" or "Right"
          e.CustomTextSize = "14"
        end)
      end
      if iconOnly and hideNames ~= false then
        -- icon only, like Tom's buttons (stop trying after the first refusal)
        hideNames = Cany({
          string.format('Set Layout %d.%d Property "VisibilityObjectName" 0', L, idx),
          string.format('Set Layout %d.%d Property "VisibilityObjectName" "No"', L, idx),
        })
      end
    end
  end
end

function assignExecutors()
  if not CFG.ASSIGN_EXECUTORS then return end
  TC.ex.tidy(false)
  -- ObjectList("Page 2.201") finds nothing, so look the executor up under its page
  local function execHandle(exec)
    local pg, ex = tostring(exec):match("^(%d+)%.(%d+)$")
    pg, ex = tonumber(pg), tonumber(ex)
    if not pg then return nil end
    local h
    pcall(function()
      local page = DataPool().Pages[pg]
      if not page then return end
      for _, c in ipairs(page:Children()) do
        if tonumber(c.No) == ex or tonumber(c.no) == ex then h = c return end
      end
      local p = page:Ptr(ex)
      if p and tonumber(p.No) == ex then h = p end
    end)
    return h
  end
  local function put(seq, ex, key, pg, fader)
    if not ex then return end
    pg = pg or CFG.EXEC_PAGE
    local exec = pg .. "." .. ex
    local path = "Page " .. exec
    local cur = execHandle(exec) or obj(path)
    local mine, other = false, false
    if cur then  -- re-running setup: an executor holding our own sequence is fine
      pcall(function()
        local o = cur.Object
        mine = o == nil or (tonumber(o.No) == seq or tostring(o.Name):sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " ")
        -- one of our groups on an executor (the old group masters on 201-208)
        if o and not mine and o:GetClass() == "Group" then
          for _, g in ipairs(CFG.GROUPS) do if tonumber(o.No) == g then mine = true end end
        end
        -- a new show's empty "Default" sequence sits on 1.201: nothing to keep, take the spot
        if o and not mine and o:GetClass() == "Sequence" and tostring(o.Name) == "Default" then
          local cues = 0
          for _, c in ipairs(o:Children()) do
            local n = tostring(c.Name)
            if n ~= "OffCue" and n ~= "CueZero" then cues = cues + 1 end
          end
          mine = cues == 0
        end
        -- our own other object (a group master, or a sequence that moved): unassigned first
        other = o ~= nil and (o:GetClass() ~= "Sequence" or tonumber(o.No) ~= seq)
      end)
    end
    if cur and not mine and not CFG.ALLOW_OVERWRITE_FOREIGN then
      local info = "?"
      pcall(function()
        local o = cur.Object
        info = o and (tostring(o:GetClass()) .. " " .. tostring(o.No) .. " '" .. tostring(o.Name) .. "'") or "empty"
      end)
      dbg(string.format("%s in use (%s) - skipped Sequence %d", path, info, seq))
      failures[#failures + 1] = path .. " is in use - assign Sequence " .. seq .. " yourself (" .. key .. ")"
      return
    end
    local fresh = other or not (cur and cur.Object)
    if other then Cmd(string.format("Delete %s /NC", path)) end
    C("Assign Sequence %d At %s", seq, path)
    local h = execHandle(exec) or obj(path)
    if h and fader then
      pcall(function() h.FADER = fader end)
      -- newly assigned: the fader starts at 0, so bringing it up starts the sequence
      if fresh then Cany({ string.format("Fader %s At 0", path), string.format("%s At 0", path) }) end
    end
    local ok = h and pcall(function() h.Key = key end)
    if ok then pcall(function() ok = tostring(h.Key) == key end) end
    if h and not ok then
      ok = okResult(Cmd(string.format('Set %s Property "Key" "%s"', h:ToAddr(), key))) and true
      pcall(function() ok = tostring(h.Key) == key end)
    end
    dbg(string.format('%s (%s) .Key = "%s"  ->  %s', path, h and h:ToAddr() or "no handle", key, tostring(ok)))
  end
  local SEQ_FOR = {
    dim = function(gi) return seqNo("dim", gi) end,
    dimfader = function(gi) return seqNo("dim", gi) end,
    bump = function(gi) return bumpSeq(1, gi) end,
    rnd = function(gi) return bumpSeq(2, gi) end,
    strobe = function(gi) return bumpSeq(3, gi) end,
    xk = function(gi) return xkSeq(gi) end,
  }
  -- Group Master: the group itself on the fader. Replaces our old G#_Full sequence;
  -- the fader goes to 100 % only when it's newly assigned, so re-running setup keeps
  -- your fader levels.
  local function groupMaster(g, ex, pg)
    local exec = (pg or CFG.EXEC_PAGE) .. "." .. ex
    local path = "Page " .. exec
    local cur = execHandle(exec) or obj(path)
    local kind, mine, info = nil, true, "empty"
    if cur then
      pcall(function()
        local o = cur.Object
        if not o then return end
        kind = o:GetClass()
        info = tostring(kind) .. " " .. tostring(o.No) .. " '" .. tostring(o.Name) .. "'"
        if kind == "Group" then mine = tonumber(o.No) == g
        else mine = tostring(o.Name):sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " " end
      end)
    end
    if kind == "Group" and mine then return end
    if not mine and not CFG.ALLOW_OVERWRITE_FOREIGN then
      dbg(string.format("%s in use (%s) - skipped Group Master %d", path, info, g))
      failures[#failures + 1] = path .. " is in use - assign Group " .. g .. " there yourself"
      return
    end
    if kind then Cmd(string.format("Delete %s /NC", path)) end
    C("Assign Group %d At %s", g, path)
    Cany({ string.format("Fader %s At 100", path), string.format("%s At 100", path) })
  end
  for _, r in ipairs(CFG.EXEC_ROWS) do  -- a row on another page (Dimmer FX knobs on page 2)
    if r.page and r.page ~= CFG.EXEC_PAGE then
      if not obj("Page " .. r.page) then C("Store Page %d", r.page) end
      -- (the Utility page used to be page 2)
      local n = objName(obj("Page " .. r.page))
      if (n == nil or n == "" or n == fs("Utility")) and r.page ~= CFG.UTIL_PAGE then
        C("Label Page %d %s", r.page, q(fs("Masters")))
      end
    end
  end
  for gi = 1, #CFG.GROUPS do
    for _, r in ipairs(CFG.EXEC_ROWS) do
      local pg, ex = TC.ex.at((r.what == "group" and "group" or r.what) .. gi, r.page or CFG.EXEC_PAGE, r.base + gi)
      if r.what == "group" then groupMaster(CFG.GROUPS[gi], ex, pg)
      elseif SEQ_FOR[r.what] then
        local key = r.key
        for slot, w in ipairs(BM.ROW) do
          if r.what == w then key = BM.key(getBump(gi, slot), slot) end
        end
        put(SEQ_FOR[r.what](gi), ex, key, pg, (r.what == "dimfader") and "Master" or nil)
      end
    end
  end
  -- the Dimmer FX faders: every group's sequence holds its look (Full when none is chosen)
  for _, r in ipairs(CFG.EXEC_ROWS) do
    if r.what == "dimfader" then
      for gi = 1, #CFG.GROUPS do TC.dim.prime(gi) end
      break
    end
  end
  do
    local pg, ex = TC.ex.at("strobeall", CFG.EXEC_PAGE, CFG.STROBE_EXEC)
    put(CFG.STROBE_SEQ, ex, "Temp", pg)
  end
  -- FIRE on an executor next to the X-Keys: Macro "FS FIRE" (fires every page)
  if CFG.FIRE_MACRO then
    local M = CFG.FIRE_MACRO
    local mh = obj("Macro " .. M)
    if not mh or isOurs(mh) or objName(mh) == fs("FIRE") then
      C("Store Macro %d /Overwrite", M)
      mh = obj("Macro " .. M)
      if mh then pcall(function() for i = mh:Count(), 1, -1 do mh:Delete(i) end end) end
      C("Label Macro %d %s", M, q(fs("FIRE")))
      if mh then addMacroLine(mh, string.format('Plugin "%s" "global fire"', CFG.PLUGIN_NAME)) end
      if CFG.FIRE_EXEC then
        local exec = table.concat({TC.ex.at("fire", CFG.EXEC_PAGE, CFG.FIRE_EXEC)}, ".")
        local cur, free = execHandle(exec), true
        pcall(function() local o = cur and cur.Object free = (o == nil) or (o:GetClass() == "Macro" and tonumber(o.No) == M) end)
        if free then C("Assign Macro %d At Page %s", M, exec)
        else failures[#failures + 1] = "Page " .. exec .. " is in use - FIRE macro " .. M .. " not assigned" end
      end
    else
      failures[#failures + 1] = "Macro " .. M .. " is in use - set FIRE_MACRO to a free macro"
    end
  end
  for _, m in ipairs(CFG.MASTER_EXECS or {}) do
    local exec = table.concat({TC.ex.at("m" .. m[2] .. m[3], m[4] or CFG.EXEC_PAGE, m[1])}, ".")
    local path = "Page " .. exec
    local cur, empty = execHandle(exec) or obj(path), true
    if cur then pcall(function() empty = cur.Object == nil end) end
    if not empty then
      pcall(function() dbg(string.format("%s holds %s '%s' - left as it is", path,
        tostring(cur.Object:GetClass()), tostring(cur.Object.Name))) end)
    end
    if empty then
      Cany({ string.format('Assign Master "%s".%d At %s', m[2], m[3], path),
             string.format('Assign Master %s.%d At %s', m[2], m[3], path),
             string.format('Assign %sMaster %d At %s', m[2], m[3], path) })
    end
  end
  -- colours: every executor's object gets the appearance of its kind; masters get their names
  local LOOK_FOR = {rnd = "rnd", strobe = "strobe", dim = "dim", dimfader = "dim", bump = "bump", xk = "xk"}
  local done = {}
  for gi = 1, #CFG.GROUPS do
    for _, r in ipairs(CFG.EXEC_ROWS) do
      local what = (r.what == "group") and ("Group " .. CFG.GROUPS[gi])
        or (SEQ_FOR[r.what] and ("Sequence " .. SEQ_FOR[r.what](gi)))
      if what and not done[what] then
        done[what] = true
        TC.look.give(LOOK_FOR[r.what] or r.what, what)
      end
    end
  end
  TC.look.give("strobe", "Sequence " .. CFG.STROBE_SEQ)
  TC.look.give("white", "Sequence " .. CFG.WHITE_SEQ)
  TC.look.give("looks", "Sequence " .. CFG.LOOKS_SEQ)
  if CFG.FIRE_MACRO then TC.look.give("fire", "Macro " .. CFG.FIRE_MACRO) end
  TC.look.masters()
  TC.ex.copies(false)
end

function rebuildAllKeys()
  for gi = 1, #CFG.GROUPS do
    for slot = 1, 3 do rebuildBump(gi, slot) end
    rebuildXk(gi)
  end
  FN.rebuildStrobeAll()
end

end

-- ==== FireSystemViews.lua (copied by tools/make_tools.py) ====
MODS.Views = function(_ENV)

-- ======================================================================
-- Layout look: black canvas, and every FS layout spans the same area (two
-- tiny black anchor buttons at the corners of the combined area), so the
-- view doesn't rescale or shift when you switch pages.
-- ======================================================================
-- Fit: the layouts are stretched (all pages alike) to the shape of the FS view, so they fill
-- the screen of this onPC window or console. FIT.sig notices a resized onPC window.
FIT = {}
function FIT.px(display)  -- usable pixel area of a display (view bar taken off)
  local w, h
  pcall(function()
    local d = GetDisplayCollect():Children()[display]
    local sc = d.ScreenContainer
    local r = tostring(sc:Get("AbsClientRect", Enums.Roles.Display))
    local _, _, rw, rh = r:match("(%-?%d+),(%-?%d+),(%d+),(%d+)")
    w, h = tonumber(rw), tonumber(rh)
    local vb = sc.ViewBar
    if vb and w then w = w - (tonumber(tostring(vb:Get("W", Enums.Roles.Display)):match("(%d+)%)?$")) or 100) end
  end)
  return w, h
end
-- running on onPC (whatever console the show was built for: a console show opened on a laptop refits too)
function FN.onPC()
  local host = ""
  pcall(function() host = tostring(HostType()) end)
  if host == "" then return gv("console") == "onPC" end
  return host:lower():find("onpc") ~= nil
end
function FIT.aspect()
  local kind, w, h = gv("console"), nil, nil
  if kind == nil or kind == "" or kind == "onPC" or FN.onPC() then w, h = FIT.px(1) end
  if not (w and h and h > 100) then w, h = 1820, 1021 end  -- console screen: 1920 x 1080 less the bars
  return w / h
end
TC.bg.aspect = FIT.aspect
function FIT.sig()
  local t = {}
  for d = 1, 3 do
    local w, h = FIT.px(d)
    if w and h then
      -- the UI scale changes how many grid units fit, so it counts as a size change too
      local sc = ""
      pcall(function() sc = tostring(GetDisplayCollect():Children()[d]:Get("ScaleRatio", Enums.Roles.Display)) end)
      t[#t + 1] = w .. "x" .. h .. "@" .. sc
    end
  end
  return table.concat(t, ";")
end

function layoutFix()
  -- no MA border / indicator bar on buttons that show an image (icon, artwork, disc, caption icon)
  for _, page in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "dpf", "pcol", "home", "tc", "songs", "rec", "tced", "upd", "mast"}) do
    local lh = (not TC.combo.DEF[page] or TC.combo.on(page)) and obj("Layout " .. layoutNo(page))
    if lh then
      local ok, spec = pcall(buildSpec, page)
      for i, b in ipairs(ok and spec or {}) do
        if not b.frame and (b.art or b.icon or b.cat or b.num or b.axis or b.fam or b.gname or b.w == 1) then
          pcall(function()
            local e = lh[i]
            if e and tostring(e:Get("VisibilityBorder", Enums.Roles.Display)) ~= "Hidden" then
              e.VisibilityBorder = false
              e.VisibilityIndicatorBar = false
            end
          end)
        end
      end
    end
  end
  local BA = CFG.APPEARANCE_BASE + 99
  if objName(obj("Appearance " .. BA)) ~= fs("Black") then
    C("Store Appearance %d /Overwrite", BA)
    C("Label Appearance %d %s", BA, q(fs("Black")))
    setApColor(BA, FN.TH.canvas)
  end
  local ap = obj("Appearance " .. BA)
  -- area of each page's real buttons (anchors not counted)
  local function s16(v) v = tonumber(v) return (v and v > 32767) and (v - 65536) or v end  -- read back unsigned
  local area = {}
  for _, page in ipairs(PAGES) do
    local lh, n = obj("Layout " .. layoutNo(page)), #buildSpec(page)
    local r
    for i = 1, n do
      pcall(function()
        local e = lh[i]
        local x, y, w, h = s16(e.PosX), s16(e.PosY), tonumber(e.Width), tonumber(e.Height)
        if not (x and y and w and h) then return end
        r = r or {x, y, x + w, y + h}
        r[1], r[2], r[3], r[4] = math.min(r[1], x), math.min(r[2], y), math.max(r[3], x + w), math.max(r[4], y + h)
      end)
    end
    area[page] = r
  end
  -- Stretch the pages to the shape of the view (discs stay round: their image keeps its aspect;
  -- thin frame lines keep their thickness). "same": all pages alike over their combined area,
  -- so buttons keep their size between pages; "fill": every page fills the view on its own.
  -- fit_<page> = "sx,sy" the page has now (createLayoutsAndMacros resets it).
  local want, fill = FIT.aspect(), gv("fit_mode") == "fill"
  local cur, base = {}, {}
  for _, page in ipairs(PAGES) do
    local r = area[page]
    if r then
      local sx, sy = tostring(gv("fit_" .. page) or ""):match("([%d%.]+),([%d%.]+)")
      cur[page] = {tonumber(sx) or 1, tonumber(sy) or 1}
      base[page] = {r[1] / cur[page][1], r[2] / cur[page][2], r[3] / cur[page][1], r[4] / cur[page][2]}
    end
  end
  local U
  for pg, r in pairs(base) do
    if not TC.combo.DEF[pg] then  -- (a combined page is twice as tall: it always fills the view on its own)
      U = U or {r[1], r[2], r[3], r[4]}
      U[1], U[2], U[3], U[4] = math.min(U[1], r[1]), math.min(U[2], r[2]), math.max(U[3], r[3]), math.max(U[4], r[4])
    end
  end
  if not U then return end
  local function stretchFor(r)
    local f = want * (r[4] - r[2]) / (r[3] - r[1])
    if f >= 1 then return f, 1 end
    return 1, 1 / f
  end
  local anchor = {}
  for _, page in ipairs(PAGES) do
    local r = base[page]
    if r then
      local ar = (fill or TC.combo.DEF[page]) and r or U
      local tx, ty = stretchFor(ar)
      local sx, sy = tx / cur[page][1], ty / cur[page][2]
      if math.abs(sx - 1) < 0.01 then sx = 1 end
      if math.abs(sy - 1) < 0.01 then sy = 1 end
      if sx ~= 1 or sy ~= 1 then
        local L, n = layoutNo(page), #buildSpec(page)
        local lh = obj("Layout " .. L)
        for i = 1, n do
          pcall(function()
            local e = lh[i]
            local x, y, w, h = s16(e.PosX), s16(e.PosY), tonumber(e.Width), tonumber(e.Height)
            if not (x and y and w and h) then return end
            local nw = (w <= CFG.GAP) and w or math.floor(w * sx + 0.5)
            local nh = (h <= CFG.GAP) and h or math.floor(h * sy + 0.5)
            Cmd(string.format('Set Layout %d.%d Property "PosX" %d "PosY" %d "PositionW" %d "PositionH" %d',
              L, i, math.floor(x * sx + 0.5), math.floor(y * sy + 0.5), nw, nh))
          end)
        end
      end
      sv("fit_" .. page, string.format("%.4f,%.4f", tx, ty))
      anchor[page] = {math.floor(ar[1] * tx + 0.5), math.floor(ar[2] * ty + 0.5),
                      math.floor(ar[3] * tx + 0.5), math.floor(ar[4] * ty + 0.5)}
      dbg(string.format("layouts: %s %s, view %.2f:1, stretched x%.2f y%.2f", page, fill and "fills the view" or "same size", want, tx, ty))
    end
  end
  local A = 4  -- anchor size
  for _, page in ipairs(PAGES) do
    local spec = buildSpec(page)
    local L, n = layoutNo(page), #spec  -- n: layout elements; the anchors' macros follow the page's block
    local lh = obj("Layout " .. L)
    pcall(function() lh.CanvasAppearance = TC.bg.ap(page) or ap end)
    local okCanvas = false
    pcall(function() okCanvas = lh.CanvasAppearance ~= nil end)
    if not okCanvas then Cany({ string.format('Set Layout %d Property "CanvasAppearance" %d', L, BA) }) end
    local ar = anchor[page] or {0, 0, A, A}
    for k, pos in ipairs({{ar[1], ar[2]}, {ar[3] - A, ar[4] - A}}) do
      local M = macroNo(page, spec.nMain + k)
      if objName(obj("Macro " .. M)) ~= fs("anchor") then
        C("Store Macro %d /Overwrite", M)
        C("Label Macro %d %s", M, q(fs("anchor")))
      end
      if lh:Count() < n + k then C("Assign Macro %d At Layout %d", M, L) end
      C('Set Layout %d.%d Property "PosX" %d "PosY" %d "PositionW" %d "PositionH" %d', L, n + k, pos[1], pos[2], A, A)
      pcall(function()
        local e = lh[n + k]
        e.VisibilityObjectName = false; e.VisibilityBorder = false; e.VisibilityIndicatorBar = false
        e.CustomTextText = ""
      end)
      C("Assign Appearance %d At Macro %d", BA, M)
    end
    TC.bg.set(page)  -- (after the anchors: the background box follows the stretched page)
  end
end

-- ======================================================================
-- Group Builder (layout 109): store the current selection as G1-G8
-- ======================================================================
-- View 101-111 on screen 1 (pages, then Group Builder / Custom Colours / Gobo Picker), 121+ screen 2, 141+ screen 3
function viewNo(screenIdx, page) return CFG.VIEW_BASE + (screenIdx - 1) * 20 + PAGE[page].i end

-- Screens: every screen switches its own views. A button acts on the screen it was pressed on
-- (TC.scr.from: the display MA hands the plugin, else the focus display); the others stay put.
TC.scr = {}
-- the displays that have FS views, by screen index (screen si -> display number)
function TC.scr.list()
  local t = {}
  for d in tostring(gv("view_disp") or ""):gmatch("%d+") do t[#t + 1] = tonumber(d) end
  if #t == 0 then  -- views built by an older version: screen n was display n
    t[1] = 1
    pcall(function()
      for si = 2, 3 do if ShowData().UserProfiles[1].Views[viewNo(si, "dim")] then t[#t + 1] = si end end
    end)
  end
  return t
end
-- display number of a display handle (nil when it isn't one)
function TC.scr.disp(h)
  if not h then return nil end
  local n
  pcall(function()
    for i, d in ipairs(GetDisplayCollect():Children()) do
      if d == h or HandleToInt(d) == HandleToInt(h) then n = i break end
    end
  end)
  if not n then pcall(function() n = tonumber(tostring(h.name):match("(%d+)$")) end) end
  return n
end
-- the screen the press came from: its screen index and display
function TC.scr.cur()
  local d = TC.scr.disp(TC.scr.from)
  if not d then pcall(function() d = TC.scr.disp(GetFocusDisplay()) end) end
  local list = TC.scr.list()
  for si, x in ipairs(list) do if x == d then return si, x end end
  return 1, list[1] or 1
end
-- the view of a page on the pressed screen (screen 1's when that screen has none)
function TC.scr.view(page, si)
  si = si or TC.scr.cur()
  if si > 1 and not ShowData().UserProfiles[1].Views[viewNo(si, page)] then si = 1 end
  return viewNo(si, page), si
end
-- a combined page's view on each screen, made when it is first opened (the show got the page after its views)
function TC.combo.views(page)
  if not (CFG.VIEWS and gv("views_ok") == "1") then return end
  local views = ShowData().UserProfiles[1].Views
  for si, d in ipairs(TC.scr.list()) do
    local vno = viewNo(si, page)
    if not views[vno] and okResult(Cmd(string.format('Import View %d /File "fs_view_d%d" /NoConfirm', vno, d))) then
      pcall(function()
        views[vno][1][1].Layout = obj("Layout " .. layoutNo(page))
        views[vno].name = fs(PAGE[page].title .. (si > 1 and (" S" .. d) or ""))
      end)
    end
  end
end
-- shows a page's view on the pressed screen only
function TC.scr.show(page)
  if not (CFG.VIEWS and gv("views_ok") == "1") then return end
  local si, d = TC.scr.cur()
  local no
  no, si = TC.scr.view(page, si)
  if ShowData().UserProfiles[1].Views[no] then
    dbg(string.format("   view %d (%s) on screen %d (display %s)", no, page, si, tostring(d)))
    Cmd(string.format("View %d", no))
  end
end
-- XML head of a view on one display (closed by the caller: "    </View>\n</GMA3>\n")
function TC.scr.xml(d, W, H)
  return string.format([[<?xml version="1.0" encoding="UTF-8"?>
<GMA3 DataVersion="2.4.2.2">
    <View Name="FS" ScreenContentMask="%d" RequestedW="Default" RequestedH="Default">
        <ViewWidget Name="WindowLayoutView" Display="%d" X="0" Y="0" W="%d" H="%d" MinW="4" MinH="4">
            <LayoutViewSettings FontSize="Default" ShowTitleBar="No" AutoFit="Yes" FitType="Elements" SelectionMode="2D Grid" RightClickToEdit="Yes" ShowSelection="Yes"/>
            <WindowAppearance WindowColor="000000FF"/>
        </ViewWidget>
]], 2 ^ (d - 1), d, W, H)
end
-- size (grid units) of the full-screen FS view on screen si
function TC.scr.size(si)
  local W, H = 48, 22
  pcall(function() local w = ShowData().UserProfiles[1].Views[viewNo(si, "dim")][1] W, H = tonumber(w.W) or W, tonumber(w.H) or H end)
  return W, H
end

openGroupBuilder = nil  -- defined below, used by setup

-- writes custom colour n into its preset (live: recipes and looks that use it follow)
function storeCustomColor(n)
  local force = BM.forcePresets
  BM.forcePresets = true  -- your colour from the Custom Colours page always replaces the old one
  local c, ci = customColor(n), NCOL + n
  local l = {
    string.format("Attribute %s At %d", q(CFG.ATTR.r), c[1]),
    string.format("Attribute %s At %d", q(CFG.ATTR.g), c[2]),
    string.format("Attribute %s At %d", q(CFG.ATTR.b), c[3]),
  }
  for _, e in ipairs({"W", "WW", "CW"}) do l[#l + 1] = string.format('?Attribute "ColorRGB_%s" At %d', e, c[4]) end
  for _, e in ipairs({"UV", "Y", "C", "M", "RY", "GY", "GC", "BC", "BM", "RM"}) do
    l[#l + 1] = string.format('?Attribute "ColorRGB_%s" At 0', e)
  end
  storePreset(4, colorPreset(ci), "COLOR " .. n, l)
  storePreset(4, tintPreset(ci, 1), "COLOR " .. n .. " Pastel", colorLines(tintRGBW({c[1], c[2], c[3]}, c[4], 1)))
  storePreset(4, tintPreset(ci, 2), "COLOR " .. n .. " Dark", colorLines(tintRGBW({c[1], c[2], c[3]}, c[4], 2)))
  BM.forcePresets = force
  -- swatch buttons show the mix (white added on top)
  local function ch(v) return math.min(255, math.floor((v + c[4] * 0.6) * 2.55)) end
  local rgb = {ch(c[1]), ch(c[2]), ch(c[3])}
  setApColor(apNo("c" .. ci), rgb)
  FN.tintSwatch(ci, rgb)
  do local a = AP_LIST[(AP["c" .. ci] or -1) + 1] if a then a[3] = rgb end end
  setApColor(apNo("cs" .. ci), {math.floor(rgb[1] * .45), math.floor(rgb[2] * .45), math.floor(rgb[3] * .45)})
end

-- opens one of the pages that aren't in PAGES (Group Builder, Custom Colours)
function openExtraPage(page)
  failures = {}
  for _, b in ipairs(buildSpec(page)) do
    local h = obj("Macro " .. b.M)
    if h and not isOurs(h) and objName(h) ~= b.label then
      MessageBox({title = "FireSystem", message = "Macro " .. b.M ..
        " is in use, so the " .. PAGE[page].title .. " page can't be made. Change MACRO_BASE or move that macro.",
        commands = {{value = 1, name = "OK"}}})
      return false
    end
  end
  importIcons()
  if not obj("Appearance " .. CFG.APPEARANCE_BASE) then createAppearances() end
  if not obj("Layout " .. layoutNo(page)) or gv("built_" .. page) ~= CFG.EXTRA_VER then
    createLayoutsAndMacros({page})
    sv("built_" .. page, CFG.EXTRA_VER)
  end
  TC.bg.set(page)
  for k in pairs(lastAp) do lastAp[k] = nil end
  for k in pairs(TC.names) do TC.names[k] = nil end
  refresh(page)
  Cany({ string.format("Select Layout %d", layoutNo(page)), string.format("Layout %d", layoutNo(page)) })
  TC.scr.show(page)
  return true
end
FS_openExtraPage = openExtraPage
function FN.groupList8()
  local t = {}
  for g = 1, 8 do if obj("Group " .. g) then t[#t + 1] = g end end
  return t
end

openGroupBuilder = function(why)
  failures = {}
  -- our macro block for this page must be free (or ours)
  for _, b in ipairs(buildSpec("grp")) do
    local h = obj("Macro " .. b.M)
    if h and not isOurs(h) and objName(h) ~= b.label then
      MessageBox({title = "FireSystem", message = "Macro " .. b.M ..
        " is in use, so the Group Builder can't be made. Change MACRO_BASE or move that macro.",
        commands = {{value = 1, name = "OK"}}})
      return
    end
  end
  importIcons()
  if not obj("Appearance " .. CFG.APPEARANCE_BASE) then createAppearances() end
  createLayoutsAndMacros({"grp"})
  TC.bg.set("grp")
  for k in pairs(lastAp) do lastAp[k] = nil end
  refresh("grp")
  Cany({ string.format("Select Layout %d", layoutNo("grp")), string.format("Layout %d", layoutNo("grp")) })
  -- its view on this screen (the views are made first if the show has none yet)
  if CFG.VIEWS and not ShowData().UserProfiles[1].Views[viewNo(1, "grp")] and FS_buildViews then FS_buildViews() end
  local vno = TC.scr.view("grp")
  -- the view gets a Selection Grid next to the layout, for arranging groups (Edit Grid)
  local views = ShowData().UserProfiles[1].Views
  if CFG.VIEWS and views[vno] and gv("grp_view") ~= CFG.VIEWS_VER .. "s" then
    local ok, err = pcall(TC.buildViews, "grp")
    dbg("Group Builder view with Selection Grid: " .. tostring(ok) .. " " .. tostring(err or ""))
    sv("grp_view", CFG.VIEWS_VER .. "s")
  end
  if ShowData().UserProfiles[1].Views[vno] then Cmd(string.format("View %d", vno)) end
  Echo("FireSystem: Group Builder - select fixtures in stage order, tap Store G1-G8, then DONE")
  if why then
    MessageBox({title = "FireSystem: Group Builder", message = why ..
      "\n\nThe Group Builder layout is open:\n1. Select fixtures in the Selection Grid in the order effects should run." ..
      "\n2. Tap Store G1-G8 and give each group a name.\n3. Tap DONE to build FireSystem.",
      commands = {{value = 1, name = "OK"}}})
  end
end

function storeGroup(g, name)
  local n = 0
  pcall(function() n = SelectionCount() end)
  if n == 0 then
    MessageBox({title = "FireSystem", message = "Nothing is selected.\nSelect fixtures in the Selection Grid first.",
      commands = {{value = 1, name = "OK"}}})
    return
  end
  if not name or name == "" then
    local def = objName(obj("Group " .. g))
    if not def then
      pcall(function()
        local sf = GetSubfixture(SelectionFirst())
        def = tostring(sf.name):gsub("^OAF: ", "")
      end)
    end
    local ok, v = pcall(TextInput, "Name for Group " .. g .. " (" .. n .. " fixtures)", def or ("G" .. g))
    if not ok or v == nil then return end
    name = (v ~= "") and v or def or ("G" .. g)
  end
  C("Store Group %d /Overwrite", g)  -- keeps the selection order and grid positions
  C("Label Group %d %s", g, q(name))
  if g >= CFG.UTIL_GROUP_BASE and g < CFG.UTIL_GROUP_BASE + #CFG.UTIL then sv("ukeep_" .. g, "1") end
  TC.capCache = {}
  dbg(string.format("Group %d '%s' stored with %d fixtures", g, name, n))
  refresh("grp")
end

-- ======================================================================
-- Views: a Layout Viewer per page and screen, sized to the console's screens
-- ======================================================================
CONSOLES = {  -- {name, main screens}; console screens are taken as 1920x1080
  {"onPC", nil}, {"compact", 1}, {"compact XT", 2}, {"light", 2}, {"full-size", 3},
}

-- asks once which console this is (stored in FS_console); returns the screen list
function FN.consoleScreens(ask)
  local kind = gv("console")
  if ask or not kind or kind == "" then
    local cmds = {}
    for i, c in ipairs(CONSOLES) do cmds[#cmds + 1] = {value = i, name = c[1]} end
    local ok, r = pcall(MessageBox, {title = "FireSystem: console",
      message = "Which console is this show for?\nFireSystem builds one view per page on each screen.",
      commands = cmds})
    local v = ok and type(r) == "table" and tonumber(r.result)
    if not v or not CONSOLES[v] then return nil end
    kind = CONSOLES[v][1]
    sv("console", kind)
  end
  local screens = {}
  if kind == "onPC" then
    -- the size of each onPC display window, as it is now
    pcall(function()
      for i, d in ipairs(GetDisplayCollect():Children()) do
        local w, h = tonumber(d.W) or 0, tonumber(d.H) or 0
        if w > 200 and h > 200 and i <= 3 then screens[#screens + 1] = {display = i, w = w, h = h} end
      end
    end)
    if #screens == 0 then screens = {{display = 1, w = 1920, h = 1021}} end
  else
    for _, c in ipairs(CONSOLES) do
      if c[1] == kind then for d = 1, c[2] do screens[#screens + 1] = {display = d, w = 1920, h = 1021} end end
    end
  end
  return screens, kind
end


-- your own view size per display, in MA blocks: FS_view_blocks = "1=22x10,2=21x14". One MA block (as MA's
-- own window sizes count them) is 2 x 2 units of the view file, so the view is made twice the blocks.
function FN.viewBlocks(display)
  local w, h = tostring(gv("view_blocks") or ""):match("%f[%d]" .. display .. "=(%d+)x(%d+)")
  w, h = tonumber(w), tonumber(h)
  if w and h and w >= 2 and h >= 2 then return w, h end
end
function FN.viewSize(display)  -- in view-file units
  local w, h = FN.viewBlocks(display)
  if w then return w * 2, h * 2 end
  w, h = tostring(gv("view_size") or ""):match("%f[%d]" .. display .. "=(%d+)x(%d+)")  -- (1.12.0-test: view units)
  w, h = tonumber(w), tonumber(h)
  if w and h and w >= 4 and h >= 4 then return w, h end
end
function FN.setViewBlocks(display, w, h)
  local t = {}
  for d, s in tostring(gv("view_blocks") or ""):gmatch("(%d+)=(%d+x%d+)") do
    if tonumber(d) ~= display then t[#t + 1] = d .. "=" .. s end
  end
  if w and h then t[#t + 1] = string.format("%d=%dx%d", display, w, h) end
  sv("view_blocks", table.concat(t, ","))
  sv("view_size", "")
end
-- the screen grid MA itself uses on a display (view-file units): its UiScreen object's Columns x Rows
-- (Display > ScreenContainer > ... > ScrollBox > UiScreen)
function FN.screenGrid(display)
  local cols, rows
  pcall(function()
    local function find(h, depth)
      if not h or depth < 0 or cols then return end
      local cls = ""
      pcall(function() cls = tostring(h:GetClass()) end)
      if cls == "UiScreen" then
        cols, rows = tonumber(tostring(h:Get("Columns", Enums.Roles.Display))), tonumber(tostring(h:Get("Rows", Enums.Roles.Display)))
        return
      end
      for _, k in ipairs(h:Children()) do find(k, depth - 1) end
    end
    find(GetDisplayCollect():Children()[display].ScreenContainer, 6)
  end)
  if cols and rows and cols >= 4 and rows >= 4 then return cols, rows end
end
-- Console & Views: shows a screen's size in MA blocks and lets you type your own
function FN.askViewSize(si, display, W, H)
  local bw, bh = math.floor(W / 2), math.floor(H / 2)  -- measured, in blocks
  local mw, mh = FN.viewSize(display)
  if mw then mw, mh = math.floor(mw / 2), math.floor(mh / 2) end
  local ok, r = pcall(MessageBox, {title = "FireSystem: screen " .. si .. " size",
    message = string.format("Display %d: FireSystem measured %d x %d MA blocks.%s\n" ..
      "Type the size the FireSystem views should have on this screen,\nor let FireSystem measure it.",
      display, bw, bh, mw and string.format("\nYour size now: %d x %d.", mw, mh) or ""),
    inputs = {{name = "Width (blocks)", value = tostring(mw or bw), whiteFilter = "0123456789", maxTextLength = 3},
              {name = "Height (blocks)", value = tostring(mh or bh), whiteFilter = "0123456789", maxTextLength = 3}},
    commands = {{value = 1, name = "Use this size"}, {value = 2, name = "Measure"}}})
  local v = ok and type(r) == "table" and tonumber(r.result)
  if v == 2 then return FN.setViewBlocks(display, nil) end
  if v ~= 1 then return end  -- closed: left as it was
  local inp = type(r.inputs) == "table" and r.inputs or {}
  local w, h = tonumber(inp["Width (blocks)"]), tonumber(inp["Height (blocks)"])
  if w and h and w >= 2 and h >= 2 then FN.setViewBlocks(display, w, h) end
end

function buildViews(ask)
  sv("grp_view", "")  -- the Group Builder's split view is made again when it next opens
  if not CFG.VIEWS then return end
  local screens, kind = FN.consoleScreens(ask)
  if not screens then return end
  local dir = PATHS.lib("userprofiles", "views")
  local views = ShowData().UserProfiles[1].Views
  local made = 0
  -- drop FireSystem's own views first (numbering may have changed); other views are left alone
  for no = CFG.VIEW_BASE, CFG.VIEW_BASE + 59 do
    local v = views[no]
    if v and tostring(v.name):sub(1, #CFG.PREFIX + 1) == CFG.PREFIX .. " " then Cmd(string.format("Delete View %d /NC", no)) end
  end
  local function usablePx(display)
    local w, h
    pcall(function()
      local d = GetDisplayCollect():Children()[display]
      local sc = d.ScreenContainer
      local r = tostring(sc:Get("AbsClientRect", Enums.Roles.Display))
      local _, _, rw, rh = r:match("(%-?%d+),(%-?%d+),(%d+),(%d+)")
      w, h = tonumber(rw), tonumber(rh)
      local vb = sc.ViewBar
      if vb and w then w = w - (tonumber(tostring(vb:Get("W", Enums.Roles.Display)):match("(%d+)%)?$")) or 100) end
    end)
    return w, h
  end
  -- the extent of the user's own views on a display (MA made those, so they are in true grid units)
  local function existingGrid(display)
    local W, H
    pcall(function()
      for _, v in ipairs(views:Children()) do
        if tostring(v.name):sub(1, #CFG.PREFIX + 1) ~= CFG.PREFIX .. " " then
          for _, w in ipairs(v:Children()) do
            if tonumber(w.Display) == display then
              W = math.max(W or 0, (tonumber(w.X) or 0) + (tonumber(w.W) or 0))
              H = math.max(H or 0, (tonumber(w.Y) or 0) + (tonumber(w.H) or 0))
            end
          end
        end
      end
    end)
    if W and W >= 4 and H and H >= 4 then return W, H end
    return nil
  end
  -- grid cell size in pixels: from a display that has views, else MA's default at this scale
  -- grid cell size in pixels: measured once from your own views (MA made those, in true grid
  -- units) and remembered - the pixel area already follows the UI scale, the cell size doesn't
  if ask then sv("cell", "") end  -- asked again: measure the cell again (the show may be on another computer now)
  local cellW, cellH = tostring(gv("cell") or ""):match("([%d%.]+)x([%d%.]+)")
  cellW, cellH = tonumber(cellW), tonumber(cellH)
  if not cellW then
    cellW, cellH = 46.85, 49.1
    for _, sc in ipairs(screens) do
      local gw, gh = existingGrid(sc.display)
      local pw, ph = usablePx(sc.display)
      if gw and pw then cellW, cellH = pw / gw, ph / gh break end
    end
    sv("cell", string.format("%.2fx%.2f", cellW, cellH))
  end
  for si, sc in ipairs(screens) do
    -- window size in MA grid units: the usable screen area divided by the grid cell size
    local W, H
    if not W then
      local pw, ph = usablePx(sc.display)
      if pw and ph then W, H = math.max(4, math.floor(pw / cellW + 0.02)), math.max(4, math.floor(ph / cellH + 0.02)) end
    end
    if not W then W, H = math.max(4, math.floor(sc.w / 40)), math.max(4, math.floor(sc.h / 46.4)) end
    -- on a console the measured height came out one row too tall: one row less there
    -- ("global viewrows <n>" sets your own adjustment, 0 = as measured)
    local dh = tonumber(gv("view_dh") or "")
    if not dh then
      local host = ""
      pcall(function() host = tostring(HostType()) end)
      dh = (host ~= "" and not host:lower():find("onpc")) and -1 or 0
    end
    H = math.max(4, H + dh)
    local gw, gh = FN.screenGrid(sc.display)  -- MA's own grid for this screen: exact, no guessing
    if gw then W, H = gw, gh end
    if ask then FN.askViewSize(si, sc.display, W, H) end
    local mw, mh = FN.viewSize(sc.display)  -- your own size in MA blocks wins over the measured one
    if mw then W, H = mw, mh end
    dbg(string.format("views: display %d -> %d x %d grid units (%s, cell %.1f x %.1f px)", sc.display, W, H,
      mw and "your size" or (gw and "MA's screen grid" or "measured"), cellW, cellH))
    local file = string.format("fs_view_d%d", sc.display)
    local f = io.open(dir .. PATHS.sep() .. file .. ".xml", "w")
    if not f then failures[#failures + 1] = "Views: can't write " .. dir return end
    f:write(TC.scr.xml(sc.display, W, H) .. "    </View>\n</GMA3>\n")
    f:close()
    local vpages = {}
    for _, page in ipairs(PAGES) do vpages[#vpages + 1] = page end
    for _, page in ipairs({"grp", "ccol", "gobo", "home", "upd"}) do vpages[#vpages + 1] = page end  -- (every screen)
    for _, page in ipairs(vpages) do
      local no = viewNo(si, page)
      local v = views[no]
      if v and tostring(v.name):sub(1, #CFG.PREFIX + 1) ~= CFG.PREFIX .. " " then
        failures[#failures + 1] = "View " .. no .. " is in use - left as it is"
      else
        C("Import View %d /File %s /NoConfirm", no, q(file))
        v = views[no]
        if v then
          pcall(function()
            v[1][1].Layout = obj("Layout " .. layoutNo(page))
            v.name = fs(PAGE[page].title .. (#screens > 1 and (" S" .. sc.display) or ""))
          end)
          made = made + 1
        end
      end
    end
  end
  sv("views_ok", made > 0 and "1" or "")
  local ds = {}
  for _, sc in ipairs(screens) do ds[#ds + 1] = tostring(sc.display) end
  sv("view_disp", table.concat(ds, ","))
  sv("views_ver", CFG.VIEWS_VER)
  sv("mast_view", "")  -- the Masters views are rebuilt at their next opening
  dbg(string.format("views: %s, %d screen(s), %d views", tostring(kind), #screens, made))
  if FS_afterViews then pcall(FS_afterViews) end  -- Home view: its layout and view bar button
end
FS_buildViews = function() buildViews(gv("console") == nil or gv("console") == "") end

end

-- ==== FireSystemHome.lua (copied by tools/make_tools.py) ====
MODS.Home = function(_ENV)

function setup(noAsk)
  for k in pairs(roundSeen) do roundSeen[k] = nil end
  for k in pairs(lastAp) do lastAp[k] = nil end  -- macros get rebuilt: redraw all
  for k in pairs(lastTxt) do lastTxt[k] = nil end
  for k in pairs(TC.names) do TC.names[k] = nil end
  for k in pairs(artSeen) do artSeen[k] = nil end
  for k in pairs(wheelCache) do wheelCache[k] = nil end
  if CFG.ROUND and gv("round_ver") ~= CFG.ROUND_VERSION then
    -- new round images: drop FireSystem's old round images / appearances so they're re-imported
    for no = CFG.ROUND_DISC_IMAGE, CFG.ROUND_IMAGE_BASE + 300 do
      local h = obj(string.format("Image %d.%d", CFG.IMAGE_POOL, no))
      if h and isOurs(h) then Cmd(string.format("Delete Image %d.%d /NC", CFG.IMAGE_POOL, no)) end
    end
    for no = CFG.ROUND_AP_BASE, CFG.ROUND_AP_BASE + 999 do
      local h = obj("Appearance " .. no)
      if h and isOurs(h) then Cmd(string.format("Delete Appearance %d /NC", no)) end
    end
    sv("round_ver", CFG.ROUND_VERSION)
  end
  failures = {}
  local missing = {}
  for _, g in ipairs(CFG.GROUPS) do if not obj("Group " .. g) then missing[#missing + 1] = g end end
  if #missing > 0 then  -- first start: let the user build the groups
    openGroupBuilder("These groups don't exist yet: " .. table.concat(missing, ", ") .. ".")
    return
  end
  BM.ensureLinears()  -- each group's linear version (kept when you stored your own)
  for _, g in ipairs(CFG.GROUPS) do BM.buildMasters(g) end  -- pixel groups' main fixtures
  TC.combo.check()  -- few groups: the combined pages join PAGES
  local nMacros = 0
  for _, page in ipairs(PAGES) do
    local spec = buildSpec(page)
    local n = spec.nMain
    nMacros = nMacros + #spec
    if n + 2 > (PAGE[page].mn or CFG.MACRO_BLOCK) then  -- (+2: the page's anchor buttons)
      MessageBox({title = "FireSystem", message = string.format(
        "The %s page needs %d macros but MACRO_BLOCK is %d. Raise MACRO_BLOCK.",
        PAGE[page].title, n, PAGE[page].mn or CFG.MACRO_BLOCK), commands = {{value = 1, name = "OK"}}})
      return
    end
  end
  local foreign = {}
  for _, path in ipairs(FN.plannedObjects()) do
    local h = obj(path)
    if h and not isOurs(h) then foreign[#foreign + 1] = path end
  end
  local msg = string.format("This builds 8 layouts, %d macros, %d sequences", nMacros, #allSequences()) ..
    (CFG.CREATE_PRESETS and ", starter presets" or "") .. " and clears the programmer.\n"
  if #foreign > 0 then
    local shown = {}
    for i = 1, math.min(#foreign, 12) do shown[#shown + 1] = foreign[i] end
    msg = msg .. "\nThese slots already hold your own objects:\n" .. table.concat(shown, ", ") ..
      (#foreign > 12 and (" ... (+" .. (#foreign - 12) .. " more)") or "") .. "\n"
    if not CFG.ALLOW_OVERWRITE_FOREIGN then
      MessageBox({title = "FireSystem", message = msg ..
        "\nNothing was changed. Move them, change the pool numbers in the plugin's CONFIG, " ..
        "or set ALLOW_OVERWRITE_FOREIGN = true.", commands = {{value = 1, name = "OK"}}})
      return
    end
  end
  if not noAsk and not Confirm("FireSystem setup", msg .. "\nContinue?") then return end

  C("ClearAll")
  importIcons()
  createAppearances()
  if CFG.CREATE_PRESETS then
    createPresets()
    -- COLOR 1-4 (and their Pastel / Dark versions) from the Custom Colours page
    for n = 1, #CFG.CUSTOM_COLORS do storeCustomColor(n) end
  end
  FN.createSequences()
  createLayoutsAndMacros()
  sv("pages_ver", TC.combo.ver())
  assignExecutors()
  buildViews(gv("console") == nil or gv("console") == "")
  layoutFix()
  sv("fit_sig", FIT.sig())
  rebuildAllKeys()
  refreshAll()
  C("ClearAll")
  if FS_openDefault then pcall(FS_openDefault) end

  log("Setup finished. Layouts %d-%d, macros from %d, sequences from %d.",
      layoutNo("dim"), layoutNo("xk"), CFG.MACRO_BASE, CFG.SEQ_BASE)
  if #failures > 0 then
    log("%d command(s) were rejected - see below. Most are cosmetic.", #failures)
    for _, f in ipairs(failures) do log("  %s", f) end
  end
end

-- ======================================================================
-- ENTRY POINT
-- ======================================================================
-- ======================================================================
-- SAVE LOOK: copy every fired recipe line into a new cue of LOOKS_SEQ
-- ======================================================================
function saveLook(name)
  local src = {}
  for _, page in ipairs(FIRE_PAGES) do
    for gi = 1, TC.fill.n(page) do
      local seq, active = seqNo(page, gi), false
      pcall(function() active = DataPool().Sequences[seq]:HasActivePlayback() end)
      if active and not obj(rAddr(seq, 1)) then
        -- fired before recipes existed: rebuild it as recipes from the last fired state
        local f = gv("fired_" .. page .. "_" .. gi)
        if type(f) == "string" and f ~= "" then
          local st = loadGroup(page, gi)
          for k, v in pairs(deser(f)) do st[k] = v end
          if CONTENT[page](st) then fireRecipe(page, gi, st) end
        end
      end
      if active then
        local pc = TC.playingCue(seq)
        TC.cue[seq] = (pc == 2) and 2 or nil  -- the look that is playing (Color / Position: cue 1 or 2)
        for k = 1, 8 do
          local h = obj(rAddr(seq, k))
          local on = false
          if h then pcall(function() on = h.Enabled and h.Selection ~= nil end) end
          if on then src[#src + 1] = rAddr(seq, k) end
        end
        TC.cue[seq] = nil
      end
    end
  end
  if #src == 0 then
    Echo("FireSystem: nothing is fired (as recipes) - FIRE a look first")
    return
  end
  local L = CFG.LOOKS_SEQ
  local isNew = DataPool().Sequences[L] == nil
  local cue = 1
  if not isNew then
    pcall(function()
      for _, c in ipairs(DataPool().Sequences[L]:Children()) do
        local n = tonumber(c.No)  -- cue 1 is No 1000 internally
        if n and tostring(c:GetClass()) == "Cue" and n >= 1000 then
          n = math.floor(n / 1000)
          if n >= cue then cue = n + 1 end
        end
      end
    end)
  end
  name = (name and name ~= "") and name or nil
  if not name then
    local ok, v = pcall(TextInput, "Save look as cue " .. cue, "Look " .. cue)
    if not ok or v == nil then return end
    name = (v ~= "") and v or ("Look " .. cue)
  end
  C("ClearAll")
  C("Store Sequence %d Cue %d /Overwrite", L, cue)
  for i, a in ipairs(src) do C("Copy %s At Sequence %d Cue %d Part 0.%d /NC", a, L, cue, i) end
  C("Label Sequence %d Cue %d %s", L, cue, q(name))
  if isNew then
    C("Label Sequence %d %s", L, q(fs("Looks")))
    Cany({ string.format('Set Sequence %d Property "Tracking" "No"', L) })  -- every look stands alone
    if CFG.LOOKS_EXEC then
      local lpg, lex = TC.ex.at("looks", CFG.EXEC_PAGE, CFG.LOOKS_EXEC)
      local exec = lpg .. "." .. lex
      local p, cur = DataPool().Pages[lpg], nil
      pcall(function() for _, c in ipairs(p:Children()) do if tonumber(c.No) == lex then cur = c end end end)
      local empty = true
      if cur then pcall(function() empty = cur.Object == nil end) end
      if empty then C("Assign Sequence %d At Page %s", L, exec) end
    end
  end
  Echo(string.format("FireSystem: saved '%s' as Sequence %d Cue %d (%d recipe lines)", name, L, cue, #src))
end

-- ======================================================================
-- Home page tools (what FireSystemStart did): patch, groups, masters page
-- ======================================================================
START = {}
function START.get(h, ...)
  for _, k in ipairs({...}) do
    local ok, v = pcall(function() return h[k] end)
    if ok and v ~= nil then return v end
    ok, v = pcall(function() return h:Get(k) end)
    if ok and v ~= nil then return v end
  end
end
function START.children(h)
  local ok, c = pcall(function() return h:Children() end)
  return (ok and type(c) == "table") and c or {}
end
-- ---- Looks pack: FireSystem's images and appearances exported once into the MA library
-- (media/images/FireSystem Images.xml, appearances/FireSystem Appearances.xml, each with a
-- .txt of the pool numbers in export order). A show without them imports the pack and every
-- object goes back to its own number, so the icons are never written out and imported again.
-- MA's import packs the objects one after another, so they land in a free block (9001+)
-- and are moved to their numbers from there.
START.PACK_AT = 9001
START.PACK_VARS = {"FS_round_ver", "FS_bg_pg_ver", "FS_art2_sig"}
START.PACK = {
  {name = "Images", dir = {"media", "images"}, from = function() return CFG.ICON_IMAGE_BASE end, to = 2999,
   pool = function() return ShowData().MediaPools.Images end,
   ref = function(n) return string.format('"Images".%d', n) end,
   addr = function(n) return string.format("Image %d.%d", CFG.IMAGE_POOL, n) end},
  {name = "Appearances", dir = {"appearances"}, from = function() return CFG.APPEARANCE_BASE end, to = 8999,
   pool = function() return ShowData().Appearances end,
   ref = function(n) return tostring(n) end,
   addr = function(n) return "Appearance " .. n end},
}
function START.packFile(k, ext) return PATHS.lib(table.unpack(k.dir)) .. PATHS.sep() .. "FireSystem " .. k.name .. (ext or "") end
function START.packExport()
  local n = 0
  for _, k in ipairs(START.PACK) do
    local list = {}
    for _, h in ipairs(START.children(k.pool())) do
      local no = tonumber(h.no)
      if no and no >= k.from() and no <= k.to then list[#list + 1] = {no, tostring(h.name)} end
    end
    table.sort(list, function(a, b) return a[1] < b[1] end)
    if #list > 0 then
      C('Export %s %s Thru %d "FireSystem %s" /NoConfirm', k.name == "Images" and "Image" or "Appearance",
        k.ref(list[1][1]), list[#list][1], k.name)
      local f = io.open(START.packFile(k, ".txt"), "w")
      if f then
        -- the versions the images were made for: a new show then keeps them instead of
        -- dropping them as out of date (round discs, numbered backgrounds, extra artwork)
        for _, v in ipairs(START.PACK_VARS) do
          local x = GetVar(GlobalVars(), v)
          if x ~= nil then f:write("#", v, "\t", tostring(x), "\n") end
        end
        for _, e in ipairs(list) do f:write(e[1], "\t", e[2], "\n") end
        f:close()
      end
      n = n + #list
      dbg(string.format("looks pack: %d %s exported", #list, k.name))
    end
  end
  return n
end
-- imports the pack into this show: objects whose number is free go there, the rest are dropped
function START.packImport()
  local placed = 0
  for _, k in ipairs(START.PACK) do  -- images first: the appearances' images are then found, not copied
    local nums, vars = {}, {}
    local f = io.open(START.packFile(k, ".txt"), "r")
    if f then
      for line in f:lines() do
        local no = tonumber(line:match("^(%d+)"))
        if no then nums[#nums + 1] = no end
        local v, x = line:match("^#([%w_]+)\t(.*)$")
        if v then vars[v] = x end
      end
      f:close()
    end
    local at = START.PACK_AT
    local free = #nums > 0 and at + #nums - 1 <= 9999 and PATHS.exists(START.packFile(k, ".xml"))
    for i = at, at + #nums - 1 do if free and obj(k.addr(i)) then free = false end end
    if free then
      C('Import %s %s "FireSystem %s" /NoConfirm', k.name == "Images" and "Image" or "Appearance", k.ref(at), k.name)
      for i, no in ipairs(nums) do
        local src = at + i - 1
        if obj(k.addr(src)) then
          if obj(k.addr(no)) then Cmd(string.format("Delete %s /NC", k.addr(src)))
          else C("Move %s At %s", k.addr(src), k.addr(no)) placed = placed + 1 end
        end
      end
      for v, x in pairs(vars) do SetVar(GlobalVars(), v, x) end
      dbg(string.format("looks pack: %s imported (%d)", k.name, #nums))
    elseif #nums > 0 then
      dbg(string.format("looks pack: %s not imported (no file, or %d-%d isn't free)", k.name, at, at + #nums - 1))
    end
  end
  return placed
end
FS_packImport = START.packImport

function START.findByName(container, wanted)
  if not container then return nil end
  local list = START.children(container)
  if wanted == nil or wanted == "" then return list[1] end
  local w = wanted:lower()
  for _, h in ipairs(list) do if tostring(START.get(h, "name") or ""):lower() == w then return h end end
  for _, h in ipairs(list) do if tostring(START.get(h, "name") or ""):lower():find(w, 1, true) then return h end end
end
-- patches CFG.RIG (fixture types must be in the show); returns the blocks that are there
function START.patchRig()
  local patched, types = {}, nil
  pcall(function() types = Patch().FixtureTypes end)
  for _, r in ipairs(CFG.RIG) do
    local ft = START.findByName(types, r.type)
    if not ft then
      failures[#failures + 1] = "Fixture type '" .. r.type .. "' is not in the show (Patch > Fixture Types > Import)"
    elseif obj("Fixture " .. r.fid) then
      patched[#patched + 1] = r  -- already patched: use what is there
    else
      local mode = START.findByName(START.get(ft, "DMXModes"), r.mode)
      if not mode then
        failures[#failures + 1] = "No DMX mode '" .. tostring(r.mode) .. "' in " .. r.type
      else
        local fp = tonumber(START.get(mode, "footprint", "Footprint", "DMXFootprint"))
        if not fp or fp <= 0 then fp = #START.children(START.get(mode, "DMXChannels")) end
        if not fp or fp <= 0 then fp = 32 end
        local ok, stage = true, nil
        pcall(function() stage = Patch().Stages[1].Fixtures end)
        Cmd("ChangeDestination Root")
        if not (stage and okResult(Cmd("ChangeDestination " .. stage:ToAddr()))) then ok = false end
        local uni, addr = 1, 1
        if r.address then uni, addr = r.address:match("(%d+)%.(%d+)") uni, addr = tonumber(uni), tonumber(addr) end
        for i = 0, (ok and r.count or 0) - 1 do
          local t = {mode = mode, amount = 1, fid = tostring(r.fid + i), name = (r.name or r.type) .. " " .. (i + 1),
                     undo = "FireSystem patch"}
          if r.address then
            if addr + fp + CFG.ADDRESS_GAP - 1 > 512 then uni, addr = uni + 1, 1 end  -- don't straddle universes
            t.patch = {string.format("%d.%03d", uni, addr)}
            addr = addr + fp + CFG.ADDRESS_GAP
          end
          local res = AddFixtures(t)
          if res == nil or res == false then ok = false end
        end
        Cmd("ChangeDestination Root")
        if ok then patched[#patched + 1] = r else failures[#failures + 1] = "Patching failed for " .. r.type end
      end
    end
  end
  local blocks = {}
  for _, r in ipairs(patched) do
    local f = {}
    for i = 0, r.count - 1 do f[#f + 1] = r.fid + i end
    blocks[#blocks + 1] = {name = r.name or r.type, fids = f}
  end
  return blocks
end
-- one block per fixture type of what is patched
function START.scanPatch()
  local byType, order = {}, {}
  local function walk(h, depth)
    if depth > 3 then return end
    for _, f in ipairs(START.children(h)) do
      local fid, ft = tonumber(START.get(f, "fid", "FID")), START.get(f, "fixturetype", "FixtureType")
      local tname = ft and START.get(ft, "name") or nil
      if fid and tname and tname ~= "Universal" then
        if not byType[tname] then byType[tname] = {} order[#order + 1] = tname end
        table.insert(byType[tname], fid)
      else walk(f, depth + 1) end
    end
  end
  pcall(function() walk(Patch().Stages, 0) end)
  local out = {}
  for _, n in ipairs(order) do table.sort(byType[n]) out[#out + 1] = {name = n, fids = byType[n]} end
  return out
end
-- splits the biggest blocks into L / R halves until there are 8
function START.splitLR(blocks)
  while CFG.SPLIT_LR and #blocks < 8 do
    local bi, best = nil, 1
    for i, b in ipairs(blocks) do if not b.split and #b.fids > best then bi, best = i, #b.fids end end
    if not bi then break end
    local b = table.remove(blocks, bi)
    local half, L, R = math.ceil(#b.fids / 2), {}, {}
    for i, f in ipairs(b.fids) do if i <= half then L[#L + 1] = f else R[#R + 1] = f end end
    table.insert(blocks, bi, {name = b.name .. " R", fids = R, split = true})
    table.insert(blocks, bi, {name = b.name .. " L", fids = L, split = true})
  end
  while #blocks > 8 do table.remove(blocks) end
  return blocks
end
-- stores the blocks as groups 1..n and makes them FireSystem's groups
function START.buildGroups(blocks)
  local nums = {}
  for i, b in ipairs(blocks) do
    local cur = obj("Group " .. i)
    local curName = cur and objName(cur)
    if cur and b.sel and curName ~= b.name and not CFG.OVERWRITE_GROUPS then
      failures[#failures + 1] = string.format("Group %d '%s' kept (OVERWRITE_GROUPS = true replaces it)", i, tostring(curName))
    else
      local sel = b.sel and ("Fixture " .. b.sel)
      if not sel then
        local parts, j = {}, 1
        while j <= #b.fids do  -- "Fixture 101 Thru 108 + 110"
          local k = j
          while k < #b.fids and b.fids[k + 1] == b.fids[k] + 1 do k = k + 1 end
          parts[#parts + 1] = (k > j) and (b.fids[j] .. " Thru " .. b.fids[k]) or tostring(b.fids[j])
          j = k + 1
        end
        sel = "Fixture " .. table.concat(parts, " + ")
      end
      C("ClearAll")
      C(sel)
      if gv("grid3d_auto") == "1" then FN.grid3d() end  -- Group Builder > Auto Groups: 3D Grid
      C("Store Group %d /Overwrite", i)
      C("Label Group %d %s", i, q(b.name))
    end
    nums[#nums + 1] = tostring(i)
  end
  C("ClearAll")
  if #nums > 0 then sv("groups", table.concat(nums, ",")) end
  return #nums
end
-- 3D Grid: re-selects the selection with each fixture in the Selection Grid where it hangs on
-- stage (its 3D position in the Patch, CFG.GRID3D_*): stage X -> grid X, height -> grid Y (top
-- row = highest), depth -> grid Z. Fixtures within GRID3D_TOL metres on an axis share a slot
-- (so a truss is one row). Each selected element (a fixture, or a child fixture / cell) is
-- selected again on its own, in the same order (effects still run in it): only the elements
-- that were selected, so a group of child fixtures (e.g. only a panel's strobe parts) keeps
-- them. A fixture's elements keep their layout from the old grid inside its slot, and a slot
-- is as wide / high / deep as its largest fixture. Returns the element count and the grid
-- size in slots, or nil.
function FN.grid3d()
  local units, byFid, elems = {}, {}, {}
  local function num(v) return tonumber((tostring(v or ""):match("^%s*(%-?[%d%.]+)"))) end
  pcall(function()
    local fi, x, y, z = SelectionFirst()
    while fi do
      local sf = GetSubfixture(fi)
      -- cells as "Fixture 1011.001.003": the command line reads "1011.1.3" differently
      local a
      pcall(function() a = tostring(sf:ToAddr()):gsub("%.(%d+)", function(d) return string.format(".%03d", tonumber(d)) end) end)
      -- the fixture with an ID above it (child fixtures and cells take its stage position)
      local h, fid = sf, nil
      for _ = 1, 5 do
        if not h then break end
        fid = num(START.get(h, "FID", "fid"))
        if fid then break end
        local ok, p = pcall(function() return h:Parent() end)
        h = ok and p or nil
      end
      if fid and a then
        local u = byFid[fid]
        if not u then
          u = {fid = fid, min = {}, size = {1, 1, 1}}
          for k, ax in ipairs(CFG.GRID3D_AXES) do u[k] = num(START.get(h, ax, ax:lower())) or 0 end
          byFid[fid] = u
          units[#units + 1] = u
        end
        local e = {addr = a, u = u, o = {tonumber(x) or 0, tonumber(y) or 0, tonumber(z) or 0}}
        for k = 1, 3 do if not u.min[k] or e.o[k] < u.min[k] then u.min[k] = e.o[k] end end
        elems[#elems + 1] = e
      end
      fi, x, y, z = SelectionNext(fi)
    end
  end)
  if #units == 0 then return nil end
  -- each element's place inside its fixture (from the old grid), and the fixture's footprint
  for _, e in ipairs(elems) do
    for k = 1, 3 do
      e.o[k] = e.o[k] - e.u.min[k]
      if e.o[k] + 1 > e.u.size[k] then e.u.size[k] = e.o[k] + 1 end
    end
  end
  local size, any = {}, false
  for i = 1, 3 do
    -- slots along the axis: sorted, a new slot when a fixture is more than the tolerance past
    -- the first fixture of the current slot
    local list = {}
    for k, u in ipairs(units) do list[k] = u end
    table.sort(list, function(a, b) return a[i] < b[i] end)
    local slot, anchor = -1, nil
    for _, u in ipairs(list) do
      if anchor == nil or u[i] - anchor > (CFG.GRID3D_TOL[i] or 0) then slot, anchor = slot + 1, u[i] end
      u["g" .. i] = slot
      if u[i] ~= 0 then any = true end
    end
    size[i] = slot + 1
    if CFG.GRID3D_INVERT[i] then for _, u in ipairs(units) do u["g" .. i] = slot - u["g" .. i] end end
    -- grid start of each slot: the slots before it, each as big as its biggest fixture
    local w = {}
    for _, u in ipairs(units) do local g = u["g" .. i] w[g] = math.max(w[g] or 1, u.size[i]) end
    local start = {[0] = 0}
    for g = 1, slot do start[g] = start[g - 1] + (w[g - 1] or 1) end
    for _, u in ipairs(units) do u["s" .. i] = start[u["g" .. i]] end
  end
  if not any then return nil end  -- no 3D positions in the Patch: the grid stays as it is
  C("ClearSelection")
  for _, e in ipairs(elems) do
    C("Grid %d/%d/%d", e.u.s1 + e.o[1], e.u.s2 + e.o[2], e.u.s3 + e.o[3])
    C(e.addr)
  end
  dbg(string.format("3D Grid: %d elements of %d fixtures -> %d x %d x %d slots", #elems, #units, size[1], size[2], size[3]))
  return #elems, size
end
-- Group Builder > 3D Grid: the selection when there is one (Edit Grid: then Save Grid), else the
-- groups picked in a pop-up, each stored again with its new grid
function FN.grid3dPress()
  local none = "None of the fixtures has a 3D position (Patch: Pos X / Y / Z), so the grid is unchanged."
  local function msg(t) MessageBox({title = "FireSystem: 3D Grid", message = t, commands = {{value = 1, name = "OK"}}}) end
  if SelectionCount() > 0 then
    local n, size = FN.grid3d()
    if not n then msg(none)
    else
      Echo(string.format("FireSystem: 3D Grid - %d fixtures / cells in %d x %d x %d slots%s", n, size[1], size[2], size[3],
        gv("grp_edit") ~= "" and " - tap Save Grid to keep it" or " - store it into a group to keep it"))
    end
    return refresh("grp")
  end
  local groups, states = {}, {}
  local function addGroup(g)
    if obj("Group " .. g) then
      local name = string.format("Group %d %s", g, tostring(objName(obj("Group " .. g)) or ""))
      groups[#groups + 1] = {g, name}
      states[#states + 1] = {name = name, state = g <= 8}
    end
  end
  for g = 1, 8 do addGroup(g) end
  for i = 1, #CFG.UTIL do addGroup(CFG.UTIL_GROUP_BASE + i - 1) end
  if #groups == 0 then msg("Store a group first (or select fixtures).") return refresh("grp") end
  local ok, r = pcall(MessageBox, {title = "FireSystem: 3D Grid",
    message = "Arrange these groups in the Selection Grid by where their fixtures are on stage\n" ..
      "(left / right = X, height = Y, depth = Z). Their fixture order (effect order) stays.",
    commands = {{value = 1, name = "Arrange"}, {value = 0, name = "Cancel"}}, states = states})
  if not ok or type(r) ~= "table" or r.result ~= 1 then return refresh("grp") end
  local done = 0
  for _, e in ipairs(groups) do
    local want = true
    if type(r.states) == "table" and r.states[e[2]] ~= nil then want = r.states[e[2]] and true or false end
    if want then
      C("ClearAll")
      C("Group %d", e[1])
      if FN.grid3d() then
        C("Store Group %d /Overwrite", e[1])
        BM.units[e[1]] = nil
        done = done + 1
      end
    end
  end
  C("ClearAll")
  TC.capCache = {}
  if done == 0 then msg(none) else Echo(string.format("FireSystem: 3D Grid - %d group(s) arranged", done)) end
  return refresh("grp")
end
-- executor page: FireSystem's executors and masters, plus the white light
function START.masters()
  failures = {}
  if not obj("Page " .. CFG.EXEC_PAGE) then
    C("Store Page %d", CFG.EXEC_PAGE)
    C("Label Page %d %s", CFG.EXEC_PAGE, q(fs("Playbacks")))
  end
  assignExecutors()
  local wpg, wex = TC.ex.at("white", CFG.EXEC_PAGE, CFG.WHITE_EXEC or 0)
  local ex = CFG.WHITE_EXEC and string.format("Page %d.%d", wpg, wex)
  if ex then
    local e, used = TC.ex.handle(wpg, wex), false
    pcall(function()
      used = e and e.Object and not isOurs(e.Object)
    end)
    if used then
      failures[#failures + 1] = ex .. " is in use - white light left out"
    else
      C("ClearAll")
      -- the colour is the White colour preset (linked, so editing it on Update Presets changes the white light)
      local wp = colorPreset(1)
      -- recipes: every group at Full and White, pixel groups' Masters at Masters Full
      if not obj("Sequence " .. CFG.WHITE_SEQ) then C("Store Sequence %d /Overwrite", CFG.WHITE_SEQ) end
      local lines = {}
      for _, g in ipairs(CFG.GROUPS) do
        if presetExists(1, FULL_PRESET) then lines[#lines + 1] = {g, "1." .. FULL_PRESET} end
        if presetExists(4, wp) then lines[#lines + 1] = {g, "4." .. wp} end
      end
      if presetExists(STROBES.pool, STROBES.mfull) then
        for _, M in ipairs(BM.masterGroups()) do lines[#lines + 1] = {M, STROBES.pool .. "." .. STROBES.mfull} end
      end
      if #lines > 0 then TC.recipeCue(CFG.WHITE_SEQ, lines)
      else failures[#failures + 1] = "White light: no Full / White preset yet (Home > Build makes them)" end
      C("Label Sequence %d %s", CFG.WHITE_SEQ, q(fs("White Light")))
      C("ClearAll")
      C("Assign Sequence %d At %s", CFG.WHITE_SEQ, ex)
      TC.ex.set(wpg, wex, CFG.WHITE_KEY, nil, nil)
    end
  end
  for _, f in ipairs(failures) do log("  %s", f) end
  MessageBox({title = "FireSystem", message = "Executor page " .. CFG.EXEC_PAGE .. " is built." ..
    (#failures > 0 and ("\n\n" .. table.concat(failures, "\n")) or ""), commands = {{value = 1, name = "OK"}}})
end
-- Utility page: executor page for front wash, specials, haze, fan and house lights
function START.utility()
  failures = {}
  TC.ex.tidy(true)
  local P = CFG.UTIL_PAGE
  if not obj("Page " .. P) then C("Store Page %d", P) end
  C("Label Page %d %s", P, q(fs("Utility")))
  local made = {}
  for i, u in ipairs(CFG.UTIL) do
    local name, fix, attr, ex = u[1], u[2], u[3], u[4]
    local g, seq = CFG.UTIL_GROUP_BASE + i - 1, CFG.UTIL_SEQ_BASE + i - 1
    local okFix = false
    local gh, sh = obj("Group " .. g), obj("Sequence " .. seq)
    -- no fixtures given, or stored / arranged on the Group Builder: the group as you stored it
    local keep = (fix == nil or fix == "") or (gh ~= nil and gv("ukeep_" .. g) == "1")
    if keep then okFix = gh ~= nil
    else pcall(function() local l = ObjectList("Fixture " .. fix) okFix = l and #l > 0 end) end
    if not okFix then
      failures[#failures + 1] = name .. (keep and (": store its fixtures into Group " .. g .. " first - skipped")
                                              or (": no fixtures " .. fix .. " in this show - skipped"))
    elseif (gh and not keep and not isOurs(gh)) or (sh and not isOurs(sh)) then
      failures[#failures + 1] = name .. ": Group " .. g .. " or Sequence " .. seq .. " is in use - skipped"
    else
      C("ClearAll")
      if not keep then
        C("Fixture %s", fix)
        C("Store Group %d /Overwrite", g)
        C("Label Group %d %s", g, q(fs(name)))
      end
      if u.specials then
        -- a Group Master: the group on the fader scales the specials toggled on the Dimmer page
        if sh and isOurs(sh) then C("Delete Sequence %d /NC", seq) end
      else
        C("Store Sequence %d /Overwrite", seq)
        C("Label Sequence %d %s", seq, q(fs(name)))
      end
      if u.specials then
        sv("spec_built", "")  -- the toggles are re-read from the group at the next press
      else  -- one cue at 100 % from the entry's own preset (dimmer, haze, fan); the fader sets the level
        local pno = CFG.UTIL_PRESET + i - 1
        local a = (attr == "dim") and CFG.ATTR.dim or attr
        storePreset(21, pno, name .. " 100", {"ClearSelection", "Group " .. g, string.format("Attribute %s At 100", q(a))})
        Cmd(string.format("Delete Sequence %d Cue 2 /NC", seq))  -- the old 0 % / 100 % crossfade
        if presetExists(21, pno) then TC.recipeCue(seq, {{g, "21." .. pno}})  -- the group + its preset
        else failures[#failures + 1] = name .. ": Preset 21." .. pno .. " couldn't be stored" end
      end
      C("ClearAll")
      local UP
      UP, ex = TC.ex.at("util" .. i, P, ex)
      if not obj("Page " .. UP) then C("Store Page %d", UP) end
      local path = string.format("Page %d.%d", UP, ex)
      local cur = TC.ex.handle(UP, ex)
      local free = true
      pcall(function() local o = cur and cur.Object free = (o == nil) or isOurs(o) end)
      if not free then
        failures[#failures + 1] = path .. " is in use - " .. name .. " not assigned"
      else
        C("Assign %s %d At %s", u.specials and "Group" or "Sequence", u.specials and g or seq, path)
        if not u.specials then TC.ex.set(UP, ex, (attr == "dim") and "Toggle" or "Flash", (attr == "dim") and "Master" or "Temp") end
        made[#made + 1] = name .. " " .. ex
      end
    end
  end
  TC.ex.copies(true)
  log("Utility page %d: %s", P, table.concat(made, ", "))
  for _, f in ipairs(failures) do log("  %s", f) end
  Echo("FireSystem: Utility page " .. P .. " - " .. table.concat(made, ", "))
  if #failures > 0 then
    MessageBox({title = "FireSystem", message = "Utility page " .. P .. ": " .. table.concat(made, ", ") ..
      "\n\n" .. table.concat(failures, "\n"), commands = {{value = 1, name = "OK"}}})
  end
end

-- Home page: launcher layout in its own view, on a view bar button of screen 1
-- after the views are (re)built: the Home view shows the Home layout and sits on its view button
function START.afterViews()
  local views = ShowData().UserProfiles[1].Views
  if not views[viewNo(1, "home")] then return end
  if not obj("Layout " .. layoutNo("home")) or gv("built_home") ~= CFG.EXTRA_VER then
    createLayoutsAndMacros({"home"})
    sv("built_home", CFG.EXTRA_VER)
    TC.bg.set("home")
    refresh("home")
  end
  -- each screen's Home view, on that screen's view bar
  for si, d in ipairs(TC.scr.list()) do
    local vno = viewNo(si, "home")
    if views[vno] then
      pcall(function() views[vno][1][1].Layout = obj("Layout " .. layoutNo("home")) end)
      local n, mine = CFG.HOME_VIEWBUTTON, true
      pcall(function()
        local b = ShowData().UserProfiles[1].ScreenConfigurations[1][2][d][n]
        local o = b and tostring(b:Get("Object", Enums.Roles.Display))
        mine = not o or o == "" or o == "None" or o:find(PAGE.home.title, 1, true) ~= nil
      end)
      if n and mine then Cmd(string.format("Assign View %d At ViewButton %d.%d", vno, d, n)) end
    end
  end
end
FS_afterViews = function()
  START.afterViews()
  if FS_tcViews and obj("Layout " .. layoutNo("tc")) then pcall(FS_tcViews) end
end
function START.openHome()
  local views = ShowData().UserProfiles[1].Views
  if not openExtraPage("home") then return end
  if CFG.VIEWS and not views[viewNo(1, "home")] then buildViews(gv("console") == nil or gv("console") == "") end
  START.afterViews()
  local vno = TC.scr.view("home")
  if views[vno] then Cmd(string.format("View %d", vno)) end
end
-- the default view: the Dimmer FX page
function START.openDefault()
  Cany({ string.format("Select Layout %d", layoutNo("dim")), string.format("Layout %d", layoutNo("dim")) })
  TC.scr.show("dim")
end
FS_openDefault = START.openDefault

end

-- ==== FireSystemTimecode.lua (copied by tools/make_tools.py) ====
MODS.Timecode = function(_ENV)

-- ======================================================================
-- Timecode: songs (Timecode 201+), source, record presses / timeline / blend
-- ======================================================================
-- source, record settings: "All Events" lets MA record playbacks and remote events
function TC.apply(i)
  local h = TC.obj(i)
  if not h then return end
  local src = TC.source()
  pcall(function()
    h.TCSLOT = (src == "internal") and -1 or (CFG.TC_SLOTS[src] or -1)
    h.PLAYBACKANDRECORD = 1
    h.RECORDREMOTEEVENTS = true
  end)
end
function TC.ensure(i, name)
  if TC.obj(i) then return true end
  if not okResult(Cmd(string.format("Store Timecode %d /NC", TC.no(i)))) then return false end
  C("Label Timecode %d %s", TC.no(i), q(fs(name or ("Song " .. i))))
  TC.apply(i)
  return true
end
-- the views follow the song: timecode windows show it, the sheet shows the Looks
function TC.target()
  local views = ShowData().UserProfiles[1].Views
  for si = 1, #TC.scr.list() do for _, page in ipairs({"tc", "rec", "tced"}) do
    pcall(function()
      for _, w in ipairs(views[viewNo(si, page)]:Children()) do
        local st = w[1]
        if tostring(w.name) == "WindowTimecode" and TC.obj() then st.TIMECODE = TC.obj() end
        if tostring(w.name) == "WindowSequenceSheet" then
          -- (the editor's: the sequence of the event picked last)
          local L = DataPool().Sequences[page == "tced" and tonumber(gv("tced_seq") or "") or CFG.LOOKS_SEQ]
          if L then st.LINKTYPE = "Fixed" st.FIXEDTARGET = L end
        end
      end
    end)
  end end
  if TC.obj() then Cmd(string.format("Select Timecode %d", TC.no())) end
end
-- after a recording, tidy the song's tracks:
--   FireSystem page tracks: Gotos to the live cue 1 are dropped (they would replay whatever
--   the page shows at that moment); recorded snapshot cues (101+) and Offs stay
--   record mode: the Looks track is dropped too (only the presses stay)
function TC.cleanup(i)
  local h, mode = TC.obj(i), TC.mode()
  if not h then return end
  local looks = objName(obj("Sequence " .. CFG.LOOKS_SEQ))
  local nEv, nTr = 0, 0
  pcall(function()
    for _, tg in ipairs(h:Children()) do
      local dropTracks = {}
      for ti, tr in ipairs(tg:Children()) do
        local n = tostring(tr.name)
        if mode == "record" and looks and n == "<" .. looks .. ">" then
          dropTracks[#dropTracks + 1] = ti
        elseif n:match("^<" .. CFG.PREFIX .. " %w+_G%d+>$") then
          local left = 0
          for _, range in ipairs(tr:Children()) do
            for _, sub in ipairs(range:Children()) do
              local drop = {}
              for ei, ev in ipairs(sub:Children()) do
                local tok = tostring(ev:Get("Token", Enums.Roles.Display))
                local cue = tonumber(tostring(ev:Get("CueDestination", Enums.Roles.Display)):match("^Cue ([%d%.]+)"))
                if tok == "Goto" and cue and cue < CFG.TC_SNAP_BASE then drop[#drop + 1] = ei end
              end
              for k = #drop, 1, -1 do sub:Delete(drop[k]) end
              nEv = nEv + #drop
              left = left + sub:Count()
            end
          end
          if left == 0 then dropTracks[#dropTracks + 1] = ti end
        end
      end
      for k = #dropTracks, 1, -1 do tg:Delete(dropTracks[k]) end
      nTr = nTr + #dropTracks
    end
  end)
  if nEv + nTr > 0 then dbg(string.format("timecode %d (%s): %d live-cue event(s), %d track(s) left out", TC.no(i), mode, nEv, nTr)) end
end
-- the Timecode / Setlist / Recording views: layout on the left, MA's windows on the right
-- (only = "grp": just the Group Builder's view, its layout with a Selection Grid on the right)
function TC.buildViews(only)
  local views = ShowData().UserProfiles[1].Views
  local dir = PATHS.lib("userprofiles", "views")
  local list = TC.scr.list()
  for si, d in ipairs(list) do  -- one set per screen
    local W, H = TC.scr.size(si)
    local lw = math.max(8, math.floor(W * 0.36))
    local rw = W - lw
    local le, th = math.max(10, math.floor(W * 0.5)), math.floor(H * 0.55)  -- the editor: a wider layout
    local layouts = {
      tc    = {{"WindowTimecode", lw, 0, rw, H}},
      songs = {{"WindowTimecodePool", lw, 0, rw, H}},
      rec   = {{"WindowTimecode", lw, 0, rw, math.floor(H / 2)}, {"WindowSequenceSheet", lw, math.floor(H / 2), rw, H - math.floor(H / 2)}},
      tced  = {{"WindowTimecode", le, 0, W - le, th}, {"WindowSequenceSheet", le, th, W - le, H - th}},
    }
    if only then
      lw = math.max(8, math.floor(W * 0.55))
      layouts = {[only] = {{"WindowSelectionView", lw, 0, W - lw, H}}}
    end
    for page, wins in pairs(layouts) do
      local no = viewNo(si, page)
      local v = views[no]
      if v and tostring(v.name):sub(1, #CFG.PREFIX + 1) ~= CFG.PREFIX .. " " then
        failures[#failures + 1] = "View " .. no .. " is in use - left as it is"
      else
        if v then Cmd(string.format("Delete View %d /NC", no)) end
        local x = {TC.scr.xml(d, (page == "tced") and wins[1][2] or lw, H)}
        for _, w in ipairs(wins) do
          x[#x + 1] = string.format('        <ViewWidget Name="%s" Display="%d" X="%d" Y="%d" W="%d" H="%d" MinW="4" MinH="4"/>\n',
            w[1], d, w[2], w[3], w[4], w[5])
        end
        x[#x + 1] = "    </View>\n</GMA3>\n"
        local file = "fs_view_" .. page .. "_d" .. d
        local f = io.open(dir .. PATHS.sep() .. file .. ".xml", "w")
        if f then
          f:write(table.concat(x))
          f:close()
          C("Import View %d /File %s /NoConfirm", no, q(file))
          pcall(function()
            views[no][1][1].Layout = obj("Layout " .. layoutNo(page))
            views[no].name = fs(PAGE[page].title .. (#list > 1 and (" S" .. d) or ""))
          end)
        end
      end
    end
  end
  TC.target()
end
-- opens one of the timecode pages (layout + view built when needed)
FS_tcViews = function() TC.buildViews() end
function TC.open(page)
  for _, p in ipairs({"tc", "songs", "rec", "tced"}) do
    if not obj("Layout " .. layoutNo(p)) or gv("built_" .. p) ~= CFG.EXTRA_VER then
      createLayoutsAndMacros({p})
      sv("built_" .. p, CFG.EXTRA_VER)
      TC.bg.set(p)
    end
  end
  if not ShowData().UserProfiles[1].Views[viewNo(TC.scr.cur(), page)] then TC.buildViews() end
  TC.refresh()
  openExtraPage(page)
end
function TC.refresh()
  TC.ed.list = nil  -- (the editor reads the song's events again)
  for _, p in ipairs({"tc", "songs", "rec", "tced", "home"}) do
    if obj("Layout " .. layoutNo(p)) and gv("built_" .. p) == CFG.EXTRA_VER then pcall(refresh, p) end
  end
end
-- recording started / stopped: the REC dot on every other page follows
function TC.refreshDots()
  for _, p in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "dpf", "pcol", "mast", "upd", "gobo", "ccol", "grp"}) do
    -- (a page built by an older version waits for its rebuild: its buttons sit elsewhere)
    local cur = (p == "grp") or ((PAGE[p].i < 8 or TC.combo.on(p)) and gv("pages_ver") == TC.combo.ver()) or gv("built_" .. p) == CFG.EXTRA_VER
    if cur and obj("Layout " .. layoutNo(p)) then pcall(refresh, p) end
  end
end
-- Update Presets page
function TC.upd.open()
  -- the buttons depend on the category: rebuild when it changed
  if gv("built_upd") == CFG.EXTRA_VER and gv("upd_built_cat") ~= TC.upd.cat() then sv("built_upd", "") end
  sv("upd_built_cat", TC.upd.cat())
  local views = ShowData().UserProfiles[1].Views
  for si, d in ipairs(TC.scr.list()) do  -- its view on each screen (the standard full-screen one)
    local vno = viewNo(si, "upd")
    if CFG.VIEWS and not views[vno] then
      if okResult(Cmd(string.format('Import View %d /File "fs_view_d%d" /NoConfirm', vno, d))) then
        pcall(function() views[vno].name = fs(PAGE.upd.title .. (si > 1 and (" S" .. d) or "")) end)
      end
    end
  end
  openExtraPage("upd")
  for si = 1, #TC.scr.list() do
    pcall(function() views[viewNo(si, "upd")][1][1].Layout = obj("Layout " .. layoutNo("upd")) end)
  end
  TC.scr.show("upd")
end
-- Masters & Utility view (117): utility macros + Running Playbacks on the left, the executors
-- of page 1 (Dimmer FX faders, strobes, playback and speed masters) and page 2 (Dimmer FX knobs, utility) on the right
function TC.mastOpen()
  failures = {}
  if not obj("Layout " .. layoutNo("mast")) or gv("built_mast") ~= CFG.EXTRA_VER then
    createLayoutsAndMacros({"mast"})
    sv("built_mast", CFG.EXTRA_VER)
    TC.bg.set("mast")
  end
  local views, list = ShowData().UserProfiles[1].Views, TC.scr.list()
  -- (rebuilt when a screen's size changed: the signature holds every screen's size)
  local sig = {}
  for si in ipairs(list) do local W, H = TC.scr.size(si) sig[#sig + 1] = W .. "x" .. H end
  sig = table.concat(sig, ",")
  for si, d in ipairs(list) do  -- one per screen
    local vno = viewNo(si, "mast")
    local W, H = TC.scr.size(si)
    local v = views[vno]
    if v and tostring(v.name):sub(1, #CFG.PREFIX + 1) ~= CFG.PREFIX .. " " then
      failures[#failures + 1] = "View " .. vno .. " is in use"
    elseif not v or gv("mast_view") ~= sig then
      if v then Cmd(string.format("Delete View %d /NC", vno)) end
      local lw = math.max(10, math.floor(W * 0.4))
      local lh = math.floor(H * 0.62)
      local rw = W - lw
      local function pb(x, y, w, h, rows)
        return string.format([[        <ViewWidget Name="WindowPlaybacks" Display="%d" X="%d" Y="%d" W="%d" H="%d" MinW="5">
            <PlaybackWindowSettings FontSize="Default" ShowTitleBar="Yes" VisibleTitlebuttons="Wing,Page" Row400="%s" Row300="%s" Row200="On" Row100="%s" Labels="On" Executors="On" #Sections="2" DisplayMode="Text+Icon"/>
            <WindowAppearance WindowColor="00000000"/>
        </ViewWidget>
]], d, x, y, w, h, rows[1], rows[2], rows[3])
      end
      local xml = TC.scr.xml(d, lw, lh) ..
        string.format('        <ViewWidget Name="WindowRunningPlaybacks" Display="%d" X="0" Y="%d" W="%d" H="%d" MinW="4" MinH="4"/>\n',
          d, lh, lw, H - lh) .. pb(lw, 0, rw, H, {"On", "On", "On"}) ..
        "    </View>\n</GMA3>\n"
      local file = "fs_view_mast_d" .. d
      local f = io.open(PATHS.lib("userprofiles", "views", file .. ".xml"), "w")
      if f then
        f:write(xml)
        f:close()
        C("Import View %d /File %s /NoConfirm", vno, q(file))
      end
      v = views[vno]
      pcall(function()
        v.name = fs(PAGE.mast.title .. (#list > 1 and (" S" .. d) or ""))
        v[1][1].Layout = obj("Layout " .. layoutNo("mast"))
        -- (the executor window follows the selected page: Page 1 / Page 2 buttons on the layout)
        local w = gv("wing")
        if w then for _, win in ipairs(v:Children()) do
          if tostring(win.name) == "WindowPlaybacks" then win[1].WINGID = "Wing" .. w end
        end end
      end)
    end
  end
  sv("mast_view", sig)
  openExtraPage("mast")
  for _, f in ipairs(failures) do log("  %s", f) end
end

-- Measure (a tab of Update Presets): one fixture at a time with one emitter at full and the rest
-- of the rig dark, so a colour meter can read each emitter. LOG READING asks for the meter's x, y
-- and lux and adds them to <library>/FireSystem-measurements.csv (type them into the fixture
-- type's emitters: Patch > Fixture Types > Edit > Physical Descriptions > Emitters)
TC.meas = {FILE = "FireSystem-measurements.csv", SLOTS = 15}
-- colour attributes a fixture can have, with their label (sub = a subtractive flag / CTx: 0 = open)
TC.meas.ATTRS = {}
for _, a in ipairs({ {"R", "Red"}, {"G", "Green"}, {"B", "Blue"}, {"W", "White"}, {"WW", "Warm White"},
                     {"CW", "Cool White"}, {"RY", "Amber"}, {"GY", "Lime"}, {"Y", "Yellow"}, {"C", "Cyan"},
                     {"M", "Magenta"}, {"GC", "Green-Cyan"}, {"BC", "Blue-Cyan"}, {"BM", "Blue-Magenta"},
                     {"RM", "Red-Magenta"}, {"UV", "UV"} }) do
  -- (MA's names are ColorRGB_*; GDTF fixture types can bring ColorAdd_*)
  TC.meas.ATTRS[#TC.meas.ATTRS + 1] = {"ColorRGB_" .. a[1], a[2]}
  TC.meas.ATTRS[#TC.meas.ATTRS + 1] = {"ColorAdd_" .. a[1], a[2]}
end
for _, a in ipairs({ {"ColorSub_C", "Cyan Flag"}, {"ColorSub_M", "Magenta Flag"}, {"ColorSub_Y", "Yellow Flag"},
                     {"CTO", "CTO"}, {"CTC", "CTC"}, {"CTB", "CTB"} }) do
  TC.meas.ATTRS[#TC.meas.ATTRS + 1] = {a[1], a[2], sub = true}
end
-- each emitter's button takes the Color page swatch nearest to it (index into CFG.COLORS)
TC.meas.CI = {Red = 3, Green = 7, Blue = 11, White = 1, ["Warm White"] = 2, ["Cool White"] = 1, Amber = 4,
              Lime = 6, Yellow = 5, Cyan = 9, Magenta = 14, ["Green-Cyan"] = 8, ["Blue-Cyan"] = 10,
              ["Blue-Magenta"] = 13, ["Red-Magenta"] = 15, UV = 13, ["Cyan Flag"] = 9, ["Magenta Flag"] = 14,
              ["Yellow Flag"] = 5, CTO = 2, CTC = 2, CTB = 10}
function TC.meas.list()
  local t = {}
  for n in tostring(gv("meas_list") or ""):gmatch("%d+") do t[#t + 1] = tonumber(n) end
  return t
end
function TC.meas.idx() return math.max(1, math.min(#TC.meas.list(), tonumber(gv("meas_i") or "") or 1)) end
function TC.meas.fid() return TC.meas.list()[TC.meas.idx()] end
-- a reading is kept per fixture type, mode and emitter (every fixture of a type shares its emitters)
function TC.meas.key(m, attr) return "meas_r_" .. (m.ft .. "_" .. m.mode .. "_" .. attr):gsub("[^%w]", "_") end
-- the selected groups' fixtures, in group order (a cell counts as its fixture; its address is kept:
-- "Fixture n" alone doesn't select a pixel fixture's cells, where the colour emitters are)
function TC.meas.load()
  local fids, seen, cells = {}, {}, {}
  pcall(function()
    Cmd("ClearSelection"); Cmd(TC.upd.groups())
    local fi = SelectionFirst()
    while fi do
      local h, fid = GetSubfixture(fi), nil
      local a
      pcall(function()  -- "1011.002" (as Store Linear writes cells)
        a = tostring(h:ToAddr()):gsub("^.-Fixture%s+", ""):gsub("%.(%d+)", function(d) return string.format(".%03d", tonumber(d)) end)
      end)
      for _ = 1, 4 do
        if not h then break end
        pcall(function() fid = tonumber(tostring(h.FID or h.fid or "")) end)
        if fid then break end
        local ok, p = pcall(function() return h:Parent() end)
        h = ok and p or nil
      end
      if fid and not seen[fid] then seen[fid] = true fids[#fids + 1] = tostring(fid) cells[fid] = {} end
      if fid and a and a:find(".", 1, true) then table.insert(cells[fid], a) end
      fi = SelectionNext(fi)
    end
  end)
  Cmd("ClearSelection")
  for fid, l in pairs(cells) do sv("meas_c_" .. fid, table.concat(l, ",")) end
  sv("meas_list", table.concat(fids, ","))
  sv("meas_i", "1")
  TC.meas.info = nil
end
-- selects fixture fid with its cells
function TC.meas.select(fid)
  local t = {"Fixture " .. fid}
  for a in tostring(gv("meas_c_" .. fid) or ""):gmatch("[^,]+") do t[#t + 1] = "Fixture " .. a end
  return table.concat(t, " + ")
end
-- fixture fid: name, fixture type, mode and the colour emitters it has (cached)
function TC.meas.about(fid)
  local m = {fid = fid, name = "", ft = "?", mode = "", em = {}}
  pcall(function()
    Cmd("ClearSelection"); Cmd(TC.meas.select(fid))
    local idx, has = {}, {}
    for _, a in ipairs(TC.meas.ATTRS) do
      local i = GetAttributeIndex(a[1])
      if i then idx[#idx + 1] = {i, a} end
    end
    local fi = SelectionFirst()
    local first = fi
    while fi do
      for _, e in ipairs(idx) do if not has[e[2][1]] and GetUIChannelIndex(fi, e[1]) then has[e[2][1]] = true end end
      fi = SelectionNext(fi)
    end
    for _, e in ipairs(idx) do
      if has[e[2][1]] and #m.em < TC.meas.SLOTS then m.em[#m.em + 1] = e[2] end
    end
    if first then
      local ft, mode = PROFILE.of(GetSubfixture(first))
      m.ft = ft and tostring(ft.name) or "?"
      m.mode = mode and tostring(mode.name) or ""
    end
    m.name = tostring(objName(obj("Fixture " .. fid)) or "")
  end)
  Cmd("ClearSelection")
  return m
end
function TC.meas.cur()
  local fid = TC.meas.fid()
  if not fid then return nil end
  if not (TC.meas.info and TC.meas.info.fid == fid) then TC.meas.info = TC.meas.about(fid) end
  return TC.meas.info
end
-- which = an emitter's attribute, "all" (every emitter full, flags open) or "dark"
function TC.meas.light(which)
  local m = TC.meas.cur()
  if not m then Echo("FireSystem: no fixtures - pick groups on the left") return end
  C("ClearAll")
  Cany({"Fixture Thru At 0", "Fixture 1 Thru 99999 At 0"})  -- the rest of the rig dark
  C("ClearSelection")
  C(TC.meas.select(m.fid))
  if which ~= "dark" then C("At 100") end
  for _, a in ipairs(m.em) do
    local v = 0
    if which == "all" then v = a.sub and 0 or 100 elseif a[1] == which then v = 100 end
    C("Attribute %s At %d", q(a[1]), v)
  end
  sv("meas_on", "1")
  sv("meas_em", which)
end
function TC.meas.log()
  local m, em = TC.meas.cur(), gv("meas_em") or ""
  if not m or em == "" then Echo("FireSystem: light an emitter first") return end
  local label = em == "all" and "All Emitters" or em == "dark" and "Dark" or em
  for _, a in ipairs(m.em) do if a[1] == em then label = a[2] end end
  local ok, v = pcall(TextInput, string.format("%s %s: x y lux from the meter", m.ft, label), "")
  if not ok or not v or trim(v) == "" then return end
  local n = {}
  for w in (tostring(v):gsub(",", " ")):gmatch("%S+") do n[#n + 1] = tonumber(w) end
  if not (n[1] and n[2] and n[1] > 0 and n[1] < 1 and n[2] > 0 and n[2] < 1) then
    MessageBox({title = "FireSystem", message = "Type x and y (0 to 1), then lux, e.g. 0.701 0.298 1520",
                commands = {{value = 1, name = "OK"}}})
    return
  end
  local path = PATHS.lib(TC.meas.FILE)
  local f = io.open(path, "r")
  local new = f == nil
  if f then f:close() end
  f = io.open(path, "a")
  if not f then Echo("FireSystem: can't write " .. path) return end
  local function csv(x) x = tostring(x or "") return x:find('[,"]') and ('"' .. x:gsub('"', '""') .. '"') or x end
  local when = ""
  pcall(function() when = os.date("%Y-%m-%d %H:%M:%S") end)
  if new then f:write("time,fixture,name,fixture type,mode,emitter,attribute,x,y,lux\n") end
  f:write(table.concat({when, tostring(m.fid), csv(m.name), csv(m.ft), csv(m.mode), csv(label), em,
                        tostring(n[1]), tostring(n[2]), n[3] and tostring(n[3]) or ""}, ",") .. "\n")
  f:close()
  sv(TC.meas.key(m, em), string.format("%.4f %.4f %s", n[1], n[2], n[3] and tostring(n[3]) or ""))
  local txt = string.format("%s %s: x %.4f y %.4f%s", m.ft, label, n[1], n[2], n[3] and (" lux " .. n[3]) or "")
  sv("meas_last", txt)
  Echo("FireSystem: " .. txt .. " -> " .. path)
end
function TC.meas.action(a, n)
  local l = TC.meas.list()
  if #l == 0 or a == "load" then TC.meas.load() l = TC.meas.list() end
  if a == "next" or a == "prev" or a == "type" then
    if #l == 0 then return end
    local i, ft = TC.meas.idx(), (TC.meas.cur() or {}).ft
    for _ = 1, (a == "type") and #l or 1 do  -- Next Type: on to the next fixture of another type
      i = i + (a == "prev" and -1 or 1)
      if i < 1 then i = #l elseif i > #l then i = 1 end
      if a ~= "type" or TC.meas.about(l[i]).ft ~= ft then break end
    end
    sv("meas_i", tostring(i))
    TC.meas.info = nil
    if gv("meas_on") == "1" then TC.meas.light("dark") end  -- the new fixture: pick its emitter
  elseif a == "em" then
    local m = TC.meas.cur()
    local e = m and m.em[tonumber(n) or 0]
    if e then TC.meas.light(e[1]) end
  elseif a == "all" or a == "dark" then
    TC.meas.light(a)
  elseif a == "log" then
    TC.meas.log()
  elseif a == "done" then  -- release the programmer: the rig plays as before
    C("ClearAll")
    sv("meas_on", "")
    sv("meas_em", "")
  end
end
function TC.upd.groups()
  local sel = getSel("upd")
  if #sel == 0 then for gi = 1, #CFG.GROUPS do sel[#sel + 1] = gi end end
  local t = {}
  for _, gi in ipairs(sel) do t[#t + 1] = tostring(CFG.GROUPS[gi]) end
  return "Group " .. table.concat(t, " + ")
end
function TC.upd.action(act, a1, a2)
  failures = {}
  if act == "cat" then
    if a1 ~= "meas" and gv("meas_on") == "1" then TC.meas.action("done") end  -- leaving Measure
    sv("upd_cat", a1)
    if a1 == "meas" and #TC.meas.list() == 0 then TC.meas.load() end
    return TC.upd.open()
  elseif act == "meas" then
    TC.meas.action(a1, a2)
  elseif act == "grp" then
    local gi, sel, out, found = tonumber(a1), getSel("upd"), {}, false
    for _, n in ipairs(sel) do if n == gi then found = true else out[#out + 1] = n end end
    if not found then out[#out + 1] = gi end
    table.sort(out)
    setSel("upd", out)
    if TC.upd.cat() == "meas" then TC.meas.load() end  -- Measure: these groups' fixtures
  elseif act == "recall" then  -- the preset for the selected groups into the programmer
    sv("upd_last", a1)
    C("ClearAll")
    C(TC.upd.groups())
    C("At Preset %s", a1)
    Echo("FireSystem: Preset " .. a1 .. " is in the programmer for " .. TC.upd.groups() .. " - change it, then UPDATE")
  elseif act == "store" then
    local id = gv("upd_last")
    if not id or id == "" then return end
    C(TC.upd.groups())  -- the selection stays as it is when nothing else is selected
    if C("Store Preset %s /Merge /NC", id) then
      sv("keep_" .. id, "1")
      Echo("FireSystem: Preset " .. id .. " updated (setup won't overwrite it any more)")
    end
    C("ClearAll")
    -- a Strobe preset: the bump keys, strobe knobs and Strobe All are stored again with it
    if tostring(id):match("^" .. STROBES.pool .. "%.") then rebuildAllKeys() end
  elseif act == "clear" then
    C("ClearAll")
  elseif act == "revert" then
    local id = gv("upd_last")
    if id and id ~= "" and gv("keep_" .. id) == "1" then
      sv("keep_" .. id, "")
      Echo("FireSystem: Preset " .. id .. " goes back to FireSystem's version at the next Build / Update")
    end
  end
  for _, f in ipairs(failures) do log("  %s", f) end
  refresh("upd")
end

-- the transport row was switched on / off: rebuild the pages that are already made
function TC.rebuildBars()
  local fire = {}
  for _, p in ipairs(PAGES) do if obj("Layout " .. layoutNo(p)) then fire[#fire + 1] = p end end
  if #fire > 0 then createLayoutsAndMacros(fire) end
  for _, p in ipairs({"home", "mast", "upd", "songs", "rec", "gobo", "ccol"}) do
    if obj("Layout " .. layoutNo(p)) then
      createLayoutsAndMacros({p})
      sv("built_" .. p, CFG.EXTRA_VER)
      if p == "upd" then sv("upd_built_cat", TC.upd.cat()) end
      TC.bg.set(p)
    end
  end
  if #fire > 0 then pcall(layoutFix) end
  if not TC.barOn() then  -- off: the row's macros aren't on any layout any more
    for k = 0, 10 * 19 - 1 do
      local h, mine = obj("Macro " .. (CFG.TCBAR_MACRO + k)), false
      -- only the row's own macros: a transport call, or an empty frame line
      pcall(function()
        if h:Count() == 0 and trim(objName(h) or "") == "" then mine = true end
        for j = 1, h:Count() do
          if tostring(h[j].Command or ""):find('"' .. CFG.PLUGIN_NAME .. '" "tc ', 1, true) then mine = true end
        end
      end)
      if h and mine then C("Delete Macro %d /NC", CFG.TCBAR_MACRO + k) end
    end
  end
  for k in pairs(lastAp) do lastAp[k] = nil end
  for k in pairs(lastTxt) do lastTxt[k] = nil end
  for k in pairs(TC.names) do TC.names[k] = nil end
  if #fire > 0 then refreshAll() end
  TC.refreshDots()
end

function TC.action(act, a1)
  failures = {}
  local i = TC.song()
  if act == "view" then
    if a1 == "tced" then return TC.ed.open() end
    return TC.open(a1)
  end
  if act == "bar" then act, a1 = a1, nil end  -- the transport row on every page
  if act == "showbar" then
    sv("tc_bar", TC.barOn() and "0" or "1")
    dbg("== timecode controls on every page: " .. (TC.barOn() and "on" or "off"))
    TC.rebuildBars()
    for _, f in ipairs(failures) do log("  %s", f) end
    return TC.refresh()
  end
  if act == "recdot" then  -- the little REC on every page: stops a recording (nothing when hidden)
    if not TC.recording() then return TC.refreshDots() end
    act = "rec"
  end
  if act == "source" then
    sv("tc_source", a1)
    for k = 1, CFG.TC_SONGS do TC.apply(k) end
    if a1 ~= "internal" then
      Echo(string.format("FireSystem: timecode from TC slot %d - route your %s input to that slot in MA's In & Out settings",
        CFG.TC_SLOTS[a1] or 0, TC.label(TC.SOURCES, a1)))
    end
  elseif act == "mode" then
    sv("tc_mode", a1)
  elseif act == "song" or act == "prev" or act == "next" then
    local n = (act == "song") and tonumber(a1) or (i + (act == "next" and 1 or -1))
    n = math.max(1, math.min(CFG.TC_SONGS, n or i))
    sv("tc_song", tostring(n))
    if not TC.obj(n) then
      local ok, name = pcall(TextInput, "Name for song " .. n, "Song " .. n)
      if not ok or not name or name == "" then sv("tc_song", tostring(i)) return TC.refresh() end
      TC.ensure(n, name)
    end
    TC.target()
  elseif act == "add" then
    local n
    for k = 1, CFG.TC_SONGS do if not TC.obj(k) then n = k break end end
    if not n then
      MessageBox({title = "FireSystem", message = "All " .. CFG.TC_SONGS .. " songs are used (TC_SONGS).",
        commands = {{value = 1, name = "OK"}}})
      return
    end
    return TC.action("song", n)
  elseif act == "rename" then
    if not TC.obj() then return end
    local ok, name = pcall(TextInput, "Name for song " .. i, TC.name() or "")
    if ok and name and name ~= "" then C("Label Timecode %d %s", TC.no(), q(fs(name))) end
  elseif act == "delete" then
    if TC.obj() and Confirm("FireSystem", "Delete song " .. i .. " '" .. tostring(TC.name()) .. "' and its timecode?") then
      C("Off Timecode %d", TC.no())
      C("Delete Timecode %d /NC", TC.no())
    end
  else
    -- transport: needs the song
    if not TC.obj() and not TC.ensure(i) then return end
    TC.apply(i)
    TC.target()
    local no = TC.no()
    if act == "play" then C("Go Timecode %d", no)
    elseif act == "pause" then Cany({string.format("Pause Timecode %d", no), string.format("Go Timecode %d", no)})
    elseif act == "top" then
      Cany({string.format("Top Timecode %d", no), string.format("Off Timecode %d", no)})
    elseif act == "stop" then
      local was = TC.recording()
      C("Off Timecode %d", no)
      if was then TC.cleanup(i) TC.rec.finish(i) end
    elseif act == "rec" then
      if TC.recording() then
        C("Off Timecode %d", no)
        TC.cleanup(i)
        TC.rec.finish(i)
      else
        -- records and runs from the cursor; the speed masters and Bump settings go in now,
        -- then whenever they change
        if C("Record Timecode %d", no) then TC.rec.begin() end
      end
    end
  end
  for _, f in ipairs(failures) do log("  %s", f) end
  TC.refresh()
  -- the REC dot (and the transport row, which also shows the song) on every other page follows
  if act == "rec" or act == "stop" or TC.barOn() then TC.refreshDots() end
end

end

-- ==== FireSystemTCEditor.lua (copied by tools/make_tools.py) ====
MODS.TCEditor = function(_ENV)

-- ======================================================================
-- Timecode Editor (Timecode > Edit Timecode) and what a recording keeps besides the presses
-- ======================================================================
-- Every recorded look (snapshot cue) keeps its group's FireSystem state (FS_tcst_<seq>_<cue>),
-- so the editor shows its look and MAtricks and the look can be edited with the page's own
-- buttons. The speed masters and the Bump page's settings are recorded as log cues in
-- Sequence TC_LOG_SEQ: each one's command puts them back when the timecode plays it.
TC.ed = {T24 = 16777216}  -- (MA's RawTime: seconds * 2^24)
TC.rec = {bmLast = {}}
function TC.ed.num(n) return string.format("%g", tonumber(n) or 0) end
function TC.ed.fmt(t)
  if not t then return "-:--.-" end
  local m = math.floor(t / 60)
  return string.format("%d:%04.1f", m, t - m * 60)
end
-- "1:02.5", "1m02.5", "62.5" -> seconds
function TC.ed.parse(s)
  s = trim(s)
  local m, sec = s:match("^(%d+)[:m](%d+%.?%d*)s?$")
  if m then return tonumber(m) * 60 + tonumber(sec) end
  return tonumber((s:gsub("s$", "")))
end
-- the FireSystem page and group of a page sequence (101-158), else nil
function TC.ed.pg(seq)
  seq = tonumber(seq)
  if not seq then return nil end
  for _, p in ipairs(FIRE_PAGES) do
    local gi = seq - seqNo(p, 1) + 1
    if gi >= 1 and gi <= TC.fill.n(p) then return p, gi end
  end
end
-- the MAtricks a look plays with, short: "F 0-2 D 0-1 W 2 P 0-360 Sym" (Y / Z axis values start with Y / Z)
TC.ed.MXS = {Block = "B", Group = "G", Wings = "W", Width = "Wd", Shift = "Sh", Shuffle = "Shuf"}
function TC.ed.mxText(page, st)
  local ok, p = pcall(matricksProps, page, st)
  if not ok or type(p) ~= "table" then return nil end
  local v, out = {}, {}
  for _, pr in ipairs(p) do v[pr[1]] = pr[2] end
  local function n(x) return tonumber(x) and TC.ed.num(x) or tostring(x) end
  for _, A in ipairs(FN.AXES) do
    local y = (A == "X") and "" or A
    for _, f in ipairs({"Fade", "Delay", "Phase", "Speed"}) do
      local a, b = v[f .. "From" .. A], v[f .. "To" .. A]
      if a then out[#out + 1] = y .. f:sub(1, 1) .. " " .. ((a == b) and n(a) or (n(a) .. "-" .. n(b))) end
    end
    for _, f in ipairs({"Block", "Group", "Wings", "Width", "Shift", "Shuffle"}) do
      if v[A .. f] then out[#out + 1] = y .. TC.ed.MXS[f] .. (f == "Shuffle" and "" or (" " .. n(v[A .. f]))) end
    end
  end
  if v.PhaserTransform then out[#out + 1] = "Sym" end
  return #out > 0 and table.concat(out, " ") or "none"
end
-- the look in words: the names of the presets it points at
function TC.ed.lookText(page, st)
  local names = {}
  local ok, lines = pcall(CONTENT[page], st)
  for _, line in ipairs(ok and type(lines) == "table" and lines or {}) do
    for p in tostring(line):gmatch("Preset (%d+%.%d+)") do
      local nm = tostring(objName(obj("Preset " .. p)) or p):gsub("^" .. CFG.PREFIX .. " ", "")
      if #names < 4 then names[#names + 1] = nm end
    end
  end
  return #names > 0 and table.concat(names, " + ") or "Off"
end
function TC.rec.desc(page, st)
  local mx = TC.ed.mxText(page, st)
  return ": " .. TC.ed.lookText(page, st) .. (mx and (" | " .. mx) or "")
end
-- a snapshot cue was made: its state is kept; returns the end of its label
function TC.rec.snap(seq, k, page, st)
  if not (page and st) then return "" end
  local s = copy(st)
  s.dirty = nil
  sv("tcst_" .. seq .. "_" .. TC.ed.num(k), ser(s))
  TC.rec.sent = (TC.rec.sent or 0) + 1
  return TC.rec.desc(page, st)
end

-- ---- log cues (speed masters, Bump settings) ----
-- vars: {var = value} kept with the log cue (FS_tclog_<n>_<var>)
function TC.rec.log(kind, data, label, vars)
  local seq = CFG.TC_LOG_SEQ
  if not obj("Sequence " .. seq .. " Cue 1") then
    C("ClearAll")  -- (once: an empty cue to copy the log cues from)
    C("Store Sequence %d Cue 1 /Overwrite", seq)
    C("Label Sequence %d %s", seq, q(fs("TC Log")))
  end
  local n = math.max(2, tonumber(gv("tclog_n") or "") or 2)
  while obj(string.format("Sequence %d Cue %d", seq, n)) do n = n + 1 end
  sv("tclog_n", tostring(n + 1))
  sv("tclog_" .. n, kind .. "|" .. data)
  for k, v in pairs(vars or {}) do sv("tclog_" .. n .. "_" .. k, v) end
  C("Copy Sequence %d Cue 1 At Sequence %d Cue %d /NC", seq, seq, n)
  C("Label Sequence %d Cue %d %s", seq, n, q(label))
  C("Goto Sequence %d Cue %d", seq, n)
  -- the command comes after the Goto: it runs when the timecode plays the cue, not now
  local cmd = string.format('Plugin "%s" "tced restore %d"', CFG.PLUGIN_NAME, n)
  if not pcall(function() obj(string.format("Sequence %d Cue %d Part 0", seq, n)):Set("Command", cmd) end) then
    BM.partProp(seq, n, "Command", q(cmd))
  end
  TC.rec.sent = (TC.rec.sent or 0) + 1
end
-- the speed masters on the executors (CFG.MASTER_EXECS): {{no, fader 0-100}}
function TC.rec.speeds()
  local t = {}
  for _, m in ipairs(CFG.MASTER_EXECS) do
    if m[2] == "Speed" then
      local h, v
      pcall(function() h = ShowData().Masters.Speed:Ptr(m[3]) end)
      if h then
        pcall(function() v = h:GetFader({}) end)
        end
      if type(v) == "number" then t[#t + 1] = {m[3], v} end
    end
  end
  return t
end
-- force: log them now (REC start); otherwise only a change, once the fader has stopped
-- (the same value two looks running)
function TC.rec.masters(force)
  local cur = TC.rec.speeds()
  local key, lbl = {}, {}
  for _, s in ipairs(cur) do
    key[#key + 1] = s[1] .. "=" .. string.format("%.2f", s[2])
    local nm = (CFG.MASTER_NAMES.Speed[s[1]] or ("Speed " .. s[1])):gsub(" Speed$", "")
    -- (the fader text can read "1482 *B": the fader position is clearer)
    lbl[#lbl + 1] = nm .. " " .. (s[2] <= 0 and "Stop" or string.format("%.0f%%", s[2]))
  end
  key = table.concat(key, ";")
  if key == "" then return end
  if not force then
    if not TC.rec.mLast or key == TC.rec.mLast then return end  -- (start values not logged yet)
    if key ~= TC.rec.mSeen then TC.rec.mSeen = key return end
  end
  TC.rec.mLast, TC.rec.mSeen = key, key
  TC.rec.log("m", key, "Speeds: " .. table.concat(lbl, " | "))
end
-- the Bump page's settings (bm_<group>_<key>); force: all of them (REC start), else the changed ones
function TC.rec.bumps(force)
  if not force and not TC.rec.bmLast then return end  -- (start values not logged yet)
  TC.rec.bmLast = TC.rec.bmLast or {}
  local keys, vars, gs, seen = {}, {}, {}, {}
  for gi = 1, #CFG.GROUPS do
    for slot = 1, #CFG.BUMP_SEQ do
      local key = "bm_" .. gi .. "_" .. slot
      local raw = gv(key)
      if force and (type(raw) ~= "string" or raw == "") then raw = ser(getBump(gi, slot)) end  -- (still the defaults)
      if type(raw) == "string" and raw ~= "" and (force or TC.rec.bmLast[key] ~= raw) then
        keys[#keys + 1], vars[key] = key, raw
        if not seen[gi] then seen[gi] = true gs[#gs + 1] = "G" .. gi end
      end
      TC.rec.bmLast[key] = raw
    end
  end
  if #keys == 0 then return end
  TC.rec.log("b", table.concat(keys, ","), force and "Bump settings at the start" or ("Bump settings " .. table.concat(gs, " ")), vars)
end
-- a log cue played: its masters / Bump settings come back
function TC.rec.restore(n)
  n = tonumber(n)
  if TC.rec.tok and TC.recording() then return end  -- (the log cue's own Goto while recording)
  local kind, data = tostring(gv("tclog_" .. tostring(n)) or ""):match("^(%w)|(.*)$")
  if kind == "m" then
    for no, v in data:gmatch("(%d+)=([%d%.]+)") do
      pcall(function() ShowData().Masters.Speed:Ptr(tonumber(no)):SetFader({value = tonumber(v)}) end)
    end
  elseif kind == "b" then
    local any = false
    for key in data:gmatch("[^,]+") do
      local raw, gi, slot = gv("tclog_" .. n .. "_" .. key), key:match("^bm_(%d+)_(%d+)$")
      if gi and type(raw) == "string" and raw ~= "" and gv(key) ~= raw then
        sv(key, raw)
        rebuildBump(tonumber(gi), tonumber(slot))
        any = true
      end
    end
    if any and obj("Layout " .. layoutNo("bump")) then pcall(refresh, "bump") end
  end
end
-- REC started: the masters and Bump settings as they are now, then their changes
function TC.rec.begin()
  TC.rec.sent, TC.rec.mLast, TC.rec.mSeen, TC.rec.bmLast = 0, nil, nil, nil
  local tok = tostring(os.clock()) .. "/" .. tostring(os.time())
  TC.rec.tok = tok
  -- the start values go in on the first two ticks, not now: MA only records once REC
  -- is running, and two Gotos of the same sequence at one instant keep only one event
  local tick = 0
  local ok = pcall(Timer, function()
    if TC.rec.tok ~= tok or not TC.recording() then return end
    tick = tick + 1
    if tick == 1 then pcall(TC.rec.masters, true)
    elseif tick == 2 then pcall(TC.rec.bumps, true)
    else pcall(TC.rec.masters) end  -- then the masters twice a second (and on every press)
  end, 0.5, 4 * 3600 * 2)
  if not ok then
    dbg("timecode: no Timer - speed masters are checked on each press only")
    TC.rec.masters(true)
    TC.rec.bumps(true)
  end
end
-- REC stopped: did MA record what FireSystem sent? (the presses and log cues are Gotos)
function TC.rec.finish(i)
  if not TC.rec.tok then return end
  TC.rec.tok = nil
  TC.ed.list = nil
  local found = 0
  for _, e in ipairs(TC.ed.get()) do
    local page = TC.ed.pg(e.seq)
    if (e.seq == CFG.TC_LOG_SEQ and (e.cue or 0) >= 2) or (page and (e.cue or 0) >= CFG.TC_SNAP_BASE) then found = found + 1 end
  end
  dbg(string.format("timecode %d: %d FireSystem event(s) sent, %d in the timecode (all songs' events of these sequences)",
    TC.no(i), TC.rec.sent or 0, found))
  if (TC.rec.sent or 0) > 0 and found == 0 then
    Echo("FireSystem: MA didn't record FireSystem's looks / log cues into this timecode - see FireSystem.log")
  end
end

-- ---- the editor ----
function TC.ed.get() if not TC.ed.list then TC.ed.scan() end return TC.ed.list end
function TC.ed.time(ev)
  local t
  pcall(function() t = tonumber(ev.RawTime) end)
  if t then return t / TC.ed.T24 end
  pcall(function() t = TC.ed.parse(tostring(ev:Get("Time", Enums.Roles.Display))) end)
  return t
end
-- every event of the song's timecode, in time order (fader moves are only counted)
function TC.ed.scan()
  local list, moves, h = {}, 0, TC.obj()
  TC.ed.list, TC.ed.moves = list, 0
  if not h then return list end
  local ok, err = pcall(function()
    for gi, tg in ipairs(h:Children()) do
      for ti, tr in ipairs(tg:Children()) do
        local seq
        pcall(function()
          local tgt = tr.Target
          if tgt and tgt:GetClass() == "Sequence" then seq = tonumber(tgt.no) end
        end)
        for ri, range in ipairs(tr:Children()) do
          for si, sub in ipairs(range:Children()) do
            local cls = "CmdSubTrack"
            pcall(function() cls = tostring(sub:GetClass()) end)
            if cls ~= "CmdSubTrack" then
              moves = moves + sub:Count()  -- a fader's moves (a master, a sequence's fader)
            else
              for ei, ev in ipairs(sub:Children()) do
                local e = {t = TC.ed.time(ev), seq = seq, track = tostring(tr.name), path = {gi, ti, ri, si, ei}}
                pcall(function() e.tok = tostring(ev:Get("Token", Enums.Roles.Display)) end)
                pcall(function()
                  local c = ev.CueDestination
                  if c then e.cue = tonumber(c.no) / 1000 e.cname = tostring(c.name) end
                end)
                list[#list + 1] = e
              end
            end
          end
        end
      end
    end
  end)
  if not ok then dbg("timecode editor: reading timecode " .. TC.no() .. " failed: " .. tostring(err)) end
  table.sort(list, function(a, b)
    if (a.t or 0) ~= (b.t or 0) then return (a.t or 0) < (b.t or 0) end
    if (a.seq or 0) ~= (b.seq or 0) then return (a.seq or 0) < (b.seq or 0) end
    return (a.cue or 0) < (b.cue or 0)
  end)
  -- each look's MAtricks, and where they changed (against the group's previous look)
  local last = {}
  for _, e in ipairs(list) do
    local page = TC.ed.pg(e.seq)
    local raw = page and e.cue and gv("tcst_" .. e.seq .. "_" .. TC.ed.num(e.cue))
    if type(raw) == "string" and raw ~= "" then
      e.page, e.st = page, deser(raw)
      e.mx = TC.ed.mxText(page, e.st)
      if last[e.seq] and last[e.seq] ~= e.mx then e.mxc, e.mxWas = true, last[e.seq] end
      last[e.seq] = e.mx
    end
  end
  TC.ed.moves = moves
  local n = #list
  if (tonumber(gv("tced_sel") or "") or 0) > n then sv("tced_sel", "") end
  if TC.ed.top() > math.max(0, n - 1) then sv("tced_top", "0") end
  return list
end
function TC.ed.top() return math.max(0, tonumber(gv("tced_top") or "") or 0) end
function TC.ed.selIdx() return tonumber(gv("tced_sel") or "") end
function TC.ed.row(r) return TC.ed.get()[TC.ed.top() + r] end
function TC.ed.cur() local i = TC.ed.selIdx() return i and TC.ed.get()[i] end
function TC.ed.ev(e)
  local h = TC.obj()
  local ok, ev = pcall(function()
    local p = e.path
    return h:Children()[p[1]]:Children()[p[2]]:Children()[p[3]]:Children()[p[4]]:Children()[p[5]]
  end)
  return ok and ev or nil
end
function TC.ed.what(e)
  local page, gi = TC.ed.pg(e.seq)
  if page then
    local n = TC.gname(gi)
    return PAGE[page].title .. " G" .. gi .. (n ~= "" and (" " .. n) or "")
  end
  if e.seq == CFG.TC_LOG_SEQ then return e.cname or "Log" end
  return (tostring(e.track or "?"):gsub("^<(.*)>$", "%1"))
end
function TC.ed.rowText(r)
  local e = TC.ed.row(r)
  if not e then return "" end
  local s = TC.ed.fmt(e.t) .. "    " .. TC.ed.what(e)
  if e.seq == CFG.TC_LOG_SEQ then return s end
  local tok = (e.tok and e.tok ~= "Goto") and (e.tok .. " ") or ""
  s = s .. "    " .. tok .. (e.cue and ("Cue " .. TC.ed.num(e.cue)) or "")
  if e.mx then s = s .. "    " .. (e.mxc and "* " or "") .. e.mx end
  return s
end
function TC.ed.title()
  local n = #TC.ed.get()
  return "Timecode Editor: " .. (TC.name() or ("Song " .. TC.song() .. " (empty)")) ..
    "   " .. n .. " event" .. (n == 1 and "" or "s") .. ((TC.ed.moves or 0) > 0 and ("  +" .. TC.ed.moves .. " fader moves") or "")
end
function TC.ed.range()
  local n, top = #TC.ed.get(), TC.ed.top()
  if n == 0 then return TC.obj() and "Nothing recorded yet: REC on the Timecode page" or "No timecode for this song yet" end
  return string.format("Events %d-%d of %d     * = MAtricks changed", top + 1, math.min(n, top + CFG.TC_ED_ROWS), n)
end
function TC.ed.detail(line)
  local e = TC.ed.cur()
  if not e then return line == 1 and "Tap an event" or "" end
  if line == 1 then
    return TC.ed.fmt(e.t) .. "   " .. TC.ed.what(e) .. (e.cue and ("   Cue " .. TC.ed.num(e.cue)) or "") ..
      ((e.cname and e.seq ~= CFG.TC_LOG_SEQ) and ("   " .. e.cname) or "")
  end
  if e.page and e.st then
    return "Look: " .. TC.ed.lookText(e.page, e.st) .. "    MAtricks: " .. tostring(e.mx) ..
      (e.mxc and ("  (was " .. e.mxWas .. ")") or "")
  end
  if e.seq == CFG.TC_LOG_SEQ then return "Log event: puts these back when the timecode plays it" end
  return (e.tok or "") .. (e.seq and ("  Sequence " .. e.seq) or "")
end
-- the event's sequence in the editor's sequence window; jump: the timecode's cursor goes there too
function TC.ed.focus(e, jump)
  if jump and e.t then
    -- (quietly: a console that refuses both just doesn't move the cursor)
    for _, c in ipairs({string.format('Set Timecode %d Property "Cursor" "%.2f"', TC.no(), e.t),
                        string.format("Goto Timecode %d Time %.2f", TC.no(), e.t)}) do
      local r = Cmd(c)
      dbg(c .. "  ->  " .. tostring(r))
      if okResult(r) then break end
    end
  end
  local L = e.seq and DataPool().Sequences[e.seq]
  if not L then return end
  sv("tced_seq", tostring(e.seq))
  local function fix(wins)
    for _, w in ipairs(wins) do
      if tostring(w.name) == "WindowSequenceSheet" then w[1].LINKTYPE = "Fixed" w[1].FIXEDTARGET = L end
    end
  end
  for si = 1, #TC.scr.list() do pcall(function() fix(ShowData().UserProfiles[1].Views[viewNo(si, "tced")]:Children()) end) end
  -- (and the window on the screen the editor was pressed on)
  local _, d = TC.scr.cur()
  pcall(function() fix(ShowData().UserProfiles[1].ScreenConfigurations[1].ScreenContents[d]:Children()) end)
end
function TC.ed.reselect(seq, cue, t)
  for i, e in ipairs(TC.ed.get()) do
    if e.seq == seq and e.cue == cue and math.abs((e.t or 0) - t) < 0.06 then
      sv("tced_sel", tostring(i))
      local R = CFG.TC_ED_ROWS
      if i <= TC.ed.top() or i > TC.ed.top() + R then sv("tced_top", tostring(math.max(0, i - 1))) end
      return
    end
  end
end
function TC.ed.setTime(e, t)
  t = math.max(0, t)
  local ev = TC.ed.ev(e)
  if not ev then return end
  local ok = false
  pcall(function() ok = okResult(Cmd(string.format('Set %s Property "Time" "%.3f"', ev:ToAddr(), t))) end)
  if not ok then ok = pcall(function() ev.RawTime = math.floor(t * TC.ed.T24 + 0.5) end) end
  dbg(string.format("timecode editor: event %s -> %s (%s)", TC.ed.fmt(e.t), TC.ed.fmt(t), ok and "ok" or "refused"))
  TC.ed.list = nil
  TC.ed.reselect(e.seq, e.cue, TC.ed.time(ev) or t)
end
function TC.ed.delete(e)
  local h = TC.obj()
  local ok = pcall(function()
    local p = e.path
    h:Children()[p[1]]:Children()[p[2]]:Children()[p[3]]:Children()[p[4]]:Delete(p[5])
  end)
  dbg("timecode editor: delete event at " .. TC.ed.fmt(e.t) .. (ok and "" or " - refused"))
  TC.ed.list = nil
end
-- a recorded look into its page (the group's live look is put aside); FIRE saves it into the cue
function TC.ed.look(e)
  local page, gi = TC.ed.pg(e.seq)
  local raw = page and e.cue and gv("tcst_" .. e.seq .. "_" .. TC.ed.num(e.cue))
  if type(raw) ~= "string" or raw == "" then
    Echo("FireSystem: this event has no FireSystem look stored (recorded before v1.4, or not a page look) - use Edit in MA")
    return
  end
  TC.ed.cancel()
  sv("tced_prev", gv(page .. "_" .. gi) or "")
  sv("tced_edit", page .. "|" .. gi .. "|" .. e.seq .. "|" .. TC.ed.num(e.cue))
  local st = deser(raw)
  st.dirty = true
  saveGroup(page, gi, st)
  setSel(page, {gi})
  C("Goto Sequence %d Cue %s", e.seq, TC.ed.num(e.cue))
  pcall(refresh, page)
  Cany({ string.format("Select Layout %d", layoutNo(page)), string.format("Layout %d", layoutNo(page)) })
  TC.scr.show(page)
  Echo(string.format("FireSystem: editing Cue %s of %s G%d - change the look, then FIRE saves it into the timecode",
    TC.ed.num(e.cue), PAGE[page].title, gi))
end
-- editing given up (the editor was opened again): the group's live look comes back
function TC.ed.cancel()
  local p, gi = tostring(gv("tced_edit") or ""):match("^(%w+)|(%d+)|")
  if not p then return end
  sv(p .. "_" .. gi, gv("tced_prev") or "")
  sv("tced_edit", "")
  if obj("Layout " .. layoutNo(p)) then pcall(refresh, p) end
end
-- edit mode: the cue a group's look is being edited into (nil when not)
function TC.ed.k(seq)
  local s, k = tostring(gv("tced_edit") or ""):match("^%w+|%d+|(%d+)|([%d%.]+)$")
  if s and tonumber(s) == seq then return tonumber(k) end
end
function TC.ed.on(page)
  local p, gi = tostring(gv("tced_edit") or ""):match("^(%w+)|(%d+)|")
  if p == page then return tonumber(gi) end
end
-- FIRE in edit mode: the look went into the timecode cue; its state and label follow
function TC.ed.saved(page, gi, seq, k, st)
  local s = copy(st)
  s.dirty = nil
  sv("tcst_" .. seq .. "_" .. TC.ed.num(k), ser(s))
  local old = tostring(objName(obj(string.format("Sequence %d Cue %s", seq, TC.ed.num(k)))) or fs("TC"))
  C("Label Sequence %d Cue %s %s", seq, TC.ed.num(k), q((old:match("^(.-):") or old) .. TC.rec.desc(page, st)))
  sv(page .. "_" .. gi, gv("tced_prev") or "")  -- the group's live look again (not fired: the stage keeps the edit)
  sv("tced_edit", "")
  Echo(string.format("FireSystem: saved into Cue %s of %s G%d", TC.ed.num(k), PAGE[page].title, gi))
  TC.ed.list = nil
  TC.ed.open()
end
function TC.ed.open()
  TC.ed.cancel()
  TC.ed.list = nil
  TC.open("tced")
  local e = TC.ed.cur()
  if e then TC.ed.focus(e) end
end
function TC.ed.action(act, a1)
  failures = {}
  if act == "restore" then return TC.rec.restore(a1) end  -- (a log cue's command, from the timecode)
  local list = TC.ed.get()
  if act == "sel" then
    local i = TC.ed.top() + (tonumber(a1) or 0)
    if list[i] then
      sv("tced_sel", tostring(i))
      TC.ed.focus(list[i], true)
    end
  elseif act == "up" or act == "down" then
    local R = CFG.TC_ED_ROWS
    local top = TC.ed.top() + ((act == "down") and R or -R)
    sv("tced_top", tostring(math.max(0, math.min(top, #list - 1))))
  elseif act == "reload" then
    TC.ed.list = nil
  else
    local e = TC.ed.cur()
    if not e then
      Echo("FireSystem: tap an event in the list first")
      return
    end
    if act == "play" then
      if e.seq and e.cue then C("Goto Sequence %d Cue %s", e.seq, TC.ed.num(e.cue)) end
    elseif act == "look" then
      return TC.ed.look(e)
    elseif act == "macue" then
      if e.seq and e.cue then Cany({string.format("Edit Sequence %d Cue %s", e.seq, TC.ed.num(e.cue)),
                                     string.format("Edit Sequence %d", e.seq)}) end
    elseif act == "nudge" then
      TC.ed.setTime(e, (e.t or 0) + (tonumber(a1) or 0))
    elseif act == "time" then
      local ok, s = pcall(TextInput, "Time of this event (m:ss.s or seconds)", TC.ed.fmt(e.t))
      local t = ok and TC.ed.parse(s)
      if t then TC.ed.setTime(e, t) end
    elseif act == "jump" then
      TC.ed.focus(e, true)
    elseif act == "del" then
      if Confirm("FireSystem", "Delete the event at " .. TC.ed.fmt(e.t) .. " (" .. TC.ed.what(e) .. ") from the timecode?") then
        TC.ed.delete(e)
      end
    end
  end
  for _, f in ipairs(failures) do log("  %s", f) end
  pcall(refresh, "tced")
end

end

-- ==== FireSystemCommands.lua (copied by tools/make_tools.py) ====
MODS.Commands = function(_ENV)

function run(displayHandle, argument)
  local arg = argument
  -- groups built by the Home page (or the old FireSystemStart) take precedence over CFG.GROUPS
  local gs = GetVar(GlobalVars(), "FS_groups")
  if type(gs) == "string" and gs ~= "" then
    local t = {}
    for n in gs:gmatch("%d+") do if #t < 8 then t[#t + 1] = tonumber(n) end end
    if #t > 0 then CFG.GROUPS = t end
  end
  -- clicking the plugin (or its view button) opens the Home page
  if type(arg) ~= "string" or arg == "" or arg == "global home" then return START.openHome() end
  if arg == "global open" then return START.openDefault() end
  if arg == "global probe" then  -- writes MA's property names / values to gma3_library/FireSystem-probe.log
    local f = io.open(PATHS.lib("FireSystem-probe.log"), "w")
    if not f then return end
    local function dump(title, h)
      f:write("== ", title, h and "" or "  (not found)", "\n")
      if not h then return end
      pcall(function() f:write("class ", tostring(h:GetClass()), "  children ", tostring(h:Count()), "\n") end)
      local n = 0
      pcall(function() n = h:PropertyCount() end)
      for i = 0, n do
        pcall(function()
          local name = h:PropertyName(i)
          if not name then return end
          local v = "?"
          pcall(function() v = tostring(h:Get(name, Enums.Roles.Display)) end)
          f:write("  ", tostring(name), " = ", v, "\n")
        end)
      end
    end
    dump("Layout home", obj("Layout " .. layoutNo("home")))
    dump("Layout home element 1", (obj("Layout " .. layoutNo("home")) or {})[1])
    dump("Appearance canvas of home", (function() local r pcall(function() r = obj("Layout " .. layoutNo("home")).CanvasAppearance end) return r end)())
    dump("Layout " .. PAGES[1], obj("Layout " .. layoutNo(PAGES[1])))
    dump("Page 1", obj("Page 1"))
    pcall(function() dump("Page 1 executor 201", DataPool().Pages[1]:Ptr(201)) end)
    pcall(function() dump("Page 1 child 1", DataPool().Pages[1][1]) end)
    pcall(function() dump("Pages pool", DataPool().Pages) end)
    pcall(function()
      for _, win in ipairs(ShowData().UserProfiles[1].ScreenConfigurations[1].ScreenContents[1]:Children()) do
        dump("Window " .. tostring(win.name), win)
        pcall(function() dump("  settings of " .. tostring(win.name), win[1]) end)
      end
    end)
    f:close()
    Echo("FireSystem: probe written to FireSystem-probe.log")
    return
  end
  if arg == "global masters" then dbg("== masters") return START.masters() end
  if arg == "global utility" then dbg("== utility") return START.utility() end
  if arg == "global upd" then return TC.upd.open() end
  if arg == "global mast" then return TC.mastOpen() end
  if arg == "global saveexec" then return TC.ex.save() end
  if arg == "global resetexec" then
    local m = gv("exec_map")
    if m and m ~= "" then sv("exec_old", m) end
    sv("exec_map", "")
    Echo("FireSystem: executor positions back to the defaults - Build / Update moves them there")
    return
  end
  if arg == "global looks" then  -- executor colours and master names only
    for gi = 1, #CFG.GROUPS do
      for _, w in ipairs({{"rnd", bumpSeq(2, gi)}, {"strobe", bumpSeq(3, gi)}, {"dim", seqNo("dim", gi)},
                          {"bump", bumpSeq(1, gi)}, {"xk", xkSeq(gi)}}) do
        TC.look.give(w[1], "Sequence " .. w[2])
      end
      TC.look.give("group", "Group " .. CFG.GROUPS[gi])
    end
    TC.look.give("strobe", "Sequence " .. CFG.STROBE_SEQ)
    TC.look.give("white", "Sequence " .. CFG.WHITE_SEQ)
    TC.look.give("looks", "Sequence " .. CFG.LOOKS_SEQ)
    if CFG.FIRE_MACRO then TC.look.give("fire", "Macro " .. CFG.FIRE_MACRO) end
    TC.look.masters()
    return
  end
  if arg == "global bgy" then  -- flips which way the background box's Y runs (if MA draws it off the page)
    sv("bg_yinv", gv("bg_yinv") == "1" and "0" or "1")
    TC.bg.apply()
    return refresh("home")
  end
  if arg:match("^global bgt %w+$") then  -- Page Backgrounds: which page the next pick is for
    sv("bg_target", arg:match("(%w+)$"))
    return refresh("home")
  end
  if arg:match("^global bg %d+$") then  -- Page Backgrounds: the background of that page (or all)
    local i, t = arg:match("(%d+)$"), gv("bg_target") or "all"
    local keys = {t}
    if t == "all" then keys = {"extra", "fader"} for _, p in ipairs(PAGES) do keys[#keys + 1] = p end end
    for _, k in ipairs(keys) do sv("bg_" .. k, i) end
    TC.bg.apply()
    return refresh("home")
  end
  if arg:match("^global wing %d$") then  -- wing of the executor window(s) in the Masters view
    local w = arg:match("(%d)$")
    sv("wing", w)
    -- the view (for the next time it opens) and the window on screen now (its ScreenContent)
    -- (only the screen it was pressed on: the other screens keep their own wing)
    local si, d = TC.scr.cur()
    pcall(function()
      for _, win in ipairs(ShowData().UserProfiles[1].Views[viewNo(si, "mast")]:Children()) do
        if tostring(win.name) == "WindowPlaybacks" then win[1].WINGID = "Wing" .. w end
      end
    end)
    pcall(function()
      for _, win in ipairs(ShowData().UserProfiles[1].ScreenConfigurations[1].ScreenContents[d]:Children()) do
        if tostring(win.name) == "WindowPlaybacks" then win[1].WINGID = "Wing" .. w end
      end
    end)
    return refresh("mast")
  end
  if arg == "global autogroups" or arg == "global rig" then
    failures = {}
    local blocks = {}
    if arg == "global rig" then
      for i, e in ipairs(CFG.GROUP_FIXTURES) do
        local ok, l = pcall(ObjectList, "Fixture " .. tostring(e.fixtures))
        if i <= 8 and ok and type(l) == "table" and #l > 0 then blocks[#blocks + 1] = {name = e.name or ("G" .. i), sel = e.fixtures, split = true} end
      end
      local rb = START.patchRig()
      if #blocks == 0 then blocks = START.splitLR(rb) end
    else
      blocks = START.splitLR(START.scanPatch())
    end
    if #blocks == 0 then
      MessageBox({title = "FireSystem", message = (arg == "global rig")
        and "Nothing to patch or group: fill in RIG (or GROUP_FIXTURES) at the top of the FireSystem plugin."
        or "No fixtures are patched yet.", commands = {{value = 1, name = "OK"}}})
      return
    end
    local n = START.buildGroups(blocks)
    local t = {}
    for i = 1, n do t[#t + 1] = i end
    CFG.GROUPS = t
    if not Confirm("FireSystem", n .. " groups are built" ..
        (#failures > 0 and ("\n\n" .. table.concat(failures, "\n")) or "") .. "\n\nBuild FireSystem with them now?") then return end
    return setup(true)
  end
  if arg == "global setup" then dbg("== setup (no prompt)") return setup(true) end  -- e.g. over OSC
  -- debugging over OSC: run one command / one Lua chunk and log the answer
  if arg:sub(1, 11) == "global cmd " then
    local c = arg:sub(12)
    dbg("cmd " .. c .. "  ->  " .. tostring(Cmd(c)))
    return
  end
  if arg == "global theme" or arg == "global theme on" or arg == "global theme off" then
    if arg ~= "global theme" then sv("theme", arg:sub(14)) end
    local ok, n, sig = pcall(FN.TH.check, true)
    local _, read = pcall(FN.TH.read)
    dbg(string.format("theme: %s, %s appearances recoloured (%s)", tostring(ok), tostring(n), tostring(sig)))
    Echo(string.format("FireSystem: button colours %s", gv("theme") == "off" and "are Tom's (global theme on follows MA's colour theme)"
      or read and "follow MA's colour theme" or "are Tom's: the colour theme could not be read"))
    return
  end
  if arg:sub(1, 11) == "global lua " then
    local f, err = load(arg:sub(12))
    if not f then dbg("lua compile: " .. tostring(err)) return end
    local ok, r = pcall(f)
    dbg("lua " .. tostring(ok) .. ": " .. tostring(r))
    return
  end
  if arg == "global savelook" or arg:sub(1, 16) == "global savelook " then
    failures = {}
    dbg("== press: " .. arg)
    saveLook(arg:sub(17))
    return
  end
  if arg == "global groups" then return openGroupBuilder() end
  if arg:sub(1, 15) == "global goboset " then
    dbg("== press: " .. arg)
    local k = tonumber(arg:sub(16))
    local gi, key = tonumber(gv("gp_g") or "") or 1, gv("gp_key") or "gobo1"
    local wheel = CFG.GROUPS[gi] and cachedWheel(CFG.GROUPS[gi], key)
    local sl = wheel and wheel[k]
    if not sl then return end
    for _, g2 in ipairs({gi}) do
      local st = loadGroup("beam", g2)
      if st[key] == k then  -- tapping the picked gobo again clears it
        st[key], st[key .. "p"], st[key .. "n"], st[key .. "f"], st[key .. "d"] = 0, nil, nil, nil, nil
      else
        st[key], st[key .. "p"], st[key .. "n"] = k, FN.goboPreset(g2, key, k, sl), sl.name
        st[key .. "f"], st[key .. "d"] = sl.file, sl.path
      end
      st.dirty = true
      saveGroup("beam", g2, st)
    end
    if getGlobal().live then firePage("beam") end
    Cany({ string.format("Select Layout %d", layoutNo("beam")) })
    TC.scr.show("beam")
    return refresh("beam")
  end
  if arg == "global looks export" then  -- this show's icons into the MA library, for new shows
    failures = {}
    local n = START.packExport()
    for _, f in ipairs(failures) do log("  %s", f) end
    return Echo(string.format("FireSystem: %d images and appearances exported to the library", n))
  end
  if arg == "global looks import" then  -- the library's icons into this show (free numbers only)
    failures = {}
    local n = START.packImport()
    for _, f in ipairs(failures) do log("  %s", f) end
    return Echo(string.format("FireSystem: %d images and appearances imported", n))
  end
  if arg == "global presets" then  -- makes every FireSystem preset again (except the ones you updated)
    failures = {}
    dbg("== remake all presets")
    BM.forcePresets = true
    local ok, err = pcall(function()
      createPresets()
      for n = 1, #CFG.CUSTOM_COLORS do storeCustomColor(n) end
    end)
    BM.forcePresets = false
    if not ok then log("presets: %s", tostring(err)) end
    rebuildAllKeys()
    for _, f in ipairs(failures) do log("  %s", f) end
    return Echo("FireSystem: presets made again, bump keys and strobes stored again")
  end
  if arg == "global keys" then  -- e.g. after storing a Strobe preset straight into the pool
    failures = {}
    dbg("== rebuild bump keys, strobe knobs and Strobe All")
    rebuildAllKeys()
    for _, f in ipairs(failures) do log("  %s", f) end
    return Echo("FireSystem: bump keys, strobe knobs and Strobe All stored again")
  end
  -- view height in rows: "global viewrows -1" = one row less than measured (0 = as measured)
  if arg:match("^global viewrows %-?%d+$") then
    failures = {}
    sv("view_dh", arg:match("(%-?%d+)$"))
    buildViews(false)
    layoutFix()
    sv("fit_sig", FIT.sig())
    for _, f in ipairs(failures) do log("  %s", f) end
    return START.openHome()
  end
  if arg == "global views" then  -- asks for the console again, rebuilds the views and refits the layouts
    failures = {}
    buildViews(true)
    layoutFix()
    sv("fit_sig", FIT.sig())
    for _, f in ipairs(failures) do log("  %s", f) end
    return START.openHome()
  end
  if arg == "global ccol" then
    if openExtraPage("ccol") then
      for n = 1, #CFG.CUSTOM_COLORS do  -- make sure COLOR 1-4 exist
        if not presetExists(4, colorPreset(NCOL + n)) then storeCustomColor(n) end
      end
    end
    return
  end
  if arg:sub(1, 13) == "global ccset " then
    dbg("== press: " .. arg)
    local n, r, v = arg:sub(14):match("^(%d+)%s+(%d+)%s+([%d%.]+)")
    n, r, v = tonumber(n), tonumber(r), tonumber(v)
    if n and r and v then
      local c = customColor(n)
      c[r] = v
      SetVar(GlobalVars(), "FS_cc_" .. n, table.concat({c[1], c[2], c[3], c[4]}, ","))
      storeCustomColor(n)
    end
    return refresh("ccol")
  end
  if arg:sub(1, 16) == "global storegrp " then
    local g, name = arg:sub(17):match("^(%d+)%s*(.*)$")
    return storeGroup(tonumber(g), name)
  end
  if arg:sub(1, 15) == "global editgrp " then  -- Edit Grid / Save Grid of group g
    local g = tonumber(arg:sub(16))
    if not g then return end
    if gv("grp_edit") == tostring(g) then
      sv("grp_edit", "")
      if SelectionCount() > 0 then
        C("Store Group %d /Overwrite", g)  -- the selection with its new grid positions
        BM.units[g] = nil
        if g >= CFG.UTIL_GROUP_BASE and g < CFG.UTIL_GROUP_BASE + #CFG.UTIL then sv("ukeep_" .. g, "1") end
  TC.capCache = {}
        dbg(string.format("Group %d: grid saved (%d fixtures)", g, SelectionCount()))
      end
      C("ClearAll")
      return refresh("grp")
    end
    if not obj("Group " .. g) then
      MessageBox({title = "FireSystem", message = "Store Group " .. g .. " first.", commands = {{value = 1, name = "OK"}}})
      return
    end
    sv("grp_edit", tostring(g))
    C("ClearAll")
    C("Group %d", g)
    Echo("FireSystem: arrange Group " .. g .. " in the Selection Grid (Setup, then drag), then tap Save Grid")
    return refresh("grp")
  end
  if arg:sub(1, 15) == "global grpfeat " then  -- Features pop-up of group g
    local g = tonumber(arg:sub(16))
    if g then TC.feat.edit(g) end
    if obj("Layout " .. layoutNo("dim")) then pcall(refreshAll) end  -- (built: grey / un-grey the pages' buttons)
    return refresh("grp")
  end
  if arg:sub(1, 16) == "global storelin " then  -- the selection, laid out in one row, as G<n>'s linear group
    local g = tonumber(arg:sub(17))
    if not g then return end
    local n = BM.storeLinear(BM.linNo(g), (objName(obj("Group " .. g)) or ("G" .. g)) .. " Lin")
    if not n then return storeGroup(BM.linNo(g), "") end  -- nothing selected: says so
    sv("lin_auto_" .. g, "0")
    return refresh("grp")
  end
  if arg:sub(1, 16) == "global clearlin " then
    local g = tonumber(arg:sub(17))
    if g and obj("Group " .. BM.linNo(g)) then C("Delete Group %d /NC", BM.linNo(g)) end
    if g then sv("lin_auto_" .. g, "1") end
    return refresh("grp")
  end
  if arg:sub(1, 16) == "global cleargrp " then
    local g = tonumber(arg:sub(17))
    if g and obj("Group " .. g) then
      local ok, v = pcall(MessageBox, {title = "FireSystem", message = "Delete Group " .. g .. " '" ..
        tostring(objName(obj("Group " .. g))) .. "'?", commands = {{value = 1, name = "Delete"}, {value = 0, name = "Cancel"}}})
      if ok and type(v) == "table" and v.result == 1 then C("Delete Group %d /NC", g) end
    end
    return refresh("grp")
  end
  if arg == "global clearsel" then Cany({ "ClearSelection", "Clear" }) return end
  if arg == "global grid3dauto" then
    sv("grid3d_auto", gv("grid3d_auto") == "1" and "0" or "1")
    return refresh("grp")
  end
  if arg == "global grid3d" then return FN.grid3dPress() end
  if arg == "global grpdone" then
    local t = FN.groupList8()
    if #t == 0 then
      MessageBox({title = "FireSystem", message = "Store at least one group first.", commands = {{value = 1, name = "OK"}}})
      return
    end
    local s = {}
    for _, g in ipairs(t) do s[#s + 1] = tostring(g) end
    SetVar(GlobalVars(), "FS_groups", table.concat(s, ","))
    CFG.GROUPS = t
    dbg("== groups done: " .. table.concat(s, ","))
    return setup()
  end
  if arg == "global layoutfix" then dbg("== layoutfix") layoutFix() return end
  if arg == "global gapdump" then  -- horizontal / vertical gaps between buttons that aren't 0 or 0.25
    local out = {}
    for _, page in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "home"}) do
      local spec = buildSpec(page)
      local rows = {}
      for _, b in ipairs(spec) do
        if not b.frame then
          for r = 0, b.h - 1 do
            local key = b.row - r
            rows[key] = rows[key] or {}
            table.insert(rows[key], {b.col, b.col + b.w, b.label})
          end
        end
      end
      local gaps = {}
      for row, list in pairs(rows) do
        table.sort(list, function(x, y) return x[1] < y[1] end)
        for i = 2, #list do
          local g = list[i][1] - list[i - 1][2]
          if g > 0.01 and math.abs(g - 0.25) > 0.01 then
            gaps[#gaps + 1] = string.format("r%s %s|%s %.2f", tostring(row), list[i - 1][3], list[i][3], g)
          end
        end
      end
      out[#out + 1] = page .. ": " .. table.concat(gaps, ", ")
    end
    dbg("gapdump " .. table.concat(out, " ## "))
    return
  end
  if arg == "global shutdump" then BM.shut = {} for _, g in ipairs(CFG.GROUPS) do BM.shutter(g) end return end
  if arg == "global noicondump" then  -- buttons that show plain text (no icon, artwork, number or category image)
    local seen, out = {}, {}
    for _, page in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "grp", "ccol", "gobo", "home", "tc", "songs", "rec", "upd"}) do
      local ok, spec = pcall(buildSpec, page)
      for _, b in ipairs(ok and spec or {}) do
        if not b.icon and not b.art and not b.num and not b.cat and not b.frame and not b.gobo
           and not tostring(b.arg):find(" color %d") and not tostring(b.arg):find(" mx c[12] ") and b.label ~= " " then
          local key = b.label .. "/" .. b.w .. "x" .. b.h .. (b.arg == "global noop" and "/cap" or "")
          if not seen[key] then seen[key] = true out[#out + 1] = page .. ":" .. key end
        end
      end
    end
    dbg("noicon " .. table.concat(out, "; "))
    return
  end
  if arg == "global capdump" then  -- list the captions (title / w / dynamic)
    local seen, out = {}, {}
    for _, page in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "grp", "ccol", "gobo"}) do
      local ok, spec = pcall(buildSpec, page)
      for _, b in ipairs(ok and spec or {}) do
        if b.arg == "global noop" and not b.frame then
          local key = page .. ":" .. b.label .. "/" .. b.w .. (b.lbl and "/dyn" or "") .. (b.icon and "/icon" or "") .. (b.art and "/art" or "")
          if not seen[key] then seen[key] = true out[#out + 1] = key end
        end
      end
    end
    dbg("capdump " .. table.concat(out, ";"))
    return
  end
  if arg == "global numdump" then  -- list the number discs (label = families) for tools/make_number_icons.py
    local seen, out = {}, {}
    for _, page in ipairs({"dim", "col", "cfx", "pos", "pfx", "beam", "bump", "xk", "grp", "ccol", "gobo"}) do
      local ok, spec = pcall(buildSpec, page)
      for _, b in ipairs(ok and spec or {}) do
        if b.w == 1 and b.h == 1 and not b.icon and not b.art and b.arg ~= "global noop" and not b.lbl
           and (b.label:match("^[%-%d%.%/°]+$") or b.label == "Half") then
          local fams = {}
          if b.fam then
            for _, ax in ipairs(FN.AXES) do
              local ok2, f = pcall(b.fam, {axis = ax, page = page})
              if ok2 and f then fams[#fams + 1] = f end
            end
          else fams[1] = textFamily(b.label) end
          for _, f in ipairs(fams) do
            local key = b.label .. "|" .. f
            if not seen[key] then seen[key] = true out[#out + 1] = key end
          end
        end
      end
    end
    table.sort(out)
    dbg("numdump " .. table.concat(out, ";"))
    return
  end
  if arg == "global fit" then  -- Same Size <-> Fill Screen
    sv("fit_mode", gv("fit_mode") == "fill" and "same" or "fill")
    dbg("== fit: " .. gv("fit_mode"))
    layoutFix()
    refreshAll()
    if obj("Layout " .. layoutNo("home")) then refresh("home") end
    return
  end
  if arg == "global execs" then  -- only (re)assign the executors
    failures = {}
    dbg("== execs")
    assignExecutors()
    for _, f in ipairs(failures) do log("  %s", f) end
    return
  end

  local t = {}
  for w in arg:gmatch("%S+") do t[#t + 1] = w end
  local page, act, a1, a2, a3 = t[1], t[2], t[3], t[4], t[5]
  failures = {}
  -- a click that arrives twice (press + repeat) would flip a toggle straight
  -- back (the big X, MAtricks values): ignore the same button within 0.4 s
  local now
  pcall(function() now = Time() end)
  if type(now) == "number" then
    local last, lastT = gv("last_arg"), tonumber(gv("last_t") or "")
    sv("last_arg", arg); sv("last_t", tostring(now))
    local rpt = page == "tced" and (act == "nudge" or act == "up" or act == "down")  -- (meant to repeat)
    if last == arg and lastT and now - lastT >= 0 and now - lastT < 0.4 and not rpt then
      dbg("== repeat ignored: " .. arg)
      return
    end
  end
  dbg("== press: " .. arg)

  if page == "global" then
    local g = getGlobal()
    if act == "noop" then return
    elseif act == "page" then
      if PAGE[a1] then
        pcall(refresh, a1)  -- up to date (e.g. the linked FIRE)
        Cany({ string.format("Select Layout %d", layoutNo(a1)), string.format("Layout %d", layoutNo(a1)) })
        -- with FS views built, switch the view of the screen it was pressed on (the others stay)
        if TC.combo.DEF[a1] then TC.combo.views(a1) end
        TC.scr.show(a1)
      end
      if #failures > 0 then log("rejected: %s", failures[1]) end
      return
    elseif act == "live" then g.live = not g.live
    elseif act == "solo" then g.solo = not g.solo
    elseif act == "fire" or act == "fireall" then
      -- linked FIRE: every page with changes waiting; nothing waiting = the page's selection again
      local any = false
      for _, p in ipairs(FIRE_PAGES) do
        local pend = false
        for gi = 1, TC.fill.n(p) do if loadGroup(p, gi).dirty then pend = true end end
        if pend then firePage(p) any = true end
      end
      if not any and a1 and LOOK_DEFAULTS[a1] then firePage(a1) end
    elseif act == "offall" then for _, p in ipairs(FIRE_PAGES) do offPage(p) end
    elseif act == "setup" then return setup()
    elseif act == "reset" then
      for _, p in ipairs(FIRE_PAGES) do
        for gi = 1, TC.fill.n(p) do sv(p .. "_" .. gi, "") end
        setSel(p, {})
      end
    end
    setGlobal(g)
    refreshAll()
  elseif page == "bump" then
    FN.bumpAction(act, a1, a2)
  elseif page == "tc" then
    return TC.action(act, a1)
  elseif page == "tced" then
    return TC.ed.action(act, a1)
  elseif page == "upd" then
    return TC.upd.action(act, a1, a2)
  elseif page == "xk" then
    FN.xkAction(act, a1, a2, a3)
  elseif TC.combo.DEF[page] then
    TC.combo.action(page, act, a1, a2, a3)
  elseif PAGE[page] and LOOK_DEFAULTS[page] then
    pageAction(page, act, a1, a2, a3)
  else
    log("Unknown argument: %s", arg)
  end
  if #failures > 0 then for _, f in ipairs(failures) do log("rejected: %s", f) end end
end

-- warns once per show and grandMA3 version when this version wasn't tested (CFG.MA_TESTED)
-- The popup waits for OK, so it only comes on a Home / open / setup press (never mid-busk);
-- other presses just echo it to the command line
function TC.verCheck(argument)
  local full = tostring(Version and Version() or "")
  if full == "" or gv("ma_ver_seen") == full then return end
  local mm = full:match("^(%d+%.%d+)") or full
  for _, v in ipairs(CFG.MA_TESTED) do if v == mm then sv("ma_ver_seen", full) dbg("== grandMA3 version " .. full) return end end
  local calm = argument == nil or argument == "" or argument == "global home" or argument == "global open"
               or argument == "global setup"
  if not calm then
    if TC.verEchoed ~= full then Echo("FireSystem: grandMA3 " .. full .. " was not tested - check the pages before the show") end
    TC.verEchoed = full
    return
  end
  sv("ma_ver_seen", full)
  dbg("== grandMA3 version " .. full .. " (not tested)")
  pcall(MessageBox, {title = "FireSystem", commands = {{value = 1, name = "OK"}}, message = string.format(
    "This console runs grandMA3 %s.\nFireSystem was tested on %s.\n\nIt should mostly work, but check the pages " ..
    "and FIRE before the show.", full, table.concat(CFG.MA_TESTED, ", "))})
end

function main(displayHandle, argument)
  nCmds = 0
  pcall(TC.verCheck, argument)
  TC.look.seen = {}
  TC.scr.from = displayHandle
  TC.combo.apply()  -- the combined pages this show has (FS_combos)
  TC.combo.busy = false
  local t0 = os.clock()
  -- views built by an older version (e.g. the extra pages only on screen 1): rebuilt once
  if type(argument) == "string" and argument ~= "" and argument ~= "global setup" and CFG.VIEWS
     and gv("views_ok") == "1" and gv("views_ver") ~= CFG.VIEWS_VER then
    dbg("== views version " .. tostring(gv("views_ver") or "none") .. " -> " .. CFG.VIEWS_VER .. ": rebuilding the views")
    failures = {}
    pcall(buildViews, false)
  end
  -- an onPC display window was resized since the views were built: refit views and layouts
  if type(argument) == "string" and argument ~= "" and argument ~= "global setup" and CFG.VIEWS
     and gv("views_ok") == "1" and FN.onPC() then
    local sig, old = FIT.sig(), gv("fit_sig")
    if sig ~= "" and sig ~= old then
      sv("fit_sig", sig)
      if old and old ~= "" then
        dbg("== display size changed (" .. tostring(old) .. " -> " .. sig .. "): refitting views and layouts")
        failures = {}
        pcall(buildViews, false)
        pcall(layoutFix)
        sv("mast_view", "")  -- the Masters view is rebuilt at its next opening
      end
    end
  end
  -- the pages gained buttons since this show was built: rebuild their layouts and macros once
  -- (the button macros sit at fixed numbers, so the old layouts would light the wrong buttons)
  if type(argument) == "string" and argument ~= "" and argument ~= "global setup" and argument ~= "global home"
     and argument:sub(1, 11) ~= "global cmd " and argument:sub(1, 11) ~= "global lua " and gv("pages_ver") ~= TC.combo.ver() and obj("Layout " .. layoutNo("dim")) and isOurs(obj("Layout " .. layoutNo("dim"))) then
    failures = {}
    if gv("combos") == nil then TC.combo.check() end  -- (a show from before the combined pages)
    dbg("== pages version " .. tostring(gv("pages_ver") or "none") .. " -> " .. TC.combo.ver() .. ": rebuilding the page layouts")
    createLayoutsAndMacros(PAGES)
    pcall(layoutFix)
    sv("fit_sig", FIT.sig())
    sv("pages_ver", TC.combo.ver())
    for k in pairs(lastAp) do lastAp[k] = nil end
    for k in pairs(lastTxt) do lastTxt[k] = nil end
    for k in pairs(TC.names) do TC.names[k] = nil end
    refreshAll()
    Echo("FireSystem: the pages were updated to this version of the plugin")
  end
  pcall(FN.TH.check)  -- (the colour theme changed: the buttons follow it)
  local r = run(displayHandle, argument)
  if TC.rec.tok and TC.recording() then pcall(TC.rec.masters) end  -- (recording: a speed master moved?)
  if type(argument) == "string" and argument ~= "" and argument:sub(1, 7) ~= "global " or
     (type(argument) == "string" and argument:sub(1, 12) == "global page ") then
    dbg(string.format("   (%d commands, %.0f ms)", nCmds, (os.clock() - t0) * 1000))
  end
  return r
end

end


-- one table for this plugin's copy of the modules (state doesn't mix with FireSystem's own)
local function build()
  local E = setmetatable({}, {__index = G})
  for _, name in ipairs(MODULES) do
    if type(MODS[name]) ~= "function" then error(TITLE .. ": module " .. name .. " is missing (rebuild with tools/make_tools.py)", 0) end
    MODS[name](E)
  end
  E.CFG.DEBUG_LOG = false  -- (FireSystem's per-command log file: slow, and not this tool's)
  return E
end

local function say(msg)
  Printf(msg)
  pcall(MessageBox, {title = TITLE, message = msg, commands = {{value = 1, name = "OK"}}})
end

-- "1 Thru 4 + 7", "1-4,7" or "1 2 3" -> {1, 2, 3, 4, 7}
local function parseGroups(s)
  local t, seen = {}, {}
  s = tostring(s or ""):lower():gsub("thru", "-"):gsub("%s*%-%s*", "-")
  for a, b in s:gmatch("(%d+)%-?(%d*)") do
    local from, to = tonumber(a), tonumber(b) or tonumber(a)
    if to < from then from, to = to, from end
    for n = from, math.min(to, from + 99) do
      if not seen[n] then seen[n] = true; t[#t + 1] = n end
    end
  end
  return t
end

-- the groups to offer: this tool's last run (var), then FireSystem's own (FS_groups), then Groups 1-8 that exist
local function defaultGroups(E, var1)
  for _, var in ipairs({var1, "FSP_groups", "FS_groups"}) do
    local v = GetVar(GlobalVars(), var)
    if type(v) == "string" and v:find("%d") then return v end
  end
  local t = {}
  for n = 1, 8 do if E.obj("Group " .. n) then t[#t + 1] = n end end
  return #t > 0 and E.rangeList(t) or "1 Thru 8"
end


